    def _library_route_shortcuts_for_current_state(
        self,
    ) -> tuple[tuple[str, str], ...]:
        """The per-mode shortcut set for whichever Library surface is live.

        Shared by ``_register_footer_shortcuts`` (the footer) and
        ``action_show_workbench_help`` (F1) -- task-2858 review (Important
        #1): before this extraction, F1 only listed check_action-filtered
        ``BINDINGS`` entries, but `/`, the landing's `i`/`n` hub
        accelerators, and F6 are ``on_key``/app-global wiring, never
        ``Binding``s, so F1 never learned about them and rendered an empty
        panel on the landing (and every other on_key-only surface). Both
        call sites now read the exact same selection, so the footer and F1
        can never disagree about what is genuinely active.

        # task-420: the "u"/evidence actions hard-gate on the Search/RAG
        # row, so advertising them screen-wide made them dead shortcuts
        # everywhere else -- they register only where they work,
        # re-registered on every rail-row switch AND on navigation-context
        # deep links (F-012: `_apply_navigation_context_state` can land on
        # the Search canvas without a rail-row press). task-2237 (R2):
        # three honest contexts -- the landing advertises its full
        # keyboard story (`/`, hub accelerators, F6), other canvases get
        # the keys that work there, never a dead key. task-2850: Files
        # mode is a fourth context -- its Escape binding only works there
        # (see ``check_action``), so it is the only state that advertises
        # "esc". task-2856: two more contexts -- a detail/viewer surface
        # (media viewer, note/prompt editor) advertises "esc back to list";
        # a list canvas showing its plain list advertises "esc focus rail".
        # Review round 3: a SEVENTH context -- the media viewer's edit/
        # delete-confirm/analysis-edit sub-states are still
        # ``_library_media_view == "viewer"`` but Escape there only steps
        # back one level (see ``action_library_media_viewer_back``), not to
        # the list, so it gets its own honest hint instead of inheriting
        # the plain viewer's "back to list" (see
        # ``_library_media_viewer_substate_active``). task-3020: two more
        # contexts -- the skill editor advertises its own "ctrl+s"/"esc"
        # (AC4, previously fell through to the bare general set since its
        # view is "editor", not "list"); an ARMED bulk-delete confirmation
        # on the Media list advertises "esc cancel delete" instead of the
        # plain list's "esc focus rail" (AC2 parity/honesty -- the list is
        # still genuinely showing, just with its toolbar swapped out).
        """
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_SEARCH:
            return self.LIBRARY_SHORTCUTS
        if not self._library_selected_row_id:
            return self.LIBRARY_LANDING_SHORTCUTS
        # task-3302 (MI-04): Ingest is its own honest context -- Enter
        # starts the import, Esc returns to the hub. Disjoint from every
        # gate below (they all require a different row id).
        if self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA:
            return self._library_ingest_shortcuts_for_current_state()
        # task-4023 AC#7: Export and the Study staging canvases advertise
        # their newly wired Escape. Export's label names the actual
        # destination -- the canvas whose "Export…" opened it, or the hub.
        if self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT:
            # task-14902 AC#3: while the quality strip is open, Enter picks
            # and Escape cancels the pick (never "back") -- the footer must
            # match what the keys genuinely do.
            if self._library_open_choice_strip() is not None:
                return (("enter", "choose quality"), ("esc", "cancel"))
            origin_label = _LIBRARY_HELP_SURFACE_LABELS.get(
                self._library_export_origin_row_id, ""
            )
            back_label = f"back to {origin_label}" if origin_label else "back to hub"
            return (
                ("/", "focus search"),
                ("F6", "next pane"),
                ("esc", back_label),
            )
        if self._library_selected_row_id in LIBRARY_STUDY_HANDOFF_ROW_IDS:
            return (
                ("/", "focus search"),
                ("F6", "next pane"),
                ("esc", "back to hub"),
            )
        # task-4023 AC#7: Collections shares the list-canvas Escape
        # contract (focus hop toward the rail) and its footer set.
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            emergency = self._library_emergency_return_eligibility()
            if emergency.visible and emergency.guarded:
                return self.LIBRARY_GENERAL_SHORTCUTS
            return self.LIBRARY_LIST_SHORTCUTS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            shortcuts: list[tuple[str, str]] = []
            if self._library_conversation_reader_layout.items_open:
                shortcuts.append(("/", "focus filter"))
            shortcuts.append(("F6", "next pane"))
            escape_label = self._library_conversation_escape_label()
            if escape_label:
                shortcuts.append(("esc", escape_label))
            return tuple(shortcuts)
        if self._file_notes_active():
            workspace = self._library_file_notes_workspace
            if workspace is not None and workspace.reload_confirmation_active:
                return self.LIBRARY_NOTES_FILES_RELOAD_CONFIRM_SHORTCUTS
            return self.LIBRARY_NOTES_FILES_SHORTCUTS
        if self._library_media_viewer_substate_active():
            return self.LIBRARY_MEDIA_SUBSTATE_BACK_SHORTCUTS
        if (
            (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                # task-4025: the Trash view shares the detail surfaces'
                # honest "esc back to list" context -- its Escape
                # (``action_library_media_trash_back``) genuinely returns
                # to the media list, exactly what this set advertises.
                and self._library_media_view in ("viewer", "trash")
            )
            or self._library_note_editor_active()
            or self._library_prompt_editor_active()
        ):
            if (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and self._library_media_view == "viewer"
            ):
                return (
                    ("/", "focus search"),
                    ("F6", "next pane"),
                    ("esc", self._library_media_escape_label()),
                )
            return self.LIBRARY_DETAIL_BACK_SHORTCUTS
        if self._library_skill_editor_active():
            shortcuts = [("/", "focus search"), ("F6", "next pane")]
            if self._library_skill_save_available():
                shortcuts.append(("ctrl+s", "save skill"))
            shortcuts.append(
                (
                    "esc",
                    "close more actions"
                    if self._library_skill_more_actions_open
                    else "back to skills list",
                )
            )
            return tuple(shortcuts)
        if self._library_media_confirming_bulk_delete:
            return self.LIBRARY_MEDIA_BULK_DELETE_CONFIRM_SHORTCUTS
        # task-14902 AC#3: an open choice strip advertises its own keys.
        # Placed AFTER the bulk-delete-confirm gate to match the escape
        # bindings' declaration order (an armed confirm's Escape wins).
        open_strip = self._library_open_choice_strip()
        if open_strip is not None:
            return (("enter", f"choose {open_strip[0]}"), ("esc", "cancel"))
        if self._library_list_canvas_showing_list():
            return self.LIBRARY_LIST_SHORTCUTS
        return self.LIBRARY_GENERAL_SHORTCUTS

    def _library_footer_shortcuts_for_current_state(
        self,
    ) -> tuple[tuple[str, str], ...]:
        """Hide rail-search hints while the compact rail has no search box."""
        shortcuts = self._library_route_shortcuts_for_current_state()
        emergency = self._library_emergency_return_eligibility()
        if emergency.enabled:
            shortcuts = tuple(pair for pair in shortcuts if pair[0] != "esc") + (
                ("esc", "rail"),
            )
        if self._library_lifecycle not in (
            LibraryLifecycle.UNKNOWN,
            LibraryLifecycle.STARTER,
        ):
            return shortcuts
        return tuple(
            pair
            for pair in shortcuts
            if not (pair[0] == "/" and pair[1].casefold() in {"focus search", "search"})
        )

    @property
    def _library_note_detail(self) -> Mapping[str, Any] | None:
        """Return a read-only compatibility projection of the session snapshot."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return None
        return {
            "id": snapshot.note_id,
            "title": snapshot.title,
            "content": snapshot.body,
            "keywords": snapshot.keywords_text,
            "version": snapshot.version,
            "created_at": snapshot.baseline.created_at,
            "last_modified": snapshot.baseline.modified_at,
        }

    @property
    def _library_note_version(self) -> int | None:
        """Return the coordinator-owned optimistic-lock version."""
        snapshot = self._library_note_session.snapshot
        return snapshot.version if snapshot is not None else None

    @property
    def _library_note_dirty(self) -> bool:
        """Return whether the canonical coordinator draft has unsaved edits."""
        snapshot = self._library_note_session.snapshot
        return snapshot.dirty if snapshot is not None else False

    @property
    def _library_note_conflict_snapshot(self) -> LibraryNoteEditorState | None:
        """Return the canonical draft presentation while conflict is active."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None or not snapshot.in_conflict:
            return None
        return self._library_note_editor_state()

    @property
    def _library_note_preview_snapshot(self) -> LibraryNoteEditorState | None:
        """Return the canonical draft presentation while preview is active."""
        if not self._library_note_preview:
            return None
        return self._library_note_editor_state()

    def _library_note_editor_state(self) -> LibraryNoteEditorState | None:
        """Project the one canonical session snapshot into incumbent canvas state."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return None
        baseline_state = build_library_note_editor_state(
            {
                "id": snapshot.note_id,
                "title": snapshot.baseline.title,
                "content": snapshot.baseline.body,
                "keywords": snapshot.baseline.keywords,
                "version": snapshot.version,
                "created_at": snapshot.baseline.created_at,
                "last_modified": snapshot.baseline.modified_at,
            }
        )
        if snapshot.in_conflict:
            status = notes_autosave_status_text(
                "conflict", word_count=self._note_word_count(snapshot.body)
            )
            if snapshot.status_message != "Conflict — review the choices below.":
                status = f"{status} · {snapshot.status_message}"
        else:
            status = snapshot.status_message
        meta_line = baseline_state.meta_line
        if status:
            meta_line = f"{meta_line} · {status}" if meta_line else status
        return LibraryNoteEditorState(
            note_id=snapshot.note_id,
            title=snapshot.title,
            content=snapshot.body,
            keywords_text=snapshot.keywords_text,
            version=snapshot.version,
            meta_line=meta_line,
            has_note=True,
        )

    def _library_note_status_line(self) -> str:
        """Return the persistent, text-labeled save state for both regions."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return "No note open"
        if self._library_note_shortcut_status:
            return self._library_note_shortcut_status
        if self._library_note_autosave_state == "saving" or snapshot.saving:
            return "Saving…"
        if snapshot.in_conflict:
            return snapshot.status_message or "Conflict — review the choices below."
        if snapshot.status_message:
            return snapshot.status_message
        return "Unsaved changes" if snapshot.dirty else "Saved"

    def _library_note_presentation_state(self) -> LibraryNotePresentationState:
        """Project the canonical session into presentation-only canvas state."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            raise RuntimeError("A note presentation requires an active session.")
        base_meta = self._library_note_meta_base_line()
        word_count = self._note_word_count(snapshot.body)
        word_copy = f"{word_count} words" if word_count != 1 else "1 word"
        status_line = self._library_note_status_line()
        metadata_line = " · ".join(part for part in (base_meta, word_copy) if part)
        operation = self._library_notes_operation_for_active_region()
        status_channels = resolve_database_note_status_channels(
            conflict=snapshot.in_conflict,
            read_only=self._library_notes_select_mode,
            save_failed=self._library_note_autosave_state in {"error", "validation"},
            saving=snapshot.saving or self._library_note_autosave_state == "saving",
            dirty=snapshot.dirty,
        )
        if self._library_note_shortcut_status:
            status_channels = dataclasses.replace(
                status_channels,
                content_recovery=status_line,
                safe_next_action=None,
            )
        elif snapshot.in_conflict or self._library_note_autosave_state in {
            "error",
            "validation",
        }:
            status_channels = dataclasses.replace(
                status_channels,
                content_recovery=status_line,
            )
        return LibraryNotePresentationState(
            snapshot=snapshot,
            metadata_line=metadata_line,
            status_line=status_line,
            region="context" if self._library_note_context else "editor",
            presentation="preview" if self._library_note_preview else "edit",
            compact=self._library_notes_compact,
            validation=self._library_note_autosave_state == "validation",
            conflict=snapshot.in_conflict,
            conflict_running=self._library_note_session.conflict_resolution_running,
            confirming_delete=self._library_note_confirming_delete,
            destructive_running=self._library_note_session.destructive_running,
            discard_new_note=(
                self._library_note_session.untouched_create_token is not None
            ),
            transfer_status=operation.status_line if operation is not None else "",
            transfer_running=bool(operation and operation.running),
            bulk_read_only=self._library_notes_select_mode,
            bulk_included=self._library_notes_row_selection.is_selected(
                snapshot.note_id
            ),
            status_channels=status_channels,
        )

    def _library_notes_active_region(
        self,
    ) -> Literal["navigator", "editor", "context", ""]:
        """Return the currently visible Notes operation-status region."""
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_view == "editor"
        ):
            return "context" if self._library_note_context else "editor"
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_view == "list"
        ):
            return "navigator"
        return ""

    def _library_notes_operation_for_active_region(
        self,
    ) -> LibraryNotesOperationState | None:
        operation = self._library_notes_operation
        if operation is None or operation.region != self._library_notes_active_region():
            return None
        return operation

    def _library_note_import_execution_active(self) -> bool:
        """Return whether reviewed import currently owns Notes mutations."""
        controller = getattr(self, "_library_note_import_controller", None)
        snapshot = getattr(controller, "snapshot", None)
        return getattr(snapshot, "phase", None) is NoteImportPhase.IMPORTING

    def _library_notes_mutation_fenced(self) -> bool:
        """Keep Database Notes single-writer while reviewed import executes."""
        return bool(
            getattr(self, "_library_notes_mutation_in_flight", False)
            or self._library_note_import_execution_active()
        )

    def _library_notes_operation_is_current_and_active(
        self, operation: LibraryNotesOperationState
    ) -> bool:
        """Return whether a running token still owns the visible region."""
        current = self._library_notes_operation
        return bool(
            current is not None
            and current.running
            and current.token == operation.token
            and current.kind == operation.kind
            and current.region == self._library_notes_active_region()
        )

    def _apply_library_notes_operation_state(self) -> None:
        """Synchronize the one active Notes operation status surface."""
        if not self.is_mounted:
            return
        if self._library_notes_active_region() == "navigator":
            _sync_library_canvas(self, "notes")
            return
        if self._library_notes_active_region() in {"editor", "context"}:
            try:
                canvas = self.query_one("#library-note-work-pane", LibraryNoteWorkPane)
            except (NoMatches, QueryError):
                return
            if canvas.mode != "editor":
                self.call_after_refresh(self._apply_library_notes_operation_state)
                return
            self._apply_library_note_presentation_state()

    def _begin_library_notes_operation(
        self, kind: Literal["import", "export", "copy", "console"]
    ) -> LibraryNotesOperationState | None:
        """Claim one typed transfer token before invoking an external seam."""
        if self._library_notes_mutation_fenced():
            return None
        current = self._library_notes_operation
        if current is not None and current.running:
            return None
        region = self._library_notes_active_region()
        if region not in {"navigator", "editor", "context"}:
            return None
        if kind not in {"import", "export", "copy", "console"}:
            return None
        self._library_notes_notice = ""
        self._library_notes_operation_counter += 1
        operation = LibraryNotesOperationState(
            kind=kind,
            token=self._library_notes_operation_counter,
            phase="running",
            region=region,
        )
        self._library_notes_operation = operation
        self._apply_library_notes_operation_state()
        return operation

    def _move_library_notes_operation(
        self,
        token: int,
        region: Literal["navigator", "editor", "context"],
    ) -> bool:
        """Move a current operation to the region its success opened."""
        operation = self._library_notes_operation
        if (
            operation is None
            or operation.token != token
            or region not in {"navigator", "editor", "context"}
        ):
            return False
        self._library_notes_operation = dataclasses.replace(operation, region=region)
        return True

    def _finish_library_notes_operation(
        self,
        operation: LibraryNotesOperationState,
        *,
        success: bool,
        completion_next_action: str = "",
        failure_next_action: str = "try again",
    ) -> bool:
        """Terminalize the current token and render only in its active region."""
        current = self._library_notes_operation
        active_region = self._library_notes_active_region()
        if (
            current is None
            or current.token != operation.token
            or current.kind != operation.kind
        ):
            return False
        terminal = dataclasses.replace(
            current,
            phase="complete" if success else "failed",
            completion_next_action=completion_next_action,
            failure_next_action=failure_next_action,
        )
        if current.region != active_region:
            # The side effect belongs to the matching token, but its former
            # status surface is no longer visible. Release the global claim
            # without leaking completion copy into the user's new region.
            self._library_notes_operation = None
            return False
        self._library_notes_operation = terminal
        self._apply_library_notes_operation_state()
        return True

    def _apply_library_note_presentation_state(self) -> None:
        """Synchronize the mounted canvas without changing its composition."""
        if not self.is_mounted or self._library_note_session.snapshot is None:
            return
        try:
            canvas = self.query_one("#library-note-work-pane", LibraryNoteWorkPane)
        except (NoMatches, QueryError):
            return
        canvas.title_placeholder_only = bool(
            self._library_note_pending_blank_gc_id
            and self._library_note_pending_blank_gc_id == self._selected_note_id
        )
        self._library_note_presentation_syncing = True
        try:
            canvas.apply_session_state(self._library_note_presentation_state())
        finally:
            self._library_note_presentation_syncing = False

        self._apply_library_notes_stage_visibility()
        self._apply_library_notes_footer_context()

    def _library_notes_workflow_active(self) -> bool:
        """Return whether the current Library route is owned by Database Notes."""
        return (
            self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
            and self._library_selected_row_id
            in {
                LIBRARY_ROW_BROWSE_NOTES,
                LIBRARY_ROW_CREATE_NOTE,
            }
        )

    def _library_notes_compact_workflow_active(self) -> bool:
        """Return whether either Notes source owns compact canvas routing."""
        return self._library_notes_workflow_active() or self._file_notes_active()

    def _library_notes_focused_task_active(self) -> bool:
        """Return whether Notes owns a task surface rather than its navigator."""
        return self._file_notes_active() or (
            self._library_notes_workflow_active()
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_view == "editor"
        )

    def _library_notes_focus_region(
        self,
    ) -> Literal[
        "",
        "navigator",
        "editor",
        "preview",
        "context",
        "create",
        "lasting_add",
        "lasting_roots",
        "import",
    ]:
        """Return the semantic Notes region currently presented by the host."""
        if self._library_selected_row_id == LIBRARY_ROW_CREATE_NOTE:
            return "create"
        if self._library_selected_row_id != LIBRARY_ROW_BROWSE_NOTES:
            return ""
        if self._library_notes_view in {"lasting_add", "lasting_roots"}:
            return self._library_notes_view
        if self._library_notes_view == "import":
            return "import"
        if self._library_notes_view == "list":
            return "navigator"
        if self._library_note_context:
            return "context"
        if self._library_note_preview:
            return "preview"
        return "editor"

    @staticmethod
    def _library_notes_widget_is_within(widget: Widget, ancestor: Widget) -> bool:
        """Return whether ``widget`` belongs to ``ancestor``'s live subtree."""
        return ancestor in widget.ancestors_with_self

    def _active_library_rail(self) -> LibraryRail | None:
        """Return the rail owned by the currently visible Library authority."""
        if self._file_notes_active():
            workspace = self._library_file_notes_workspace
            shell = workspace._reader_shell if workspace is not None else None
            rail = shell.library if shell is not None else None
            if isinstance(rail, LibraryRail) and rail.is_attached:
                return rail
        try:
            return self.query_one("#library-rail", LibraryRail)
        except (NoMatches, QueryError):
            return None

    def _library_notes_authority_root(
        self, authority: Literal["database", "files"]
    ) -> Widget | None:
        """Resolve one retained Notes authority's mounted subtree."""
        if authority == "files":
            workspace = self._library_file_notes_workspace
            return (
                workspace if workspace is not None and workspace.is_attached else None
            )
        try:
            return self.query_one(
                "#library-notes-reader-shell", LibraryAdaptiveReaderShell
            )
        except (NoMatches, QueryError):
            return None

    def _remember_library_notes_authority_focus(self, focused: Widget | None) -> None:
        """Remember a reachable descendant without treating source chrome as work."""
        if focused is None or focused.id in {
            "library-notes-source-database",
            "library-notes-source-files",
            "library-notes-task-return",
        }:
            return
        for authority in ("database", "files"):
            root = self._library_notes_authority_root(authority)
            if root is not None and self._library_notes_widget_is_within(focused, root):
                self._library_notes_authority_focus[authority] = focused
                return

    def _evacuate_library_notes_authority_focus(
        self, authority: Literal["database", "files"]
    ) -> None:
        """Capture the outgoing authority and clear focus before hiding it."""
        focused = self.focused
        root = self._library_notes_authority_root(authority)
        if (
            focused is not None
            and root is not None
            and self._library_notes_widget_is_within(focused, root)
        ):
            self._library_notes_authority_focus[authority] = focused
        self.set_focus(None)

    def _restore_library_notes_authority_focus(
        self, authority: Literal["database", "files"]
    ) -> bool:
        """Restore the destination's reachable focus or its honest first target."""
        target = self._library_notes_authority_focus[authority]
        if target is not None and (
            not target.is_attached
            or not target.visible
            or target not in self.focus_chain
        ):
            target = None
        if target is None:
            selector = (
                "#file-notes-search"
                if authority == "files"
                else (
                    "#library-note-body" if self._library_notes_view == "editor" else ""
                )
            )
            if selector:
                try:
                    candidate = self.query_one(selector, Widget)
                except (NoMatches, QueryError):
                    candidate = None
                if (
                    candidate is not None
                    and candidate.visible
                    and candidate in self.focus_chain
                ):
                    target = candidate
        if target is None:
            return False
        self.set_focus(target, scroll_visible=False)
        return True

    def _library_notes_focus_stage(
        self, focused: Widget | None
    ) -> Literal["rail", "notes"]:
        """Map a live focused widget to the portable Library stage."""
        if focused is None:
            return self._library_notes_stage
        rail = self._active_library_rail()
        if rail is not None and self._library_notes_widget_is_within(focused, rail):
            return "rail"
        canvas = self._library_layout_ref("#library-canvas")
        if canvas is not None and self._library_notes_widget_is_within(focused, canvas):
            return "notes"
        work_pane = self._library_compose_scoped_ref("#library-note-work-pane")
        if work_pane is not None and self._library_notes_widget_is_within(
            focused, work_pane
        ):
            return "notes"
        return self._library_notes_stage

    def _library_notes_semantic_role(self, focused: Widget | None) -> str:
        """Map one mounted control to its stable Notes semantic identity."""
        if focused is None:
            return ""
        landing_control_id = self._library_landing_focus_control_id(focused)
        if landing_control_id:
            return f"landing-control:{landing_control_id}"
        row_id = str(getattr(focused, "row_id", "") or "")
        if row_id and focused.has_class("library-rail-row"):
            return f"library-row:{row_id}"
        note_id = str(getattr(focused, "note_id", "") or "")
        if note_id and focused.has_class("library-notes-row"):
            placement_id = str(getattr(focused, "placement_id", "") or "")
            if placement_id:
                return f"note-placement:{placement_id}"
            return f"note-row:{note_id}"
        media_id = str(getattr(focused, "media_id", "") or "")
        if media_id and focused.has_class("library-media-row"):
            return f"media-row:{media_id}"
        if focused.id == "library-media-open-viewer":
            try:
                media_canvas = self.query_one(
                    "#library-media-canvas", LibraryMediaCanvas
                )
            except (NoMatches, QueryError):
                pass
            else:
                selected_id = str(media_canvas.canvas.selected_id or "")
                if selected_id:
                    return f"media-preview-open:{selected_id}"
        if focused.has_class("library-notes-folder-row"):
            placement_id = str(getattr(focused, "placement_id", "") or "")
            if placement_id:
                return f"folder-placement:{placement_id}"
        if focused.has_class("library-notes-tree-pager") and focused.id:
            return f"tree-pager:{focused.id}"
        template_key = str(getattr(focused, "template_key", "") or "")
        if template_key:
            return f"create-template:{template_key}"

        widget_id = focused.id or ""
        if widget_id and self._file_notes_active():
            workspace = self._library_file_notes_workspace
            if workspace is not None and self._library_notes_widget_is_within(
                focused,
                workspace,
            ):
                return f"file-notes:{widget_id}"
        direct_roles = {
            "library-notes-filter": "filter",
            "library-notes-select-toggle": "select-toggle",
            "library-note-title": "title",
            "library-note-body": "body",
            "library-note-preview-region": "preview-body",
            "library-note-preview-body": "preview-body",
            "library-note-context-region": "context",
            "library-note-context": "context",
            "library-note-save": "save",
            "library-note-load-retry": "load-retry",
            "library-note-conflict-copy": "conflict-callout",
            "library-note-delete-cancel": "delete-cancel",
            "notes-sync-display-name": "lasting-display-name",
            "notes-sync-folder-choose": "lasting-folder-choose",
            "notes-sync-check": "lasting-check",
            "notes-sync-roots-back": "lasting-roots-back",
            "note-import-add-source": "import-add-source",
            "note-import-destination": "import-destination",
            "note-import-check": "import-check",
            "note-import-import": "import-execute",
            "note-import-cancel": "import-cancel",
            "note-import-retry": "import-retry",
            "library-notes-import-back": "import-back",
            "library-notes-create-blank": "create-template:blank",
        }
        if widget_id in direct_roles:
            return direct_roles[widget_id]
        if widget_id in {
            "library-note-back",
            "library-note-context-back",
            "library-notes-create-back",
            "notes-sync-back",
            "notes-sync-roots-back",
        }:
            return f"region-back:{self._library_notes_focus_region()}"
        if widget_id.startswith("library-note-context-"):
            return f"context-action:{widget_id}"
        direction = "notes-sync-direction-"
        if widget_id.startswith(direction):
            return (
                f"sync-direction:{widget_id.removeprefix(direction).replace('-', '_')}"
            )
        return ""

    def _library_landing_focus_control_id(self, focused: Widget | None) -> str:
        """Return the stable id of a focused returning-landing action."""
        if focused is None or not focused.id:
            return ""
        landing = self._library_layout_ref("#library-landing-canvas")
        if landing is None:
            return ""
        if not self._library_notes_widget_is_within(focused, landing):
            return ""
        if focused.id == "library-hub-continue" or focused.has_class(
            "library-hub-attention-action"
        ):
            return focused.id
        if focused.has_class("library-hub-recent") or focused.has_class(
            "library-hub-action"
        ):
            return focused.id
        return ""

    def _library_landing_control_row_id(self, control_id: str) -> str:
        """Map one landing action to its compact-rail destination."""
        if not control_id:
            return ""
        try:
            control = self.query_one(f"#{control_id}", Widget)
        except (NoMatches, QueryError):
            return ""
        row_id = str(getattr(control, "row_id", "") or "")
        if row_id:
            return row_id
        action_kind = str(getattr(control, "action_kind", "") or "")
        if action_kind:
            return {
                "ingest-review": LIBRARY_ROW_INGEST_MEDIA,
                "media-retry": LIBRARY_ROW_BROWSE_MEDIA,
                "prompts-retry": LIBRARY_ROW_BROWSE_PROMPTS,
                "conversations-retry": LIBRARY_ROW_BROWSE_CONVERSATIONS,
            }.get(action_kind, "")
        source_type = str(getattr(control, "source_type", "") or "")
        return {
            "notes": LIBRARY_ROW_BROWSE_NOTES,
            "media": LIBRARY_ROW_BROWSE_MEDIA,
            "conversations": LIBRARY_ROW_BROWSE_CONVERSATIONS,
        }.get(source_type, "")

    def _library_notes_scroll_owner(self, region: str) -> Widget | None:
        """Resolve the one named scroll/content owner for a Notes region."""
        selector = {
            "rail": "#library-rail",
            "navigator": "#library-notes-list",
            "editor": "#library-note-body",
            "preview": "#library-note-preview-region",
            "context": "#library-note-context-region",
            "create": "#library-notes-create-viewport",
            "lasting_add": "#notes-sync-body",
            "lasting_roots": "#notes-sync-roots-body",
            "import": "#library-note-import-canvas",
        }.get(region)
        if selector is None:
            return None
        # TASK-23025: positive ref cache -- a mounted owner is one attribute
        # read; absence still costs one walk, so callers should not probe
        # regions their route cannot mount (see the observer installer).
        return self._library_layout_ref(selector)

    def _capture_library_notes_focus_identity(
        self, *, stage_from_focus: bool = True
    ) -> LibraryNotesFocusIdentity:
        """Capture only portable focus, selection, and scroll values."""
        focused = self.focused
        region = self._library_notes_focus_region()
        stage = (
            self._library_notes_focus_stage(focused)
            if stage_from_focus
            else self._library_notes_stage
        )
        role = self._library_notes_semantic_role(focused)
        snapshot = self._library_note_session.snapshot
        note_id = snapshot.note_id if snapshot is not None else None
        if note_id is None and region == "navigator":
            note_id = str(getattr(focused, "note_id", "") or "") or None
        selection_start: tuple[int, int] | None = None
        selection_end: tuple[int, int] | None = None
        if region in {"editor", "preview", "context"}:
            try:
                body = self.query_one("#library-note-body", TextArea)
            except (NoMatches, QueryError):
                pass
            else:
                selection_start = tuple(body.selection.start)
                selection_end = tuple(body.selection.end)

        owner_region = "rail" if stage == "rail" else region
        scroll_owner = self._library_notes_scroll_owner(owner_region)
        if role.startswith(("media-row:", "media-preview-open:")):
            try:
                scroll_owner = self.query_one("#library-media-row-scroll", Widget)
            except (NoMatches, QueryError):
                scroll_owner = None
        scroll_offset = (
            (int(scroll_owner.scroll_x), int(scroll_owner.scroll_y))
            if scroll_owner is not None
            else None
        )
        return LibraryNotesFocusIdentity(
            stage=stage,
            region=region,
            note_id=note_id,
            semantic_role=role,
            body_selection_start=selection_start,
            body_selection_end=selection_end,
            scroll_offset=scroll_offset,
        )

    def _capture_library_notes_recompose_state(
        self,
    ) -> _LibraryNotesRecomposeCapture | None:
        """Capture coordinator identity and transient presentation, never draft text."""
        if not self.is_mounted or not self._library_notes_workflow_active():
            return None
        snapshot = self._library_note_session.snapshot
        return _LibraryNotesRecomposeCapture(
            focus=self._capture_library_notes_focus_identity(stage_from_focus=True),
            recompose_generation=self._library_notes_recompose_generation,
            scroll_generation=self._library_notes_scroll_intent_generation,
            focus_generation=self._library_notes_focus_intent_generation,
            session_generation=(
                snapshot.session_generation if snapshot is not None else None
            ),
            draft_revision=(snapshot.draft_revision if snapshot is not None else None),
            preview=self._library_note_preview,
            context=self._library_note_context,
            confirming_delete=self._library_note_confirming_delete,
        )

    def _capture_library_notes_browse_return_receipt(
        self,
        *,
        note_id: str = "",
        placement_id: str = "",
    ) -> LibraryNotesTreeReceipt:
        """Capture record-free semantic browse context before a focused task."""
        focus = self._capture_library_notes_focus_identity(stage_from_focus=False)
        if focus.region != "navigator" or not focus.semantic_role:
            for cached in (
                self._library_notes_last_user_focus,
                self._library_notes_interaction_focus,
                self._library_notes_last_presented_focus,
            ):
                if cached is not None and cached.region == "navigator":
                    focus = cached
                    break
        notes_list = self._library_notes_scroll_owner("navigator")
        scroll_offset = (
            (int(notes_list.scroll_x), int(notes_list.scroll_y))
            if notes_list is not None
            else focus.scroll_offset
        )
        resolved_note_id = note_id or str(focus.note_id or "")
        semantic_role = focus.semantic_role or "filter"
        if resolved_note_id:
            semantic_role = (
                f"note-placement:{placement_id}"
                if placement_id
                else f"note-row:{resolved_note_id}"
            )
        if ":" in semantic_role:
            focus_role, focus_semantic_id = semantic_role.split(":", 1)
        else:
            focus_role, focus_semantic_id = semantic_role, ""
        rail = self._library_notes_scroll_owner("rail")
        rail_scroll_offset = (
            (int(rail.scroll_x), int(rail.scroll_y)) if rail is not None else None
        )
        branch_ranges = tuple(
            LibraryNotesBranchRange(
                key.parent_id,
                key.slice_kind,
                state.start_offset,
                state.start_offset + len(state.items),
            )
            for key, state in sorted(
                self._library_notes_tree_branches.items(),
                key=lambda item: (
                    item[0].parent_id is not None,
                    item[0].parent_id or "",
                    item[0].slice_kind,
                ),
            )
            if state.freshness == "fresh" and not state.loading and not state.error
        )
        filter_state = self._library_notes_tree_filter_state
        selected_placement_id = (
            placement_id or self._library_notes_tree_selected_placement_id
        )
        projection = self._build_library_notes_tree_projection()
        selected_row = (
            projection.row(selected_placement_id)
            if projection is not None and selected_placement_id
            else None
        )
        return LibraryNotesTreeReceipt(
            selected_placement_id=selected_placement_id,
            selected_note_id=resolved_note_id,
            expanded_folder_ids=tuple(sorted(self._library_notes_tree_expanded_ids)),
            branch_ranges=branch_ranges,
            filter_query=self._library_notes_filter,
            filter_range=(
                filter_state.range_descriptor
                if filter_state is not None
                and filter_state.query == self._library_notes_filter
                and not filter_state.loading
                and not filter_state.error
                else None
            ),
            focus_semantic_id=focus_semantic_id,
            focus_role=focus_role,
            scroll_offset=scroll_offset,
            rail_scroll_offset=rail_scroll_offset,
            lifecycle_generation=self._library_notes_tree_lifecycle_generation,
            topology_epoch=self._library_notes_tree_topology_epoch,
            preferred_folder_id=(
                selected_row.folder_id
                if selected_row is not None and selected_row.membership_id
                else None
            ),
            preferred_membership_id=(
                selected_row.membership_id if selected_row is not None else None
            ),
        )

    def _restore_library_notes_browse_return_receipt(
        self,
        receipt: LibraryNotesTreeReceipt,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Restore live semantic state or reload the receipt's exact ranges."""
        if (
            receipt.lifecycle_generation
            != self._library_notes_tree_lifecycle_generation
            or receipt.topology_epoch != self._library_notes_tree_topology_epoch
        ):
            self.run_worker(
                self._reload_library_notes_browse_return_receipt(receipt, guard),
                exclusive=True,
                group="library_notes_tree:return",
            )
            return
        self._library_notes_tree_expanded_ids = set(receipt.expanded_folder_ids)
        self._library_notes_tree_selected_placement_id = receipt.selected_placement_id
        semantic_role = receipt.focus_role
        if receipt.focus_semantic_id:
            semantic_role = f"{semantic_role}:{receipt.focus_semantic_id}"
        focus = LibraryNotesFocusIdentity(
            stage="notes",
            region="navigator",
            note_id=receipt.selected_note_id or None,
            semantic_role=semantic_role or "filter",
            scroll_offset=receipt.scroll_offset,
        )
        if not self._restore_library_notes_focus_identity(focus, guard):
            return
        rail = (
            self._library_notes_scroll_owner("rail")
            if receipt.rail_scroll_offset is not None
            else None
        )
        if rail is not None:
            rail.scroll_to(
                x=receipt.rail_scroll_offset[0],
                y=receipt.rail_scroll_offset[1],
                animate=False,
                force=True,
                immediate=True,
            )

    async def _reload_library_notes_browse_return_receipt(
        self,
        receipt: LibraryNotesTreeReceipt,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Reload semantic receipt ranges after a topology/lifecycle change."""
        if not LibraryScreen._library_notes_restore_guard_is_current(self, guard):
            return
        generation = LibraryScreen._supersede_library_notes_navigation(self)

        def current() -> bool:
            return bool(
                generation == self._library_notes_navigation_generation
                and LibraryScreen._library_notes_restore_guard_is_current(self, guard)
            )

        for descriptor in receipt.branch_ranges:
            if not current():
                return
            key = descriptor.key
            await LibraryScreen._load_library_notes_tree_slice(
                self,
                key,
                direction="target",
                offset=descriptor.start_offset,
                navigation_generation=generation,
            )
            while current():
                state = self._library_notes_tree_branches.get(key)
                if (
                    state is None
                    or state.loading
                    or state.error
                    or state.freshness != "fresh"
                    or state.topology_epoch != self._library_notes_tree_topology_epoch
                ):
                    break
                authoritative_end = (
                    min(descriptor.end_offset, state.total)
                    if state.total is not None
                    else descriptor.end_offset
                )
                loaded_end = state.start_offset + len(state.items)
                if loaded_end >= authoritative_end or state.next_offset != loaded_end:
                    break
                await LibraryScreen._load_library_notes_tree_slice(
                    self,
                    key,
                    direction="more",
                    offset=loaded_end,
                    navigation_generation=generation,
                )
        if receipt.filter_query and receipt.filter_range is not None:
            await LibraryScreen._run_library_notes_filter(
                self,
                receipt.filter_query,
                offset=receipt.filter_range.start_offset,
                direction="replace",
                navigation_generation=generation,
            )
            while current():
                state = self._library_notes_tree_filter_state
                if (
                    state is None
                    or state.query != receipt.filter_query
                    or state.loading
                    or state.error
                    or state.stale
                    or state.topology_epoch != self._library_notes_tree_topology_epoch
                ):
                    break
                authoritative_end = (
                    min(receipt.filter_range.end_offset, state.total)
                    if state.total is not None
                    else receipt.filter_range.end_offset
                )
                loaded_end = state.start_offset + len(state.placements)
                if loaded_end >= authoritative_end or state.next_offset != loaded_end:
                    break
                await LibraryScreen._run_library_notes_filter(
                    self,
                    receipt.filter_query,
                    offset=loaded_end,
                    direction="more",
                    navigation_generation=generation,
                )
        if not current():
            return
        self._library_notes_tree_expanded_ids = set(receipt.expanded_folder_ids)
        if receipt.filter_query and receipt.filter_range is not None:
            self._library_notes_filter = receipt.filter_query
        if receipt.selected_note_id:
            await LibraryScreen._locate_library_notes_tree_target(
                self,
                note_id=receipt.selected_note_id,
                preferred_folder_id=receipt.preferred_folder_id,
                preferred_membership_id=receipt.preferred_membership_id,
                focus=True,
                focus_scroll_offset=receipt.scroll_offset,
                navigation_generation=generation,
                restore_guard=guard,
            )
        elif receipt.focus_role == "folder-placement" and receipt.focus_semantic_id:
            folder_id = receipt.focus_semantic_id.removeprefix("folder:")
            await LibraryScreen._locate_library_notes_tree_target(
                self,
                folder_id=folder_id,
                focus=True,
                navigation_generation=generation,
                restore_guard=guard,
            )
        if not current():
            return
        rail = (
            self._library_notes_scroll_owner("rail")
            if receipt.rail_scroll_offset is not None
            else None
        )
        if rail is not None:
            rail.scroll_to(
                x=receipt.rail_scroll_offset[0],
                y=receipt.rail_scroll_offset[1],
                animate=False,
                force=True,
                immediate=True,
            )

    def _commit_library_note_widgets_before_recompose(self) -> None:
        """Move queued editor values into the canonical coordinator before teardown."""
        if (
            not self.is_mounted
            or not self._library_note_editor_armed
            or self._library_note_presentation_syncing
            or self._library_notes_focus_region()
            not in {"editor", "preview", "context"}
            or self._library_note_session.snapshot is None
        ):
            return
        try:
            title = self.query_one("#library-note-title", Input).value
            body = self.query_one("#library-note-body", TextArea).text
            keywords_selector = (
                "#library-note-context-keywords"
                if self._library_note_context
                else "#library-note-keywords"
            )
            keywords_text = self.query_one(keywords_selector, Input).value
        except (NoMatches, QueryError):
            return
        if self._library_note_session.mutate(
            title=title,
            body=body,
            keywords_text=keywords_text,
        ):
            self._library_note_shortcut_status = ""
            self._schedule_library_note_autosave()

    def _library_notes_role_target(
        self, identity: LibraryNotesFocusIdentity
    ) -> Widget | None:
        """Resolve one portable semantic role against the current widget tree."""
        role = identity.semantic_role
        selector = {
            "filter": "#library-notes-filter",
            "select-toggle": "#library-notes-select-toggle",
            "title": "#library-note-title",
            "body": "#library-note-body",
            "preview-body": "#library-note-preview-region",
            "context": "#library-note-context-region",
            "save": "#library-note-save",
            "load-retry": "#library-note-load-retry",
            "conflict-callout": "#library-note-conflict-copy",
            "delete-cancel": "#library-note-delete-cancel",
            "lasting-display-name": "#notes-sync-display-name",
            "lasting-folder-choose": "#notes-sync-folder-choose",
            "lasting-check": "#notes-sync-check",
            "lasting-roots-back": "#notes-sync-roots-back",
            "import-add-source": "#note-import-add-source",
            "import-destination": "#note-import-destination",
            "import-check": "#note-import-check",
            "import-execute": "#note-import-import",
            "import-cancel": "#note-import-cancel",
            "import-retry": "#note-import-retry",
            "import-back": "#library-notes-import-back",
            "create-template:blank": "#library-notes-create-blank",
        }.get(role)
        if role.startswith("context-action:"):
            selector = f"#{role.removeprefix('context-action:')}"
        elif role.startswith("sync-direction:"):
            selector = f"#notes-sync-direction-{role.removeprefix('sync-direction:').replace('_', '-')}"
        elif role.startswith("region-back:"):
            selector = {
                "context": "#library-note-context-back",
                "create": "#library-notes-create-back",
                "lasting_add": "#notes-sync-back",
                "lasting_roots": "#notes-sync-roots-back",
            }.get(role.removeprefix("region-back:"), "#library-note-back")
        elif role.startswith("landing-control:"):
            control_id = role.removeprefix("landing-control:")
            if control_id:
                selector = f"#{control_id}"
        elif role.startswith("file-notes:"):
            widget_id = role.removeprefix("file-notes:")
            workspace = self._library_file_notes_workspace
            if workspace is None or not widget_id:
                return None
            try:
                return workspace.query_one(f"#{widget_id}", Widget)
            except (NoMatches, QueryError):
                return None
        elif role.startswith(("media-row:", "media-preview-open:")):
            media_id = role.split(":", 1)[1]
            if (
                role.startswith("media-preview-open:")
                and not self._library_notes_compact
            ):
                try:
                    return self.query_one("#library-media-open-viewer", Widget)
                except (NoMatches, QueryError):
                    return None
            for row in self.query(".library-media-row"):
                if str(getattr(row, "media_id", "") or "") == media_id:
                    return row
            return None
        if selector is not None:
            try:
                return self.query_one(selector, Widget)
            except (NoMatches, QueryError):
                return None

        if role.startswith("library-row:"):
            row_id = role.removeprefix("library-row:")
            for row in self.query(".library-rail-row"):
                if str(getattr(row, "row_id", "") or "") == row_id:
                    return row
        elif role.startswith("note-placement:"):
            placement_id = role.removeprefix("note-placement:")
            for row in self.query(".library-notes-row"):
                if str(getattr(row, "placement_id", "") or "") == placement_id:
                    return row
        elif role.startswith("folder-placement:"):
            placement_id = role.removeprefix("folder-placement:")
            for row in self.query(".library-notes-folder-row"):
                if str(getattr(row, "placement_id", "") or "") == placement_id:
                    return row
        elif role.startswith("tree-pager:"):
            pager_id = role.removeprefix("tree-pager:")
            for pager in self.query(".library-notes-tree-pager"):
                if pager.id == pager_id:
                    return pager
        elif role.startswith("note-row:"):
            note_id = role.removeprefix("note-row:")
            for row in self.query(".library-notes-row"):
                if str(getattr(row, "note_id", "") or "") == note_id:
                    return row
        elif role.startswith("create-template:"):
            template_key = role.removeprefix("create-template:")
            for row in self.query(".library-notes-template-row"):
                if str(getattr(row, "template_key", "") or "") == template_key:
                    return row
        return None

    def _library_notes_fallback_focus_target(
        self, identity: LibraryNotesFocusIdentity
    ) -> Widget | None:
        """Choose the safest visible focus target when an exact role vanished."""
        if self._library_notes_compact and identity.stage != self._library_notes_stage:
            identity = dataclasses.replace(
                identity,
                stage=self._library_notes_stage,
                semantic_role="",
            )
        if identity.stage == "rail":
            role = f"library-row:{self._library_selected_row_id}"
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role=role)
            )
        region = self._library_notes_focus_region()
        if region == "navigator":
            role = f"note-row:{identity.note_id}" if identity.note_id else "filter"
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role=role)
            ) or self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="filter")
            )
        if region == "context":
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="context")
            )
        if region == "preview":
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="preview-body")
            )
        if region == "editor":
            snapshot = self._library_note_session.snapshot
            role = "body"
            if self._library_note_load_state == "failed":
                role = "load-retry"
            elif snapshot is not None and snapshot.in_conflict:
                role = "conflict-callout"
            elif self._library_note_confirming_delete:
                role = "delete-cancel"
            elif self._library_note_session.untouched_create_token is not None:
                role = "title"
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role=role)
            )
        if region == "create":
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="create-template:blank")
            )
        if region == "lasting_add":
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="lasting-display-name")
            )
        if region == "lasting_roots":
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="lasting-roots-back")
            )
        if region == "import":
            phase = self._library_note_import_controller.snapshot.phase
            role = {
                NoteImportPhase.SELECT: "import-add-source",
                NoteImportPhase.DESTINATION: "import-destination",
                NoteImportPhase.CHECKING: "import-cancel",
                NoteImportPhase.REVIEW: "import-execute",
                NoteImportPhase.IMPORTING: "import-cancel",
                NoteImportPhase.RECEIPT: "import-retry",
            }[phase]
            return self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role=role)
            ) or self._library_notes_role_target(
                dataclasses.replace(identity, semantic_role="import-back")
            )
        return None

    def _restore_library_notes_focus_identity(
        self,
        identity: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> bool:
        """Restore semantic focus, retaining pending intent until its exact target exists."""
        if not self.is_mounted or not self._library_notes_restore_guard_is_current(
            guard
        ):
            return False
        target = None
        if not (
            self._library_notes_compact and identity.stage != self._library_notes_stage
        ):
            target = self._library_notes_role_target(identity)
        restored_exact_target = target is not None
        if target is None:
            target = self._library_notes_fallback_focus_target(identity)
        if target is None:
            return False
        if identity.semantic_role == "conflict-callout" and isinstance(target, Static):
            target.can_focus = True
        start = identity.body_selection_start
        end = identity.body_selection_end
        if start is not None and end is not None:
            try:
                body = self.query_one("#library-note-body", TextArea)
            except (NoMatches, QueryError):
                pass
            else:
                body.move_cursor(start)
                body.move_cursor(end, select=start != end)
        self._library_notes_restoring_focus = True
        try:
            if self.focused is not target:
                exact_scroll = identity.scroll_offset is not None
                self._library_notes_programmatic_focus_target = target
                self.set_focus(target, scroll_visible=not exact_scroll)
                if not exact_scroll:
                    target.scroll_visible(animate=False, force=True, immediate=True)
            self._restore_library_notes_scroll_offset(identity, guard)
        finally:
            self._library_notes_restoring_focus = False
        if (
            restored_exact_target
            and not self._library_notes_pending_focus_waits_for_snapshot
            and self._library_notes_pending_focus_identity == identity
        ):
            self._library_notes_pending_focus_identity = None
            self._library_notes_pending_focus_generation = None
        return restored_exact_target

    def _restore_library_notes_after_targeted_sync(
        self, identity: LibraryNotesFocusIdentity
    ) -> None:
        """Restore portable Notes focus + scroll after a canvas-scoped sync.

        task-15457 review round 1. The whole-screen seam does this through
        ``_rehydrate_library_notes_after_recompose``; a canvas-scoped sync
        never reaches ``LibraryScreen.refresh``, so it needs its own entry
        into the same restore. No ``_LibraryNotesRestoreGuard`` is passed:
        the guard exists to invalidate a DEFERRED restore that a newer
        navigation intent has superseded, and this one runs synchronously
        from the canvas's own ``recompose``, against the state that was
        captured moments earlier in the same handler.

        Args:
            identity: The portable identity captured before the sync.

        Returns:
            None.
        """
        # Focus FIRST and synchronously: the callback runs from the canvas's
        # own ``recompose``, so focus is restored before any frame in which
        # it could be seen sitting outside the canvas.
        self._restore_library_notes_focus_identity(identity)
        # Scroll SECOND and deferred. The restore above already attempts it,
        # but at this point the freshly mounted children have not been laid
        # out yet -- the container's max scroll is still 0, so ``scroll_to``
        # clamps the offset away (measured: a 12-row offset restored as 0).
        # The whole-screen seam never hits this because it restores from
        # ``call_after_refresh``, i.e. after a display refresh; re-applying
        # from the same primitive here gives the offset a laid-out container
        # to land in. Idempotent, so the earlier attempt costs nothing.
        self.call_after_refresh(self._restore_library_notes_scroll_offset, identity)

    def _restore_library_notes_scroll_offset(
        self,
        identity: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Apply only the named owner's portable offset, without changing focus."""
        if not self._library_notes_restore_guard_is_current(guard):
            return
        owner_region = (
            "rail" if identity.stage == "rail" else self._library_notes_focus_region()
        )
        owner = self._library_notes_scroll_owner(owner_region)
        if identity.semantic_role.startswith(("media-row:", "media-preview-open:")):
            try:
                owner = self.query_one("#library-media-row-scroll", Widget)
            except (NoMatches, QueryError):
                owner = None
        if owner is not None and identity.scroll_offset is not None:
            owner.scroll_to(
                x=identity.scroll_offset[0],
                y=identity.scroll_offset[1],
                animate=False,
                force=True,
                immediate=True,
            )

    def _library_notes_restore_guard_is_current(
        self, guard: _LibraryNotesRestoreGuard | None
    ) -> bool:
        """Treat focus, scroll, and recompose generations as one restore intent."""
        if guard is None:
            return True
        return bool(
            (
                guard.recompose_generation is None
                or guard.recompose_generation
                == self._library_notes_recompose_generation
            )
            and (
                guard.scroll_generation is None
                or guard.scroll_generation
                == self._library_notes_scroll_intent_generation
            )
            and (
                guard.focus_generation is None
                or guard.focus_generation == self._library_notes_focus_intent_generation
            )
        )

    def _supersede_library_notes_navigation(self, *, render: bool = True) -> int:
        """Synchronously revoke every task owned by an older Notes route intent."""
        self._library_notes_navigation_generation = (
            getattr(self, "_library_notes_navigation_generation", 0) + 1
        )
        self._library_notes_pending_focus_identity = None
        self._library_notes_pending_focus_waits_for_snapshot = False
        self._library_notes_pending_focus_generation = None
        self._library_notes_navigation_status = ""
        branches = getattr(self, "_library_notes_tree_branches", {})
        generations = getattr(self, "_library_notes_tree_request_generations", {})
        navigation_requests = getattr(
            self, "_library_notes_tree_navigation_requests", {}
        )
        for key in tuple(navigation_requests):
            state = branches.get(key)
            if state is None:
                continue
            generation = (
                max(generations.get(key, state.generation), state.generation) + 1
            )
            generations[key] = generation
            branches[key] = dataclasses.replace(
                state,
                generation=generation,
                loading=False,
                recovery_attempted=False,
                requested_direction=None,
                requested_offset=None,
                requested_limit=None,
                failed_direction=None,
                error="",
            )
        navigation_requests.clear()
        if (
            getattr(self, "_library_notes_filter_navigation_generation", None)
            is not None
        ):
            state = getattr(self, "_library_notes_tree_filter_state", None)
            if state is not None and state.loading:
                self._library_notes_filter_generation = (
                    max(
                        getattr(self, "_library_notes_filter_generation", 0),
                        state.generation,
                    )
                    + 1
                )
                self._library_notes_tree_filter_state = dataclasses.replace(
                    state,
                    generation=self._library_notes_filter_generation,
                    loading=False,
                    requested_direction=None,
                    requested_offset=None,
                    requested_limit=None,
                    request_is_recovery=False,
                    failed_direction=None,
                    failed_offset=None,
                    error="",
                )
            self._library_notes_filter_navigation_generation = None
        sync_canvas = getattr(self, "_sync_library_notes_tree_canvas_if_present", None)
        if render and callable(sync_canvas):
            sync_canvas()
        return self._library_notes_navigation_generation

    def _release_library_notes_focus_after_snapshot(self) -> None:
        """Complete a Back focus handoff after its source refresh settles."""
        if (
            self._library_notes_pending_focus_generation
            != self._library_notes_navigation_generation
        ):
            self._library_notes_pending_focus_identity = None
            self._library_notes_pending_focus_waits_for_snapshot = False
            self._library_notes_pending_focus_generation = None
            return
        identity = self._library_notes_pending_focus_identity
        self._library_notes_pending_focus_waits_for_snapshot = False
        if identity is not None:
            self._restore_library_notes_focus_identity(identity)

    def _library_note_session_is_unsafe(self) -> bool:
        """Return whether rail focus must not hide the active note session."""
        snapshot = self._library_note_session.snapshot
        return bool(
            self._library_note_load_state == "failed"
            or self._library_note_confirming_delete
            or self._library_note_session.destructive_running
            or self._library_note_session.destructive_admission is not None
            or (
                snapshot is not None
                and (
                    snapshot.dirty
                    or snapshot.saving
                    or snapshot.in_conflict
                    or self._library_note_autosave_state
                    in {"saving", "error", "validation", "conflict"}
                    or self._library_note_session.conflict_resolution_running
                )
            )
        )

    def _compact_library_notes_stage(
        self, identity: LibraryNotesFocusIdentity
    ) -> Literal["rail", "notes"]:
        """Resolve compact stage precedence without consulting layout children."""
        if self._library_note_session_is_unsafe():
            return "notes"
        if self._library_notes_explicit_stage_intent:
            return "notes"
        if identity.stage == "rail":
            return "rail"
        if (
            identity.stage == "notes"
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
        ):
            return "notes"
        if identity.stage == "notes" and self._library_notes_compact_workflow_active():
            return "notes"
        if self._library_notes_focus_region() in {
            "editor",
            "preview",
            "context",
            "create",
            "lasting_add",
            "lasting_roots",
        }:
            return "notes"
        return "rail"

    def _library_notes_compact_stage_applies(self) -> bool:
        """Scope compact single-stage behavior to active Notes routes."""
        return self._library_notes_compact_workflow_active()

    def _library_ordinary_route_active(self) -> bool:
        """Return whether the retained two-pane ordinary shell owns the route."""
        return self._library_selected_row_id not in {
            LIBRARY_ROW_BROWSE_MEDIA,
            LIBRARY_ROW_BROWSE_CONVERSATIONS,
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_CREATE_NOTE,
            LIBRARY_ROW_CREATE_PROMPT,
            LIBRARY_ROW_CREATE_SKILL,
        }

    def _advance_library_stage_interaction(self) -> int:
        """Invalidate any older emergency focus/scroll restoration."""
        self._library_stage_interaction_generation += 1
        return self._library_stage_interaction_generation

    def _advance_library_ordinary_emergency_user_interaction(
        self, target: Widget | None
    ) -> None:
        """Invalidate restore only for real input inside the ordinary canvas."""
        if (
            target is None
            or self._library_emergency_stage != "canvas-only"
            or self._library_emergency_restore_receipt is None
        ):
            return
        owner = self._library_entry_canvas_owner()
        if owner is not None and owner in target.ancestors_with_self:
            self._advance_library_stage_interaction()

    def _library_emergency_return_eligibility(
        self,
    ) -> _LibraryEmergencyReturnEligibility:
        """Project the sole guarded truth for narrow canvas-to-rail recovery."""
        visible = self._library_emergency_stage == "canvas-only"
        guarded = bool(
            (self.is_mounted and self.app.screen is not self)
            or self._library_open_choice_strip() is not None
            or self._library_prompt_editor_active()
            or self._library_skill_editor_active()
            or self._library_prompts_mutation_in_flight
            or self._library_prompt_dirty
            or self._library_prompt_conflict_snapshot is not None
            or self._library_skill_mutation_in_flight
            or self._library_skill_dirty
            or self._library_skill_conflict
            or self._library_skill_confirming_delete
            or self._library_skill_more_actions_open
            or self._library_export_running
            or self._library_ingest_start_consent is not None
            or self._library_media_confirming_bulk_delete
            or self._library_media_bulk_delete_in_flight
        )
        return _LibraryEmergencyReturnEligibility(
            visible=visible,
            enabled=visible and not guarded,
            guarded=guarded,
        )

    def _sync_library_emergency_return(self, bar: LibraryEmergencyReturn) -> None:
        """Patch presentation from the immutable eligibility projection."""
        eligibility = self._library_emergency_return_eligibility()
        bar.display = eligibility.visible
        bar.disabled = not eligibility.enabled
        bar.tooltip = (
            "Finish or cancel the current Library action first."
            if eligibility.guarded
            else "Return to the Library rail"
        )

    def _restore_library_emergency_receipt(
        self, receipt: _LibraryEmergencyRestoreReceipt
    ) -> None:
        """Restore only when no newer rail/canvas/Notes interaction won."""
        if receipt.generation != self._library_stage_interaction_generation:
            return
        if receipt.route_key != self._library_entry_route_key():
            return
        try:
            owner = self.query_one(f"#{receipt.owner_id}", Widget)
            scroll_owner = self.query_one(f"#{receipt.scroll_owner_id}", Widget)
        except (NoMatches, QueryError):
            return
        rail_query = self.query("#library-rail")
        current_rail = rail_query.first(LibraryRail) if rail_query else None
        if owner not in (self._library_entry_canvas_owner(), current_rail):
            return
        if owner not in scroll_owner.ancestors_with_self:
            return
        target: Widget | None = None
        if receipt.focus.source_id:
            for candidate in Widget.query(owner, Widget):
                if any(
                    str(getattr(candidate, attribute, "") or "")
                    == receipt.focus.source_id
                    for attribute in (
                        "conversation_id",
                        "media_id",
                        "note_id",
                        "prompt_id",
                        "skill_name",
                        "record_id",
                        "source_id",
                    )
                ):
                    target = candidate
                    break
        elif receipt.focus.widget_id:
            try:
                target = owner.query_one(f"#{receipt.focus.widget_id}", Widget)
            except (NoMatches, QueryError):
                target = None
        if target is not None and not getattr(target, "disabled", False):
            target.focus()
        if receipt.focus.scroll_offset is not None and hasattr(
            scroll_owner, "scroll_to"
        ):
            scroll_owner.scroll_to(
                x=receipt.focus.scroll_offset[0],
                y=receipt.focus.scroll_offset[1],
                animate=False,
                force=True,
            )

    def _capture_library_emergency_restore_receipt(
        self, rail: LibraryRail, canvas: Widget
    ) -> _LibraryEmergencyRestoreReceipt:
        """Capture current stage focus and its retained owner's scroll tuple."""
        focused = self.focused
        owner = self._library_entry_canvas_owner() or canvas
        if focused is not None and rail in focused.ancestors_with_self:
            owner = rail
        scroll_owner: Widget | None = None
        if focused is not None and owner in focused.ancestors_with_self:
            scroll_owner = next(
                (
                    candidate
                    for candidate in focused.ancestors_with_self
                    if isinstance(candidate, VerticalScroll)
                    and owner in candidate.ancestors_with_self
                ),
                None,
            )
        if scroll_owner is None and isinstance(owner, VerticalScroll):
            scroll_owner = owner
        if scroll_owner is None:
            scroll_owner = next(
                (
                    candidate
                    for candidate in Widget.query(owner, VerticalScroll)
                    if candidate.display
                ),
                owner,
            )
        source_id = ""
        if focused is not None:
            for attribute in (
                "conversation_id",
                "media_id",
                "note_id",
                "prompt_id",
                "skill_name",
                "record_id",
                "source_id",
            ):
                value = getattr(focused, attribute, None)
                if value is not None and str(value):
                    source_id = str(value)
                    break
        scroll_offset = (
            (int(scroll_owner.scroll_x), int(scroll_owner.scroll_y))
            if hasattr(scroll_owner, "scroll_x") and hasattr(scroll_owner, "scroll_y")
            else None
        )
        return _LibraryEmergencyRestoreReceipt(
            owner_id=str(owner.id or "library-canvas"),
            scroll_owner_id=str(scroll_owner.id or owner.id or "library-canvas"),
            focus=LibraryEntryFocusIdentity(
                widget_id=str(getattr(focused, "id", "") or ""),
                source_id=source_id,
                scroll_offset=scroll_offset,
            ),
            route_key=self._library_entry_route_key(),
            generation=self._library_stage_interaction_generation,
        )

    def _apply_library_emergency_geometry(
        self,
        *,
        shell: Widget,
        rail: LibraryRail,
        canvas: Widget,
        rail_handle: Widget | None,
    ) -> bool:
        """Apply one full-width ordinary stage below the hard floor."""
        width = min(shell.region.width, self.size.width)
        if width <= 0:
            return False
        if self.query(
            "#library-media-reader-shell, "
            "#library-collections-reader-shell, "
            "#library-conversations-reader-shell, "
            "#library-notes-reader-shell, "
            "#library-prompts-reader-shell, "
            "#library-skills-reader-shell"
        ):
            self._library_emergency_stage = None
            self._library_emergency_restore_receipt = None
            for bar in self.query(LibraryEmergencyReturn):
                bar.display = False
            return False
        emergency = (
            self._library_ordinary_route_active() and ordinary_emergency_required(width)
        )
        bars = self.query("#library-emergency-return")
        bar = bars.first(LibraryEmergencyReturn) if bars else None
        if not emergency:
            receipt = self._library_emergency_restore_receipt
            self._library_emergency_stage = None
            self._library_emergency_restore_receipt = None
            if bar is not None:
                bar.display = False
            canvas.styles.width = "13fr"
            canvas.styles.min_width = 40
            if receipt is not None:
                self.call_after_refresh(
                    self._restore_library_emergency_receipt, receipt
                )
            return False
        if self._library_emergency_stage is None:
            self._library_emergency_restore_receipt = (
                self._capture_library_emergency_restore_receipt(rail, canvas)
            )
            focused = self.focused
            if focused is not None and canvas in focused.ancestors_with_self:
                self._library_emergency_stage = "canvas-only"
            elif focused is not None and rail in focused.ancestors_with_self:
                self._library_emergency_stage = "rail-only"
            else:
                self._library_emergency_stage = (
                    "canvas-only" if self._library_selected_row_id else "rail-only"
                )
        canvas_only = self._library_emergency_stage == "canvas-only"
        if rail_handle is not None:
            rail_handle.display = False
        rail.display = not canvas_only
        canvas.display = canvas_only
        canvas.styles.width = "1fr"
        canvas.styles.min_width = 0
        if bar is not None:
            self._sync_library_emergency_return(bar)
        presentation = (
            OrdinaryRailPresentation.HIDDEN
            if canvas_only
            else OrdinaryRailPresentation.RAIL_ONLY
        )
        shared = self._library_reader_shared_preferences
        rail.apply_ordinary_width_contract(
            resolve_ordinary_rail_contract(
                width,
                presentation,
                shared.custom_widths_enabled,
                shared.library_width,
            )
        )
        return True

    def _library_notes_stage_signature(self) -> tuple[Any, ...] | None:
        """Signature of every input the stage-visibility leg turns into a write.

        TASK-23151: built from cached widget references and cheap flags only
        (the TASK-23025 pattern in this file) so a resize frame can decide,
        before any query work, whether ``_apply_library_notes_stage_visibility``
        could write anything different. It mirrors, in order, the compact
        class inputs, ``_apply_library_emergency_geometry``'s effective
        decision (route gate AND width bucket -- the raw bucket alone flips
        on non-ordinary routes where the geometry is inert), and the
        single-stage/focused-task flags the display toggles derive from.
        Returns ``None`` when it cannot be decided cheaply; callers then run
        the full leg, exactly as before.

        Returns:
            The signature tuple, or ``None`` when it cannot be computed cheaply.
        """
        if not self.is_mounted:
            return None
        shell = self._library_layout_ref("#library-shell-grid")
        rail = self._library_layout_ref("#library-rail")
        canvas = self._library_layout_ref("#library-canvas")
        if shell is None or rail is None or canvas is None:
            return None
        # The emergency leg measures exactly this width, so the signature must
        # too -- a wider grid inside a narrower viewport is still an emergency.
        width = min(shell.region.width, self.size.width)
        if width <= 0:
            return None
        reader_active = self._library_adaptive_reader_shell_active()
        emergency = self._library_ordinary_route_active() and (
            ordinary_emergency_required(width)
        )
        reader_shell_id = (
            getattr(self._library_reader_shell_ref, "id", None)
            if reader_active
            else None
        )
        return (
            self._library_compose_generation,
            shell,
            rail,
            canvas,
            reader_active,
            reader_shell_id,
            self._library_selected_row_id,
            self._library_notes_source,
            self._library_notes_view,
            self._library_notes_stage,
            self._library_notes_compact,
            self._library_rail_collapsed,
            self._library_notes_compact_stage_applies(),
            self._library_notes_focused_task_active(),
            self._library_emergency_stage,
            self._library_emergency_restore_receipt is not None,
            self._library_reader_shared_preferences,
            # Rail/canvas display are what the legacy stage toggles WRITE, so
            # they are carried to catch an outside mutation -- but only while
            # the legacy path owns them. Under an adaptive reader shell the
            # leg returns before the toggles and the reader's own
            # ``sync_layout`` owns the rail, hiding it purely as a function of
            # width; carrying it there made every same-side resize look like a
            # change (TASK-23151).
            rail.display if not reader_active else None,
            canvas.display if not reader_active else None,
            emergency,
            # Below the hard floor the emergency leg is the ONLY writer of the
            # rail width contract (``_sync_library_ordinary_rail_width_contract``
            # returns early there), so the raw width matters inside the band
            # and nowhere else.
            width if emergency else None,
        )

    def _apply_library_notes_stage_visibility_for_resize(self) -> None:
        """Run the stage-visibility leg only on a frame that can change it.

        TASK-23151: the resize legs must call this leg above their
        compact-crossing early-out, because the ordinary emergency band
        (``LIBRARY_EMERGENCY_WIDTH``, 64 cells) is a different band from
        ``LIBRARY_NOTES_COMPACT_BREAKPOINT`` (120) and a 63<->64 resize
        crosses only the former. Calling it unconditionally, however, put
        per-frame DOM work back on every same-side resize -- the exact defect
        the 2026-08-02 zero-work ratchet exists to hold at zero. Gate, do not
        move: moving the call below the crossing return would strand the
        narrow emergency return path.
        """
        signature = self._library_notes_stage_signature()
        if (
            signature is not None
            and signature == self._library_notes_stage_applied_signature
        ):
            return
        self._apply_library_notes_stage_visibility()

    def _apply_library_notes_stage_visibility(self) -> None:
        """Apply compact classes and mutually exclusive mounted stage visibility.

        TASK-23151: every call -- from any of this screen's ~20 seams, not
        only the resize legs -- records the signature of the state it just
        settled, so ``_apply_library_notes_stage_visibility_for_resize`` can
        skip a frame that cannot change the result. The record is taken
        AFTER the legs because they mutate flags the signature reads (rail
        and canvas display, the emergency stage), and it is cleared first so
        a leg that raises leaves the gate re-armed rather than stale.
        """
        self._library_notes_stage_applied_signature = None
        self._apply_library_notes_stage_legs()
        self._library_notes_stage_applied_signature = (
            self._library_notes_stage_signature()
        )

    def _project_library_media_stage_classes(self, shell_grid: Widget) -> bool:
        """Project effective Media stage classes; return whether they changed."""
        changed = False
        if shell_grid.has_class("library-notes-compact"):
            shell_grid.remove_class("library-notes-compact")
            changed = True
        if shell_grid.has_class("library-adaptive-compact") != self._library_notes_compact:
            shell_grid.set_class(
                self._library_notes_compact,
                "library-adaptive-compact",
            )
            changed = True
        if changed:
            current_owner: LibraryMediaRowScroll | None = None
            if shell_grid.is_attached:
                tree = self._library_media_settlement_tree()
                if tree is not None and shell_grid in tree[0].ancestors:
                    current_owner = tree[2]
            self._advance_library_media_presentation_epoch(current_owner)
        return changed

    def _library_media_settlement_tree(
        self,
    ) -> tuple[LibraryMediaReaderShell, Vertical, LibraryMediaRowScroll] | None:
        """Return the current attached Media shell, Items host, and row owner."""
        try:
            shell = self.query_one(
                "#library-media-reader-shell",
                LibraryMediaReaderShell,
            )
            items_host = self.query_one("#library-canvas", Vertical)
            owner = self.query_one(
                "#library-media-row-scroll",
                LibraryMediaRowScroll,
            )
        except (NoMatches, QueryError):
            return None
        if not (shell.is_attached and items_host.is_attached and owner.is_attached):
            return None
        if items_host not in owner.ancestors or shell not in items_host.ancestors:
            return None
        if self not in shell.ancestors:
            return None
        return shell, items_host, owner

    def _adopt_library_media_row_owner(self, owner: LibraryMediaRowScroll) -> bool:
        """Advance presentation authority when the row owner is replaced."""
        owner_identity = id(owner)
        if self._library_media_current_owner is owner:
            return False
        self._library_media_current_owner = owner
        self._library_media_presentation_epoch += 1
        self._library_media_geometry_floor_owner_identity = owner_identity
        self._library_media_geometry_floor = 0
        self._library_media_return_settlement = None
        return True

    def _advance_library_media_presentation_epoch(
        self,
        owner: LibraryMediaRowScroll | None,
        *,
        rearm: bool = True,
    ) -> None:
        """Fence geometry already emitted before a Media presentation change."""
        self._library_media_presentation_epoch += 1
        if owner is None:
            self._library_media_current_owner = None
            self._library_media_geometry_floor_owner_identity = None
            self._library_media_geometry_floor = 0
        else:
            self._library_media_current_owner = owner
            self._library_media_geometry_floor_owner_identity = id(owner)
            latest = owner.latest_geometry
            self._library_media_geometry_floor = (
                latest.revision if latest is not None else 0
            )
        self._library_media_return_settlement = None
        receipt = self._library_pending_list_entry_media_return
        if (
            rearm
            and owner is not None
            and self._library_media_return_candidate(receipt)
        ):
            self._arm_library_media_return_settlement(receipt)

    def _library_media_return_candidate(
        self,
        receipt: _LibraryMediaReturnReceipt | None,
    ) -> bool:
        """Return whether one retained receipt can enter Media settlement."""
        return bool(
            receipt is not None
            and receipt.final_focus_policy in {"row", "control"}
            and receipt.scroll_offset is not None
            and receipt.scroll_offset[0] >= 0
            and receipt.scroll_offset[1] >= 0
        )

    def _library_media_exact_return_candidate(
        self,
        receipt: _LibraryMediaReturnReceipt | None,
    ) -> bool:
        """Return whether one retained Media coordinate system is unchanged."""
        return bool(
            self._library_media_return_candidate(receipt)
            and receipt is not None
            and receipt.content_signature == self._library_media_content_signature()
            and receipt.layout_signature == self._library_media_layout_signature()
        )

    def _library_media_semantic_row_is_current(
        self,
        receipt: _LibraryMediaReturnReceipt,
        items_host: Vertical,
    ) -> bool:
        """Return whether the receipt's attached row belongs to current Items."""
        return any(
            row.is_attached
            and str(getattr(row, "media_id", "") or "") == receipt.stable_id
            and items_host in row.ancestors
            for row in self.query(".library-media-row")
        )

    def _library_media_request_matches_current_authority(
        self,
        request: _LibraryMediaReturnSettlement,
        receipt: _LibraryMediaReturnReceipt,
        tree: tuple[LibraryMediaReaderShell, Vertical, LibraryMediaRowScroll],
    ) -> bool:
        """Compare one immutable request with every non-geometry fence."""
        shell, items_host, owner = tree
        return bool(
            request.receipt is receipt
            and request.final_focus_policy == receipt.final_focus_policy
            and request.final_focus_identity == receipt.final_focus_identity
            and request.focus_intent_generation
            == self._library_notes_focus_intent_generation
            and request.compose_generation == self._library_compose_generation
            and request.media_lifecycle_generation
            == self._library_media_lifecycle_generation
            and request.presentation_epoch == self._library_media_presentation_epoch
            and request.content_signature == self._library_media_content_signature()
            and request.layout_signature == self._library_media_layout_signature()
            and request.route_identity == self._library_entry_route_key()
            and request.media_view_identity == self._library_media_view == "list"
            and request.shell_identity == id(shell)
            and request.items_host_identity == id(items_host)
            and request.owner_identity == id(owner)
            and request.focus_anchor
            is self._library_pending_list_entry_focus_anchor
            and self._library_media_live_focus_is_allowed(
                request.focus_anchor,
                receipt.stable_id,
            )
            and self._library_media_current_owner is owner
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._library_media_reader_layout.items_open
            and items_host.display
        )

    def _library_media_live_focus_is_allowed(
        self,
        focus_anchor: Widget | None,
        stable_id: str,
        target: Widget | None = None,
    ) -> bool:
        """Return whether live focus still belongs to one exact return."""
        focused = self.focused
        if focused is None or focused is focus_anchor:
            return True
        guarded_target = target or self._library_notes_programmatic_focus_target
        receipt = self._library_pending_list_entry_media_return
        transient_focus_allowed = bool(
            guarded_target is not None
            and focused is guarded_target
            and self._library_notes_programmatic_focus_target is guarded_target
            and receipt is not None
            and self._library_media_focus_target_matches_receipt(
                focused,
                receipt,
                stable_id,
            )
        )
        return transient_focus_allowed or bool(
            receipt is not None
            and self._library_media_successful_focus_is_allowed(
                receipt,
                stable_id,
            )
        )

    def _library_media_successful_focus_is_allowed(
        self,
        receipt: _LibraryMediaReturnReceipt,
        stable_id: str,
    ) -> bool:
        """Recognize exact-settled focus for this outer arm only."""
        ownership = self._library_media_successful_focus_ownership
        if ownership is None:
            return False
        request = ownership.request
        target = ownership.target
        return bool(
            self._library_pending_list_entry_focus
            and self._library_pending_list_entry_media_return is receipt
            and ownership.outer_generation
            == self._library_list_entry_focus_generation
            and request.receipt is receipt
            and request.request_id <= self._library_media_return_request_id
            and request.focus_intent_generation
            == self._library_notes_focus_intent_generation
            and request.route_identity == self._library_entry_route_key()
            and request.media_view_identity == self._library_media_view == "list"
            and request.final_focus_policy == receipt.final_focus_policy
            and request.final_focus_identity == receipt.final_focus_identity
            and request.receipt.stable_id == stable_id
            and ownership.selected_media_id == self._selected_media_id == stable_id
            and self.focused is target
            and self._library_media_focus_target_matches_receipt(
                target,
                receipt,
                stable_id,
            )
        )

    def _library_media_focus_target_matches_receipt(
        self,
        target: Widget,
        receipt: _LibraryMediaReturnReceipt,
        stable_id: str,
    ) -> bool:
        """Return whether a guarded target satisfies one receipt's policy."""
        if not target.is_attached or self not in target.ancestors:
            return False
        target_is_semantic_row = bool(
            target.has_class("library-media-row")
            and str(getattr(target, "media_id", "") or "") == stable_id
        )
        if receipt.final_focus_policy == "row":
            if target_is_semantic_row:
                return True
            revised = bool(
                receipt.content_signature != self._library_media_content_signature()
                or receipt.layout_signature != self._library_media_layout_signature()
            )
            return revised and bool(
                target.has_class("library-media-row")
                or target.id
                in {
                    "library-media-trash-open",
                    "library-media-type-filter",
                    "library-media-empty-import",
                }
            )
        if (
            receipt.final_focus_policy == "control"
            and receipt.final_focus_identity
            and target.id == receipt.final_focus_identity
        ):
            return True
        responsive_layout_revised = bool(
            receipt.layout_signature != self._library_media_layout_signature()
        )
        return responsive_layout_revised and bool(
            target_is_semantic_row
            or target.id
            in {
                "library-media-trash-open",
                "library-media-type-filter",
                "library-media-empty-import",
            }
        )

    def _arm_library_media_return_settlement(
        self,
        receipt: _LibraryMediaReturnReceipt,
        *,
        consume_latest_geometry: bool = True,
    ) -> _LibraryMediaReturnSettlement | None:
        """Create current-owner authority and optionally consume ready geometry."""
        if (
            not self._library_pending_list_entry_focus
            or self._library_pending_list_entry_media_return is not receipt
            or not self._library_media_return_candidate(receipt)
            or self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view != "list"
            or not self._library_media_live_focus_is_allowed(
                self._library_pending_list_entry_focus_anchor,
                receipt.stable_id,
            )
        ):
            self._library_media_return_settlement = None
            return None
        tree = self._library_media_settlement_tree()
        if tree is None:
            self._library_media_return_settlement = None
            return None
        shell, items_host, owner = tree
        self._adopt_library_media_row_owner(owner)
        if (
            receipt.final_focus_policy == "row"
            and not self._library_media_exact_return_candidate(receipt)
            and not self._library_media_semantic_row_is_current(receipt, items_host)
        ):
            # A revised list that removed the semantic origin uses the
            # established retained-row/recovery focus path. It cannot mint a
            # geometry settlement whose row identity is already gone.
            self._library_media_return_settlement = None
            return None

        current = self._library_media_return_settlement
        if current is not None:
            if self._library_media_request_matches_current_authority(
                current,
                receipt,
                tree,
            ):
                latest = owner.latest_geometry
                if consume_latest_geometry and latest is not None:
                    self._settle_library_media_return_from_geometry(
                        current,
                        owner,
                        latest,
                    )
                return self._library_media_return_settlement
            # A request that lost any non-geometry fence cannot renew itself
            # from the geometry event it was waiting for. Real replacement or
            # presentation seams clear the old request before arming authority
            # for their current tree.
            self._library_media_return_settlement = None
            return None

        last_success = self._library_media_last_successful_settlement
        if (
            last_success is not None
            and self._library_media_request_matches_current_authority(
                last_success[0],
                receipt,
                tree,
            )
            and last_success[2] == self._library_media_content_signature()
            and last_success[3] == self._library_media_layout_signature()
        ):
            return None

        self._library_media_return_request_id += 1
        owner_identity = id(owner)
        floor = (
            self._library_media_geometry_floor
            if self._library_media_geometry_floor_owner_identity == owner_identity
            else 0
        )
        request = _LibraryMediaReturnSettlement(
            request_id=self._library_media_return_request_id,
            receipt=receipt,
            final_focus_policy=receipt.final_focus_policy,
            final_focus_identity=receipt.final_focus_identity,
            focus_intent_generation=self._library_notes_focus_intent_generation,
            compose_generation=self._library_compose_generation,
            media_lifecycle_generation=self._library_media_lifecycle_generation,
            presentation_epoch=self._library_media_presentation_epoch,
            content_signature=self._library_media_content_signature(),
            layout_signature=self._library_media_layout_signature(),
            route_identity=self._library_entry_route_key(),
            media_view_identity=self._library_media_view,
            shell_identity=id(shell),
            items_host_identity=id(items_host),
            owner_identity=owner_identity,
            exclusive_geometry_floor=floor,
            focus_anchor=self._library_pending_list_entry_focus_anchor,
        )
        self._library_media_return_settlement = request
        self._library_media_last_exact_settlement = None
        self._library_media_last_successful_settlement = None
        self._library_media_last_settlement_attempt = None
        self._library_media_last_settlement_outcome = None
        self._bind_library_media_settlement_deadline(request.request_id)
        latest = owner.latest_geometry
        if (
            consume_latest_geometry
            and latest is not None
            and latest.revision > floor
        ):
            self._settle_library_media_return_from_geometry(request, owner, latest)
        return self._library_media_return_settlement

    def _bind_library_media_settlement_deadline(self, request_id: int) -> None:
        """Bind the outer deadline to its Media request and focus generation."""
        deadline = self._library_list_entry_focus_deadline
        if deadline is None or not self._library_pending_list_entry_focus:
            return
        if self._library_list_entry_focus_timer is not None:
            self._library_list_entry_focus_timer.stop()
        remaining = max(0.0, deadline - time.monotonic())
        self._library_list_entry_focus_timer = self.set_timer(
            remaining,
            partial(
                self._expire_library_media_return_settlement,
                request_id,
                self._library_list_entry_focus_generation,
            ),
        )

    def _settle_library_media_return_from_geometry(
        self,
        request: _LibraryMediaReturnSettlement,
        owner: LibraryMediaRowScroll,
        geometry: LibraryMediaRowGeometry,
    ) -> bool:
        """Commit one honest scroll/focus outcome from current-owner geometry."""
        if (
            self._library_media_return_settlement is not request
            or self._library_media_return_settlement.request_id != request.request_id
        ):
            return False
        tree = self._library_media_settlement_tree()
        receipt = self._library_pending_list_entry_media_return
        if (
            tree is None
            or receipt is None
            or tree[2] is not owner
            or not self._library_media_request_matches_current_authority(
                request,
                receipt,
                tree,
            )
            or geometry.revision <= request.exclusive_geometry_floor
            or owner.latest_geometry != geometry
            or (owner.size, owner.virtual_size, owner.container_size)
            != (geometry.size, geometry.virtual_size, geometry.container_size)
        ):
            return False
        last_outcome = self._library_media_last_settlement_outcome
        if (
            last_outcome is not None
            and last_outcome[0] == request.request_id
            and last_outcome[2] == geometry.revision
        ):
            return True
        last_exact = self._library_media_last_exact_settlement
        if (
            last_exact is not None
            and last_exact[0].request_id == request.request_id
            and last_exact[1] >= geometry.revision
        ):
            return True
        desired = request.receipt.scroll_offset
        if desired is None:
            return False
        revised = not self._library_media_exact_return_candidate(request.receipt)
        if not revised and request.receipt.stable_id != self._selected_media_id:
            return False
        if revised:
            desired = (
                min(desired[0], int(owner.max_scroll_x)),
                min(desired[1], int(owner.max_scroll_y)),
            )
            outcome: _LibraryMediaSettlementOutcome = "clamped-after-revision"
        else:
            if (
                desired[0] > int(owner.max_scroll_x)
                or desired[1] > int(owner.max_scroll_y)
            ):
                return False
            outcome = "exact-settled"
        committed = self._commit_library_media_return(
            request,
            owner,
            geometry,
            desired,
            outcome,
        )
        if committed and revised:
            self._disarm_library_list_entry_focus()
        return committed

    def _resolve_library_media_settlement_target(
        self,
        request: _LibraryMediaReturnSettlement,
        items_host: Vertical,
        *,
        revised: bool,
        responsive_layout_revised: bool,
    ) -> tuple[Widget, bool] | None:
        """Resolve final semantic/control focus before settlement mutation."""
        rows = [
            row
            for row in self.query(".library-media-row")
            if row.is_attached and items_host in row.ancestors
        ]
        semantic_row = next(
            (
                row
                for row in rows
                if str(getattr(row, "media_id", "") or "")
                == request.receipt.stable_id
            ),
            None,
        )
        if request.final_focus_policy == "row":
            if semantic_row is not None:
                return semantic_row, False
            if not revised:
                return None
            if rows:
                return rows[0], True

        else:
            control: Widget | None = None
            identity = request.final_focus_identity
            if identity:
                try:
                    candidate = self.query_one(f"#{identity}", Widget)
                except (NoMatches, QueryError):
                    pass
                else:
                    if (
                        candidate.is_attached
                        and self in candidate.ancestors
                        and candidate.display
                        and candidate.can_focus
                        and not bool(getattr(candidate, "disabled", False))
                    ):
                        control = candidate
            if semantic_row is None:
                if not revised:
                    return None
                if rows:
                    return rows[0], True
            elif control is not None:
                return control, False
            if semantic_row is not None and not responsive_layout_revised:
                return None
            if semantic_row is not None:
                return semantic_row, True
        for selector in (
            "#library-media-trash-open",
            "#library-media-type-filter",
            "#library-media-empty-import",
        ):
            try:
                fallback = self.query_one(selector, Widget)
            except (NoMatches, QueryError):
                continue
            if (
                fallback.is_attached
                and fallback.display
                and fallback.can_focus
                and not bool(getattr(fallback, "disabled", False))
            ):
                return fallback, True
        return None

    def _commit_library_media_return(
        self,
        request: _LibraryMediaReturnSettlement,
        owner: LibraryMediaRowScroll,
        geometry: LibraryMediaRowGeometry,
        desired: tuple[int, int],
        outcome: _LibraryMediaSettlementOutcome,
        *,
        allow_reused_geometry: bool = False,
    ) -> bool:
        """Transactionally apply scroll, guarded focus, and terminal outcome."""
        tree = self._library_media_settlement_tree()
        receipt = self._library_pending_list_entry_media_return
        if (
            tree is None
            or receipt is None
            or tree[2] is not owner
            or not self._library_media_request_matches_current_authority(
                request,
                receipt,
                tree,
            )
        ):
            return False
        current_content_signature = self._library_media_content_signature()
        current_layout_signature = self._library_media_layout_signature()
        responsive_layout_revised = bool(
            receipt.layout_signature != current_layout_signature
        )
        revised = bool(
            responsive_layout_revised
            or receipt.content_signature != current_content_signature
        )
        resolved = self._resolve_library_media_settlement_target(
            request,
            tree[1],
            revised=revised,
            responsive_layout_revised=responsive_layout_revised,
        )
        if resolved is None:
            return False
        target, focus_fallback = resolved
        if not self._library_media_live_focus_is_allowed(
            request.focus_anchor,
            receipt.stable_id,
            target,
        ):
            return False
        last_attempt = self._library_media_last_settlement_attempt
        if (
            not allow_reused_geometry
            and last_attempt is not None
            and last_attempt[0] == request.request_id
            and last_attempt[1] >= geometry.revision
        ):
            return False

        pre_scroll = (int(owner.scroll_x), int(owner.scroll_y))
        pre_focus = self.focused
        pre_selected_id = self._selected_media_id
        pre_outcome = self._library_media_last_settlement_outcome
        committed = False
        self._library_media_last_settlement_attempt = (
            request.request_id,
            geometry.revision,
        )
        try:
            owner.scroll_to(
                x=desired[0],
                y=desired[1],
                animate=False,
                force=True,
                immediate=True,
            )
            if (int(owner.scroll_x), int(owner.scroll_y)) == desired and (
                self._library_media_live_focus_is_allowed(
                    request.focus_anchor,
                    request.receipt.stable_id,
                    target,
                )
            ):
                self._library_notes_programmatic_focus_target = target
                self.set_focus(target, scroll_visible=False)
                committed = bool(
                    self.focused is target
                    and (int(owner.scroll_x), int(owner.scroll_y)) == desired
                    and self._selected_media_id == pre_selected_id
                )
                if committed:
                    if (
                        request.final_focus_policy == "control"
                        and focus_fallback
                        and desired == receipt.scroll_offset
                    ):
                        outcome = "exact-scroll-focus-fallback"
                    if outcome in {
                        "exact-settled",
                        "exact-scroll-focus-fallback",
                    }:
                        self._library_media_last_exact_settlement = (
                            request,
                            geometry.revision,
                        )
                    self._library_media_last_settlement_outcome = (
                        request.request_id,
                        outcome,
                        geometry.revision,
                    )
                    self._library_media_last_successful_settlement = (
                        request,
                        geometry.revision,
                        current_content_signature,
                        current_layout_signature,
                    )
                    self._library_media_successful_focus_ownership = (
                        _LibraryMediaSuccessfulFocusOwnership(
                            request=request,
                            outer_generation=self._library_list_entry_focus_generation,
                            selected_media_id=pre_selected_id,
                            target=target,
                        )
                        if outcome == "exact-settled"
                        else None
                    )
                    self._library_media_return_settlement = None
        finally:
            self._library_notes_programmatic_focus_target = None
            if not committed:
                owner.scroll_to(
                    x=pre_scroll[0],
                    y=pre_scroll[1],
                    animate=False,
                    force=True,
                    immediate=True,
                )
                valid_pre_focus = bool(
                    pre_focus is not None
                    and pre_focus.is_attached
                    and self in pre_focus.ancestors
                )
                if self.focused is not pre_focus:
                    self.set_focus(
                        pre_focus if valid_pre_focus else None,
                        scroll_visible=False,
                    )
                self._selected_media_id = pre_selected_id
                self._library_media_last_settlement_outcome = pre_outcome
        if committed:
            # Keep the existing one-event guard for the queued Focus bubble;
            # every failed path leaves it cleared by the finally block above.
            self._library_notes_programmatic_focus_target = target
        return committed

    def _expire_library_media_return_settlement(
        self,
        request_id: int,
        outer_generation: int,
    ) -> None:
        """Finish one ABA-bound outer arm without inferring layout readiness."""
        if (
            request_id != self._library_media_return_request_id
            or outer_generation != self._library_list_entry_focus_generation
        ):
            return
        request = self._library_media_return_settlement
        if request is None:
            self._disarm_library_list_entry_focus()
            return
        if request.request_id != request_id:
            return
        tree = self._library_media_settlement_tree()
        receipt = self._library_pending_list_entry_media_return
        if (
            tree is None
            or receipt is None
            or not self._library_media_request_matches_current_authority(
                request,
                receipt,
                tree,
            )
        ):
            self._disarm_library_list_entry_focus()
            return

        owner = tree[2]
        geometry = owner.latest_geometry
        committed = False
        if (
            geometry is not None
            and geometry.revision > request.exclusive_geometry_floor
            and (owner.size, owner.virtual_size, owner.container_size)
            == (geometry.size, geometry.virtual_size, geometry.container_size)
        ):
            desired = request.receipt.scroll_offset
            if desired is not None:
                committed = self._commit_library_media_return(
                    request,
                    owner,
                    geometry,
                    (
                        min(desired[0], int(owner.max_scroll_x)),
                        min(desired[1], int(owner.max_scroll_y)),
                    ),
                    "clamped-after-settlement-failure",
                    allow_reused_geometry=True,
                )
        if not committed:
            self._library_media_last_settlement_outcome = (
                request.request_id,
                "layout-settlement-failed",
                geometry.revision if geometry is not None else None,
            )
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(
                "Media return layout did not settle before its deadline.",
                severity="warning",
            )
        self._disarm_library_list_entry_focus()

    @on(LibraryMediaRowGeometryChanged)
    def _handle_library_media_row_geometry_changed(
        self,
        event: LibraryMediaRowGeometryChanged,
    ) -> None:
        """Settle only from the current attached Media row-scroll owner."""
        event.stop()
        tree = self._library_media_settlement_tree()
        if tree is None or tree[2] is not event.owner:
            return
        self._adopt_library_media_row_owner(event.owner)
        receipt = self._library_pending_list_entry_media_return
        if not self._library_media_return_candidate(receipt):
            return
        request = self._arm_library_media_return_settlement(
            receipt,
            consume_latest_geometry=False,
        )
        if request is not None:
            self._settle_library_media_return_from_geometry(
                request,
                event.owner,
                event.geometry,
            )

    def _reconcile_library_media_stage_presentation(self) -> bool:
        """Equality-reconcile the mounted Media stage; return whether it changed."""
        try:
            self.query_one("#library-media-reader-shell", LibraryMediaReaderShell)
            shell_grid = self.query_one("#library-shell-grid", Widget)
        except (NoMatches, QueryError):
            return False
        changed = self._project_library_media_stage_classes(shell_grid)
        if changed:
            self.refresh(layout=True)
        return changed

    def _apply_library_notes_stage_legs(self) -> None:
        """Apply compact classes and mutually exclusive mounted stage visibility."""
        if not self.is_mounted:
            return
        try:
            shell = self.query_one("#library-shell-grid", Widget)
            rail = self.query_one("#library-rail", LibraryRail)
            canvas = self.query_one("#library-canvas", Widget)
        except (NoMatches, QueryError):
            return
        rail_handles = self.query("#library-rail-handle")
        rail_handle = rail_handles.first(Widget) if rail_handles else None
        adaptive_reader = bool(
            self.query(
                "#library-media-reader-shell, "
                "#library-collections-reader-shell, "
                "#library-conversations-reader-shell, "
                "#library-notes-reader-shell, "
                "#library-prompts-reader-shell, "
                "#library-skills-reader-shell"
            )
        )
        adaptive_notes = bool(self.query("#library-notes-reader-shell"))
        adaptive_media = bool(self.query("#library-media-reader-shell"))
        # Only the grid and canvas host participate in compact CSS selectors;
        # tagging the rail and inner Notes canvas forced two needless global
        # stylesheet matches on every breakpoint crossing. Apply these before
        # the emergency stage can return so a just-recomposed ordinary route
        # cannot retain wide padding/borders at the narrow stage. Adaptive
        # readers share only the shell box-model contract; their internal pane
        # geometry must not inherit the legacy Notes/Media compact selectors.
        legacy_compact = self._library_notes_compact and (
            not adaptive_reader or adaptive_notes
        )
        compact_widgets = (canvas,) if adaptive_media else (shell, canvas)
        for widget in compact_widgets:
            if widget.has_class("library-notes-compact") != legacy_compact:
                widget.set_class(legacy_compact, "library-notes-compact")
        adaptive_compact = self._library_notes_compact and adaptive_reader
        if adaptive_media:
            # Media's Task 1 projection is the single class writer and the
            # presentation-epoch/floor producer for its adaptive shell.
            self._project_library_media_stage_classes(shell)
        elif shell.has_class("library-adaptive-compact") != adaptive_compact:
            shell.set_class(adaptive_compact, "library-adaptive-compact")
        if self._apply_library_emergency_geometry(
            shell=shell,
            rail=rail,
            canvas=canvas,
            rail_handle=rail_handle,
        ):
            return
        try:
            notes_canvas = canvas.query_one("#library-notes-canvas", LibraryNotesCanvas)
        except (NoMatches, QueryError):
            pass
        else:
            if notes_canvas.compact != self._library_notes_compact:
                notes_canvas.apply_compact_presentation(self._library_notes_compact)
        try:
            notes_work = self.query_one("#library-note-work-pane", LibraryNoteWorkPane)
        except (NoMatches, QueryError):
            pass
        else:
            if notes_work.compact != self._library_notes_compact:
                notes_work.apply_compact_presentation(self._library_notes_compact)
        try:
            media_canvas = canvas.query_one("#library-media-canvas", LibraryMediaCanvas)
        except (NoMatches, QueryError):
            pass
        else:
            if (
                not self.query("#library-media-reader-shell")
                and media_canvas.compact != self._library_notes_compact
            ):
                media_canvas.apply_compact_presentation(self._library_notes_compact)
        if adaptive_reader:
            # The adaptive shell owns pane visibility. The legacy compact
            # stage toggles below predate the permanent reader work panes and
            # would hide retained siblings or move focus to an unrelated
            # legacy handle.
            self._sync_library_ordinary_rail_width_contract()
            return
        compact_single_stage = (
            self._library_notes_compact and self._library_notes_compact_stage_applies()
        )
        wide_focused_task = (
            not self._library_notes_compact
            and self._library_notes_focused_task_active()
        )
        single_stage = compact_single_stage or wide_focused_task
        manually_collapsed = self._library_rail_collapsed and not single_stage
        rail_display = (
            False
            if wide_focused_task
            else (not compact_single_stage or self._library_notes_stage == "rail")
            and not manually_collapsed
        )
        canvas_display = (
            True
            if wide_focused_task
            else (not compact_single_stage or self._library_notes_stage == "notes")
        )
        handle_display = manually_collapsed
        if rail_handle is not None and rail_handle.display != handle_display:
            rail_handle.display = handle_display
        if rail.display != rail_display:
            rail.display = rail_display
        if canvas.display != canvas_display:
            canvas.display = canvas_display
        try:
            collapse = rail.query_one("#library-rail-collapse", Button)
        except (NoMatches, QueryError):
            pass
        else:
            collapse.display = not single_stage
        for selector in (
            "#library-notes-source-database",
            "#library-notes-source-separator",
            "#library-notes-source-files",
        ):
            try:
                source_control = self.query_one(selector, Widget)
            except (NoMatches, QueryError):
                continue
            source_control.display = not wide_focused_task
        try:
            task_return = self.query_one("#library-notes-task-return", Button)
        except (NoMatches, QueryError):
            pass
        else:
            task_return.display = wide_focused_task
        try:
            note_back = self.query_one("#library-note-back", Button)
        except (NoMatches, QueryError):
            pass
        else:
            note_back.display = not wide_focused_task
        self._sync_library_ordinary_rail_width_contract()

    def _hide_library_adaptive_reader_rail_collapse(self) -> None:
        """Hide the rail's legacy collapse control beside adaptive grips."""
        matches = self.query("#library-rail-collapse")
        if matches:
            matches.first().display = False

    def _library_adaptive_reader_allocation_is_current(self, reader: Widget) -> bool:
        """Reject transient reader and compact-box allocations during resize."""
        try:
            shell = self.query_one("#library-shell-grid", Widget)
        except (NoMatches, QueryError):
            return False
        compact_box_model = shell.content_region.width == shell.region.width
        expected_compact_box_model = (
            shell.region.width < LIBRARY_NOTES_COMPACT_BREAKPOINT
        )
        return bool(
            reader.region.width > 0
            and reader.region.width == shell.content_region.width
            and compact_box_model is expected_compact_box_model
        )

    def _sync_library_ordinary_rail_width_contract(self) -> None:
        """Apply the settled ordinary rail contract at the existing UI seams."""
        if self.query(
            "#library-media-reader-shell, "
            "#library-collections-reader-shell, "
            "#library-conversations-reader-shell, "
            "#library-notes-reader-shell, "
            "#library-prompts-reader-shell, "
            "#library-skills-reader-shell"
        ):
            return
        try:
            shell = self.query_one("#library-shell-grid", Widget)
            rail = self.query_one("#library-rail", LibraryRail)
            canvas = self.query_one("#library-canvas", Widget)
        except (NoMatches, QueryError):
            return
        width = shell.content_region.width
        if width < LIBRARY_EMERGENCY_WIDTH:
            return
        if not rail.display:
            presentation = OrdinaryRailPresentation.HIDDEN
        elif not canvas.display:
            presentation = OrdinaryRailPresentation.RAIL_ONLY
        else:
            presentation = OrdinaryRailPresentation.ALONGSIDE
        shared = self._library_reader_shared_preferences
        contract = resolve_ordinary_rail_contract(
            width,
            presentation,
            shared.custom_widths_enabled,
            shared.library_width,
        )
        rail.apply_ordinary_width_contract(contract)

    def _load_library_reader_preference_snapshot(
        self,
    ) -> tuple[
        AdaptiveReaderLayoutPreferences,
        MediaReaderLayoutPreferences,
        AdaptiveReaderLayoutPreferences,
        AdaptiveReaderLayoutPreferences,
        AdaptiveReaderLayoutPreferences,
        AdaptiveReaderLayoutPreferences,
        AdaptiveReaderLayoutPreferences,
        AdaptiveReaderLayoutPreferences,
    ]:
        """Normalize one shared reader snapshot plus destination Items choices."""
        app_config = getattr(self.app_instance, "app_config", None)
        library_config: Mapping[str, Any] = {}
        if isinstance(app_config, Mapping):
            candidate = app_config.get("library")
            if isinstance(candidate, Mapping):
                library_config = candidate

        reader = library_config.get("reader")
        shared_raw = dict(reader) if isinstance(reader, Mapping) else {}
        legacy_media = library_config.get("media_reader")
        if isinstance(legacy_media, Mapping) and "library_open" not in shared_raw:
            shared_raw["library_open"] = legacy_media.get("library_open")
        shared = normalize_adaptive_reader_preferences(shared_raw)

        def destination_preferences(
            section: str,
        ) -> AdaptiveReaderLayoutPreferences:
            destination = library_config.get(section)
            raw = dict(shared_raw)
            if isinstance(destination, Mapping):
                raw.update(destination)
            normalized = normalize_adaptive_reader_preferences(raw)
            return dataclasses.replace(
                normalized,
                library_open=shared.library_open,
                custom_widths_enabled=shared.custom_widths_enabled,
                library_width=shared.library_width,
            )

        file_notes_raw = dict(shared_raw)
        notes_reader = library_config.get("notes_reader")
        if isinstance(notes_reader, Mapping):
            if "files_tree_open" in notes_reader:
                file_notes_raw["items_open"] = notes_reader["files_tree_open"]
            if "files_tree_width" in notes_reader:
                file_notes_raw["items_width"] = notes_reader["files_tree_width"]
        file_notes = normalize_adaptive_reader_preferences(file_notes_raw)
        file_notes = dataclasses.replace(
            file_notes,
            library_open=shared.library_open,
            custom_widths_enabled=shared.custom_widths_enabled,
            library_width=shared.library_width,
        )

        return (
            shared,
            destination_preferences("media_reader"),
            destination_preferences("collections_reader"),
            destination_preferences("conversations_reader"),
            destination_preferences("notes_reader"),
            file_notes,
            destination_preferences("prompts_reader"),
            destination_preferences("skills_reader"),
        )

    def _library_notes_work_session_reader_width(self) -> int | None:
        """Return the settled reader width for the active Notes authority."""
        try:
            if self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES:
                workspace = self._library_file_notes_workspace
                if workspace is None or not workspace.is_mounted:
                    return None
                shell = workspace.query_one(
                    "#library-file-notes-reader-shell",
                    LibraryAdaptiveReaderShell,
                )
            else:
                shell = self.query_one(
                    "#library-notes-reader-shell",
                    LibraryAdaptiveReaderShell,
                )
        except (NoMatches, QueryError):
            return None
        return shell.region.width if shell.region.width > 0 else None

    def _dispatch_library_notes_work_session(
        self,
        event: NotesWorkSessionEvent,
        *,
        reader_width: int | None = None,
        sync_layout: bool = True,
    ) -> bool:
        """Apply one named transient Notes lifecycle event."""
        if event in {
            NotesWorkSessionEvent.DATABASE_IDENTITY_CLEARED,
            NotesWorkSessionEvent.FOLDER_IDENTITY_CLEARED,
            NotesWorkSessionEvent.AUTHORITY_CHANGED,
            NotesWorkSessionEvent.FOLDER_ROOT_CHANGED,
            NotesWorkSessionEvent.LEFT_NOTES,
        }:
            self._library_notes_work_session_activation_pending = False
        phase = reduce_notes_work_session(
            self._library_notes_work_session_phase,
            event,
            reader_width=(
                self._library_notes_work_session_reader_width()
                if reader_width is None
                and event is NotesWorkSessionEvent.EDITABLE_ITEM_OPENED
                else reader_width
            ),
        )
        if phase is self._library_notes_work_session_phase:
            return False
        self._library_notes_work_session_phase = phase
        if sync_layout:
            if self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES:
                self._sync_library_file_notes_reader_layout_from_shell()
            else:
                self._sync_library_notes_reader_layout_from_shell()
        return True

    def _library_notes_work_first_preferences(
        self,
        preferences: AdaptiveReaderLayoutPreferences,
    ) -> AdaptiveReaderLayoutPreferences:
        """Derive the Library-only work-first override."""
        if self._library_notes_work_session_phase is NotesWorkSessionPhase.ACTIVE:
            return dataclasses.replace(preferences, library_open=False)
        return preferences

    def _set_library_notes_source(
        self,
        source: Literal["database", "files"],
    ) -> bool:
        """Set one admitted Notes authority and reset only on a real change."""
        if source == self._library_notes_source:
            return False
        self._library_notes_source = source
        self._dispatch_library_notes_work_session(
            NotesWorkSessionEvent.AUTHORITY_CHANGED,
            sync_layout=False,
        )
        return True

    def _dispatch_database_note_identity_cleared(self) -> bool:
        """Reset only when a Database selected/loaded identity is cleared."""
        if not self._selected_note_id and self._library_note_session.snapshot is None:
            return False
        return self._dispatch_library_notes_work_session(
            NotesWorkSessionEvent.DATABASE_IDENTITY_CLEARED
        )

    def _activate_database_note_work_session(self, note_id: str) -> None:
        """Activate after the admitted editor has settled its real shell width."""
        if (
            not self._library_notes_work_session_activation_pending
            or self._library_notes_source != LIBRARY_NOTES_SOURCE_DATABASE
            or self._library_notes_view != "editor"
            or self._selected_note_id != note_id
            or self._library_note_session.snapshot is None
        ):
            return
        reader_width = self._library_notes_work_session_reader_width()
        if reader_width is None:
            return
        self._library_notes_work_session_activation_pending = False
        self._dispatch_library_notes_work_session(
            NotesWorkSessionEvent.EDITABLE_ITEM_OPENED,
            reader_width=reader_width,
        )

