    def _replace_library_reader_preference(
        self,
        destination: LibraryReaderDestination,
        key: Literal["library_open", "items_open"],
        value: bool,
    ) -> None:
        """Replace one pane choice, sharing only the Library-pane preference."""
        attributes = {
            "media": "_library_media_reader_preferences",
            "collections": "_library_collections_reader_preferences",
            "conversations": "_library_conversation_reader_preferences",
            "notes": "_library_notes_reader_preferences",
            "notes_files": "_library_file_notes_reader_preferences",
            "prompts": "_library_prompts_reader_preferences",
            "skills": "_library_skills_reader_preferences",
        }
        attribute = attributes[destination]
        preferences = getattr(self, attribute)
        setattr(self, attribute, dataclasses.replace(preferences, **{key: value}))
        if key != "library_open":
            return
        for other_attribute in attributes.values():
            if other_attribute == attribute:
                continue
            other = getattr(self, other_attribute)
            setattr(
                self,
                other_attribute,
                dataclasses.replace(other, library_open=value),
            )

    @staticmethod
    def _library_reader_persistence_key(
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
    ) -> str:
        if pane == "library":
            return "library"
        return (
            "notes_file_items"
            if destination == "notes_files"
            else f"{destination}_items"
        )

    def _claim_library_reader_persistence(
        self,
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
    ) -> int:
        """Claim the shared Library or destination-specific Items authority."""
        key = self._library_reader_persistence_key(destination, pane)
        generation = self._library_reader_persistence_generations[key] + 1
        self._library_reader_persistence_generations[key] = generation
        self._library_reader_dirty_persistence_authorities.add(key)
        return generation

    def _library_reader_persistence_is_current(
        self,
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
        generation: int,
    ) -> bool:
        key = self._library_reader_persistence_key(destination, pane)
        return self._library_reader_persistence_generations[key] == generation

    def _sync_library_reader_preference_layout(
        self,
        destination: LibraryReaderDestination,
        key: Literal["library_open", "items_open"],
        priority: Literal["library", "items"] | None = None,
        *,
        manual_reopen: PaneName | None = None,
        automatic_priority: bool = True,
    ) -> None:
        """Sync the mounted consumer of one optimistic choice or rollback."""
        if key == "library_open" or destination == "media":
            self._sync_library_media_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "collections":
            self._sync_library_collections_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "conversations":
            self._sync_library_conversation_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "notes":
            self._sync_library_notes_reader_layout_from_shell(
                priority,
                manual_reopen=manual_reopen,
            )
        if key == "library_open" or destination == "notes_files":
            self._sync_library_file_notes_reader_layout_from_shell(
                priority,
                manual_reopen=manual_reopen,
                automatic_priority=automatic_priority,
            )
        if key == "library_open" or destination == "prompts":
            self._sync_library_prompts_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "skills":
            self._sync_library_skills_reader_layout_from_shell(priority)

    async def _read_library_reader_persisted_preference(
        self,
        section: str,
        key: str,
    ) -> bool | None:
        """Read one effective pane value from the authoritative config boundary."""
        try:
            serialized = await asyncio.to_thread(read_cli_config_serialized)
            values = tomllib.loads(serialized)
            if section == "library.reader" and key == "library_open":
                library = values.get("library", {})
                if not isinstance(library, Mapping):
                    raise KeyError("library")
                reader = library.get("reader", {})
                legacy = library.get("media_reader", {})
                if isinstance(reader, Mapping) and key in reader:
                    raw_value = reader.get(key)
                elif isinstance(legacy, Mapping):
                    raw_value = legacy.get(key)
                else:
                    raw_value = None
            else:
                value: object = values
                for part in section.split("."):
                    if not isinstance(value, Mapping):
                        raise KeyError(part)
                    value = value.get(part, {})
                if not isinstance(value, Mapping):
                    raise KeyError(key)
                raw_value = value.get(key)
            logical_key = "library_open" if key == "library_open" else "items_open"
            return getattr(
                normalize_adaptive_reader_preferences({logical_key: raw_value}),
                logical_key,
            )
        except Exception:
            logger.warning("Library reader persisted pane value could not be verified.")
            return None

    async def _persist_library_reader_preference(
        self,
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
        value: bool,
        generation: int,
        verify_failure_from_config: bool = False,
    ) -> None:
        """Persist one grip choice and reconcile writes superseded in flight."""
        key: Literal["library_open", "items_open"] = (
            "library_open" if pane == "library" else "items_open"
        )
        authority = self._library_reader_persistence_key(destination, pane)
        preferences_attribute = {
            "media": "_library_media_reader_preferences",
            "collections": "_library_collections_reader_preferences",
            "conversations": "_library_conversation_reader_preferences",
            "notes": "_library_notes_reader_preferences",
            "notes_files": "_library_file_notes_reader_preferences",
            "prompts": "_library_prompts_reader_preferences",
            "skills": "_library_skills_reader_preferences",
        }[destination]
        locks = {
            "media": self._library_media_reader_persistence_locks,
            "collections": self._library_collections_reader_persistence_locks,
            "conversations": self._library_conversation_reader_persistence_locks,
            "notes": self._library_notes_reader_persistence_locks,
            "notes_files": self._library_file_notes_reader_persistence_locks,
            "prompts": self._library_prompts_reader_persistence_locks,
            "skills": self._library_skills_reader_persistence_locks,
        }[destination]
        section = (
            "library.reader"
            if pane == "library"
            else (
                "library.notes_reader"
                if destination == "notes_files"
                else f"library.{destination}_reader"
            )
        )
        config_key = (
            "library_open"
            if pane == "library"
            else "files_tree_open"
            if destination == "notes_files"
            else "items_open"
        )
        mirror = {
            "media": self._mirror_library_media_reader_preference,
            "collections": self._mirror_library_collections_reader_preference,
            "conversations": self._mirror_library_conversation_reader_preference,
            "notes": self._mirror_library_notes_reader_preference,
            "notes_files": self._mirror_library_file_notes_reader_preference,
            "prompts": self._mirror_library_prompts_reader_preference,
            "skills": self._mirror_library_skills_reader_preference,
        }[destination]
        attempted_generation = generation
        attempted_value = value
        verified_physical_value = False
        async with locks[pane]:
            if (
                not self._library_reader_persistence_is_current(
                    destination, pane, attempted_generation
                )
                or getattr(getattr(self, preferences_attribute), key) != attempted_value
            ):
                return
            while True:
                if (
                    self._library_reader_durable_generations[authority]
                    == attempted_generation
                    and self._library_reader_durable_preferences[authority]
                    == attempted_value
                ):
                    return
                try:
                    persisted = await asyncio.to_thread(
                        save_setting_to_cli_config,
                        section,
                        config_key,
                        attempted_value,
                    )
                except Exception:
                    persisted = False
                if persisted is True:
                    self._library_reader_durable_preferences[authority] = (
                        attempted_value
                    )
                    self._library_reader_durable_generations[authority] = (
                        attempted_generation
                    )

                current_generation = self._library_reader_persistence_generations[
                    authority
                ]
                current_value = getattr(getattr(self, preferences_attribute), key)
                if persisted is True:
                    if (
                        attempted_generation == current_generation
                        and attempted_value == current_value
                    ):
                        app_config = getattr(self.app_instance, "app_config", None)
                        library_config = (
                            app_config.get("library", {})
                            if isinstance(app_config, Mapping)
                            else {}
                        )
                        section_name = (
                            "reader"
                            if pane == "library"
                            else "notes_reader"
                            if destination == "notes_files"
                            else f"{destination}_reader"
                        )
                        section_config = (
                            library_config.get(section_name, {})
                            if isinstance(library_config, Mapping)
                            else {}
                        )
                        if (
                            isinstance(section_config, Mapping)
                            and section_config.get(config_key) is attempted_value
                        ):
                            self._library_reader_dirty_persistence_authorities.discard(
                                authority
                            )
                        return
                    attempted_generation = current_generation
                    attempted_value = current_value
                    continue
                if verify_failure_from_config:
                    physical_value = (
                        await self._read_library_reader_persisted_preference(
                            section, config_key
                        )
                    )
                    current_generation = self._library_reader_persistence_generations[
                        authority
                    ]
                    current_value = getattr(getattr(self, preferences_attribute), key)
                    if (
                        attempted_generation != current_generation
                        or attempted_value != current_value
                    ):
                        return
                    if physical_value is None:
                        notify = getattr(self.app_instance, "notify", None)
                        if callable(notify):
                            notify(
                                "Library reader layout could not be verified from configuration; the current pane choice was kept.",
                                severity="warning",
                            )
                        return
                    self._library_reader_durable_preferences[authority] = physical_value
                    self._library_reader_durable_generations[authority] = (
                        attempted_generation
                    )
                    if physical_value == current_value:
                        self._library_reader_dirty_persistence_authorities.discard(
                            authority
                        )
                        return
                    verified_physical_value = True
                    break
                if (
                    attempted_generation != current_generation
                    or attempted_value != current_value
                ):
                    return
                break

        durable_value = self._library_reader_durable_preferences[authority]
        self._replace_library_reader_preference(destination, key, durable_value)
        mirror(key, durable_value)
        self._sync_library_reader_preference_layout(destination, key)
        if (
            verified_physical_value
            and self._library_reader_persistence_generations[authority]
            == attempted_generation
        ):
            self._library_reader_dirty_persistence_authorities.discard(authority)
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(
                "Library reader layout could not be saved; the previous pane choice was restored.",
                severity="warning",
            )

    def _sync_library_media_reader_layout_from_shell(
        self,
        priority: Literal["library", "items"] | None = None,
        focus_intent: tuple[Widget, int] | None = None,
    ) -> None:
        """Resolve the settled Media shell width and patch geometry in place."""
        try:
            shell = self.query_one(
                "#library-media-reader-shell", LibraryMediaReaderShell
            )
        except (NoMatches, QueryError):
            return
        width = shell.region.width
        if not self._library_adaptive_reader_allocation_is_current(shell):
            return
        if (
            priority is None
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._library_media_view == "trash"
            and self._library_media_reader_preferences.items_open
            and not (
                self._library_media_reader_layout.priority_pane == "library"
                and self._library_media_reader_preferences.library_open
            )
        ):
            # Trash is an Items surface. At the compact allocation the reader
            # otherwise consumes every cell after a screen recompose, even
            # though the user's Items preference remains open. Reassert that
            # existing preference as layout priority. A still-requested,
            # explicitly prioritized Library pane wins until it is collapsed;
            # an explicit Items close flips that preference first too.
            priority = "items"
        previous = self._library_media_reader_layout
        # ``__init__`` resolves a zero-width sentinel before Textual has
        # assigned the mounted shell its first real region. Treating that
        # sentinel as a genuine previous layout lets hysteresis preserve its
        # necessarily-collapsed panes at borderline usable widths forever.
        # The first settled measurement has no user-visible prior layout, so
        # resolve it without hysteresis; subsequent measurements keep the
        # normal anti-flap behavior.
        if (
            previous.reader_width == 0
            and previous.library_width == 0
            and previous.items_width == 0
        ):
            previous = None
        layout = resolve_media_reader_layout(
            width,
            self._library_media_reader_preferences,
            previous=previous,
            priority=priority,
        )
        layout_changed = layout != self._library_media_reader_layout
        focused = self.focused
        if focus_intent is not None and (
            focus_intent[1] == self._library_notes_focus_intent_generation
            or self._library_notes_resize_settling
        ):
            focused = focus_intent[0]
        hidden_focus_target: tuple[Widget, Widget] | None = None
        for now_open, pane, grip in (
            (
                layout.library_open,
                shell.library,
                shell.library_grip,
            ),
            (
                layout.items_open,
                shell.items,
                shell.items_grip,
            ),
        ):
            if (
                not now_open
                and focused is not None
                and (focused is pane or pane in focused.ancestors)
            ):
                hidden_focus_target = (focused, grip)
                break
        generation = self._library_notes_focus_intent_generation
        if layout_changed:
            tree = self._library_media_settlement_tree()
            self._advance_library_media_presentation_epoch(
                tree[2] if tree is not None else None,
                rearm=False,
            )
        shell.sync_layout(layout)
        self._library_media_reader_layout = layout
        if layout_changed:
            receipt = self._library_pending_list_entry_media_return
            if self._library_media_return_candidate(receipt):
                self._arm_library_media_return_settlement(receipt)
        if hidden_focus_target is not None:
            self._focus_library_media_grip_if_current(
                generation,
                *hidden_focus_target,
            )
        elif (
            layout.items_open
            and self._library_pending_list_entry_focus
            and not self._library_media_return_candidate(
                self._library_pending_list_entry_media_return
            )
            and (
                self._library_pending_list_entry_media_return is not None
                or focused is None
                or not focused.has_class("library-media-row")
            )
        ):
            # Reapply only when focus has not already landed on a Media row,
            # and cross one refresh so the Items host has final geometry.
            self.call_after_refresh(
                self._focus_library_list_entry_if_current,
                self._library_list_entry_focus_generation,
            )

    def _mirror_library_media_reader_preference(
        self,
        key: Literal["library_open", "items_open"],
        value: bool,
    ) -> None:
        """Mirror an optimistic manual pane choice into the live app config."""
        app_config = getattr(self.app_instance, "app_config", None)
        if not isinstance(app_config, dict):
            return
        library_config = app_config.get("library")
        if not isinstance(library_config, dict):
            library_config = {}
            app_config["library"] = library_config
        section_name = "reader" if key == "library_open" else "media_reader"
        section = library_config.get(section_name)
        if not isinstance(section, dict):
            section = {}
            library_config[section_name] = section
        section[key] = value

    def request_library_reader_layout_refresh(self, generation: int) -> None:
        """Apply newer Library reader settings without reloading destination data."""
        if generation <= self._library_reader_layout_refresh_generation:
            return
        locally_persisted = {
            authority: authority in self._library_reader_dirty_persistence_authorities
            for authority in self._library_reader_persistence_generations
        }
        previous_persistence_generations = dict(
            self._library_reader_persistence_generations
        )
        previous_durable_generations = dict(self._library_reader_durable_generations)
        previous_durable_values = dict(self._library_reader_durable_preferences)
        self._library_reader_layout_refresh_generation = generation
        self._library_media_layout_refresh_generation = generation
        for authority in self._library_reader_persistence_generations:
            self._library_reader_persistence_generations[authority] += 1
        (
            self._library_reader_shared_preferences,
            self._library_media_reader_preferences,
            self._library_collections_reader_preferences,
            self._library_conversation_reader_preferences,
            self._library_notes_reader_preferences,
            self._library_file_notes_reader_preferences,
            self._library_prompts_reader_preferences,
            self._library_skills_reader_preferences,
        ) = self._load_library_reader_preference_snapshot()
        current_values = {
            "library": self._library_reader_shared_preferences.library_open,
            "collections_items": self._library_collections_reader_preferences.items_open,
            "conversations_items": self._library_conversation_reader_preferences.items_open,
            "media_items": self._library_media_reader_preferences.items_open,
            "notes_items": self._library_notes_reader_preferences.items_open,
            "notes_file_items": self._library_file_notes_reader_preferences.items_open,
            "prompts_items": self._library_prompts_reader_preferences.items_open,
            "skills_items": self._library_skills_reader_preferences.items_open,
        }
        persistence_authorities: tuple[
            tuple[
                LibraryReaderDestination,
                str,
                str,
            ],
            ...,
        ] = (
            ("media", "library", "library"),
            ("media", "items", "media_items"),
            ("collections", "items", "collections_items"),
            ("conversations", "items", "conversations_items"),
            ("notes", "items", "notes_items"),
            ("notes_files", "items", "notes_file_items"),
            ("prompts", "items", "prompts_items"),
            ("skills", "items", "skills_items"),
        )
        repair_authorities = {
            authority
            for authority in current_values
            if locally_persisted[authority]
            and (
                previous_durable_generations[authority]
                != previous_persistence_generations[authority]
                or previous_durable_values[authority] != current_values[authority]
            )
        }
        for authority, value in current_values.items():
            if authority not in repair_authorities:
                self._library_reader_durable_preferences[authority] = value
                self._library_reader_durable_generations[authority] = (
                    self._library_reader_persistence_generations[authority]
                )
        self._sync_library_media_reader_layout_from_shell()
        self._sync_library_collections_reader_layout_from_shell()
        self._sync_library_conversation_reader_layout_from_shell()
        self._sync_library_notes_reader_layout_from_shell()
        self._sync_library_file_notes_reader_layout_from_shell()
        self._sync_library_prompts_reader_layout_from_shell()
        self._sync_library_skills_reader_layout_from_shell()
        self._sync_library_ordinary_rail_width_contract()
        for destination, pane, authority in persistence_authorities:
            if authority not in repair_authorities:
                continue
            self.run_worker(
                self._persist_library_reader_preference(
                    destination,
                    pane,
                    current_values[authority],
                    self._library_reader_persistence_generations[authority],
                    verify_failure_from_config=True,
                ),
                group=f"library_reader_{authority}_settings_persistence",
            )
        self._library_reader_dirty_persistence_authorities.difference_update(
            authority
            for authority, dirty in locally_persisted.items()
            if dirty and authority not in repair_authorities
        )

    def request_library_media_layout_refresh(self, generation: int) -> None:
        """Compatibility alias for callers using the former Media-specific name."""
        self.request_library_reader_layout_refresh(generation)

    def _focus_library_media_grip_if_current(
        self,
        generation: int,
        hidden_focus: Widget,
        grip: Widget,
    ) -> None:
        """Move focus only when no newer user focus intent superseded resize."""
        if (
            generation != self._library_notes_focus_intent_generation
            and not self._library_notes_resize_settling
        ):
            return
        focused = self.focused
        if focused is hidden_focus or focused is None or not focused.display:
            self.set_focus(grip, scroll_visible=False)

    @on(PaneToggleRequested)
    def _toggle_library_media_reader_pane(self, event: PaneToggleRequested) -> None:
        """Apply and persist one manual preferred pane choice."""
        event.stop()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            layout = self._library_collections_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key: Literal["library_open", "items_open"] = (
                "library_open" if event.pane == "library" else "items_open"
            )
            generation = self._claim_library_reader_persistence(
                "collections", event.pane
            )
            self._replace_library_reader_preference("collections", key, opening)
            self._mirror_library_collections_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "collections", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "collections", event.pane, opening, generation
                ),
                group=f"library_collections_reader_{event.pane}_persistence",
            )
            return
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            layout = self._library_conversation_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key: Literal["library_open", "items_open"] = (
                "library_open" if event.pane == "library" else "items_open"
            )
            generation = self._claim_library_reader_persistence(
                "conversations", event.pane
            )
            self._replace_library_reader_preference("conversations", key, opening)
            self._mirror_library_conversation_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "conversations", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "conversations", event.pane, opening, generation
                ),
                group=f"library_conversation_reader_{event.pane}_persistence",
            )
            return
        if (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES
        ):
            layout = self._library_file_notes_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            if (
                event.pane == "library"
                and opening
                and self._library_notes_work_session_phase
                is NotesWorkSessionPhase.ACTIVE
            ):
                self._dispatch_library_notes_work_session(
                    NotesWorkSessionEvent.MANUAL_LIBRARY_EXPAND,
                    sync_layout=False,
                )
                if self._library_file_notes_reader_preferences.library_open:
                    self._sync_library_reader_preference_layout(
                        "notes_files",
                        key,
                        "library",
                        manual_reopen="library",
                        automatic_priority=False,
                    )
                    return
            generation = self._claim_library_reader_persistence(
                "notes_files", event.pane
            )
            self._replace_library_reader_preference("notes_files", key, opening)
            self._mirror_library_file_notes_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "notes_files",
                key,
                event.pane if opening else None,
                manual_reopen=event.pane if opening else None,
                automatic_priority=False,
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "notes_files", event.pane, opening, generation
                ),
                group=f"library_file_notes_reader_{event.pane}_persistence",
            )
            return
        if (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            layout = self._library_notes_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            if (
                event.pane == "library"
                and opening
                and self._library_notes_work_session_phase
                is NotesWorkSessionPhase.ACTIVE
            ):
                self._dispatch_library_notes_work_session(
                    NotesWorkSessionEvent.MANUAL_LIBRARY_EXPAND,
                    sync_layout=False,
                )
                if self._library_notes_reader_preferences.library_open:
                    self._sync_library_reader_preference_layout(
                        "notes",
                        key,
                        "library",
                        manual_reopen="library",
                    )
                    return
            generation = self._claim_library_reader_persistence("notes", event.pane)
            self._replace_library_reader_preference("notes", key, opening)
            self._mirror_library_notes_reader_preference(key, opening)
            if (
                event.pane == "library"
                and not opening
                and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
                and self._library_notes_view == "list"
            ):
                # At the narrow widths where opening Library necessarily
                # evicts Items, closing it must return the reclaimed cells to
                # the title navigator rather than leaving only Work visible.
                self._sync_library_notes_reader_layout_from_shell(
                    (
                        "items"
                        if self._library_notes_reader_preferences.items_open
                        else None
                    ),
                    ignore_previous=True,
                )
            else:
                self._sync_library_reader_preference_layout(
                    "notes",
                    key,
                    event.pane if opening else None,
                    manual_reopen=event.pane if opening else None,
                )
            self.run_worker(
                self._persist_library_reader_preference(
                    "notes", event.pane, opening, generation
                ),
                group=f"library_notes_reader_{event.pane}_persistence",
            )
            return
        if self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_CREATE_PROMPT,
        }:
            layout = self._library_prompts_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            generation = self._claim_library_reader_persistence("prompts", event.pane)
            self._replace_library_reader_preference("prompts", key, opening)
            self._mirror_library_prompts_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "prompts", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "prompts", event.pane, opening, generation
                ),
                group=f"library_prompts_reader_{event.pane}_persistence",
            )
            return
        if self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_CREATE_SKILL,
        }:
            layout = self._library_skills_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            generation = self._claim_library_reader_persistence("skills", event.pane)
            self._replace_library_reader_preference("skills", key, opening)
            self._mirror_library_skills_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "skills", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "skills", event.pane, opening, generation
                ),
                group=f"library_skills_reader_{event.pane}_persistence",
            )
            return
        layout = self._library_media_reader_layout
        opening = not (
            layout.library_open if event.pane == "library" else layout.items_open
        )
        key: Literal["library_open", "items_open"] = (
            "library_open" if event.pane == "library" else "items_open"
        )
        generation = self._claim_library_reader_persistence("media", event.pane)
        self._replace_library_reader_preference("media", key, opening)
        self._mirror_library_media_reader_preference(key, opening)
        self._sync_library_reader_preference_layout(
            "media", key, event.pane if opening else None
        )
        self.run_worker(
            self._persist_library_reader_preference(
                "media",
                event.pane,
                opening,
                generation,
            ),
            group=f"library_media_reader_{event.pane}_persistence",
        )

    @on(AdaptiveReaderShellResized)
    def _resize_library_adaptive_reader_shell(
        self,
        event: AdaptiveReaderShellResized,
    ) -> None:
        """Resolve one mounted shared shell through its destination authority."""
        event.stop()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            self._sync_library_collections_reader_layout_from_shell()
        elif self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            self._sync_library_conversation_reader_layout_from_shell()
        elif (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES
        ):
            self._sync_library_file_notes_reader_layout_from_shell()
        elif self._library_selected_row_id in (
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_CREATE_NOTE,
        ):
            self._sync_library_notes_reader_layout_from_shell()
            if self._library_notes_work_session_activation_pending:
                self._activate_database_note_work_session(self._selected_note_id)

    @on(MediaShellResized)
    def _resize_library_media_reader_shell(self, event: MediaShellResized) -> None:
        """Resolve a mounted shell after Textual assigns its real width."""
        event.stop()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            self._sync_library_conversation_reader_layout_from_shell()
        elif (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            self._sync_library_notes_reader_layout_from_shell()
        elif self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_CREATE_PROMPT,
        }:
            self._sync_library_prompts_reader_layout_from_shell()
        elif self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_CREATE_SKILL,
        }:
            self._sync_library_skills_reader_layout_from_shell()
        else:
            self._reconcile_library_media_stage_presentation()
            self._sync_library_media_reader_layout_from_shell()
            receipt = self._library_pending_list_entry_media_return
            if self._library_media_return_candidate(receipt):
                # Shell lifecycle establishes the replacement identity fences;
                # only owner Resize geometry may complete the request.
                self._arm_library_media_return_settlement(receipt)

    def _sync_library_ingest_rail_for_width(self, width: int) -> None:
        """Auto-collapse the rail only while narrow Ingest needs the space."""
        # The grid carries a wide min-width and can report its virtual width
        # while overflowing an 80-column terminal. The user experiences the
        # screen viewport, so use the smaller real allocation for this gate.
        viewport_width = self.size.width if self.is_mounted else 0
        if viewport_width > 0:
            width = min(width, viewport_width)
        ingest_active = self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA
        should_collapse = (
            ingest_active and width < LIBRARY_INGEST_RAIL_COLLAPSE_BREAKPOINT
        )
        if should_collapse and not self._library_rail_collapsed:
            self._library_rail_collapsed = True
            self._library_ingest_auto_collapsed_rail = True
            self._apply_library_notes_stage_visibility()
        elif self._library_ingest_auto_collapsed_rail and (
            not ingest_active or not should_collapse
        ):
            self._library_rail_collapsed = False
            self._library_ingest_auto_collapsed_rail = False
            self._apply_library_notes_stage_visibility()

    def _sync_library_ingest_rail_from_shell(self) -> None:
        """Measure the settled shell, then apply the Ingest rail policy."""
        try:
            width = self.query_one("#library-shell-grid").region.width
        except (NoMatches, QueryError):
            return
        if width > 0:
            self._sync_library_ingest_rail_for_width(width)

    def _transition_library_notes_presentation(
        self,
        compact: bool,
        identity: LibraryNotesFocusIdentity,
    ) -> None:
        """Cross the one measured compact/wide boundary losslessly."""
        landing_prefix = "landing-control:"
        if (
            compact
            and self._library_notes_compact_stage_applies()
            and identity.semantic_role.startswith(landing_prefix)
        ):
            control_id = identity.semantic_role.removeprefix(landing_prefix)
            row_id = self._library_landing_control_row_id(control_id)
            if row_id:
                self._library_landing_responsive_focus_id = control_id
                identity = dataclasses.replace(
                    identity,
                    stage="rail",
                    semantic_role=f"library-row:{row_id}",
                )
        elif not compact and self._library_landing_responsive_focus_id:
            control_id = self._library_landing_responsive_focus_id
            row_id = self._library_landing_control_row_id(control_id)
            if identity.semantic_role == f"library-row:{row_id}":
                identity = dataclasses.replace(
                    identity,
                    stage="notes",
                    semantic_role=f"{landing_prefix}{control_id}",
                )
            else:
                self._library_landing_responsive_focus_id = ""
        self._library_notes_compact = compact
        self._sync_library_notes_source_controls()
        if compact:
            self._library_notes_stage = self._compact_library_notes_stage(identity)
            self._library_notes_explicit_stage_intent = False
        self._library_notes_transition_scroll_generation = (
            self._library_notes_scroll_intent_generation
        )
        self._library_notes_transition_focus_generation = (
            self._library_notes_focus_intent_generation
        )
        guard = _LibraryNotesRestoreGuard(
            scroll_generation=self._library_notes_transition_scroll_generation,
            focus_generation=self._library_notes_transition_focus_generation,
        )
        self._apply_library_notes_stage_visibility()
        self._apply_library_note_presentation_state()
        self._apply_library_notes_footer_context()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA and self.query(
            "#library-media-reader-shell"
        ):
            # Media's resolver owns pane visibility and focus settlement;
            # the Notes tuple would otherwise restore focus into hidden Items.
            self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
            return
        self.call_after_refresh(
            self._restore_library_notes_focus_identity,
            identity,
            guard,
        )
        self.call_after_refresh(
            self._queue_library_notes_settled_focus_restore,
            identity,
            guard,
        )

    def _queue_library_notes_settled_focus_restore(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Repeat restoration after resize layout settles, then sample it."""
        self.call_later(
            self._defer_library_notes_settled_focus_restore,
            expected,
            guard,
        )

    def _defer_library_notes_settled_focus_restore(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Cross the extra turn Textual may need to finish scrollbar layout."""
        self.call_later(
            self._restore_library_notes_settled_focus,
            expected,
            guard,
        )

    def _restore_library_notes_settled_focus(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Apply the tuple after geometry clamps and queue its actual position."""
        if not self._library_notes_restore_guard_is_current(guard):
            return
        self._restore_library_notes_focus_identity(expected, guard)
        self.call_later(
            self._restore_library_notes_final_scroll,
            expected,
            guard,
        )

    def _restore_library_notes_final_scroll(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Reapply the exact offset after deferred focus visibility has settled."""
        if not self._library_notes_restore_guard_is_current(guard):
            return
        self._library_notes_restoring_focus = True
        try:
            self._restore_library_notes_scroll_offset(expected, guard)
        finally:
            self._library_notes_restoring_focus = False
        self.call_later(
            self._settle_library_notes_final_scroll,
            expected,
            guard,
        )

    def _settle_library_notes_final_scroll(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Win the last focus-visibility clamp before recording the tuple."""
        if not self._library_notes_restore_guard_is_current(guard):
            return
        self._library_notes_restoring_focus = True
        try:
            self._restore_library_notes_scroll_offset(expected, guard)
        finally:
            self._library_notes_restoring_focus = False
        # A Markdown preview recalculates its virtual height on the refresh
        # after compact CSS is applied. The earlier immediate restores can
        # therefore see max_scroll_y == 0 and clamp a retained offset away.
        # Cross that refresh once, then restore and sample the laid-out owner.
        self.call_after_refresh(
            self._restore_library_notes_scroll_after_layout,
            expected,
            guard,
        )

    def _restore_library_notes_scroll_after_layout(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Restore and record a portable offset after descendant layout settles."""
        if not self._library_notes_restore_guard_is_current(guard):
            return
        self._library_notes_restoring_focus = True
        try:
            self._restore_library_notes_scroll_offset(expected, guard)
        finally:
            self._library_notes_restoring_focus = False
        self._record_library_notes_presented_focus(expected, guard)

    def _record_library_notes_presented_focus(
        self,
        expected: LibraryNotesFocusIdentity,
        guard: _LibraryNotesRestoreGuard | None = None,
    ) -> None:
        """Remember the actual clamped position for user-change detection."""
        if not self._library_notes_restore_guard_is_current(guard):
            return
        self._install_library_notes_scroll_observers()
        current = self._capture_library_notes_focus_identity()
        if (
            current.region == expected.region
            and current.note_id == expected.note_id
            and current.semantic_role == expected.semantic_role
        ):
            self._library_notes_last_presented_focus = current
            self._library_notes_interaction_focus = current

    def _install_library_notes_scroll_observers(self) -> None:
        """Watch current named scroll owners only while their mounted tree lives.

        TASK-23025: probe only regions the current route can mount. Every
        non-rail region here is a Notes-workflow surface (Database Notes or
        File Notes canvases); outside those routes each probe was a
        guaranteed-failing whole-tree ``query_one`` walk, seven of them per
        focus change on the landing/list routes.
        """
        regions: tuple[str, ...] = ("rail",)
        if self._library_notes_compact_workflow_active():
            regions = (
                "rail",
                "navigator",
                "editor",
                "preview",
                "context",
                "create",
                "lasting_add",
                "lasting_roots",
            )
        owners: dict[int, Widget] = {}
        for region in regions:
            owner = self._library_notes_scroll_owner(region)
            if owner is not None:
                owners[id(owner)] = owner
        for owner in owners.values():
            if getattr(owner, "_library_notes_scroll_observed", False):
                continue
            owner._library_notes_scroll_observed = True
            self.watch(
                owner,
                "scroll_x",
                partial(self._queue_library_notes_scroll_interaction, owner),
                init=False,
            )
            self.watch(
                owner,
                "scroll_y",
                partial(self._queue_library_notes_scroll_interaction, owner),
                init=False,
            )

    def _queue_library_notes_scroll_interaction(
        self, owner: Widget, old_value: float, new_value: float
    ) -> None:
        """Defer scroll intent so a resize epoch can reject layout clamping."""
        del old_value, new_value
        epoch = self._library_notes_resize_epoch
        programmatic = bool(
            self._library_notes_restoring_focus or self._library_notes_resize_settling
        )
        stage = self._library_notes_focus_stage(self.focused)
        region = "rail" if stage == "rail" else self._library_notes_focus_region()
        relevant = self._library_notes_workflow_active() or stage == "rail"
        user_intent = bool(
            not programmatic
            and relevant
            and self._library_notes_scroll_owner(region) is owner
        )
        if user_intent:
            # Invalidate any older deferred resize/recompose restore before
            # its callback can overwrite this explicit scroll interaction.
            self._library_notes_scroll_intent_generation += 1
        self.call_later(
            self._record_library_notes_scroll_interaction,
            owner,
            epoch,
            user_intent,
        )

    def _record_library_notes_scroll_interaction(
        self, owner: Widget, epoch: int, user_intent: bool
    ) -> None:
        """Cache one settled user scroll without a global Idle hot path."""
        if epoch != self._library_notes_resize_epoch or not self.is_mounted:
            return
        stage = self._library_notes_focus_stage(self.focused)
        if not self._library_notes_workflow_active() and stage != "rail":
            return
        region = "rail" if stage == "rail" else self._library_notes_focus_region()
        if self._library_notes_scroll_owner(region) is not owner:
            return
        identity = self._capture_library_notes_focus_identity(stage_from_focus=True)
        self._library_notes_interaction_focus = identity
        if user_intent:
            self._advance_library_stage_interaction()
            self._library_notes_last_user_scroll_focus = identity

    def _record_library_notes_focus_interaction(
        self, expected: Widget, user_intent: bool
    ) -> None:
        """Capture a settled focus change and attach its current scroll owner."""
        if not self.is_mounted or self.focused is not expected:
            return
        if (
            not self._library_notes_workflow_active()
            and self._library_notes_focus_stage(self.focused) != "rail"
            and not (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and self._library_media_view == "list"
            )
        ):
            return
        self._install_library_notes_scroll_observers()
        identity = self._capture_library_notes_focus_identity(stage_from_focus=True)
        self._library_notes_interaction_focus = identity
        if user_intent:
            self._advance_library_stage_interaction()
            self._library_notes_last_user_focus = identity

    def _remember_library_notes_responsive_focus(
        self, identity: LibraryNotesFocusIdentity
    ) -> LibraryNotesFocusIdentity:
        """Keep offsets that an expanded viewport temporarily clamps away."""
        previous = self._library_notes_responsive_focus_memory
        same_target = bool(
            previous is not None
            and previous.region == identity.region
            and previous.note_id == identity.note_id
            and previous.semantic_role == identity.semantic_role
        )
        if (
            same_target
            and previous is not None
            and previous.scroll_offset is not None
            and identity.scroll_offset is not None
        ):
            user_scroll = self._library_notes_last_user_scroll_focus
            user_changed_since_transition = bool(
                self._library_notes_scroll_intent_generation
                != self._library_notes_transition_scroll_generation
                and user_scroll is not None
                and user_scroll.region == identity.region
                and user_scroll.note_id == identity.note_id
                and user_scroll.semantic_role == identity.semantic_role
            )
            current_x, current_y = identity.scroll_offset
            previous_x, previous_y = previous.scroll_offset
            if not user_changed_since_transition:
                current_x, current_y = previous_x, previous_y
            identity = dataclasses.replace(
                identity, scroll_offset=(current_x, current_y)
            )
        self._library_notes_responsive_focus_memory = identity
        return identity

    def _update_library_notes_responsive_state(self) -> None:
        """Measure the invariant shell allocation and transition only on crossing."""
        if not self.is_mounted:
            return
        try:
            width = self.query_one("#library-shell-grid").region.width
        except (NoMatches, QueryError):
            return
        if width <= 0:
            return
        self._sync_library_ingest_rail_for_width(width)
        self._sync_library_ordinary_rail_width_contract()
        self._apply_library_notes_stage_visibility_for_resize()
        compact = width < LIBRARY_NOTES_COMPACT_BREAKPOINT
        if compact == self._library_notes_compact:
            self._library_notes_pre_resize_focus = None
            return
        identity = self._library_notes_pre_resize_focus or (
            self._capture_library_notes_focus_identity(stage_from_focus=True)
        )
        self._library_notes_pre_resize_focus = None
        identity = self._remember_library_notes_responsive_focus(identity)
        self._transition_library_notes_presentation(compact, identity)

    def _library_ref_is_live(self, widget: Widget) -> bool:
        """Return whether a cached reference is still this screen's live node.

        TASK-23025: ``is_mounted`` alone is NOT a validity check --
        ``_is_mounted`` lags detachment, and ``App._prune`` marks the doomed
        subtree ``_pruning`` synchronously while the detach happens later
        (the task-2200 lesson: ``is_mounted`` != in-the-DOM; a targeted
        canvas sync's replaced notes list measured exactly this, the scroll
        restore landing on the pruned corpse). Walking the ``_parent`` chain
        back to this screen is a handful of attribute hops -- still far
        cheaper than a DOM walk -- and matches what ``query_one`` would
        resolve.
        """
        if getattr(widget, "_pruning", False) or not widget.is_mounted:
            return False
        node: DOMNode | None = widget
        while node is not None:
            if node is self:
                return True
            node = node._parent
        return False

    def _library_layout_ref(self, selector: str) -> Widget | None:
        """Resolve one invariant shell-chrome widget through the ref cache.

        TASK-23025: positive references only, validated by
        ``_library_ref_is_live`` and cleared in ``compose_content`` (the
        choke point every whole-screen recompose passes through), so hot
        per-frame paths read attributes instead of re-walking the DOM. A
        miss falls back to one id-selector ``query_one`` and re-caches;
        absence is never cached, so a widget that mounts later is still
        found.
        """
        cached = self._library_layout_ref_cache.get(selector)
        if cached is not None and self._library_ref_is_live(cached):
            return cached
        try:
            widget = self.query_one(selector, Widget)
        except (NoMatches, QueryError):
            self._library_layout_ref_cache.pop(selector, None)
            return None
        self._library_layout_ref_cache[selector] = widget
        return widget

    def _library_compose_scoped_ref(self, selector: str) -> Widget | None:
        """Positive AND negative ref cache for compose_content-exclusive ids.

        TASK-23025: only valid for ids constructed exclusively inside
        ``compose_content`` (e.g. the note work pane) -- cached absence
        would otherwise go stale when a widget mounts through another seam.
        The cache, including cached absence, is cleared in
        ``compose_content``.
        """
        if selector in self._library_compose_ref_cache:
            cached = self._library_compose_ref_cache[selector]
            if cached is None:
                return None
            if self._library_ref_is_live(cached):
                return cached
        try:
            widget: Widget | None = self.query_one(selector, Widget)
        except (NoMatches, QueryError):
            widget = None
        self._library_compose_ref_cache[selector] = widget
        return widget

    def _library_adaptive_reader_shell_active(self) -> bool:
        """Report adaptive reader-shell presence without a per-frame walk.

        All five ``*-reader-shell`` ids are constructed exclusively in
        ``compose_content``, so shells (un)mount only across a compose
        generation -- one failed probe per recompose is exact, and a
        mounted shell is revalidated by its own ``is_mounted`` flag.
        """
        cached = self._library_reader_shell_ref
        if cached is not None and self._library_ref_is_live(cached):
            return True
        if (
            self._library_reader_shell_probe_generation
            == self._library_compose_generation
        ):
            return False
        self._library_reader_shell_probe_generation = self._library_compose_generation
        shells = self.query(_LIBRARY_READER_SHELL_SELECTOR)
        self._library_reader_shell_ref = shells.first(Widget) if shells else None
        return self._library_reader_shell_ref is not None

    def _library_resize_layout_signature(self) -> tuple[Any, ...] | None:
        """Signature of every width-derived decision the resize legs make.

        TASK-23025 (AC: gate before query work): built from cached widget
        references and cheap flags only -- ``region``/``content_region``
        attribute reads, never a DOM walk. Mirrors, in order, the inputs of
        ``_sync_library_ingest_rail_for_width`` (ingest collapse bucket),
        ``_sync_library_ordinary_rail_width_contract`` (the resolved
        contract itself, so the custom-width clamp band stays exact),
        ``_apply_library_notes_stage_visibility`` (its route/stage flags
        plus ``_apply_library_emergency_geometry``'s bucket), and the
        compact-crossing check. Returns ``None`` when it cannot be decided
        cheaply; callers then run the full legs, exactly as before.
        """
        shell = self._library_layout_ref("#library-shell-grid")
        rail = self._library_layout_ref("#library-rail")
        canvas = self._library_layout_ref("#library-canvas")
        if shell is None or rail is None or canvas is None:
            return None
        width = shell.region.width
        if width <= 0:
            return None
        viewport = self.size.width if self.is_mounted else 0
        effective = min(width, viewport) if viewport > 0 else width
        content_width = shell.content_region.width
        emergency_width = min(width, viewport)
        reader_active = self._library_adaptive_reader_shell_active()
        contract: OrdinaryRailStyleContract | None = None
        if not reader_active and content_width >= LIBRARY_EMERGENCY_WIDTH:
            if not rail.display:
                presentation = OrdinaryRailPresentation.HIDDEN
            elif not canvas.display:
                presentation = OrdinaryRailPresentation.RAIL_ONLY
            else:
                presentation = OrdinaryRailPresentation.ALONGSIDE
            shared = self._library_reader_shared_preferences
            contract = resolve_ordinary_rail_contract(
                content_width,
                presentation,
                shared.custom_widths_enabled,
                shared.library_width,
            )
        return (
            self._library_compose_generation,
            shell,
            rail,
            canvas,
            self._library_selected_row_id,
            self._library_notes_source,
            self._library_notes_view,
            self._library_notes_stage,
            self._library_notes_compact,
            self._library_rail_collapsed,
            self._library_ingest_auto_collapsed_rail,
            self._library_emergency_stage,
            self._file_notes_active(),
            rail.display,
            canvas.display,
            reader_active,
            self._library_reader_shared_preferences,
            width < LIBRARY_NOTES_COMPACT_BREAKPOINT,
            effective < LIBRARY_INGEST_RAIL_COLLAPSE_BREAKPOINT,
            (
                ordinary_emergency_required(emergency_width)
                if emergency_width > 0
                else None
            ),
            content_width < LIBRARY_EMERGENCY_WIDTH,
            contract,
        )

    def on_resize(self, event: events.Resize) -> None:
        """Capture only a crossing, decided by the measured invariant grid."""
        del event
        self._library_notes_resize_epoch += 1
        self._library_notes_resize_settling = True
        # TASK-22228 (item 7): the Media reader layout leg is scheduled only
        # while Browse Media owns the canvas -- the one route that mounts
        # ``#library-media-reader-shell`` (``compose``'s
        # ``canvas_kind == "media"`` branch; the same predicate
        # ``_sync_library_media_viewer_state`` gates the viewer on). Anywhere
        # else the scheduled call could only walk the whole Library DOM
        # looking for a shell that is not mounted and return: a FAILED
        # ``query_one`` takes no id-cache fast path, so every Notes /
        # Conversations / Ingest resize frame paid two full breadth-first
        # walks (measured 16.0 us each on a 118-widget fixture) to do
        # nothing. Behaviour is unchanged -- the skipped call was already a
        # no-op on those routes.
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            focused = self.focused
            focus_intent = (
                (focused, self._library_notes_focus_intent_generation)
                if focused is not None
                else None
            )
            self.call_after_refresh(
                self._sync_library_media_reader_layout_from_shell,
                focus_intent=focus_intent,
            )
        # TASK-23025: decide from cheap state -- cached references and
        # width-bucket arithmetic -- whether this frame can change anything
        # the legs below derive, BEFORE any of their query work. The
        # signature is recorded pre-legs, so a frame whose legs mutate flags
        # simply runs once more on the next event and then settles; a skip
        # can never hide a crossing because every bucket the legs compare is
        # part of the signature.
        signature = self._library_resize_layout_signature()
        if signature is not None:
            if signature == self._library_resize_applied_signature:
                self._library_notes_pre_resize_focus = None
                return
            self._library_resize_applied_signature = signature
        try:
            width = self.query_one("#library-shell-grid").region.width
        except (NoMatches, QueryError):
            return
        if width <= 0:
            return
        self._sync_library_ingest_rail_for_width(width)
        self._sync_library_ordinary_rail_width_contract()
        self._apply_library_notes_stage_visibility_for_resize()
        compact = width < LIBRARY_NOTES_COMPACT_BREAKPOINT
        if compact == self._library_notes_compact:
            self._library_notes_pre_resize_focus = None
            return
        current = self._capture_library_notes_focus_identity(stage_from_focus=True)
        identity = current
        for cached in (
            self._library_notes_last_user_focus,
            self._library_notes_interaction_focus,
            self._library_notes_last_presented_focus,
            self._library_notes_responsive_focus_memory,
        ):
            if (
                cached is not None
                and cached.region == current.region
                and cached.note_id == current.note_id
                and (
                    not current.semantic_role.startswith(
                        (
                            "media-row:",
                            "media-preview-open:",
                            "landing-control:",
                            "library-row:",
                        )
                    )
                    or cached.semantic_role == current.semantic_role
                )
            ):
                identity = dataclasses.replace(
                    cached,
                    stage=current.stage,
                    body_selection_start=current.body_selection_start,
                    body_selection_end=current.body_selection_end,
                )
                break
        user_scroll = self._library_notes_last_user_scroll_focus
        if (
            user_scroll is not None
            and user_scroll.region == current.region
            and user_scroll.note_id == current.note_id
            and (
                not current.semantic_role.startswith(
                    (
                        "media-row:",
                        "media-preview-open:",
                        "landing-control:",
                        "library-row:",
                    )
                )
                or user_scroll.semantic_role == current.semantic_role
            )
        ):
            identity = dataclasses.replace(
                identity,
                scroll_offset=user_scroll.scroll_offset,
            )
        self._library_notes_pre_resize_focus = identity
        self.call_after_refresh(self._update_library_notes_responsive_state)

    def _mark_library_notes_user_interaction(self) -> None:
        """End resize suppression only when a real input event can own changes."""
        self._library_notes_resize_settling = False

    def on_mouse_down(self, event: events.MouseDown) -> None:
        """Let click-driven focus changes supersede resize memory."""
        try:
            target, _ = self.get_widget_at(event.screen_x, event.screen_y)
        except (NoMatches, NoWidget):
            target = None
        self._advance_library_ordinary_emergency_user_interaction(target)
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()

    def on_mouse_scroll_down(self, event: events.MouseScrollDown) -> None:
        """Let wheel scrolling supersede resize and list-return memory."""
        self._advance_library_ordinary_emergency_user_interaction(
            getattr(event, "widget", None)
        )
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()

    def on_mouse_scroll_up(self, event: events.MouseScrollUp) -> None:
        """Let wheel scrolling supersede resize and list-return memory."""
        self._advance_library_ordinary_emergency_user_interaction(
            getattr(event, "widget", None)
        )
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()

    def _notes_footer_tier(
        self,
        wide: tuple[tuple[str, str], ...],
        compact: tuple[tuple[str, str], ...],
    ) -> tuple[tuple[str, str], ...]:
        """Pick the width tier of one Notes footer set (task-4023 AC#5).

        Same keys and destinations in both tiers; the compact tier only
        compresses labels so the context still fits the ≤100-col displayed
        footer -- mirroring ``AppFooterStatus``'s own FULL/COMPACT global
        tiers rather than inventing a second dialect.
        """
        return compact if self._library_notes_compact else wide

    def _library_notes_footer_shortcuts(self) -> tuple[tuple[str, str], ...]:
        """Return exact one-row local help for the visible Notes state."""
        if not self._library_notes_workflow_active() or (
            self._library_notes_compact and self._library_notes_stage != "notes"
        ):
            return self._library_footer_shortcuts_for_current_state()
        snapshot = self._library_note_session.snapshot
        if snapshot is not None and (
            snapshot.in_conflict
            or self._library_note_session.conflict_resolution_running
        ):
            # A running resolution locks every key -- advertise nothing
            # (globals only) rather than a dead entry (AC#5 honesty).
            if self._library_note_session.conflict_resolution_running:
                return ()
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_CONFLICT_SHORTCUTS,
                self.LIBRARY_NOTES_CONFLICT_SHORTCUTS_COMPACT,
            )
        if self._library_note_confirming_delete:
            return self._notes_footer_tier(
                (("enter", "confirm delete"), ("esc", "cancel delete")),
                (("enter", "confirm"), ("esc", "cancel")),
            )
        region = self._library_notes_focus_region()
        if region == "navigator":
            if self._library_notes_select_mode:
                return self._notes_footer_tier(
                    (("enter", "select note"), ("esc", "done")),
                    (("enter", "select"), ("esc", "done")),
                )
            if self._library_notes_sort_choices_visible:
                return self._notes_footer_tier(
                    (("enter", "choose sort"), ("esc", "cancel")),
                    (("enter", "choose sort"), ("esc", "cancel")),
                )
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_NAVIGATOR_SHORTCUTS,
                self.LIBRARY_NOTES_NAVIGATOR_SHORTCUTS_COMPACT,
            )
        if region == "preview":
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_PREVIEW_SHORTCUTS,
                self.LIBRARY_NOTES_PREVIEW_SHORTCUTS_COMPACT,
            )
        if region == "context":
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_CONTEXT_SHORTCUTS,
                self.LIBRARY_NOTES_CONTEXT_SHORTCUTS_COMPACT,
            )
        if region == "editor":
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_EDITOR_SHORTCUTS,
                self.LIBRARY_NOTES_EDITOR_SHORTCUTS_COMPACT,
            )
        if region == "create":
            if self._library_note_create_running:
                return ()
            return self._notes_footer_tier(
                (("enter", "create note"), ("esc", "back to notes")),
                (("enter", "create"), ("esc", "notes")),
            )
        if region in {"lasting_add", "lasting_roots"}:
            phase = self._library_notes_sync_controller.snapshot.phase
            if phase in {"checking", "activating"}:
                return (("wait", "current step"),)
            return self._notes_footer_tier(
                (("enter", "run action"), ("esc", "back to notes")),
                (("enter", "act"), ("esc", "notes")),
            )
        if region == "import":
            phase = self._library_note_import_controller.snapshot.phase
            if phase in {NoteImportPhase.CHECKING, NoteImportPhase.IMPORTING}:
                return (("esc", "cancel"),)
            return (("esc", "back to notes"),)
        return self._library_footer_shortcuts_for_current_state()

    def _apply_library_notes_footer_context(self) -> None:
        """Persist region help and hide only compact Notes ancillary indicators."""
        shortcuts = self._library_notes_footer_shortcuts()
        registration = ("library", tuple(shortcuts))
        if self._footer_shortcut_registration != registration:
            self.register_footer_shortcuts(source="library", shortcuts=shortcuts)
        hide_ancillary = bool(
            self._library_notes_compact
            and self._library_notes_stage == "notes"
            and self._library_notes_workflow_active()
        )
        # TASK-23025: this method runs on EVERY screen refresh (see the
        # ``refresh`` override), several times per resize frame and focus
        # change -- resolve the stable footer chrome through the ref cache
        # and skip the no-op display writes.
        for selector in (
            "#footer-word-count",
            "#footer-token-count",
            "#internal-db-size-indicator",
        ):
            indicator = self._library_layout_ref(selector)
            if indicator is not None and indicator.display == hide_ancillary:
                indicator.display = not hide_ancillary

    def _rehydrate_library_notes_after_recompose(
        self, restore: _LibraryNotesRecomposeCapture
    ) -> None:
        """Reapply the live coordinator snapshot and portable presentation tuple."""
        if (
            not self.is_mounted
            or restore.recompose_generation != self._library_notes_recompose_generation
        ):
            return
        snapshot = self._library_note_session.snapshot
        session_matches = restore.session_generation is None or bool(
            snapshot is not None
            and snapshot.note_id == restore.focus.note_id
            and snapshot.session_generation == restore.session_generation
        )
        revision_matches = restore.draft_revision is None or bool(
            snapshot is not None and snapshot.draft_revision == restore.draft_revision
        )
        presentation_matches = session_matches and revision_matches
        pending_focus = (
            self._library_notes_pending_focus_identity
            if self._library_notes_pending_focus_generation
            == self._library_notes_navigation_generation
            else None
        )
        focus_identity = pending_focus or restore.focus
        may_restore_focus = pending_focus is not None or presentation_matches
        explicit_stage_intent = self._library_notes_explicit_stage_intent
        if (
            self._library_notes_compact
            and may_restore_focus
            and not explicit_stage_intent
        ):
            self._library_notes_stage = focus_identity.stage
        self._apply_library_notes_stage_visibility()
        if snapshot is not None and session_matches:
            if snapshot.in_conflict:
                self._library_note_preview = False
                self._library_note_context = False
            elif presentation_matches:
                self._library_note_preview = restore.preview
                self._library_note_context = restore.context
            if presentation_matches:
                self._library_note_confirming_delete = restore.confirming_delete
            self._apply_library_note_presentation_state()
            self.call_after_refresh(
                self._arm_library_note_editor, restore.recompose_generation
            )
        self._apply_library_notes_footer_context()
        if may_restore_focus:
            guard = _LibraryNotesRestoreGuard(
                recompose_generation=restore.recompose_generation,
                scroll_generation=restore.scroll_generation,
                focus_generation=restore.focus_generation,
            )
            self._restore_library_notes_focus_identity(focus_identity, guard)
            self.call_after_refresh(
                self._queue_library_notes_settled_focus_restore,
                focus_identity,
                guard,
            )
        if explicit_stage_intent:
            self._library_notes_explicit_stage_intent = False

    def refresh(
        self,
        *regions: Region,
        repaint: bool = True,
        layout: bool = False,
        recompose: bool = False,
    ) -> "LibraryScreen":
        """Capture one coordinator-safe seam around every screen recompose."""
        if recompose:
            self._commit_library_note_widgets_before_recompose()
        restore = self._capture_library_notes_recompose_state() if recompose else None
        if restore is not None:
            self._library_notes_recompose_generation += 1
            restore = dataclasses.replace(
                restore,
                recompose_generation=self._library_notes_recompose_generation,
            )
        self._apply_library_notes_footer_context()
        result = super().refresh(
            *regions,
            repaint=repaint,
            layout=layout,
            recompose=recompose,
        )
        if restore is not None:
            self.call_after_refresh(
                self._rehydrate_library_notes_after_recompose, restore
            )
        elif recompose:
            self.call_after_refresh(self._apply_library_notes_stage_visibility)
            self.call_after_refresh(self._apply_library_notes_footer_context)
        return result

    async def action_library_notes_new(self) -> None:
        """Open Create only after the active canonical draft flushes."""
        await self._select_library_rail_row(LIBRARY_ROW_CREATE_NOTE)

    def action_library_notes_focus_filter(self) -> None:
        """Focus Navigator Filter without claiming literal input keystrokes."""
        self._focus_library_notes_filter_input()
        try:
            self.query_one("#library-notes-filter", Input).scroll_visible(
                animate=False, force=True, immediate=True
            )
        except (NoMatches, QueryError):
            return

    def _show_library_note_shortcut_refusal(self, message: str) -> None:
        """Keep a blocked local action visible in status and notification."""
        self._library_note_shortcut_status = message
        self._apply_library_note_presentation_state()
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(message, severity="warning")

    async def action_library_notes_save(self) -> None:
        """Request an immediate save or explain the owning safety gate."""
        if self._library_notes_select_mode:
            self._show_library_note_shortcut_refusal(
                "Save unavailable — finish bulk selection first."
            )
            return
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return
        if (
            self._library_note_confirming_delete
            or self._library_note_session.destructive_running
            or self._library_note_session.destructive_admission is not None
        ):
            self._show_library_note_shortcut_refusal(
                "Save locked — finish or cancel the destructive action."
            )
            if self._library_note_confirming_delete:
                self._focus_library_note_control("#library-note-delete-cancel")
            return
        if (
            snapshot.in_conflict
            or self._library_note_session.conflict_resolution_running
        ):
            self._show_library_note_shortcut_refusal(
                "Save locked — resolve the note conflict below."
            )
            self._focus_library_note_conflict_callout()
            return
        self._invalidate_library_note_autosave()
        await self._save_library_note(explicit=True)

    async def action_library_notes_escape(self) -> None:
        """Follow the visible Notes Back hierarchy without bypassing vetoes."""
        snapshot = self._library_note_session.snapshot
        if self._library_note_confirming_delete:
            if self._library_note_session.destructive_running:
                self._show_library_note_shortcut_refusal(
                    "Delete is running — wait for it to finish."
                )
                return
            admission = self._library_note_session.destructive_admission
            if (
                admission is not None
                and not self._library_note_session.cancel_destructive(admission)
            ):
                self._show_library_note_shortcut_refusal(
                    "Delete is running — wait for it to finish."
                )
                return
            self._restore_library_note_delete_origin()
            return
        if snapshot is not None and (
            snapshot.in_conflict
            or self._library_note_session.conflict_resolution_running
        ):
            self._show_library_note_shortcut_refusal(
                "Conflict locked — choose Overwrite or Reload before leaving."
            )
            self._focus_library_note_conflict_callout()
            return
        if self._library_note_context:
            self._library_note_context = False
            self._apply_library_note_presentation_state()
            self._focus_library_note_control("#library-note-context")
            return
        if self._library_notes_select_mode:
            self._library_notes_select_mode = False
            self._library_notes_row_selection.clear()
            _sync_library_canvas(
                self,
                "notes",
                then=lambda: self._focus_library_note_control(
                    "#library-notes-select-toggle"
                ),
            )
            return
        if self._library_notes_view == "editor":
            # P0 (found independently by task-3315 and at dev 4d0232358):
            # this called `_back_from_library_note_editor()`, a method that
            # never existed in ANY commit (introduced dangling on the
            # notes-adaptive branch at e453e9099, "feat(notes): preserve
            # focus across compact stages") -- a real Escape keypress from
            # the note editor raised an uncaught AttributeError that
            # terminated the whole app. Route through the one shared Back
            # seam the "‹ Back to list" button and
            # `action_library_note_editor_back` already use (dirty-flush +
            # veto + session-blank GC + list restore) instead of inventing
            # a second exit path.
            await self._exit_library_note_editor_guarded()
            return
        if self._library_selected_row_id == LIBRARY_ROW_CREATE_NOTE:
            if self._library_note_create_running:
                notify = getattr(self.app_instance, "notify", None)
                if callable(notify):
                    notify(
                        "Create is running — wait for it to finish.", severity="warning"
                    )
                return
            self._library_note_create_status = ""
            await self._select_library_rail_row(LIBRARY_ROW_BROWSE_NOTES)
            return
        if self._library_notes_view in {"lasting_add", "lasting_roots"}:
            await self._exit_library_notes_lasting_sync()
            return
        if self._library_notes_view == "import":
            phase = self._library_note_import_controller.snapshot.phase
            if phase in {NoteImportPhase.CHECKING, NoteImportPhase.IMPORTING}:
                self._library_note_import_controller.cancel()
                return
            self._library_notes_view = "list"
            _sync_library_canvas(
                self, "notes", then=self._focus_library_notes_filter_input
            )
            return
        if self._library_notes_sort_choices_visible:
            self._library_notes_sort_choices_visible = False
            _sync_library_canvas(
                self,
                "notes",
                then=lambda: self._focus_library_note_control("#library-notes-sort"),
            )
            return
        self._advance_library_stage_interaction()
        self._library_notes_stage = "rail"
        self._library_notes_explicit_stage_intent = False
        self._supersede_library_notes_navigation()
        if self.query("#library-notes-reader-shell"):
            # The adaptive shell keeps all three owners mounted, so Escape
            # from Navigator moves toward Library by granting that pane one
            # effective-layout priority. This is deliberately not persisted:
            # the user's requested pane preferences remain authoritative and
            # return on the next unconstrained layout. Resolve visibility
            # before restoring focus so a narrow shell never strands focus in
            # the auto-collapsed Library pane.
            self._sync_library_notes_reader_layout_from_shell(priority="library")
        self._apply_library_notes_stage_visibility()
        self._apply_library_notes_footer_context()
        identity = LibraryNotesFocusIdentity(
            stage="rail",
            region="navigator",
            note_id=None,
            semantic_role=f"library-row:{self._library_selected_row_id}",
        )
        self.call_after_refresh(self._restore_library_notes_focus_identity, identity)

    def _register_footer_shortcuts(self) -> None:
        """Register Library shortcuts via BaseAppScreen's persisting API.

        Persistence matters here: the destination-switch failsafes call
        ``screen.refresh(recompose=True)``, which replaces the footer widget;
        the registration must survive that. This method is ALSO called from
        ``compose_content`` on every recompose (not just at the transition
        call sites elsewhere in this class), so a sub-view entered from ANY
        of the editor/viewer's several call sites (see
        ``_library_note_editor_active`` etc.) can never leave the footer
        stale the way an easily-missed per-call-site registration could.
        """
        shortcuts = self._library_footer_shortcuts_for_current_state()
        self.register_footer_shortcuts(source="library", shortcuts=shortcuts)
        for bar in self.query(LibraryEmergencyReturn):
            self._sync_library_emergency_return(bar)

    def _sync_library_emergency_guard_presentation(self) -> None:
        """Repaint guarded return truth after an in-place state transition."""
        if (
            getattr(self, "_is_mounted", False)
            and self._library_emergency_stage == "canvas-only"
        ):
            self._register_footer_shortcuts()

    def on_key(self, event: Key) -> None:
        """Keyboard affordances: ``/`` anywhere, plus landing accelerators.

        F-012's focus-search key, implemented as a screen-level key handler
        (the settings screen's task-1715 pattern) rather than a ``Binding``:
        the key stays out of the key palette, and it can never fire while an
        ``Input``/``TextArea`` owns focus -- text fields consume printable
        keys before this handler runs, so the isinstance guard is belt and
        braces for any field that lets an event through. Once the rail box
        itself has focus, its own ``_on_key`` re-arms the query instead
        (see ``LibraryRailSearchInput``).

        task-2237 (R2): `i` and `n` are the hub next-action accelerators
        (import content / new note), dispatched through the same guarded
        row-switch the hub rows use. task-3302 (MI-04) widened `i` to work
        from ANY Library canvas (it opens the same Ingest canvas from
        anywhere, and the row-switch guards still veto over dirty edits);
        `n` stays landing-scoped because it opens a create editor.

        task-2856 (AC1): Up/Down move DOM focus between Library list rows
        (Media/Notes/Prompts/Skills) -- see ``_move_library_list_row_focus``,
        which claims the key only while a list row genuinely has focus, so
        Up/Down are left alone everywhere else (rail rows, form Inputs, the
        command palette, etc.).

        task-2856 (review round 2): ANY key disarms a pending entry-focus
        request (``_library_pending_list_entry_focus``) the instant it is
        pressed -- unconditionally, before the Input/TextArea early
        return, since typing into a Tab-reached field is exactly the kind
        of user interaction that must stop the request too. Disarming an
        already-idle flag is a harmless no-op, so this never needs its own
        gate. Complements ``on_descendant_focus`` (which also catches
        mouse clicks -- see its docstring); together the two mean the
        settle-window timer is only ever the LAST resort for a
        still-armed, still-idle request.
        """
        emergency_tab = bool(
            event.key in {"tab", "shift+tab", "backtab"}
            and self._library_emergency_stage == "canvas-only"
            and self._library_emergency_restore_receipt is not None
        )
        if emergency_tab:
            if event.key == "tab":
                focused = self.focus_next()
            else:
                owner = self._library_entry_canvas_owner()
                route_focus_chain = (
                    [
                        widget
                        for widget in self.focus_chain
                        if widget is not owner and owner in widget.ancestors_with_self
                    ]
                    if owner is not None
                    else []
                )
                if route_focus_chain and self.focused is route_focus_chain[0]:
                    try:
                        focused = self.query_one(
                            "#library-emergency-return", LibraryEmergencyReturn
                        )
                    except (NoMatches, QueryError):
                        focused = None
                    else:
                        focused.focus()
                else:
                    focused = self.focus_previous()
            self._advance_library_ordinary_emergency_user_interaction(focused)
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()
        if emergency_tab:
            event.stop()
            event.prevent_default()
            return
        if isinstance(self.focused, (Input, TextArea)):
            return
        if event.key in ("up", "down") and _move_library_list_row_focus(
            self.focused, event.key
        ):
            event.stop()
            event.prevent_default()
            return
        is_slash = (
            event.key in {"/", "slash"} or getattr(event, "character", None) == "/"
        )
        if is_slash:
            if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                if self._library_conversation_reader_layout.items_open:
                    try:
                        self.query_one("#library-conversations-filter", Input).focus()
                    except (NoMatches, QueryError):
                        return
                    event.stop()
                    event.prevent_default()
                return
            # task-3315: this screen-wide rail-search grab predates the
            # notes-adaptive "/" binding (library_notes_focus_filter, PR
            # #1439) and runs BEFORE bindings dispatch, so the notes-scoped
            # "/" could never fire -- inside the Notes Navigator with a
            # non-text control focused, "/" jumped to the rail search
            # instead of the notes filter (reproduced failing at dev base
            # ebeae1440). Defer to the binding's own check_action gate so
            # the precedence lives in exactly one place.
            if self.check_action("library_notes_focus_filter", ()):
                self.action_library_notes_focus_filter()
                event.stop()
                event.prevent_default()
                return
            if self._library_lifecycle in (
                LibraryLifecycle.UNKNOWN,
                LibraryLifecycle.STARTER,
            ):
                return
            rail = self._active_library_rail()
            if rail is None:
                return
            try:
                rail.query_one("#library-search-input", Input).focus()
            except (NoMatches, QueryError):
                return
            event.stop()
            event.prevent_default()
            return
        # task-3302 (MI-04): `i` (import content) works from ANY Library
        # canvas, not just the landing -- there was no keyboard route into
        # Ingest once a row was selected. Still never fires while an
        # Input/TextArea owns focus (the early return above), and it rides
        # the same guarded row switch as the rail rows, so dirty
        # note/prompt/skill edits still flush-or-veto the jump. A no-op
        # while Ingest already owns the canvas.
        if event.key == "i":
            if self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA:
                return
            self.run_worker(
                self._select_library_rail_row(LIBRARY_ROW_INGEST_MEDIA),
                exclusive=True,
                group="library_rail_row_switch",
            )
            event.stop()
            event.prevent_default()
            return
        # Landing-scoped hub accelerator (task-2237): `n` (new note) stays
        # landing-only -- unlike `i`, it opens a CREATE editor, which would
        # be a surprising context loss from a browse canvas.
        if self._library_selected_row_id:
            return
        if event.key != "n":
            return
        self.run_worker(
            self._select_library_rail_row(LIBRARY_ROW_CREATE_NOTE),
            exclusive=True,
            group="library_rail_row_switch",
        )
        event.stop()
        event.prevent_default()

    def action_focus_next_workbench_pane(self) -> None:
        """F6: move focus to the next Library workbench pane (task-2237).

        Previously the screen defined no pane targets, so the app's global
        F6 dead-ended in a "no focus target" notification here. The rail's
        search box is the rail target; on the landing the hub's first
        action is the canvas target (other canvases mount their own focus
        order and are skipped when the target is absent).
        """
        focus_relative_workbench_pane(
            self,
            self._library_workbench_focus_targets(),
            direction=1,
        )

    def action_focus_previous_workbench_pane(self) -> None:
        """Shift+F6: move focus to the previous Library workbench pane."""
        focus_relative_workbench_pane(
            self,
            self._library_workbench_focus_targets(),
            direction=-1,
        )

    def _library_workbench_focus_targets(
        self,
    ) -> tuple[WorkbenchPaneTarget, ...]:
        """Return the active destination's stable global focus regions."""
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            return self._MEDIA_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            return self._COLLECTIONS_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            return self._CONVERSATION_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES:
            return self._NOTES_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            return self._PROMPTS_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_CREATE_SKILL,
        }:
            return self._SKILLS_WORKBENCH_FOCUS_TARGETS
        return self._WORKBENCH_FOCUS_TARGETS

    def refresh_notes_sync_runtime(self) -> None:
        """Project the app-owned runtime after detached startup settles."""

        self._library_notes_sync_controller.refresh_roots()
        if (
            self.is_mounted
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
            and self._library_notes_view == "list"
        ):
            # This callback is scheduled from ``on_mount``/``on_screen_resume``
            # and may run while the retained Notes canvas is still mounting.
            # Its roots refresh is opportunistic; the ordinary source snapshot
            # reconciliation owns the authoritative projection.  Falling back
            # to a whole-screen recompose here tears down the just-mounted
            # shell and races that reconciliation.
            _sync_library_canvas(self, "notes", allow_screen_fallback=False)

    def on_screen_resume(self) -> None:
        """Refresh lasting-sync availability whenever Library becomes current."""

        self.call_after_refresh(self.refresh_notes_sync_runtime)

    def on_mount(self) -> None:
        """Populate the Library on entry, rendering instantly from cache.

        The constructor has already seeded any valid, recent app-scoped
        snapshot before first compose. Mount arms the snapshot-timeout
        failsafe and unconditionally kicks ``_refresh_local_source_snapshot``
        to reconcile against the DB. It also seeds the ingest registry listener
        and runs deferred deep-link loads (collections / note editor / media
        viewer) that ``apply_navigation_context`` could not run before mount.
        """
        self._library_conversation_reader_mounted_authority = True
        self._library_media_trash_mounted_authority = True
        self._register_footer_shortcuts()
        self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
        self.call_after_refresh(self._sync_library_ordinary_rail_width_contract)
        self.call_after_refresh(self._present_library_skills_import_choice_if_needed)
        if (
            self._library_new_profile_admission
            and not self._library_lifecycle_was_stored
        ):
            self._queue_library_lifecycle_persistence(LibraryLifecycle.UNKNOWN)
        # No super().on_mount(): the dispatcher already invokes
        # BaseAppScreen.on_mount separately for this Mount event.
        self.call_after_refresh(self._update_library_notes_responsive_state)
        self.call_after_refresh(self.refresh_notes_sync_runtime)
        self._load_library_ingest_options_from_config()
        self.set_timer(
            LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS,
            self._apply_source_snapshot_timeout,
        )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and self._pending_library_source_open is None
        ):
            self._start_library_conversation_page_request(
                self._library_conversation_requested_page,
                self._library_conversation_requested_query,
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._library_media_view == "list"
            and self._pending_library_source_open is None
        ):
            self._request_library_media_browse(
                self._library_media_browse_controller.mutation_refresh_scope,
                focus_identity=None,
            )
            self._request_library_media_facets()
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._library_media_view == "trash"
            and self._pending_library_source_open is None
        ):
            self._library_media_trash_query_draft = ""
            self._library_media_trash_input_error = ""
            self._library_media_trash_type_choices_visible = False
            self._library_media_trash_browse_controller.invalidate()
            self._library_media_trash_browse_controller.state = MediaTrashBrowseState()
            self._library_media_trash_browse_controller.request(
                MediaTrashScope(),
                origin="entry",
                focus_identity="#library-media-trash-row-0",
            )
        self._refresh_local_source_snapshot()
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            self._request_library_notes_tree_initial_load()
        if (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_PROMPTS, LIBRARY_ROW_CREATE_PROMPT)
            and self._library_prompts_view == "list"
        ):
            self._request_library_prompts_browse(
                self._library_prompt_browse_controller.scope,
                focus_identity=None,
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
            and self._library_skills_view == "list"
        ):
            # A restored Skills route may begin its exact page before mount,
            # when Textual cannot own a worker yet. Re-kick the retained scope
            # here just like Prompts, Media, and Collections so it cannot stay
            # stranded in its Loading projection after a tab revisit.
            self._request_library_skills_browse(
                self._library_skills_browse_controller.mutation_refresh_scope,
                focus_identity=None,
            )
        registry = self._library_ingest_registry()
        if registry is not None:
            counts_fn = getattr(registry, "counts", None)
            if callable(counts_fn):
                # Seed from whatever the registry already knows so a
                # freshly composed screen doesn't treat jobs that finished
                # during a previous Library visit as a brand-new
                # done-transition and fire a redundant snapshot refresh.
                self._library_ingest_last_done_count = counts_fn().get("done", 0)
            registry.add_listener(self._handle_library_ingest_registry_changed)
            add_progress_listener = getattr(registry, "add_progress_listener", None)
            if callable(add_progress_listener):
                add_progress_listener(self._handle_library_ingest_progress_changed)
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            self.run_worker(
                self._load_library_collections_capture_entry(),
                exclusive=True,
                group="library_collections_capture_entry",
            )
        if (
            self._library_notes_view == "editor"
            and self._selected_note_id
            and self._library_note_detail is None
        ):
            # Mirrors the collections case above: a note_id deep-link applied
            # before mount cannot run_worker yet, so the detail fetch is
            # deferred to here once the canvas has actually been composed.
            self.run_worker(
                self._refresh_library_note_detail(
                    self._selected_note_id,
                    entry_origin=True,
                ),
                exclusive=True,
                group="library_note_detail",
            )
        if (
            self._library_media_view == "viewer"
            and self._selected_media_id
            and self._library_media_detail is None
        ):
            # Cross-visit state restore (``restore_state``) sets the media
            # viewer's selection/view attrs before mount the same way a
            # note_id nav-context deep-link does above, but -- unlike that
            # case -- nothing else pre-mount kicks off the detail fetch:
            # ``handle_library_media_row`` (the only other caller of
            # ``_refresh_library_media_detail``) only runs from a live row
            # click. Without this, a restored viewer would render its
            # "Loading media…" placeholder forever. Deleted-record safety
            # uses the permanent Reader's explicit error + Retry surface,
            # matching a live row whose backing record vanished before open.
            if self._library_media_reader_session.pending_request is None:
                reader_identity = self._library_media_reader_identity(
                    self._selected_media_id
                )
                if reader_identity is not None:
                    canonical_id, backing_id = reader_identity
                    self._library_media_reader_session = begin_selection(
                        self._library_media_reader_session,
                        canonical_id,
                        backing_id,
                        self._selected_media_id,
                        immediate=True,
                    )
            self.run_worker(
                self._refresh_library_media_detail(
                    self._selected_media_id,
                    entry_origin=True,
                ),
                exclusive=True,
                group="library_media_detail",
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT
            and self._library_export_counts is None
        ):
            # Same restored-placeholder class as the media viewer/notes
            # editor above: a cross-visit ``restore_state`` (or a tab
            # round-trip whose ``save_state`` persisted
            # ``_library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT``)
            # lands a fresh instance on the export canvas with
            # ``_library_export_counts is None`` -> the scope line renders
            # "Counting…" and Export stays disabled. But the counts worker
            # is only kicked from the two LIVE entry points
            # (``_select_library_rail_row`` and
            # ``_open_library_export_canvas``), never from a restore --
            # so without this re-kick the form would stay stuck
            # "Counting…" with Export permanently disabled until the user
            # clicked another rail row and back. Mirrors
            # ``_select_library_rail_row``'s own post-recompose kick. The
            # ``is None`` guard keeps this from redundantly re-running when
            # counts already landed (they never survive a restore today --
            # ``save_state`` doesn't persist them -- but the guard makes
            # the intent explicit and is cheap insurance).
            self._start_library_export_counts_worker()
        if self._pending_library_source_open is not None:
            self.run_worker(
                self._open_pending_library_source(),
                exclusive=True,
                group="library_nav_open_source",
            )

    async def on_unmount(self) -> None:
        """Unregister the ingest registry listener registered in ``on_mount``.

        ``on_unmount`` (not ``on_screen_suspend``) is the correct pairing:
        listener add/remove must be symmetric with the mount/unmount
        cycle, not the temporary suspend/resume pair a screen gets while
        merely covered by another screen on the stack (suspend does not
        tear down this screen, so pairing removal with it would silently
        stop live updates while
        still fully composed and, per the plan brief, still able to
        resume). The registry itself is a plain in-memory object owned by
        the app, not this screen, and can keep firing mutations long after
        this screen is gone -- the listener body also guards on
        ``self.is_mounted`` (belt and braces, matching this file's
        established convention elsewhere), though note that in this
        Textual version ``is_mounted`` tracks "has been mounted at least
        once" rather than "currently mounted" (it is never reset back to
        ``False`` after removal) -- so this call is what actually closes
        the window, not the guard.
        """
        self._disarm_library_list_entry_focus()
        self._invalidate_library_notes_tree_for_unmount()
        self._library_conversation_reader_mounted_authority = False
        self._invalidate_library_conversation_reader_authority()
        self._library_notes_sync_controller.invalidate_for_remount()
        # A local thread read may outlive this screen. Revoke apply authority
        # before any awaited shutdown work can yield back to its completion.
        self._library_onboarding_generation += 1
        self._library_conversation_request_generation += 1
        self._invalidate_library_prompts_browse()
        self._library_skills_browse_controller.invalidate()
        self._invalidate_library_prompt_detail_generation()
        self._library_media_lifecycle_generation += 1
        self._library_media_return_settlement = None
        self._library_media_last_settlement_outcome = None
        self._library_media_current_owner = None
        self._library_media_geometry_floor_owner_identity = None
        self._library_media_geometry_floor = 0
        self._library_media_trash_mounted_authority = False
        self._library_media_browse_controller.invalidate()
        self._library_media_trash_browse_controller.invalidate()
        if self._library_collections_capture_controller is not None:
            self._library_collections_capture_controller.unmount()
        lifecycle_worker = self._library_lifecycle_persist_worker
        if lifecycle_worker is not None and not lifecycle_worker.is_finished:
            try:
                await lifecycle_worker.wait()
            except Exception:
                logger.opt(exception=True).warning(
                    "Pending Library lifecycle write failed during unmount."
                )
        if self._library_lifecycle_pending_persist is not None:
            await self._drain_library_lifecycle_persistence()
        # TASK-22210: the last captured reading position must survive
        # teardown. Await the drainer, then re-queue a value it may have
        # been cancelled under mid-write (the abandoned thread may or may
        # not have committed; the upsert is idempotent, so rewriting the
        # ambiguous value is harmless), then drain any residue inline.
        progress_worker = self._library_media_progress_write_worker
        if progress_worker is not None and not progress_worker.is_finished:
            try:
                await progress_worker.wait()
            except Exception:
                logger.opt(exception=True).warning(
                    "Pending Library media progress write failed during unmount."
                )
        inflight = self._library_media_progress_inflight_write
        if inflight is not None:
            self._library_media_progress_inflight_write = None
            self._library_media_progress_pending_writes.setdefault(
                inflight[0], (inflight[1], inflight[2])
            )
        if self._library_media_progress_pending_writes:
            await self._drain_library_media_progress_writes()
        self._library_note_import_controller.cancel()
        workspace = self._library_file_notes_workspace
        if workspace is not None:
            await workspace.shutdown()
        self._invalidate_library_note_autosave()
        self._library_prompt_collections_controller.invalidate()
        self._clear_library_prompt_selection(announce=False)
        self._library_prompt_mutation_disabled_states.clear()
        self._invalidate_library_external_submission()
        super().on_unmount()
        registry = self._library_ingest_registry()
        if registry is not None:
            registry.remove_listener(self._handle_library_ingest_registry_changed)
            remove_progress_listener = getattr(
                registry, "remove_progress_listener", None
            )
            if callable(remove_progress_listener):
                remove_progress_listener(self._handle_library_ingest_progress_changed)

    @staticmethod
    def _restore_library_prompts_scope(state: Mapping[str, Any]) -> PromptBrowseScope:
        """Return a dispatch-safe applied Prompt scope from screen state."""
        saved = state.get("library_prompts_scope")
        if isinstance(saved, PromptBrowseScope):
            raw = dataclasses.asdict(saved)
        elif type(saved) is dict:
            raw = saved
        else:
            legacy_sort = state.get("library_prompts_sort")
            legacy_query = state.get("library_prompts_filter")
            raw = {
                "query": legacy_query if type(legacy_query) is str else "",
                "sort_by": "name" if legacy_sort == "name" else "last_modified",
                "sort_order": "asc" if legacy_sort == "name" else "desc",
            }

        query = raw.get("query", "")
        if type(query) is not str:
            query = ""
        page = raw.get("page", 1)
        max_page = (2**63 - 1) // DEFAULT_PROMPT_BROWSE_PAGE_SIZE + 1
        if type(page) is not int or not 1 <= page <= max_page:
            page = 1
        try:
            return PromptBrowseScope(
                query=query,
                collection_id=raw.get("collection_id"),
                sort_by=raw.get("sort_by", "last_modified"),
                sort_order=raw.get("sort_order", "desc"),
                page=page,
                page_size=DEFAULT_PROMPT_BROWSE_PAGE_SIZE,
            )
        except (TypeError, ValueError):
            return PromptBrowseScope()

    @staticmethod
    def _restore_library_skills_scope(state: Mapping[str, Any]) -> SkillBrowseScope:
        """Return a dispatch-safe applied Skills scope from screen state."""
        saved = state.get("library_skills_scope")
        if isinstance(saved, SkillBrowseScope):
            raw = dataclasses.asdict(saved)
        elif type(saved) is dict:
            raw = saved
        else:
            raw = {
                "query": state.get("library_skills_filter", ""),
                "sort": state.get("library_skills_sort", "name"),
                "page": 1,
            }
        query = raw.get("query", "")
        page = raw.get("page", 1)
        if type(query) is not str:
            query = ""
        if type(page) is not int or not 1 <= page <= MAX_SKILL_BROWSE_PAGE:
            page = 1
        try:
            return SkillBrowseScope(
                query=query,
                sort=raw.get("sort", "name"),
                page=page,
                page_size=DEFAULT_SKILL_BROWSE_PAGE_SIZE,
            )
        except (TypeError, ValueError):
            return SkillBrowseScope()

    @staticmethod
    def _restore_library_collections_page(state: Mapping[str, Any]) -> int:
        """Return one strict page number for the capture reader."""
        page = state.get("library_collections_page", 1)
        return page if type(page) is int and 1 <= page <= 2**31 - 1 else 1

    def save_state(self) -> dict[str, Any]:
        """Persist Library selection/view state for the next visit.

        Only lightweight selection, view, and browse-request scope is captured
        -- never bulk fetched snapshots (``_local_source_records`` and friends
        re-fetch fresh on the next mount's ``_refresh_local_source_snapshot``,
        and a restored id may be stale by then) or note editor text
        (``flush_pending_work`` has already persisted any dirty edit to the DB
        before the app calls this). The ingest form/queue, rail collapse
        preferences, and search history are deliberately excluded here: they
        are already persisted elsewhere (the app-owned ingest job registry and
        the CLI config, respectively) and re-seeding them from this in-memory
        dict would fight those owners.

        The RAG results tuple and settled retrieval/recovery state are safe to
        carry because their rows are frozen dataclasses. A transient
        ``searching`` value may be snapshotted while admitted work drains, but
        ``restore_state`` normalizes it because a fresh screen owns no matching
        worker.

        The media type cycle, notes sort/filter, selected prompt id, and
        conversations query are view/selection state. Prompt restore carries
        only the last successfully applied scope; drafts, failures, rows, and
        transient loading state stay with the current screen instance. Its
        immutable fields are saved as a primitive mapping and fetched fresh.
        ``_library_notes_filter_records`` is likewise never persisted because
        it is a derived/bulk snapshot recomputed from the saved notes filter.
        """
        state = super().save_state()
        continue_receipt = self._library_continue_receipt_for_current_route()
        if continue_receipt is not None:
            self._library_continue_receipt = continue_receipt
        state["library_continue_receipt"] = self._copy_library_continue_receipt(
            self._library_continue_receipt
        )
        state["library_selected_row_id"] = self._library_selected_row_id
        state["selected_conversation_id"] = self._selected_conversation_id
        state["selected_note_id"] = self._selected_note_id
        state["library_notes_view"] = self._library_notes_view
        state["selected_media_id"] = self._selected_media_id
        state["library_media_view"] = self._library_media_view
        state["library_rag_query"] = self._library_rag_query
        state["library_rag_mode"] = self._library_rag_mode
        state["library_rag_scope_deselected"] = set(self._library_rag_scope_deselected)
        state["library_rag_results"] = tuple(self._library_rag_results)
        state["library_rag_selected_result_id"] = self._library_rag_selected_result_id
        state["library_rag_retrieval_status"] = self._library_rag_retrieval_status
        state["library_rag_recovery_state"] = self._library_rag_recovery_state
        state["library_rag_diagnostics"] = dict(self._library_rag_diagnostics)
        state["library_rag_searched_query"] = self._library_rag_searched_query
        # PR-3 Task 4: the answer travels with the results it was generated
        # from -- same lifecycle as the two fields above, and for the same
        # reason (a `LibraryRagAnswer` is a frozen dataclass, so it is safe
        # to carry verbatim). `_library_rag_answer_in_flight` is deliberately
        # absent: see its `__init__` comment.
        state["library_rag_answer"] = self._library_rag_answer
        state["library_rag_answer_query"] = self._library_rag_answer_query
        state["library_rag_answer_mode"] = self._library_rag_answer_mode
        applied_media = self._library_media_browse_controller.applied_result
        state["library_media_scope"] = dataclasses.asdict(
            applied_media.scope if applied_media is not None else MediaBrowseScope()
        )
        state["library_notes_sort"] = self._library_notes_sort
        state["library_notes_filter"] = self._library_notes_filter
        applied_prompts = self._library_prompt_browse_controller.applied_result
        state["library_prompts_scope"] = dataclasses.asdict(
            applied_prompts.scope
            if applied_prompts is not None
            else PromptBrowseScope()
        )
        applied_skills = self._library_skills_browse_controller.applied_result
        state["library_skills_scope"] = dataclasses.asdict(
            applied_skills.scope if applied_skills is not None else SkillBrowseScope()
        )
        capture_controller = self._library_collections_capture_controller
        applied_collections = (
            capture_controller.state.applied_scope
            if capture_controller is not None
            else None
        )
        state["library_collections_page"] = (
            applied_collections.page if applied_collections is not None else 1
        )
        state["selected_prompt_id"] = self._selected_prompt_id
        conversation_applied = self._library_conversation_freshness != "uninitialized"
        state["library_conversation_page"] = (
            self._library_conversation_page if conversation_applied else 1
        )
        state["library_conversation_query"] = (
            self._library_conversation_query if conversation_applied else ""
        )
        # task-2858 AC#3 (LIB-12): extend the receipt's durability past a
        # full navigate-away-and-back, not just within-instance canvas
        # switches (see the field's own ``__init__`` comment).
        state["library_export_last_path"] = self._library_export_last_path
        state["library_export_last_at"] = self._library_export_last_at
        return state

    @staticmethod
    def _copy_library_continue_receipt(
        receipt: Mapping[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Detach the small primitive returning-Library receipt."""

        if receipt is None:
            return None
        scope = dict(receipt["scope"])
        deselected = scope.get("scope_deselected")
        if isinstance(deselected, list):
            scope["scope_deselected"] = list(deselected)
        return {
            "version": receipt["version"],
            "row_id": receipt["row_id"],
            "scope": scope,
            "source_list_adjusted": receipt["source_list_adjusted"],
        }

    def _library_continue_receipt_for_current_route(self) -> dict[str, Any] | None:
        """Return an authoritative, content-free receipt for the active source."""

        row_id = self._library_selected_row_id
        scope: dict[str, Any]
        source_list_adjusted = False

        if row_id == LIBRARY_ROW_BROWSE_MEDIA:
            if self._library_media_view == "trash":
                return None
            applied = self._library_media_browse_controller.applied_result
            if applied is None:
                return None
            media_scope = applied.scope
            scope = {
                "query": media_scope.query,
                "media_type": media_scope.media_type,
                "sort_by": media_scope.sort_by,
                "page": media_scope.page,
            }
            source_list_adjusted = self._library_media_view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            applied = self._library_prompt_browse_controller.applied_result
            if applied is None:
                return None
            prompt_scope = applied.scope
            scope = {
                "query": prompt_scope.query,
                "collection_id": prompt_scope.collection_id,
                "sort_by": prompt_scope.sort_by,
                "sort_order": prompt_scope.sort_order,
                "page": prompt_scope.page,
            }
            source_list_adjusted = self._library_prompts_view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            if (
                not self._library_conversation_page_loaded
                or self._library_conversation_freshness not in {"fresh", "stale"}
            ):
                return None
            scope = {
                "page": self._library_conversation_page,
                "query": self._library_conversation_query,
            }
        elif row_id == LIBRARY_ROW_BROWSE_NOTES:
            if (
                self._library_notes_source != LIBRARY_NOTES_SOURCE_DATABASE
                or not self._library_loaded
                or self._library_lookup_error
            ):
                return None
            scope = {
                "sort": self._library_notes_sort,
                "filter": self._library_notes_filter,
            }
            source_list_adjusted = self._library_notes_view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
            applied = self._library_skills_browse_controller.applied_result
            if applied is None:
                return None
            skill_scope = applied.scope
            scope = {
                "sort": skill_scope.sort,
                "filter": skill_scope.query,
                "page": skill_scope.page,
            }
            source_list_adjusted = self._library_skills_view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            controller = self._library_collections_capture_controller
            applied = controller.state.applied_scope if controller is not None else None
            if applied is None or controller.state.page_stale:
                return None
            scope = {"page": applied.page}
        elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
            if self._library_rag_retrieval_status not in {"ready", "empty"}:
                return None
            scope = {
                "query": self._library_rag_searched_query,
                "mode": self._library_rag_mode,
                "scope_deselected": sorted(self._library_rag_scope_deselected),
            }
        else:
            return None

        return {
            "version": 1,
            "row_id": row_id,
            "scope": scope,
            "source_list_adjusted": source_list_adjusted,
        }

    @classmethod
    def _restore_library_continue_receipt(
        cls,
        value: object,
    ) -> dict[str, Any] | None:
        """Validate one versioned receipt without recovering private row data."""

        if type(value) is not dict or set(value) != {
            "version",
            "row_id",
            "scope",
            "source_list_adjusted",
        }:
            return None
        if type(value["version"]) is not int or value["version"] != 1:
            return None
        if type(value["source_list_adjusted"]) is not bool:
            return None
        row_id = value["row_id"]
        raw_scope = value["scope"]
        if type(row_id) is not str or type(raw_scope) is not dict:
            return None

        try:
            if row_id == LIBRARY_ROW_BROWSE_MEDIA:
                if set(raw_scope) != {"query", "media_type", "sort_by", "page"}:
                    return None
                normalized = MediaBrowseScope(**raw_scope)
                scope = {
                    "query": normalized.query,
                    "media_type": normalized.media_type,
                    "sort_by": normalized.sort_by,
                    "page": normalized.page,
                }
            elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
                if set(raw_scope) != {
                    "query",
                    "collection_id",
                    "sort_by",
                    "sort_order",
                    "page",
                }:
                    return None
                normalized_prompt = PromptBrowseScope(**raw_scope)
                scope = {
                    "query": normalized_prompt.query,
                    "collection_id": normalized_prompt.collection_id,
                    "sort_by": normalized_prompt.sort_by,
                    "sort_order": normalized_prompt.sort_order,
                    "page": normalized_prompt.page,
                }
            elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                if set(raw_scope) != {"page", "query"}:
                    return None
                page = raw_scope["page"]
                query = raw_scope["query"]
                if (
                    type(page) is not int
                    or cls._normalize_library_conversation_page(page) != page
                    or type(query) is not str
                ):
                    return None
                scope = {"page": page, "query": query.strip()[:200]}
            elif row_id == LIBRARY_ROW_BROWSE_NOTES:
                if set(raw_scope) != {"sort", "filter"}:
                    return None
                sort = raw_scope["sort"]
                filter_value = raw_scope["filter"]
                if (
                    sort not in {"newest", "oldest", "title"}
                    or type(filter_value) is not str
                ):
                    return None
                scope = {"sort": sort, "filter": filter_value}
            elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
                if set(raw_scope) not in (
                    {"sort", "filter"},
                    {"sort", "filter", "page"},
                ):
                    return None
                sort = raw_scope["sort"]
                filter_value = raw_scope["filter"]
                page = raw_scope.get("page", 1)
                normalized_skill = SkillBrowseScope(
                    query=filter_value,
                    sort=sort,
                    page=page,
                )
                scope = {
                    "sort": normalized_skill.sort,
                    "filter": normalized_skill.query,
                    "page": normalized_skill.page,
                }
            elif row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
                if set(raw_scope) not in (set(), {"page"}):
                    return None
                page = raw_scope.get("page", 1)
                if type(page) is not int or not 1 <= page <= 2**31 - 1:
                    return None
                scope = {"page": page}
            elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
                if set(raw_scope) != {"query", "mode", "scope_deselected"}:
                    return None
                query = raw_scope["query"]
                mode = raw_scope["mode"]
                deselected = raw_scope["scope_deselected"]
                if (
                    type(query) is not str
                    or mode not in {"search", "rag"}
                    or type(deselected) is not list
                    or any(type(item) is not str for item in deselected)
                    or len(set(deselected)) != len(deselected)
                    or not set(deselected).issubset(
                        LIBRARY_RAG_SCOPE_TOGGLE_SOURCE_TYPES
                    )
                ):
                    return None
                scope = {
                    "query": query,
                    "mode": mode,
                    "scope_deselected": sorted(deselected),
                }
            else:
                return None
        except (TypeError, ValueError):
            return None

        return {
            "version": 1,
            "row_id": row_id,
            "scope": scope,
            "source_list_adjusted": value["source_list_adjusted"],
        }

    def restore_state(self, state: dict[str, Any]) -> None:
        """Restore Library selection/view state saved by ``save_state``.

        The app calls this on a freshly-constructed, not-yet-mounted
        instance BEFORE ``switch_screen`` mounts it, so these attrs are
        exactly what ``on_mount`` and the first ``compose_content`` see.

        Stale-id safety (the record was deleted or is otherwise gone by the
        time the user comes back): the conversations and media LIST canvases
        already fall back to the first displayed row when the restored id is
        absent (``build_library_conversations_state`` /
        ``build_library_media_state``); the notes-editor and media-viewer
        deep-link fetches this triggers from ``on_mount`` recover when the id
        no longer resolves (``_refresh_library_note_detail`` returns Notes to
        its list; ``_refresh_library_media_detail`` keeps the permanent Reader
        mounted with an explicit Retry state).
        A restored ``editor``/``viewer`` view with no matching selected id
        (should never happen, but a saved-state dict is not statically typed)
        degrades to the list view below rather than rendering a permanent
        loading placeholder.

        The per-pane filter/sort values restored below are read by the
        canvas builders at mount time (``_build_library_media_state``,
        the notes canvas branch of ``compose_content``,
        ``_build_library_conversations_state``) -- setting them here, before
        ``switch_screen`` mounts this instance, makes the first paint reflect
        them. A restored conversation query is then reissued once by the real
        source refresh so it searches the complete dataset rather than the
        cached first-page sample. The conversations query is user text
        re-sanitized through ``_safe_text`` here too -- it was
        already sanitized once when the user submitted it
        (``handle_library_conversations_filter_submitted``), but a saved-
        state dict is not statically typed, so this is defense against a
        corrupted/foreign dict rather than a real double-sanitization of
        trusted input.
        """
        super().restore_state(state)
        if not isinstance(state, dict):
            return

        has_continue_receipt = "library_continue_receipt" in state
        continue_receipt = self._restore_library_continue_receipt(
            state.get("library_continue_receipt")
        )
        self._library_continue_receipt = continue_receipt
        self._library_selected_row_id = (
            ""
            if has_continue_receipt
            else str(state.get("library_selected_row_id") or "")
        )
        self._selected_conversation_id = str(
            state.get("selected_conversation_id") or ""
        )

        selected_note_id = str(state.get("selected_note_id") or "")
        notes_view = str(state.get("library_notes_view") or "list")
        if notes_view == "editor" and not selected_note_id:
            notes_view = "list"
        self._selected_note_id = selected_note_id
        self._library_notes_view = notes_view

        selected_media_id = str(state.get("selected_media_id") or "")
        media_view = str(state.get("library_media_view") or "list")
        if media_view == "viewer" and not selected_media_id:
            media_view = "list"
        # task-4025: the Trash view is session-transient -- its fetched
        # page is never persisted, so a restored session lands on the
        # media list (which is where its "Trash" entry point lives)
        # rather than an unloaded Trash shell nothing would populate.
        if media_view == "trash":
            media_view = "list"
        self._selected_media_id = selected_media_id
        self._library_media_view = media_view

        self._library_rag_query = str(state.get("library_rag_query") or "")
        rag_mode = state.get("library_rag_mode")
        self._library_rag_mode = rag_mode if rag_mode in ("search", "rag") else "search"
        scope_deselected = state.get("library_rag_scope_deselected")
        self._library_rag_scope_deselected = (
            set(scope_deselected)
            if isinstance(scope_deselected, (set, frozenset, list, tuple))
            else set()
        )
        rag_results = state.get("library_rag_results")
        self._library_rag_results = (
            tuple(rag_results) if isinstance(rag_results, (list, tuple)) else ()
        )
        self._library_rag_selected_result_id = str(
            state.get("library_rag_selected_result_id") or ""
        )
        restored_retrieval_status = str(state.get("library_rag_retrieval_status") or "")
        self._library_rag_retrieval_status = (
            ""
            if restored_retrieval_status == "searching"
            else restored_retrieval_status
        )
        recovery_state = state.get("library_rag_recovery_state")
        self._library_rag_recovery_state = (
            recovery_state
            if isinstance(recovery_state, DestinationRecoveryState)
            else None
        )
        rag_diagnostics = state.get("library_rag_diagnostics")
        self._library_rag_diagnostics = (
            dict(rag_diagnostics) if isinstance(rag_diagnostics, Mapping) else {}
        )
        self._library_rag_searched_query = str(
            state.get("library_rag_searched_query") or ""
        )
        rag_answer = state.get("library_rag_answer")
        self._library_rag_answer = (
            rag_answer if isinstance(rag_answer, LibraryRagAnswer) else None
        )
        self._library_rag_answer_query = str(
            state.get("library_rag_answer_query") or ""
        )
        rag_answer_mode = state.get("library_rag_answer_mode")
        self._library_rag_answer_mode = (
            rag_answer_mode if rag_answer_mode in ("search", "rag") else ""
        )
        # `_library_rag_answer_in_flight` (and its Task 3 companion,
        # `_library_rag_answer_in_flight_provider`) are intentionally left
        # at their `__init__` defaults (False / ""): this instance has no
        # answer worker running, so restoring an in-flight "answering"
        # status would be a dangling one nothing could ever resolve.

        restored_media_scope = self._restore_library_media_scope(state)
        self._library_media_browse_controller.invalidate(restored_media_scope)
        self._library_media_type_filter = restored_media_scope.media_type
        notes_sort = state.get("library_notes_sort")
        self._library_notes_sort = (
            notes_sort if isinstance(notes_sort, str) and notes_sort else "newest"
        )
        notes_filter = state.get("library_notes_filter")
        self._library_notes_filter = (
            notes_filter if isinstance(notes_filter, str) else ""
        )
        restored_prompts_scope = self._restore_library_prompts_scope(state)
        self._library_prompt_browse_controller.invalidate(restored_prompts_scope)
        restored_skills_scope = self._restore_library_skills_scope(state)
        self._library_skills_browse_controller.invalidate(restored_skills_scope)
        self._library_skills_sort = restored_skills_scope.sort
        self._library_skills_filter = restored_skills_scope.query
        self._library_collections_requested_page = (
            self._restore_library_collections_page(state)
        )
        selected_prompt_id = state.get("selected_prompt_id")
        self._selected_prompt_id = (
            selected_prompt_id if isinstance(selected_prompt_id, int) else None
        )
        self._library_conversation_page_records = ()
        self._library_conversation_page = 1
        self._library_conversation_query = ""
        self._library_conversation_total = 0
        self._library_conversation_total_known = False
        self._library_conversation_has_more = False
        self._library_conversation_page_loaded = False
        self._library_conversation_loading = False
        self._library_conversation_error = ""
        self._library_conversation_freshness = "uninitialized"
        self._library_conversation_stale_copy = ""
        self._library_conversation_selection_notice = ""
        self._library_conversation_focus_after_apply = ""
        self._library_conversations_select_mode = False
        self._library_conversations_row_selection.clear()
        conversation_query = state.get("library_conversation_query")
        self._library_conversation_requested_query = self._safe_text(
            conversation_query if isinstance(conversation_query, str) else "",
            "",
            max_length=200,
        )
        self._library_conversation_requested_page = (
            self._normalize_library_conversation_page(
                state.get("library_conversation_page")
            )
        )
        if continue_receipt is not None:
            scope = continue_receipt["scope"]
            row_id = continue_receipt["row_id"]
            if row_id == LIBRARY_ROW_BROWSE_MEDIA:
                receipt_media_scope = MediaBrowseScope(**scope)
                self._library_media_browse_controller.invalidate(receipt_media_scope)
                self._library_media_type_filter = receipt_media_scope.media_type
                self._library_media_view = "list"
                self._selected_media_id = ""
            elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
                receipt_prompt_scope = PromptBrowseScope(**scope)
                self._library_prompt_browse_controller.invalidate(receipt_prompt_scope)
                self._library_prompts_view = "list"
                self._selected_prompt_id = None
            elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                self._library_conversation_requested_page = scope["page"]
                self._library_conversation_requested_query = scope["query"]
                self._selected_conversation_id = ""
            elif row_id == LIBRARY_ROW_BROWSE_NOTES:
                self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
                self._library_notes_sort = scope["sort"]
                self._library_notes_filter = scope["filter"]
                self._library_notes_view = "list"
                self._selected_note_id = ""
            elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
                receipt_skills_scope = SkillBrowseScope(
                    query=scope["filter"],
                    sort=scope["sort"],
                    page=scope.get("page", 1),
                )
                self._library_skills_browse_controller.invalidate(receipt_skills_scope)
                self._library_skills_sort = receipt_skills_scope.sort
                self._library_skills_filter = receipt_skills_scope.query
                self._library_skills_view = "list"
                self._selected_skill_name = ""
            elif row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
                self._library_collections_requested_page = scope.get("page", 1)
            elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
                self._library_rag_query = scope["query"]
                self._library_rag_mode = scope["mode"]
                self._library_rag_scope_deselected = set(scope["scope_deselected"])
        # task-2858 AC#3 (LIB-12): restore the durable export receipt
        # (see the field's ``__init__`` comment) -- a foreign/corrupted
        # dict degrades to "no receipt yet" rather than raising.
        last_export_path = state.get("library_export_last_path")
        self._library_export_last_path = (
            last_export_path if isinstance(last_export_path, str) else ""
        )
        last_export_at = state.get("library_export_last_at")
        self._library_export_last_at = (
            float(last_export_at)
            if isinstance(last_export_at, (int, float))
            and not isinstance(last_export_at, bool)
            else None
        )
        # task-15459: re-seed from the cache now that ``_selected_
        # conversation_id`` above reflects the RESTORED id, not ``__init__``'s
        # empty default -- ``_apply_local_source_snapshot``'s carry-forward
        # (``_carry_selected_conversation_into_snapshot``) needs the real id
        # to know whether a not-on-the-cached-page selected conversation
        # must be prepended. Safe to call unconditionally: a cache miss here
        # is a no-op, and a hit is idempotent pre-mount attribute assignment
        # (see the method's own docstring).
        self._seed_local_source_snapshot_from_cache()

    def _seed_local_source_snapshot_from_cache(self) -> None:
        """Apply the app-scoped snapshot cache before this screen mounts.

        Called from both ``__init__`` and ``restore_state`` (task-15459) --
        the app calls both on a freshly constructed, not-yet-mounted
        instance before ``switch_screen`` mounts it (see ``restore_state``'s
        own docstring), so seeding here is what lets a warm revisit's FIRST
        ``compose_content`` already render the previous visit's data instead
        of the "Loading…" placeholder -- rather than composing once with
        that placeholder and then being forced into an immediate second,
        explicit ``refresh(recompose=True)`` from ``on_mount`` to correct it
        (that fallback still exists there, for the cache-miss/expired case
        this seed does not cover).

        Mirrors ``on_mount``'s own freshness check
        (``LIBRARY_SNAPSHOT_CACHE_TTL_SECONDS``) so a stale cache is never
        instant-applied here either.

        Safe to call this early: ``_apply_local_source_snapshot`` only
        touches the DOM (recompose / rail sync) when ``self.is_mounted`` is
        True, which is never the case at either call site, so a hit is a
        pure attribute assignment with no recompose or widget-query side
        effects.
        """
        cached_snapshot = getattr(
            self.app_instance, "_library_source_snapshot_cache", None
        )
        cached_stamp = getattr(
            self.app_instance, "_library_source_snapshot_cache_stamp", None
        )
        if (
            cached_snapshot is None
            or cached_stamp is None
            or time.monotonic() - cached_stamp >= LIBRARY_SNAPSHOT_CACHE_TTL_SECONDS
        ):
            return
        self._apply_local_source_snapshot(*cached_snapshot)

    def _file_notes_active(self) -> bool:
        """Return whether the retained File Notes workspace owns the canvas."""
        return (
            getattr(
                self,
                "_library_notes_source",
                LIBRARY_NOTES_SOURCE_DATABASE,
            )
            == LIBRARY_NOTES_SOURCE_FILES
            and getattr(self, "_library_selected_row_id", "")
            == LIBRARY_ROW_BROWSE_NOTES
            and getattr(self, "_library_file_notes_workspace", None) is not None
        )

    def _library_media_viewer_substate_active(self) -> bool:
        """True while the media viewer's edit/delete-confirm/analysis-edit
        sub-state is the live view (task-2856 review round 3).

        All three sub-states leave ``_library_media_view == "viewer"``
        unchanged (see ``handle_library_media_edit`` etc.), so they are
        otherwise indistinguishable from the plain read-only viewer to
        ``_register_footer_shortcuts`` -- but ``action_library_media_viewer_
        back`` only steps back ONE level while any of these is set (to the
        plain viewer, not the list), so the footer must not claim "back to
        list" while this is true.
        """
        return (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._library_media_view == "viewer"
            and (
                self._library_media_editing
                or self._library_media_confirming_delete
                or self._library_media_editing_analysis
            )
        )

    def _library_note_editor_active(self) -> bool:
        """True while the in-canvas DATABASE note editor is the live view (task-2856).

        Scoped to Database Notes so this never
        overlaps ``_file_notes_active()`` -- Files mode has its own
        dedicated Escape gate and never sets ``_library_notes_view``.
        """
        return (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and getattr(
                self,
                "_library_notes_source",
                LIBRARY_NOTES_SOURCE_DATABASE,
            )
            == LIBRARY_NOTES_SOURCE_DATABASE
            and getattr(self, "_library_notes_view", "list") == "editor"
        )

    def _library_prompt_editor_active(self) -> bool:
        """True while the in-canvas prompt editor is the live view (task-2856).

        Mirrors ``_library_skill_editor_active``: the Create flow keeps
        ``_library_selected_row_id == LIBRARY_ROW_CREATE_PROMPT`` while its
        editor is open (never reassigned to ``LIBRARY_ROW_BROWSE_PROMPTS``
        -- see ``_enter_library_prompt_create_editor``), so both row ids
        are checked here.
        """
        return (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_PROMPTS, LIBRARY_ROW_CREATE_PROMPT)
            and getattr(self, "_library_prompts_view", "list") == "editor"
        )

    def _library_list_canvas_showing_list(self) -> bool:
        """True while Media/Notes/Prompts/Skills shows its plain LIST sub-view.

        The state task-2856's Escape-to-rail action targets: entering a
        detail/viewer/editor/create/sync sub-view of any of these four
        canvases returns False here (each of those has its own more
        specific Escape gate, or genuinely nothing to leave toward the
        rail for). Prompts/Skills also check the CREATE_* row id -- a
        "New prompt"/"New skill" editor exited back to the list never
        reassigns ``_library_selected_row_id`` away from CREATE_PROMPT/
        CREATE_SKILL (mirroring ``_library_skill_editor_active``'s own
        dual-row-id gate), so the list is genuinely showing under either
        id.
        """
        row_id = self._library_selected_row_id
        if row_id == LIBRARY_ROW_BROWSE_MEDIA:
            return getattr(self, "_library_media_view", "list") == "list"
        if row_id == LIBRARY_ROW_BROWSE_NOTES:
            return (
                getattr(
                    self,
                    "_library_notes_source",
                    LIBRARY_NOTES_SOURCE_DATABASE,
                )
                == LIBRARY_NOTES_SOURCE_DATABASE
                and getattr(self, "_library_notes_view", "list") == "list"
            )
        if row_id in (LIBRARY_ROW_BROWSE_PROMPTS, LIBRARY_ROW_CREATE_PROMPT):
            return getattr(self, "_library_prompts_view", "list") == "list"
        if row_id in (LIBRARY_ROW_BROWSE_SKILLS, LIBRARY_ROW_CREATE_SKILL):
            return getattr(self, "_library_skills_view", "list") == "list"
        if row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            return bool(self.query("#library-conversations-canvas"))
        return False

    def _library_conversation_focus_region(self) -> str:
        """Return the retained Conversations role containing current focus."""
        focused = self.focused
        if focused is None:
            return ""
        try:
            shell = self.query_one(
                "#library-conversations-reader-shell", LibraryAdaptiveReaderShell
            )
        except (NoMatches, QueryError):
            return ""
        for name, pane in (
            ("library", shell.library),
            ("items", shell.items),
            ("work", shell.work),
        ):
            if focused is pane or pane in focused.ancestors:
                return name
        return ""

    def _library_conversation_escape_label(self) -> str:
        """Name the nearest visible prior role reached by Escape."""
        region = self._library_conversation_focus_region()
        layout = self._library_conversation_reader_layout
        if region == "work" and layout.items_open:
            return "focus Items"
        if region in {"work", "items"} and layout.library_open:
            return "focus Library"
        return ""

    def _arm_library_list_entry_focus(
        self,
        *,
        media_return: _LibraryMediaReturnReceipt | None = None,
    ) -> None:
        """Request the primary list's first row be focused (task-2856 AC1).

        Call this (never ``call_after_refresh(self._focus_library_list_entry)``
        directly) from every "enter/return to a list canvas" seam -- a
        fresh rail-row press landing on Media/Notes/Prompts/Skills, and
        every "back to list" exit from that canvas's viewer/editor. Arms
        ``_library_pending_list_entry_focus`` for
        ``LIBRARY_LIST_ENTRY_FOCUS_ARMED_SECONDS`` (re-requested by
        ``compose_content`` on every recompose while armed -- see that
        flag's docstring in ``__init__`` for why a single-consume flag
        is not enough) IN ADDITION TO scheduling the immediate attempt.

        The settle window is a background-recompose safety net ONLY --
        review round 2 found the timer was the sole disarm path, so a
        user who Tabbed (or clicked) away from the list within the window
        had their navigation silently overridden by the next background
        recompose. ``on_key``/``on_descendant_focus`` now disarm
        IMMEDIATELY the moment the user does anything that is not the
        system re-focusing its own row (see both methods' docstrings), so
        the timer's only remaining job is bounding how long an IDLE list
        keeps re-requesting focus across its own chained background
        workers.

        PR #1410 review (Qodo): re-arming before a prior timer's own
        deadline (e.g. two "enter/return to list" seams firing back-to-
        back) used to leave that PRIOR timer scheduled underneath this
        one -- if it fired later it disarmed a request THIS arm still
        intended to keep active. The stored handle
        (``_library_list_entry_focus_timer``) is stopped here before the
        new one is scheduled, so only the most recent arm's timer is ever
        live.
        """
        self._library_media_successful_focus_ownership = None
        if self._library_list_entry_focus_timer is not None:
            self._library_list_entry_focus_timer.stop()
            self._library_list_entry_focus_timer = None
        self._library_list_entry_focus_deadline = (
            time.monotonic() + LIBRARY_LIST_ENTRY_FOCUS_ARMED_SECONDS
        )
        self._library_list_entry_focus_generation += 1
        self._library_pending_list_entry_focus = True
        self._library_pending_list_entry_media_return = media_return
        self._library_pending_list_entry_focus_anchor = self.focused
        settlement_media_return = self._library_media_return_candidate(media_return)
        if settlement_media_return:
            self._arm_library_media_return_settlement(media_return)
            # Preserve the bounded outer-arm continuation. It may construct
            # fresh authority after composition, but `_arm` still requires a
            # current owner's public geometry before exact settlement.
            self.call_after_refresh(
                self._focus_library_list_entry_if_current,
                self._library_list_entry_focus_generation,
            )
        elif media_return is None:
            self.call_after_refresh(self._focus_library_list_entry)
        else:
            self.call_after_refresh(
                self._focus_library_list_entry_if_current,
                self._library_list_entry_focus_generation,
            )
        if self._library_list_entry_focus_timer is None:
            self._library_list_entry_focus_timer = self.set_timer(
                LIBRARY_LIST_ENTRY_FOCUS_ARMED_SECONDS,
                self._disarm_library_list_entry_focus,
            )

    def _disarm_library_list_entry_focus(self) -> None:
        """End an entry-focus request's settle window (task-2856 AC1).

        Fired by: the timer ``_arm_library_list_entry_focus`` sets; the
        top of ``on_key`` for ANY key while the request is armed (the
        user doing anything at all is "taking control"; disarming an
        already-idle flag is a harmless no-op); or ``on_descendant_focus``
        the moment focus lands somewhere other than a row of the armed
        list (Tab, Shift+Tab, a mouse click -- anything that is not the
        system's own re-focus of its own row) -- whichever comes first.
        Also stops and clears the stored timer handle (PR #1410 review)
        so an interaction-driven disarm never leaves the settle-window
        timer dangling behind it.
        """
        self._library_list_entry_focus_generation += 1
        self._library_pending_list_entry_focus = False
        self._library_pending_list_entry_media_return = None
        self._library_pending_list_entry_focus_anchor = None
        self._library_media_return_settlement = None
        self._library_media_last_exact_settlement = None
        self._library_media_last_successful_settlement = None
        self._library_media_successful_focus_ownership = None
        self._library_media_last_settlement_attempt = None
        self._library_list_entry_focus_deadline = None
        if self._library_list_entry_focus_timer is not None:
            self._library_list_entry_focus_timer.stop()
            self._library_list_entry_focus_timer = None

    def _disarm_library_media_return_for_route_change(self) -> None:
        """Clear all transient Media-return state at an admitted route exit."""
        self._disarm_library_list_entry_focus()
        self._library_media_last_settlement_outcome = None
        self._library_notes_programmatic_focus_target = None

    def on_descendant_focus(self, event: DescendantFocus) -> None:
        """Record Notes focus intent and disarm foreign list-entry focus.

        The Notes workbench caches meaningful semantic focus changes so a
        breakpoint crossing can restore the same control and scroll owner.
        Independently, task-2856's list-entry settle window is disarmed as
        soon as focus leaves the list rows it owns.

        Textual posts ``DescendantFocus`` for every focus change, including
        the system's OWN ``_focus_library_list_entry()`` call -- that case
        must NOT immediately disarm what it just armed, so it is excluded
        by checking the newly-focused widget against the armed list's own
        row class. Anything else (Tab/Shift+Tab landing elsewhere in the
        canvas, a mouse click on a different control, `/` moving focus to
        the rail search box) disarms: the user has taken over, and a later
        background recompose must never yank focus back out from under
        them. Complements the unconditional disarm at the top of
        ``on_key`` -- this hook is what also covers mouse clicks, which
        never reach ``on_key`` at all.
        """
        focused = event.widget
        if focused is not self.focused:
            # Focus bubbles are queued. A transactional Media rollback may
            # restore its prior live focus before the abandoned target's
            # earlier bubble arrives; that stale event owns no authority.
            if self._library_notes_programmatic_focus_target is focused:
                self._library_notes_programmatic_focus_target = None
            return
        self._remember_library_notes_authority_focus(focused)
        target_restore = self._library_notes_programmatic_focus_target is focused
        pending_receipt = self._library_pending_list_entry_media_return
        successful_return_focus = bool(
            pending_receipt is not None
            and self._library_media_successful_focus_is_allowed(
                pending_receipt,
                pending_receipt.stable_id,
            )
        )
        programmatic = bool(
            target_restore
            or successful_return_focus
            or self._library_notes_restoring_focus
            or self._library_notes_resize_settling
        )
        if (
            self._library_pending_list_entry_focus
            and pending_receipt is not None
        ):
            guarded_return_focus = bool(
                (target_restore or successful_return_focus)
                and focused is not None
                and self._library_media_focus_target_matches_receipt(
                    focused,
                    pending_receipt,
                    pending_receipt.stable_id,
                )
            )
            if not guarded_return_focus:
                # Revoke the retained receipt before a genuine row selection
                # can recompose Media and expose any newer owner geometry.
                self._disarm_library_list_entry_focus()
        if (
            focused is not None
            and focused.has_class("library-media-row")
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and not self._library_media_select_mode
            and not programmatic
        ):
            media_id = str(getattr(focused, "media_id", "") or "")
            title = str(getattr(focused, "_library_media_title", "") or media_id)
            if media_id and media_id != self._selected_media_id:
                self._select_library_media_reader_row(media_id, title, immediate=False)
        if self.is_mounted:
            stage = self._library_notes_focus_stage(focused)
            relevant = bool(
                self._library_notes_workflow_active()
                or stage == "rail"
                or (
                    self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                    and self._library_media_view in {"list", "trash"}
                )
                or self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            )
            if target_restore:
                self._library_notes_programmatic_focus_target = None
            user_intent = relevant and not programmatic
            if user_intent:
                # Veto every older deferred restore before its next turn can
                # steal the control the user just chose.
                self._library_notes_focus_intent_generation += 1
                if self._library_notes_navigation_status:
                    LibraryScreen._supersede_library_notes_navigation(self)
            self.call_after_refresh(
                self._record_library_notes_focus_interaction,
                focused,
                user_intent,
            )
            if (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and self._library_media_view == "viewer"
            ):
                self._register_footer_shortcuts()

        if not self._library_pending_list_entry_focus:
            return
        if (
            (target_restore or successful_return_focus)
            and pending_receipt is not None
            and focused is not None
        ):
            if self._library_media_focus_target_matches_receipt(
                focused,
                pending_receipt,
                pending_receipt.stable_id,
            ):
                return
        row_class = _LIBRARY_LIST_ROW_CLASS_BY_ROW_ID.get(self._library_selected_row_id)
        widget = event.widget
        if row_class is not None and widget is not None and widget.has_class(row_class):
            return
        if (
            self._library_notes_restoring_focus
            and self._library_pending_list_entry_media_return is not None
        ):
            return
        self._disarm_library_list_entry_focus()

    def _focus_library_list_entry_if_current(self, generation: int) -> None:
        """Apply one semantic Media return only while its arm still owns focus."""
        if (
            self._library_pending_list_entry_focus
            and generation == self._library_list_entry_focus_generation
        ):
            receipt = self._library_pending_list_entry_media_return
            if self._library_media_return_candidate(receipt):
                self._arm_library_media_return_settlement(receipt)
                tree = self._library_media_settlement_tree()
                revised_row_without_origin = bool(
                    receipt is not None
                    and receipt.final_focus_policy == "row"
                    and not self._library_media_exact_return_candidate(receipt)
                    and tree is not None
                    and not self._library_media_semantic_row_is_current(
                        receipt,
                        tree[1],
                    )
                )
                if tree is None or revised_row_without_origin:
                    # Empty Media has no row-scroll geometry owner. Preserve
                    # its Import/recovery focus path; a revised list whose
                    # origin disappeared likewise uses its retained first row.
                    self._focus_library_list_entry()
                return
            self._focus_library_list_entry()

    def _focus_library_list_entry(self) -> None:
        """Focus the primary list's first row -- see ``_arm_library_list_entry_focus``.

        A no-op when the canvas isn't one of the four list canvases
        (nothing to focus), the list is empty, or the query can't resolve
        (e.g. a recompose still in flight).

        task-3020 AC3: while the Media canvas is in Select mode with a
        non-empty selection (a partial, or total, bulk-delete failure
        leaves the failed id(s) still checked, waiting for a retry), the
        first STILL-CHECKED row is preferred over the literal first row --
        landing keyboard focus on a row the user never selected would be
        a worse regression than the original "nothing focused" bug this
        method exists to fix. Every other caller is unaffected: the
        preference requires BOTH the Media row class and a non-empty
        selection, so notes/prompts/skills (no row_selection concept
        here) and Media outside an active selection (e.g. the bulk
        delete's own full-success path, which clears the selection before
        arming this) fall straight through to the plain first-row
        behavior, unchanged from before.
        """
        if self._library_emergency_stage == "rail-only":
            return
        row_class = _LIBRARY_LIST_ROW_CLASS_BY_ROW_ID.get(self._library_selected_row_id)
        if row_class is None:
            return
        rows = list(self.query(f".{row_class}"))
        if not rows:
            fallback_selector = {
                "library-prompt-row": "#library-prompts-filter",
                "library-skill-row": f"#{LIBRARY_SKILLS_FILTER_ID}",
            }.get(row_class)
            if fallback_selector is not None:
                try:
                    control = self.query_one(fallback_selector, Widget)
                except (NoMatches, QueryError):
                    pass
                else:
                    self.set_focus(control)
                    return
            if row_class == "library-media-row":
                for selector in (
                    "#library-media-type-filter",
                    "#library-media-empty-clear-type",
                    "#library-media-empty-import",
                    "#library-media-retry",
                ):
                    try:
                        control = self.query_one(selector, Widget)
                    except (NoMatches, QueryError):
                        continue
                    if not getattr(control, "disabled", False):
                        self._library_notes_programmatic_focus_target = control
                        self.set_focus(control)
                        return
            return
        if (
            row_class == "library-media-row"
            and self._library_media_select_mode
            and self._library_media_row_selection.count
        ):
            for row in rows:
                if self._library_media_row_selection.is_selected(
                    getattr(row, "media_id", "")
                ):
                    self.set_focus(row)
                    return
        target = rows[0]
        media_return = self._library_pending_list_entry_media_return
        if row_class == "library-media-row" and media_return is not None:
            target = next(
                (
                    row
                    for row in rows
                    if str(getattr(row, "media_id", "") or "")
                    == media_return.stable_id
                ),
                target,
            )
        if row_class == "library-media-row":
            # Initial entry focus is system-owned just like a viewer return;
            # it must not be mistaken for user row selection by
            # ``on_descendant_focus`` and activate the Reader before Enter.
            self._library_notes_programmatic_focus_target = target
        self.set_focus(target, scroll_visible=False)
        if row_class == "library-media-row" and media_return is not None:
            scroll_offset = media_return.scroll_offset
            if scroll_offset is not None:
                try:
                    scroll = self.query_one("#library-media-row-scroll", Widget)
                except (NoMatches, QueryError):
                    return
                scroll.scroll_to(
                    x=max(0, min(scroll_offset[0], int(scroll.max_scroll_x))),
                    y=max(0, min(scroll_offset[1], int(scroll.max_scroll_y))),
                    animate=False,
                    force=True,
                    immediate=True,
                )

    async def _flush_active_file_notes(self) -> bool:
        """Delegate the common leave guard only while Files owns Notes."""
        if not self._file_notes_active():
            return True
        assert self._library_file_notes_workspace is not None
        return await self._library_file_notes_workspace.flush_pending_work()

    def _acquire_file_notes_transition(
        self,
        kind: Literal["screen", "source"],
    ) -> Callable[[], None] | Literal[False] | None:
        """Synchronously admit a transition for the active exact root binding."""
        if not self._file_notes_active():
            return None
        assert self._library_file_notes_workspace is not None
        return self._library_file_notes_workspace.acquire_transition(kind)

    def acquire_navigation_transition(
        self,
    ) -> Callable[[], None] | Literal[False] | None:
        """Admit outgoing screen navigation after the awaited leave flush."""
        if self._library_prompts_mutation_in_flight:
            return False
        return self._acquire_file_notes_transition("screen")

    async def flush_pending_work(self) -> bool:
        """Persist pending note edits before the app navigates away.

        The app awaits this from ``handle_screen_navigation`` before
        discarding this screen instance -- without it, a note edit whose
        debounced autosave has not fired yet (the timer re-arms on every
        keystroke) would be destroyed with the screen when the user switches
        tabs mid-edit.

        Returns:
            True only for the coordinator's typed ``PERMITTED`` result and
            successful prompt/skill barriers. Conflict, failure, validation,
            blocked, and stale Notes outcomes all veto navigation even when a
            presentation scalar or snapshot appears clean.
        """
        if self._library_prompts_mutation_in_flight:
            return False
        file_notes_flush_allowed = await self._flush_active_file_notes()
        note_flush = await self._flush_library_note_save()
        prompt_flush_allowed = await self._flush_library_prompt_save()
        skill_flush_allowed = await self._flush_library_skill_save()
        if not prompt_flush_allowed:
            self._notify_prompt_dirty_veto()
        if not skill_flush_allowed:
            # task-449: the app-level navigation veto only logs, so tell
            # the user why the tab switch was refused -- same toast as the
            # in-screen Back / row-switch / rail-switch vetoes. Notes show
            # their own conflict banner and prompts predate this pattern,
            # so only the skill veto reports here.
            self._notify_skill_dirty_veto()
        return (
            file_notes_flush_allowed
            and note_flush.kind is NoteFlushOutcomeKind.PERMITTED
            and prompt_flush_allowed
            and skill_flush_allowed
        )

    def apply_navigation_context(self, context: Mapping[str, Any]) -> None:
        """Apply route context supplied by shell navigation.

        Args:
            context: Navigation payload from ``NavigateToScreen``. A valid
                Library mode switches the active mode. A ``conversation_id``
                selects that conversation when the local source snapshot
                arrives, defaulting the mode to Conversations when no valid
                mode is supplied. A ``notes_create`` flag lands on the
                in-canvas Create > New note view (the retired Notes tab's
                "new note" deep link). A ``note_id`` opens that note's
                in-canvas editor directly (the retired Notes tab's
                chat-sidebar deep link); ``mode="notes"`` alone (no
                ``note_id``) lands on the Notes list instead. An
                ``ingest_media`` flag lands on the in-canvas Ingest >
                Import media view (Home's ingest-jobs "Open details"
                control, L3b Task 6). A supported ``open_source_type`` and
                exact ``open_source_id`` pair delegates to Library's existing
                item opener.
        """
        if self._library_prompts_mutation_in_flight:
            return
        if not isinstance(context, Mapping):
            return
        target_row_id = self._library_navigation_context_target_row(context)
        if target_row_id is None:
            return
        self._library_navigation_context_generation += 1
        if target_row_id != LIBRARY_ROW_BROWSE_MEDIA:
            self._library_media_browse_controller.invalidate()
        if (
            target_row_id != LIBRARY_ROW_BROWSE_COLLECTIONS
            and self._library_collections_capture_controller is not None
        ):
            self._library_collections_capture_controller.unmount()
        generation = self._library_navigation_context_generation
        if (
            self.is_mounted
            and target_row_id == LIBRARY_ROW_BROWSE_PROMPTS
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS
        ):
            return
        if self.is_mounted:
            # A cached mounted screen must admit the route through the same
            # awaited save/leave guards as a rail switch. Applying it
            # synchronously could discard a dirty editor or an active Prompt
            # selection before the transition is actually admitted.
            self.run_worker(
                self._apply_navigation_context_after_flush(
                    dict(context),
                    target_row_id,
                    generation,
                ),
                exclusive=True,
                group="library_nav_context",
            )
            return
        self._apply_navigation_context_state(context)

    def _library_navigation_context_target_row(
        self,
        context: Mapping[str, Any],
    ) -> str | None:
        """Return the validated destination row, or ``None`` for no route."""
        requested_mode = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_MODE),
            max_length=64,
        )
        target_row_id = LIBRARY_NAV_MODE_TO_ROW_ID.get(requested_mode)
        conversation_id = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_CONVERSATION_ID),
            max_length=200,
        )
        note_id = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_NOTE_ID),
            max_length=200,
        )
        if conversation_id:
            target_row_id = LIBRARY_ROW_BROWSE_CONVERSATIONS
        if requested_mode == "notes" and not note_id:
            target_row_id = LIBRARY_ROW_BROWSE_NOTES
        if bool(context.get(LIBRARY_NAV_CONTEXT_NOTES_CREATE)):
            target_row_id = LIBRARY_ROW_CREATE_NOTE
        if bool(context.get(LIBRARY_NAV_CONTEXT_INGEST)):
            target_row_id = LIBRARY_ROW_INGEST_MEDIA
        if note_id:
            target_row_id = LIBRARY_ROW_BROWSE_NOTES

        raw_source_type = context.get(LIBRARY_NAV_CONTEXT_OPEN_SOURCE_TYPE)
        raw_source_id = context.get(LIBRARY_NAV_CONTEXT_OPEN_SOURCE_ID)
        if type(raw_source_type) is str and type(raw_source_id) is str:
            source_type = self._safe_text(raw_source_type, max_length=64)
            source_id = self._safe_text(raw_source_id, max_length=500)
            if (
                source_type == raw_source_type
                and source_id == raw_source_id
                and source_type in {"media", "notes", "conversations", "prompt"}
                and source_id
            ):
                target_row_id = {
                    "media": LIBRARY_ROW_BROWSE_MEDIA,
                    "notes": LIBRARY_ROW_BROWSE_NOTES,
                    "conversations": LIBRARY_ROW_BROWSE_CONVERSATIONS,
                    "prompt": LIBRARY_ROW_BROWSE_PROMPTS,
                }[source_type]
        return target_row_id

    async def _apply_navigation_context_after_flush(
        self,
        context: Mapping[str, Any],
        target_row_id: str | None = None,
        generation: int | None = None,
    ) -> None:
        """Admit every mounted editor/source, then apply navigation context.

        Pending saves are awaited before the recompose that tears an editor
        down. If unsaved edits survive any guard, the switch aborts and leaves
        the current route in place -- the same contract as a rail-row switch.
        """
        if self._library_prompts_mutation_in_flight:
            return
        if target_row_id is None:
            target_row_id = self._library_navigation_context_target_row(context)
        if target_row_id is None:
            return
        if generation is None:
            generation = self._library_navigation_context_generation
        if generation != self._library_navigation_context_generation:
            return
        file_notes_flush_allowed = await self._flush_active_file_notes()
        if generation != self._library_navigation_context_generation:
            return
        if not file_notes_flush_allowed:
            return
        release_source = self._acquire_file_notes_transition("source")
        if release_source is False:
            return
        try:
            await self._apply_navigation_context_after_source_admission(
                context,
                target_row_id,
                generation,
            )
        finally:
            if callable(release_source):
                release_source()

    async def _apply_navigation_context_after_source_admission(
        self,
        context: Mapping[str, Any],
        target_row_id: str,
        generation: int,
    ) -> None:
        """Apply mounted navigation context while source admission is held."""
        if self._library_prompts_mutation_in_flight:
            return
        if generation != self._library_navigation_context_generation:
            return
        note_flush = await self._flush_library_note_save()
        if generation != self._library_navigation_context_generation:
            return
        if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
            return
        prompt_flush_allowed = await self._flush_library_prompt_save()
        if generation != self._library_navigation_context_generation:
            return
        if not prompt_flush_allowed:
            return
        skill_flush_allowed = await self._flush_library_skill_save()
        if generation != self._library_navigation_context_generation:
            return
        if not skill_flush_allowed:
            self._notify_skill_dirty_veto()
            return
        if target_row_id != LIBRARY_ROW_BROWSE_PROMPTS:
            self._clear_library_prompt_selection(announce=True)
        self._apply_navigation_context_state(context, recompose=False)
        if self.is_mounted and self._pending_library_source_open is None:
            await self.recompose()

    def _apply_navigation_context_state(
        self,
        context: Mapping[str, Any],
        *,
        recompose: bool = True,
    ) -> None:
        """Apply validated navigation context to canvas state and recompose.

        Split from ``apply_navigation_context`` so its mounted path can admit
        every pending save first (see
        ``_apply_navigation_context_after_flush``) while the pre-mount and
        clean-editor paths apply directly.
        """
        if self._library_prompts_mutation_in_flight:
            return
        self._supersede_library_notes_navigation()
        raw_open_source_type = context.get(LIBRARY_NAV_CONTEXT_OPEN_SOURCE_TYPE)
        raw_open_source_id = context.get(LIBRARY_NAV_CONTEXT_OPEN_SOURCE_ID)
        open_source_type = ""
        open_source_id = ""
        should_open_pending_source = False
        if type(raw_open_source_type) is str and type(raw_open_source_id) is str:
            validated_source_type = self._safe_text(
                raw_open_source_type,
                max_length=64,
            )
            validated_source_id = self._safe_text(
                raw_open_source_id,
                max_length=500,
            )
            if (
                validated_source_type == raw_open_source_type
                and validated_source_id == raw_open_source_id
                and validated_source_type
                in ("media", "notes", "conversations", "prompt")
                and validated_source_id
            ):
                open_source_type = validated_source_type
                open_source_id = validated_source_id
                self._pending_library_source_open = (
                    open_source_type,
                    open_source_id,
                )
                should_open_pending_source = True
        requested_mode = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_MODE),
            max_length=64,
        )
        conversation_id = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_CONVERSATION_ID),
            max_length=200,
        )
        note_id = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_NOTE_ID),
            max_length=200,
        )
        notes_create = bool(context.get(LIBRARY_NAV_CONTEXT_NOTES_CREATE))
        ingest_media = bool(context.get(LIBRARY_NAV_CONTEXT_INGEST))
        target_mode = (
            requested_mode if requested_mode in LIBRARY_NAV_MODE_TO_ROW_ID else ""
        )
        if conversation_id and not target_mode:
            target_mode = LIBRARY_MODE_CONVERSATIONS
        if target_mode:
            selected_row_id = LIBRARY_NAV_MODE_TO_ROW_ID.get(target_mode)
            if selected_row_id:
                self._set_library_destination_with_conversation_fence(selected_row_id)
            self._invalidate_library_workspace_depth_state()
        if conversation_id:
            self._selected_conversation_id = conversation_id
            self._set_library_destination_with_conversation_fence(
                LIBRARY_ROW_BROWSE_CONVERSATIONS
            )
            if not should_open_pending_source:
                # Persona still emits the legacy conversation_id context.
                # A paged snapshot may not contain that id, so resolve it
                # through the same point-lookup opener used by Search/RAG.
                self._pending_library_source_open = (
                    "conversations",
                    conversation_id,
                )
                should_open_pending_source = True
        if requested_mode == "notes" and not note_id:
            # "notes" is a canvas row, not a nav-context table entry (see
            # target_mode above), so it needs its own selection here --
            # mirrors handle_library_notes_row's list-view entry state.
            self._set_library_destination_with_conversation_fence(
                LIBRARY_ROW_BROWSE_NOTES
            )
        if notes_create:
            # Mirrors _select_library_rail_row(LIBRARY_ROW_CREATE_NOTE) --
            # the create-note rail row's own target_id. The rail row's
            # flush of a dirty editor is handled upstream by
            # apply_navigation_context's mounted dirty-editor branch; here we
            # only apply the selection the recompose reads. Reset the note
            # editor state FIRST (a mounted screen re-entered via this
            # deep link can still hold a previously opened note's
            # id/detail/version) then re-assert the create-note target state
            # AFTER, since the reset flips _library_notes_view back to
            # "list" -- same reset-then-set ordering as
            # _open_library_item_by_id's notes branch.
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
            self._dispatch_database_note_identity_cleared()
            self._reset_library_note_editor_state()
            self._set_library_destination_with_conversation_fence(
                LIBRARY_ROW_CREATE_NOTE
            )
        if ingest_media:
            # Home's ingest-jobs "Open details" control re-points here
            # (L3b Task 6): running/queued/failed Library ingest jobs
            # mirror into Home's Running and Needs Attention sections, and
            # this deep link is their one-hop route back to the in-canvas
            # ingest queue. Mirrors
            # _select_library_rail_row(LIBRARY_ROW_INGEST_MEDIA) -- unlike
            # collections/note_id above, the ingest canvas reads the job
            # registry directly on recompose, so no async data fetch (and
            # therefore no on_mount deferral) is needed even pre-mount.
            self._set_library_destination_with_conversation_fence(
                LIBRARY_ROW_INGEST_MEDIA
            )
            # Mirrors _select_library_rail_row's reset: a cached LibraryScreen
            # re-entered via this deep link (e.g. from Home's ingest-jobs
            # "Open details" control) must never show a stale half-filled
            # form left over from a previous Ingest visit.
            self._reset_library_ingest_transient_state()
        if note_id:
            # Forward-compat entry point: the retired Notes tab's chat-sidebar
            # deep link carried a note id, and this rebuilds the editor for it.
            # No caller in the tree emits a note_id context today (the surviving
            # open_notes_workspace route carries none, landing on the list), so
            # this is exercised only by tests until such a producer is wired --
            # not orphaned wiring.
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
            self._set_library_destination_with_conversation_fence(
                LIBRARY_ROW_BROWSE_NOTES
            )
            if self.is_mounted:
                self._begin_library_note_load(note_id)
            else:
                self._library_note_session.close_session()
                self._selected_note_id = note_id
                self._library_notes_view = "editor"
                self._library_note_load_state = "loading"
                self._library_note_load_message = ""
                self._library_note_autosave_state = "idle"
                self._library_note_confirming_delete = False
                self._library_note_preview = False
                self._library_note_editor_armed = False
            # A deep link never owns the current blank-note GC identity.
            self._library_note_pending_blank_gc_id = None
            self._library_note_session_blank_id = None
            self._library_note_title_user_edited = False
        if open_source_type:
            self._set_library_destination_with_conversation_fence(
                {
                    "media": LIBRARY_ROW_BROWSE_MEDIA,
                    "notes": LIBRARY_ROW_BROWSE_NOTES,
                    "conversations": LIBRARY_ROW_BROWSE_CONVERSATIONS,
                    "prompt": LIBRARY_ROW_BROWSE_PROMPTS,
                }[open_source_type]
            )
            if open_source_type == "media":
                self._selected_media_id = open_source_id
                self._library_media_view = "list"
            elif open_source_type == "notes":
                self._selected_note_id = open_source_id
                self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
                self._library_notes_view = "list"
            elif open_source_type == "conversations":
                self._selected_conversation_id = open_source_id
            elif open_source_type == "prompt":
                try:
                    self._selected_prompt_id = int(open_source_id)
                except ValueError:
                    self._selected_prompt_id = None
                self._library_prompts_view = "list"
        if should_open_pending_source and self.is_mounted:
            self.run_worker(
                self._open_pending_library_source(),
                exclusive=True,
                group="library_nav_open_source",
            )
        # F-012: a deep link can change the active canvas (e.g. mode="search")
        # without a rail-row press -- the footer's `u` hint must follow the
        # canvas, not just the rail switch, or the key works unadvertised.
        self._register_footer_shortcuts()
        if self._library_notes_workflow_active():
            self._library_notes_stage = "notes"
            self._library_notes_explicit_stage_intent = not self.is_mounted
        else:
            self._library_notes_explicit_stage_intent = False
        if self.is_mounted:
            if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
                self.run_worker(
                    self._load_library_collections_capture_entry(),
                    exclusive=True,
                    group="library_collections_capture_entry",
                )
            elif recompose and not open_source_type:
                self.refresh(recompose=True)

    async def _open_pending_library_source(
        self,
    ) -> LibraryEntryReconcileResult | None:
        """Consume one validated navigation target through Library's opener.

        A conversation point lookup may overlap the initial paged snapshot.
        That snapshot advances entry generation, so the first lookup result is
        correctly rejected; while the same pending target still owns the same
        conversation selection, retry under the new generation instead of
        permanently falling back to the first loaded row.
        """

        if self._library_prompts_mutation_in_flight:
            return

        pending = self._pending_library_source_open
        if pending is None:
            return
        while self._pending_library_source_open == pending:
            result = await self._open_library_item_by_id(*pending, entry_origin=True)
            if result is not LibraryEntryReconcileResult.SUPERSEDED:
                if result is None and pending[0] == "conversations":
                    return result
                if self._pending_library_source_open == pending:
                    self._pending_library_source_open = None
                return result
            if not self._pending_library_source_open_is_current(pending):
                if self._pending_library_source_open == pending:
                    self._pending_library_source_open = None
                return result
            # Let a scheduled snapshot reconcile finish before recapturing the
            # current generation in the next point-lookup attempt.
            await asyncio.sleep(0)
        return LibraryEntryReconcileResult.SUPERSEDED

    def _pending_library_source_open_is_current(self, pending: tuple[str, str]) -> bool:
        """Return whether a generation-only retry still owns its deep link."""

        source_type, record_id = pending
        if source_type == "media":
            return (
                self._pending_library_source_open == pending
                and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and self._selected_media_id == record_id
            )
        return (
            source_type == "conversations"
            and self._pending_library_source_open == pending
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and self._selected_conversation_id == record_id
        )

    def _adopt_library_conversation_state_selection(self, selected_id: str) -> None:
        """Adopt list normalization unless it would consume a pending deep link."""

        pending = self._pending_library_source_open
        if (
            pending is not None
            and pending[0] == "conversations"
            and self._selected_conversation_id == pending[1]
            and selected_id != pending[1]
        ):
            return
        retained_reader_id = self._library_conversation_reader_state.selected_id
        if (
            retained_reader_id
            and not self._library_conversation_reader_state.unavailable
            and selected_id != retained_reader_id
        ):
            return
        self._selected_conversation_id = selected_id

    # Own group, deliberately separate from the "default" group the plain
    # `self.run_worker(self._sync_collections_panel(...))` calls above use
    # (they take no explicit group either). Both were previously exclusive
    # in the SAME (default) group, so an ingest-completion poke into this
    # worker (see `_handle_library_ingest_registry_changed`) could cancel
    # an in-flight Collections load. A separate group makes the two
    # `exclusive=True` scopes independent.
    @work(exclusive=True, group="library_source_snapshot")
    async def _refresh_local_source_snapshot(self) -> None:
        self._refresh_library_onboarding_evidence()
        (
            records,
            counts,
            total_known,
            lookup_error,
            recovery_state,
            study_counts,
        ) = await self._list_local_source_snapshot()
        # Refresh the app-scoped instant-repeat-visit cache (seeded in
        # `__init__` before first compose)
        # with this fresh snapshot before applying it, so any other
        # LibraryScreen instance mounted from here on -- including a
        # concurrent one, since screens are recomposed per visit -- reads
        # this fetch's result rather than stale/no data.
        #
        # Only a SUCCESSFUL snapshot (``lookup_error is None``) is cached: an
        # error/service-unavailable result still applies to the current view
        # as usual below (unchanged), but must not become the next visit's
        # instant-apply seed -- otherwise a return visit within TTL would
        # flash the "services unavailable" banner for one frame before the
        # reconcile corrects it. Skipping the write leaves the previous good
        # snapshot (or nothing) in place, so the next visit does a normal
        # fresh fetch instead.
        if lookup_error is None:
            snapshot = clone_library_source_snapshot(
                (
                    records,
                    counts,
                    total_known,
                    lookup_error,
                    recovery_state,
                    study_counts,
                )
            )
            if snapshot is not None:
                self.app_instance._library_source_snapshot_cache = snapshot
                self.app_instance._library_source_snapshot_cache_stamp = (
                    time.monotonic()
                )
        presentation_changed = self._apply_local_source_snapshot(
            records, counts, total_known, lookup_error, recovery_state, study_counts
        )
        if (
            not presentation_changed
            and self._library_notes_pending_focus_waits_for_snapshot
        ):
            # A no-op snapshot has no reconciliation callback to finish the
            # pending Notes Back receipt. Release it after the current frame
            # just as a changed snapshot does from
            # `_complete_library_entry_reconcile` below.
            self.call_after_refresh(self._release_library_notes_focus_after_snapshot)
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS:
            # Task 5: this snapshot includes the skills entry the list view
            # reads (``_build_library_skills_state``) -- re-check the trust
            # posture alongside it (scoped to when skills are actually
            # being browsed, so every OTHER content type's refresh doesn't
            # pay for an off-thread keyring read it has no use for).
            self._refresh_library_skills_trust_posture()

    def _carry_selected_conversation_into_snapshot(
        self,
        records: dict[str, tuple[Mapping[str, Any], ...]],
    ) -> dict[str, tuple[Mapping[str, Any], ...]]:
        """Preserve an out-of-page selected conversation across a snapshot replace.

        (C3) A wholesale ``_local_source_records`` replace -- the periodic
        background refresh, not a user action -- can silently drop the
        currently-open conversation if it fell off the loaded page (the
        conversations snapshot is capped, see
        ``LIBRARY_SOURCE_PAGE_SIZES["conversations"]``) or was fetched
        out-of-band via ``_open_library_item_by_id`` and prepended into the
        OLD records. Without this, the next recompose would silently reset
        the selection to the first row (``_ensure_selected_conversation_id``)
        even though the user never navigated away -- the same class of race
        ``_open_library_item_by_id`` already guards against for its own
        out-of-snapshot fetch, just triggered by a background refresh
        instead of a user click.

        Pure in-memory merge: reads the OLD ``self._local_source_records``
        (not yet replaced) and the INCOMING ``records``, and -- only when the
        selected id is present in the old snapshot but missing from the new
        one -- prepends the old record into the new conversations tuple so
        the selection survives the replace.

        Args:
            records: The incoming snapshot about to replace
                ``self._local_source_records``.

        Returns:
            ``records``, unchanged, or with the selected conversation's
            record prepended into its ``"conversations"`` tuple.
        """
        selected_id = getattr(self, "_selected_conversation_id", "")
        if not selected_id:
            return records
        old_conversations = getattr(self, "_local_source_records", {}).get(
            "conversations", ()
        )
        old_index_by_id = {
            self._conversation_record_id(record, index): record
            for index, record in enumerate(old_conversations)
        }
        carried_record = old_index_by_id.get(selected_id)
        if carried_record is None:
            # Not present in the old snapshot either -- nothing to carry.
            return records
        new_conversations = records.get("conversations", ())
        new_ids = {
            self._conversation_record_id(record, index)
            for index, record in enumerate(new_conversations)
        }
        if selected_id in new_ids:
            # Still present in the incoming snapshot -- no carry-over needed.
            return records
        merged = dict(records)
        merged["conversations"] = (carried_record, *new_conversations)[
            :LIBRARY_CONVERSATION_PAGE_SIZE
        ]
        return merged

    @staticmethod
    def _structural_records_for_comparison(
        records: Mapping[str, tuple[Any, ...]],
    ) -> dict[str, Any]:
        """Mask the DECORATIVE-only rail-count fields out of ``records``
        for the task-15459 ``unchanged`` check in
        ``_apply_local_source_snapshot`` -- see that method's own comment
        for why decorative counts must not gate a recompose.

        ``records["prompts"]`` is entirely decorative: its second slot is
        permanently ``()`` (Prompt rows have their own exact browse owner
        -- see the ``__init__``/``_list_local_source_snapshot`` comments on
        this key), so the whole entry is dropped. ``records["skills"]`` is
        mixed: only its COUNT (first slot) is the decorative rail badge;
        its ``available_skills``/``blocked_skills`` payload (second slot)
        is the actual content a mounted Skills canvas renders
        (``_build_library_skills_state``), so only the count is masked out
        there, not the whole entry.

        Args:
            records: A ``_local_source_records``-shaped snapshot (either
                the incoming one or the currently-rendered one).

        Returns:
            A shallow copy of ``records`` with decorative count fields
            neutralized, suitable for ``==`` comparison against another
            such copy to detect a genuine STRUCTURAL (rendered-content)
            change.
        """
        view = {key: value for key, value in records.items() if key != "prompts"}
        skills_entry = view.get("skills")
        if isinstance(skills_entry, tuple) and len(skills_entry) == 2:
            view["skills"] = (None, skills_entry[1])
        return view

    @staticmethod
    def _decorative_rail_counts_for_comparison(
        records: Mapping[str, tuple[Any, ...]],
    ) -> tuple[Any, Any]:
        """Return the two decorative rail counts folded into ``records``
        (Prompts, Skills) as a comparable tuple -- the counterpart half of
        ``_structural_records_for_comparison``'s masking. ``study_counts``
        is the third decorative field but lives outside ``records``
        entirely, so callers compare it separately.

        Args:
            records: A ``_local_source_records``-shaped snapshot.

        Returns:
            ``(prompts_count, skills_count)``, each ``None`` when the
            corresponding entry is absent or malformed (mirrors
            ``_build_library_shell_input``'s own extraction of these two
            fields for the rail).
        """
        prompts_entry = records.get("prompts")
        prompts_count = (
            prompts_entry[0]
            if isinstance(prompts_entry, tuple) and len(prompts_entry) == 2
            else None
        )
        skills_entry = records.get("skills")
        skills_count = (
            skills_entry[0]
            if isinstance(skills_entry, tuple) and len(skills_entry) == 2
            else None
        )
        return (prompts_count, skills_count)

    def _library_entry_route_key(self) -> tuple[object, ...]:
        """Return the state fields that select the mounted Library owner."""
        return (
            self._library_selected_row_id,
            self._library_notes_source,
            self._library_notes_view,
            self._library_media_view,
            self._library_prompts_view,
            self._library_skills_view,
            self._selected_note_id,
            self._selected_media_id,
            self._selected_prompt_id,
            self._selected_skill_name,
        )

    def _library_entry_canvas_host(self) -> Vertical | None:
        """Return the route-only host, or an adaptive reader's items host."""
        retained_hosts = self.query("#library-canvas-route-content")
        if retained_hosts:
            return retained_hosts.first(Vertical)
        try:
            return self.query_one("#library-canvas", Vertical)
        except (NoMatches, QueryError):
            return None

    def _library_entry_canvas_owner(self) -> Widget | None:
        """Return the active route child without treating recovery chrome as one."""
        host = self._library_entry_canvas_host()
        if host is None:
            return None
        return next((child for child in host.children if child.display), None)

    def _capture_library_entry_focus(self) -> LibraryEntryFocusIdentity | None:
        """Capture a focused canvas descendant by stable control or row identity."""
        focused = self.focused
        owner = self._library_entry_canvas_owner()
        route_key = self._library_entry_route_key()
        capture = self._library_entry_focus_capture
        if focused is None:
            if capture is not None and capture.route_key == route_key:
                return capture.identity
            self._library_entry_focus_capture = None
            return None
        if owner is None or owner not in focused.ancestors_with_self:
            self._library_entry_focus_capture = None
            return None

        source_id = ""
        for attribute in (
            "conversation_id",
            "media_id",
            "note_id",
            "prompt_id",
            "skill_name",
            "record_id",
            "source_id",
        ):
            value = getattr(focused, attribute, None)
            if value is not None and str(value):
                source_id = str(value)
                break
        scroll_offset: tuple[int, int] | None = None
        if hasattr(owner, "scroll_x") and hasattr(owner, "scroll_y"):
            scroll_offset = (int(owner.scroll_x), int(owner.scroll_y))
        identity = LibraryEntryFocusIdentity(
            widget_id=str(focused.id or ""),
            source_id=source_id,
            scroll_offset=scroll_offset,
        )
        notes_identity = (
            self._capture_library_notes_focus_identity()
            if owner.id == "library-notes-canvas"
            else None
        )
        self._library_entry_focus_capture = _LibraryEntryFocusCapture(
            identity=identity,
            outgoing_focus=focused,
            route_key=route_key,
            notes_identity=notes_identity,
        )
        # Detach DOM focus before the owner removes its focused child. Textual
        # otherwise falls back to unrelated screen chrome during teardown,
        # which is indistinguishable from a user focus move at restore time.
        # Any real focus move after this point lands on a non-None widget and
        # is therefore protected by `_restore_library_entry_focus`'s guard.
        self.set_focus(None)
        return identity

    def _restore_library_entry_focus(
        self,
        identity: LibraryEntryFocusIdentity,
        *,
        generation: int,
        route_key: tuple[object, ...],
    ) -> bool:
        """Restore one current semantic target without overriding user movement."""
        if generation != self._library_snapshot_state_generation:
            return False
        if route_key != self._library_entry_route_key():
            return False
        capture = self._library_entry_focus_capture
        outgoing_focus = (
            capture.outgoing_focus
            if capture is not None and capture.identity is identity
            else None
        )

        owner = self._library_entry_canvas_owner()
        if owner is None:
            return False
        target: Widget | None = None
        if identity.source_id:
            for candidate in owner.query(Widget):
                if any(
                    str(getattr(candidate, attribute, "") or "") == identity.source_id
                    for attribute in (
                        "conversation_id",
                        "media_id",
                        "note_id",
                        "prompt_id",
                        "skill_name",
                        "record_id",
                        "source_id",
                    )
                ):
                    target = candidate
                    break
        elif identity.widget_id:
            try:
                target = owner.query_one(f"#{identity.widget_id}", Widget)
            except (NoMatches, QueryError):
                target = None
        if (
            self.focused is not outgoing_focus
            and self.focused is not None
            and self.focused is not target
        ):
            if self._library_entry_focus_capture is capture:
                self._library_entry_focus_capture = None
            return False
        if target is not None and not getattr(target, "disabled", False):
            self.set_focus(target, scroll_visible=False)
        if identity.scroll_offset is not None and hasattr(owner, "scroll_to"):
            owner.scroll_to(
                x=identity.scroll_offset[0],
                y=identity.scroll_offset[1],
                animate=False,
                force=True,
            )
        if self._library_entry_focus_capture is capture:
            self._library_entry_focus_capture = None
        return True

    def _finish_library_entry_canvas_sync(
        self,
        identity: LibraryEntryFocusIdentity | None,
        *,
        generation: int,
        route_key: tuple[object, ...],
    ) -> bool:
        """Restore focus/scroll and complete one generation in one callback."""
        focus_is_current = True
        if identity is not None:
            focus_is_current = self._restore_library_entry_focus(
                identity,
                generation=generation,
                route_key=route_key,
            )
        self._complete_library_entry_reconcile(generation, route_key)
        return focus_is_current

    def _library_entry_reconcile_is_current(
        self, generation: int, route_key: tuple[object, ...]
    ) -> bool:
        """Return whether deferred entry work still owns this screen route."""
        return (
            self.is_mounted
            and generation == self._library_snapshot_state_generation
            and route_key == self._library_entry_route_key()
        )

    def _schedule_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> None:
        """Queue one generation/route-specific DOM projection on this pump."""
        pending = (generation, route_key)
        if self._library_entry_reconcile_pending == pending:
            return
        self._library_entry_reconcile_pending = pending
        self.call_later(self._reconcile_library_entry_state, generation, route_key)

    def _complete_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> None:
        """Mark a still-current snapshot generation as rendered."""
        if generation != self._library_snapshot_state_generation:
            return
        if route_key != self._library_entry_route_key():
            return
        self._library_snapshot_rendered_generation = generation
        self._library_entry_reconcile_dirty = False
        self._library_entry_reconcile_pending = None
        self._library_entry_reconcile_retry_generation = None
        if self._library_notes_pending_focus_waits_for_snapshot:
            # Notes Back waits for the fresh list projection so its row and
            # scroll receipt cannot be overwritten by the snapshot-driven
            # list sync. The pending identity is Notes-owned and generation
            # guarded; all other destinations are a no-op here.
            self.call_after_refresh(self._release_library_notes_focus_after_snapshot)

    def _supersede_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Release markers owned by one stale reconciliation callback."""
        pending = (generation, route_key)
        if self._library_entry_reconcile_pending == pending:
            self._library_entry_reconcile_pending = None
            if self._library_entry_reconcile_retry_generation == pending:
                self._library_entry_reconcile_retry_generation = None
        return LibraryEntryReconcileResult.SUPERSEDED

    def _retry_or_fail_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Retry one still-current missing target, then leave it dirty."""
        if generation != self._library_snapshot_state_generation:
            return self._supersede_library_entry_reconcile(generation, route_key)
        if route_key != self._library_entry_route_key():
            return self._supersede_library_entry_reconcile(generation, route_key)
        self._library_entry_reconcile_dirty = True
        pending = (generation, route_key)
        if self._library_entry_reconcile_retry_generation != pending:
            self._library_entry_reconcile_retry_generation = pending
            self._library_entry_reconcile_pending = pending
            self.call_later(self._reconcile_library_entry_state, generation, route_key)
            return LibraryEntryReconcileResult.FAILED
        self._library_entry_reconcile_pending = None
        self._library_entry_reconcile_retry_generation = None
        return LibraryEntryReconcileResult.FAILED

    def _fail_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Leave a failed generation dirty and release its owned markers."""
        pending = (generation, route_key)
        self._library_entry_reconcile_dirty = True
        if self._library_entry_reconcile_pending == pending:
            self._library_entry_reconcile_pending = None
            if self._library_entry_reconcile_retry_generation == pending:
                self._library_entry_reconcile_retry_generation = None
        return LibraryEntryReconcileResult.FAILED

    def _build_library_entry_active_child(self) -> Widget | None:
        """Build the active entry-owned child from the latest screen state."""
        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        if shell.canvas_kind == "conversations":
            state = self._build_library_conversations_state()
            self._adopt_library_conversation_state_selection(state.selected_id)
            return LibraryConversationsCanvas(state, id="library-conversations-canvas")
        if shell.canvas_kind == "media":
            # Every media view (list / viewer / trash) resolves through the
            # one shared builder -- the duplicated "trash" check that used
            # to live here is exactly what let the builder itself go
            # missing one (task-21116 review, M1).
            return self._build_library_media_active_child()
        if shell.canvas_kind in (
            LIBRARY_CANVAS_KIND_NOTES,
            LIBRARY_CANVAS_KIND_NOTES_CREATE,
        ):
            if self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES:
                return self._library_file_notes_workspace or Static(
                    "Opening File Notesâ€¦",
                    id="library-file-notes-loading",
                    classes="destination-purpose",
                    markup=False,
                )
            return LibraryNotesCanvas(
                **self._library_notes_list_canvas_kwargs(),
                id="library-notes-canvas",
            )
        if shell.canvas_kind == "prompts":
            return LibraryPromptsListCanvas(
                **self._library_prompts_canvas_kwargs(),
                id="library-prompts-canvas",
            )
        if shell.canvas_kind == "skills":
            return LibrarySkillsListCanvas(
                **self._library_skills_canvas_kwargs(),
                id="library-skills-canvas",
            )
        if shell.canvas_kind == "collections":
            # Collections changes the whole route topology (rail scopes +
            # Items + Work), so the ordinary one-child replacement seam must
            # fall through to the central recompose path.
            return None
        if shell.canvas_kind == "export":
            return LibraryExportCanvas(
                self._build_library_export_state(),
                id="library-export-canvas",
            )
        if shell.canvas_kind == "search":
            return LibrarySearchRagPanel(
                self._library_rag_panel_state(),
                id="library-search-rag-panel",
            )
        if shell.canvas_kind == "ingest-media":
            return LibraryIngestCanvas(
                self._build_library_ingest_state(),
                external_busy=self._library_external_submit_busy,
                external_status=self._library_external_submit_status,
                id="library-ingest-canvas",
            )
        if shell.canvas_kind == "handoff":
            return LibraryStudyHandoffCanvas(
                self._library_study_handoff_canvas_state(shell.canvas_target),
                id="library-study-handoff-canvas",
            )
        if shell.canvas_kind == "empty":
            return LibraryLandingCanvas(
                self._library_landing_canvas_state(),
                id="library-landing-canvas",
            )
        return None

    def _sync_library_entry_owner_from_current_state(self, owner: Widget) -> bool:
        """Re-read state into a matching retained owner after an await."""
        if isinstance(owner, LibraryMediaViewer):
            return self._sync_library_media_viewer_state(owner)
        kind = None
        if isinstance(owner, LibraryConversationsCanvas):
            kind = "conversations"
        elif isinstance(owner, LibraryMediaCanvas):
            kind = "media"
        elif isinstance(owner, LibraryMediaTrashCanvas):
            kind = "media-trash"
        elif isinstance(owner, LibraryNotesCanvas):
            kind = "notes"
        elif isinstance(owner, LibraryPromptsListCanvas):
            kind = "prompts"
        elif isinstance(owner, LibrarySkillsListCanvas):
            kind = "skills"
        elif isinstance(owner, LibraryExportCanvas):
            kind = "export"
        elif isinstance(owner, LibraryLandingCanvas):
            kind = "landing"
        elif isinstance(owner, LibraryStudyHandoffCanvas):
            kind = "handoff"
        if kind is None:
            return False
        return _sync_library_canvas(
            self,
            kind,
            allow_screen_fallback=False,
            projection_owned=True,
        )

    async def _repair_library_entry_canvas_owner(self) -> bool:
        """Converge an interrupted child swap on the latest route, in place.

        Two review-round (m3) hardenings:

        * the generation/route pair is captured AFTER the builder runs.
          ``_build_library_entry_active_child`` RESOLVES state as it builds
          (the media arm mirrors the resolved ``_selected_media_id`` back
          onto the screen, and that field is part of the route key), so
          capturing first made this loop see its own builder's resolution
          as a newer navigation -- the identical shape as the supersede
          defect found in ``_apply_library_open_item_surface``. It
          self-healed in one iteration, but only by spinning.
        * the iteration count is bounded. Every ``continue`` path here is
          await-free, so a mismatch that does NOT clear would spin this
          loop hot rather than merely retry it.
        """
        mount_failures = 0
        # Bounded purely as a hot-spin guard: convergence normally happens
        # on the first or second pass.
        for _attempt in range(8):
            if not getattr(self, "_is_mounted", False):
                break
            replacement = self._build_library_entry_active_child()
            if replacement is None:
                return False
            # Captured AFTER the builder -- see the docstring.
            generation = self._library_snapshot_state_generation
            route_key = self._library_entry_route_key()
            canvas_host = self._library_entry_canvas_host()
            if canvas_host is None:
                return False
            owner = self._library_entry_canvas_owner()
            if (
                owner is not None
                and type(owner) is type(replacement)
                and owner.id == replacement.id
            ):
                if self._library_entry_reconcile_is_current(generation, route_key):
                    return self._sync_library_entry_owner_from_current_state(owner)
                continue
            # This loop detaches the host's child across awaits too, so it
            # holds the same projection marker: a ``_sync_library_canvas``
            # landing inside the window must suppress its whole-screen
            # fallback rather than race a duplicate-id canvas into the
            # mount (review round, M3).
            self._library_canvas_projection_depth += 1
            try:
                outgoing = tuple(canvas_host.children)
                for child in outgoing:
                    child.display = False
                if outgoing:
                    await canvas_host.remove_children(outgoing)
                if not self._library_entry_reconcile_is_current(generation, route_key):
                    continue
                await canvas_host.mount(replacement)
                if not self._library_entry_reconcile_is_current(generation, route_key):
                    continue
                return self._sync_library_entry_owner_from_current_state(replacement)
            except Exception:
                mount_failures += 1
                logger.debug("Library entry canvas repair attempt failed.")
                if mount_failures >= 2:
                    return False
            finally:
                self._finish_library_canvas_projection()
        return False

    def _schedule_library_entry_canvas_repair(self) -> None:
        """Project already-settled state under fresh generation authority."""
        if getattr(self, "_is_mounted", False):
            self.call_later(self._repair_library_entry_canvas_owner)

    def _finish_library_canvas_projection(self) -> None:
        """Close one projection window and replay any suppressed state sync."""

        self._library_canvas_projection_depth = max(
            0, self._library_canvas_projection_depth - 1
        )
        if (
            self._library_canvas_projection_depth == 0
            and self._library_canvas_resync_pending
        ):
            self._library_canvas_resync_pending = False
            self._schedule_library_entry_canvas_repair()

    async def _replace_library_canvas_child(
        self,
        widget: Widget,
        *,
        generation: int,
        route_key: tuple[object, ...],
        rail_mode: str = "sync",
        then: Callable[[], None] | None = None,
    ) -> LibraryEntryReconcileResult:
        """Replace only the active Library canvas child for one entry owner.

        The generation/route pair is checked before every DOM mutation and
        after each await.  Once mounted, stateful owners are synchronized from
        the screen again so state changed while removal/mounting yielded to the
        message pump cannot be stranded in the pre-await constructor snapshot.

        Args:
            widget: The destination canvas child to mount.
            generation: Snapshot generation this projection belongs to.
            route_key: Route key this projection belongs to.
            rail_mode: ``"sync"`` (default) fully recomposes the rail from
                the fresh shell state -- required for entry reconciliation,
                where counts/sections may have changed with the snapshot.
                ``"selection"`` patches only the two selection-affected rows
                in place (``LibraryRail.apply_selection``) -- the task-21116
                per-click open seam, where only the selected row moved and a
                full rail rebuild would recreate every row button per click.
            then: Optional follow-up ordered AFTER the mounted owner's own
                post-mount synchronization recompose settles (task-21116).
                Required for follow-ups that measure or scroll the new
                children: the sync recompose is serviced by the CANVAS's
                pump, so a follow-up scheduled from the caller's
                continuation can run against children the sync is about to
                replace (reproduced: the compact Media viewer-back scroll
                restore clamped to 0 against a not-yet-final list). Runs
                only when the replacement APPLIED.
        """
        if not self._library_entry_reconcile_is_current(generation, route_key):
            return LibraryEntryReconcileResult.SUPERSEDED

        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        try:
            rail = self.query_one("#library-rail", LibraryRail)
            header = self.query_one("#library-header-line", Static)
        except (NoMatches, QueryError):
            return LibraryEntryReconcileResult.FAILED
        canvas_host = self._library_entry_canvas_host()
        if canvas_host is None:
            return LibraryEntryReconcileResult.FAILED

        focus_identity = self._capture_library_entry_focus()
        restore_focus = (
            partial(
                self._restore_library_entry_focus,
                focus_identity,
                generation=generation,
                route_key=route_key,
            )
            if focus_identity is not None
            else None
        )
        try:
            if rail_mode == "selection":
                rail.apply_selection(
                    shell,
                    lifecycle=self._library_lifecycle,
                    onboarding_all_empty=self._library_onboarding_all_empty,
                )
            else:
                rail.sync_state(
                    shell,
                    self._library_rail_preferences(),
                    query=self._library_rag_query,
                    lifecycle=self._library_lifecycle,
                    onboarding_all_empty=self._library_onboarding_all_empty,
                )
            header_renderable = header.renderable
            header_text = getattr(header_renderable, "plain", str(header_renderable))
            expected_header = self._library_header_line(shell.header_line)
            if header_text != expected_header:
                header.update(expected_header)
            if self.is_running:
                self.app.capture_mouse(None)
        except Exception:
            logger.debug("Strict Library entry shell synchronization failed.")
            if restore_focus is not None:
                restore_focus()
            return LibraryEntryReconcileResult.FAILED

        if not self._library_entry_reconcile_is_current(generation, route_key):
            return LibraryEntryReconcileResult.SUPERSEDED

        # From here the canvas host's child is detached across awaits.
        # Mark the window so a ``_sync_library_canvas`` landing inside it
        # suppresses its whole-screen fallback instead of racing a
        # duplicate-id canvas into the in-flight mount (review round, M3).
        # try/finally rather than an inline guard: this region has eight
        # early returns.
        self._library_canvas_projection_depth += 1
        try:
            return await self._project_library_canvas_child(
                widget,
                canvas_host=canvas_host,
                generation=generation,
                route_key=route_key,
                focus_identity=focus_identity,
                restore_focus=restore_focus,
                then=then,
            )
        finally:
            self._finish_library_canvas_projection()

    async def _project_library_canvas_child(
        self,
        widget: Widget,
        *,
        canvas_host: Vertical,
        generation: int,
        route_key: tuple[object, ...],
        focus_identity: LibraryEntryFocusIdentity | None,
        restore_focus: Callable[[], bool] | None,
        then: Callable[[], None] | None,
    ) -> LibraryEntryReconcileResult:
        """Swap the canvas host's child and synchronize the new owner.

        Split out of ``_replace_library_canvas_child`` purely so that its
        caller can hold ``_library_canvas_projection_depth`` across every
        one of this region's early-return paths (review round, M3).
        """
        outgoing = tuple(canvas_host.children)
        try:
            for child in outgoing:
                child.display = False
            if outgoing:
                await canvas_host.remove_children(outgoing)
        except Exception:
            logger.debug("Strict Library entry canvas removal failed.")
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.FAILED

        if not self._library_entry_reconcile_is_current(generation, route_key):
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.SUPERSEDED
        try:
            await canvas_host.mount(widget)
        except Exception:
            logger.debug("Strict Library entry canvas mount failed.")
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.FAILED
        if not self._library_entry_reconcile_is_current(generation, route_key):
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.SUPERSEDED

        sync_kind: str | None = None
        if isinstance(widget, LibraryConversationsCanvas):
            sync_kind = "conversations"
        elif isinstance(widget, LibraryMediaCanvas):
            sync_kind = "media"
        elif isinstance(widget, LibraryNotesCanvas):
            sync_kind = "notes"
        elif isinstance(widget, LibraryPromptsListCanvas):
            sync_kind = "prompts"
        elif isinstance(widget, LibrarySkillsListCanvas):
            sync_kind = "skills"
        elif isinstance(widget, LibraryExportCanvas):
            sync_kind = "export"
        elif isinstance(widget, LibraryMediaViewer):
            if not self._sync_library_media_viewer_state(widget):
                return LibraryEntryReconcileResult.FAILED
        follow_up: Callable[[], bool | None] | None = restore_focus
        if then is not None:
            if restore_focus is None:
                follow_up = then
            else:

                def follow_up(
                    _restore: Callable[[], bool] = restore_focus,
                    _then: Callable[[], None] = then,
                ) -> bool:
                    # Preserve the restore's veto-relevant return while
                    # still running the caller's follow-up.
                    restored = _restore()
                    _then()
                    return restored

        if sync_kind is not None:
            capture = self._library_entry_focus_capture
            if not _sync_library_canvas(
                self,
                sync_kind,
                then=follow_up,
                allow_screen_fallback=False,
                notes_focus_identity=(
                    capture.notes_identity
                    if capture is not None and capture.identity is focus_identity
                    else None
                ),
                projection_owned=True,
            ):
                return LibraryEntryReconcileResult.FAILED
        elif then is not None:
            # No owner-driven sync recompose to order against (loading
            # Static, media viewer, collections): after-refresh is the
            # settled point.
            self.call_after_refresh(then)
        self._apply_library_notes_stage_visibility()
        self._apply_library_notes_footer_context()
        return LibraryEntryReconcileResult.APPLIED

    async def _apply_library_open_item_surface(
        self,
        build: Callable[[], Widget],
        *,
        then: Callable[[], None] | None = None,
    ) -> None:
        """Project one just-selected Library surface without a screen recompose.

        task-21116: the per-click "open this item / open this canvas" sites
        (Search/RAG result opens, media row opens, section "Export…"
        actions, media-viewer exits) used to end in a whole-screen
        ``self.refresh(recompose=True)`` -- a remove/remount of the nav
        bar, footer, rail, and canvas on the largest screen in the app.
        This seam routes them through the same strict canvas-child
        replacement the entry lifecycle already uses
        (``_replace_library_canvas_child``): the rail and header are
        synchronized in place and only the canvas host's child is
        replaced. It also re-registers the footer shortcut set, which
        ``compose_content`` would otherwise refresh on the retired
        whole-screen recompose.

        The caller must have fully applied the destination state (row id,
        views, selected ids) BEFORE calling: the replacement seam derives
        its shell state and supersede guards from the live screen state.

        Args:
            build: Zero-argument builder for the destination canvas child.
                Called lazily so a failure falls back to the legacy
                whole-screen recompose instead of raising.
            then: Optional follow-up ordered after the mounted destination's
                children have settled (see ``_replace_library_canvas_child``).
                On a whole-screen fallback it runs synchronously right after
                the ``refresh`` call -- the exact statement order the
                retired call sites used (``refresh(recompose=True)`` then
                arm/focus). Dropped when a newer navigation superseded the
                projection.

        Returns:
            None.
        """
        if not self.is_mounted:
            # Parity with the retired unconditional refresh: an unmounted
            # screen simply records the recompose request for mount time.
            self.refresh(recompose=True)
            if then is not None:
                then()
            return
        self._advance_library_stage_interaction()
        self._register_footer_shortcuts()
        # Crossing the Notes boundary is STRUCTURAL: the Database/Files
        # source strip is route-owned chrome composed OUTSIDE the canvas
        # host (above the shell grid), so adding/removing it must go
        # through the central whole-screen seam -- the same rule
        # ``_replace_library_browse_canvas`` enforces. Every other
        # transition keeps the targeted path.
        destination_shell: LibraryShellState | None = None
        try:
            destination_shell = build_library_shell_state(
                self._build_library_shell_input(),
                selected_row_id=self._library_selected_row_id,
            )
            strip_mounted = bool(self.query("#library-notes-source-strip"))
            strip_needed = (
                destination_shell.canvas_kind in LIBRARY_NOTES_SOURCE_STRIP_CANVAS_KINDS
            )
        except Exception:
            logger.debug("Library open-surface strip probe failed.", exc_info=True)
            strip_mounted, strip_needed = False, True
        adaptive_shell_selectors = {
            LIBRARY_CANVAS_KIND_NOTES: "#library-notes-reader-shell",
            LIBRARY_CANVAS_KIND_NOTES_CREATE: "#library-notes-reader-shell",
            "prompts": "#library-prompts-reader-shell",
            "skills": "#library-skills-reader-shell",
            "collections": "#library-collections-reader-shell",
            "conversations": "#library-conversations-reader-shell",
            "media": "#library-media-reader-shell",
        }
        destination_reader = adaptive_shell_selectors.get(
            destination_shell.canvas_kind if destination_shell is not None else ""
        )
        mounted_reader = next(
            (
                selector
                for selector in set(adaptive_shell_selectors.values())
                if self.query(selector)
            ),
            None,
        )
        if strip_mounted != strip_needed or mounted_reader != destination_reader:
            await self.recompose()
            if then is not None:
                self.call_after_refresh(then)
            return
        try:
            widget = build()
        except Exception:
            logger.debug("Targeted Library open-surface build failed.", exc_info=True)
            widget = None
        if widget is None:
            self.refresh(recompose=True)
            if then is not None:
                then()
            return
        # Captured AFTER ``build()``: the state builders are allowed to
        # RESOLVE state as they build (``_build_library_media_active_child``
        # mirrors the resolved ``_selected_media_id`` back onto the screen
        # when the requested row no longer exists), and ``_selected_media_id``
        # is part of the route key. Capturing before the build made the
        # replacement seam see its own builder's resolution as a newer
        # navigation and silently SUPERSEDE the projection -- reproduced:
        # viewer Back after the opened row was deleted left the dead viewer
        # on screen while the state said "list".
        generation = self._library_snapshot_state_generation
        route_key = self._library_entry_route_key()
        try:
            result = await self._replace_library_canvas_child(
                widget,
                generation=generation,
                route_key=route_key,
                # A per-click open moves only the rail SELECTION; counts and
                # sections are untouched, so patch the two affected rows in
                # place instead of recreating every rail row per click.
                rail_mode="selection",
                then=then,
            )
        except Exception:
            logger.debug(
                "Targeted Library open-surface projection failed.", exc_info=True
            )
            result = LibraryEntryReconcileResult.FAILED
        if result is LibraryEntryReconcileResult.FAILED:
            self.refresh(recompose=True)
            if then is not None:
                then()
        elif (
            result is LibraryEntryReconcileResult.SUPERSEDED
            and then is not None
            and route_key == self._library_entry_route_key()
        ):
            # A GENERATION-only supersede is not a navigation (review round,
            # M4). ``_library_entry_reconcile_is_current`` compares the
            # snapshot generation as well as the route key, and the ORDINARY
            # local-source snapshot bumps that generation -- one that
            # ``_exit_library_media_viewer`` itself kicks (via
            # ``_load_library_media_list_if_needed``) a line before
            # scheduling this projection. A snapshot landing mid-await
            # therefore dropped the follow-up, silently losing BOTH the
            # task-2856 AC1 first-row focus and the media_return scroll
            # restore that the pre-conversion code armed unconditionally.
            #
            # The route is unchanged here, so the destination is still ours
            # and the follow-up is still meaningful; the reconcile pass the
            # new generation schedules repaints the canvas. A genuine
            # ROUTE-change supersede still skips it -- that is the
            # TASK-15706 transitioning-surface rule, and it is the only
            # case the branch below now covers.
            then()
        # A ROUTE-change SUPERSEDED is deliberately NOT a fallback: the route
        # moved mid-await, so a newer navigation owns the canvas and will
        # paint (or already painted) its own surface -- rebuilding the
        # whole screen here is exactly the transitioning-surface stomp
        # lessons-testing-evidence.md records for TASK-15706.

    async def _apply_library_media_active_surface(self) -> None:
        """Synchronize the permanent Media Reader without replacing Items.

        Shared completion seam for the media open click and the media
        detail worker (task-21116). Skips entirely when the media surface
        no longer owns the route -- the fetched detail is retained state,
        and rebuilding an unrelated mounted surface is the TASK-15706
        transition stomp.

        The Trash view is one of those "no longer owns it" cases (review
        round, M1): it is a distinct surface with its own updater
        (``_sync_library_canvas(self, "media-trash")``), so a media-detail
        worker landing after the user pressed "Trash" must leave it alone
        rather than remount it and drop its selection.

        Returns:
            None.
        """
        if self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA:
            return
        viewer = self._mounted_library_media_viewer()
        if viewer is not None and self._sync_library_media_viewer_state(viewer):
            try:
                canvas = self.query_one("#library-media-canvas", LibraryMediaCanvas)
            except (NoMatches, QueryError):
                pass
            else:
                canvas.apply_reader_state(self._build_library_media_state())
            return
        self.refresh(recompose=True)

    async def _apply_library_media_list_return(
        self,
        media_return: _LibraryMediaReturnReceipt | None,
    ) -> None:
        """Project the viewer-to-list return and arm the list entry focus.

        Args:
            media_return: The exited viewer's origin row id and list scroll
                offset, captured by ``_open_library_media_viewer``.

        Returns:
            None.
        """
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view == "trash"
        ):
            return
        await self._apply_library_open_item_surface(
            self._build_library_media_active_child,
            then=partial(self._finish_library_media_list_return, media_return),
        )

    def _finish_library_media_list_return(
        self,
        media_return: _LibraryMediaReturnReceipt | None,
    ) -> None:
        """Arm row/scroll/focus only after the normal Media child is mounted."""
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view != "list"
        ):
            return
        self._register_footer_shortcuts()
        viewer = self._mounted_library_media_viewer()
        if viewer is not None:
            self._sync_library_media_viewer_state(viewer)
        self._arm_library_list_entry_focus(media_return=media_return)

    async def _reconcile_library_entry_state(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Project one current snapshot into the mounted rail and canvas."""
        pending = (generation, route_key)
        if not self.is_attached:
            return self._supersede_library_entry_reconcile(generation, route_key)
        if generation != self._library_snapshot_state_generation:
            return self._supersede_library_entry_reconcile(generation, route_key)
        if route_key != self._library_entry_route_key():
            return self._supersede_library_entry_reconcile(generation, route_key)
        if (
            not self._library_entry_reconcile_dirty
            and self._library_snapshot_rendered_generation == generation
        ):
            if self._library_entry_reconcile_pending == pending:
                self._library_entry_reconcile_pending = None
            self._library_entry_reconcile_retry_generation = None
            return LibraryEntryReconcileResult.ALREADY_CURRENT

        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        try:
            rail = self.query_one("#library-rail", LibraryRail)
            header = self.query_one("#library-header-line", Static)
        except (NoMatches, QueryError):
            return self._retry_or_fail_library_entry_reconcile(generation, route_key)

        identity = self._capture_library_entry_focus()
        restore_focus = (
            partial(
                self._restore_library_entry_focus,
                identity,
                generation=generation,
                route_key=route_key,
            )
            if identity is not None
            else None
        )
        try:
            rail.sync_state(
                shell,
                self._library_rail_preferences(),
                query=self._library_rag_query,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
            )
            header_renderable = header.renderable
            header_text = getattr(header_renderable, "plain", str(header_renderable))
            expected_header = self._library_header_line(shell.header_line)
            if header_text != expected_header:
                header.update(expected_header)
        except Exception:
            logger.debug("Library snapshot shell reconciliation failed.")
            if restore_focus is not None:
                restore_focus()
            return self._fail_library_entry_reconcile(generation, route_key)

        sync_kind: str | None = None
        expected_selector = ""
        replacement: Widget | None = None
        local_list_surface = False
        if shell.canvas_kind == "conversations":
            local_list_surface = True
            expected_selector = "#library-conversations-canvas"
            if self._library_lookup_error is None:
                conversations_state = self._build_library_conversations_state()
                self._adopt_library_conversation_state_selection(
                    conversations_state.selected_id
                )
                sync_kind = "conversations"
                replacement = LibraryConversationsCanvas(
                    conversations_state,
                    id="library-conversations-canvas",
                )
        elif (
            shell.canvas_kind == LIBRARY_CANVAS_KIND_NOTES
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            local_list_surface = True
            expected_selector = "#library-notes-canvas"
            if self._library_lookup_error is None:
                sync_kind = "notes"
                replacement = LibraryNotesCanvas(
                    **self._library_notes_list_canvas_kwargs(),
                    id="library-notes-canvas",
                )
        elif shell.canvas_kind == "prompts":
            local_list_surface = True
            expected_selector = "#library-prompts-canvas"
            if self._library_lookup_error is None:
                sync_kind = "prompts"
                replacement = LibraryPromptsListCanvas(
                    **self._library_prompts_list_canvas_kwargs(),
                    id="library-prompts-canvas",
                )
        elif shell.canvas_kind == "skills":
            local_list_surface = True
            expected_selector = "#library-skills-canvas"
            if self._library_lookup_error is None:
                sync_kind = "skills"
                replacement = LibrarySkillsListCanvas(
                    **self._library_skills_list_canvas_kwargs(),
                    id="library-skills-canvas",
                )
        elif shell.canvas_kind == "handoff":
            sync_kind = "handoff"
            expected_selector = "#library-study-handoff-canvas"
        elif shell.canvas_kind == "empty":
            sync_kind = "landing"
            expected_selector = "#library-landing-canvas"

        if local_list_surface and self._library_lookup_error is not None:
            expected_selector = "#library-canvas-error"
            replacement = Static(
                self._library_lookup_error,
                id="library-canvas-error",
                classes="destination-purpose",
                markup=False,
            )

        if expected_selector and self.query(expected_selector):
            if sync_kind is None:
                if restore_focus is not None:
                    restore_focus()
                self._complete_library_entry_reconcile(generation, route_key)
                return LibraryEntryReconcileResult.APPLIED
            capture = self._library_entry_focus_capture
            finish = partial(
                self._finish_library_entry_canvas_sync,
                identity,
                generation=generation,
                route_key=route_key,
            )
            if _sync_library_canvas(
                self,
                sync_kind,
                then=finish,
                allow_screen_fallback=False,
                notes_focus_identity=(
                    capture.notes_identity
                    if capture is not None and capture.identity is identity
                    else None
                ),
                deferred_guard=partial(
                    self._library_entry_reconcile_is_current,
                    generation,
                    route_key,
                ),
            ):
                if sync_kind == "conversations":
                    self._ensure_library_conversation_reader_selection()
                self._library_entry_reconcile_retry_generation = None
                return LibraryEntryReconcileResult.APPLIED
            if restore_focus is not None:
                restore_focus()
            return self._retry_or_fail_library_entry_reconcile(generation, route_key)

        if local_list_surface and replacement is not None:
            try:
                canvas_host = self._library_entry_canvas_host()
                if canvas_host is None:
                    raise NoMatches("Library canvas host is unavailable")
                outgoing = tuple(canvas_host.children)
                for child in outgoing:
                    child.display = False
                if outgoing:
                    await canvas_host.remove_children(outgoing)
                if generation != self._library_snapshot_state_generation:
                    await self._repair_library_entry_canvas_owner()
                    return self._supersede_library_entry_reconcile(
                        generation, route_key
                    )
                if route_key != self._library_entry_route_key():
                    await self._repair_library_entry_canvas_owner()
                    return self._supersede_library_entry_reconcile(
                        generation, route_key
                    )
                await canvas_host.mount(replacement)
            except Exception:
                logger.debug("Library snapshot canvas replacement failed.")
                return self._retry_or_fail_library_entry_reconcile(
                    generation, route_key
                )
            if generation != self._library_snapshot_state_generation:
                await self._repair_library_entry_canvas_owner()
                return self._supersede_library_entry_reconcile(generation, route_key)
            if route_key != self._library_entry_route_key():
                await self._repair_library_entry_canvas_owner()
                return self._supersede_library_entry_reconcile(generation, route_key)
            if sync_kind is not None:
                capture = self._library_entry_focus_capture
                finish = partial(
                    self._finish_library_entry_canvas_sync,
                    identity,
                    generation=generation,
                    route_key=route_key,
                )
                if not _sync_library_canvas(
                    self,
                    sync_kind,
                    then=finish,
                    allow_screen_fallback=False,
                    notes_focus_identity=(
                        capture.notes_identity
                        if capture is not None and capture.identity is identity
                        else None
                    ),
                    deferred_guard=partial(
                        self._library_entry_reconcile_is_current,
                        generation,
                        route_key,
                    ),
                ):
                    return self._retry_or_fail_library_entry_reconcile(
                        generation, route_key
                    )
                if sync_kind == "conversations":
                    self._ensure_library_conversation_reader_selection()
                # A freshly constructed replacement already carries the
                # target state, so its sync may be a no-op and never fire the
                # queued after-recompose completion.  APPLIED must still
                # settle this generation; the guarded focus callback can run
                # later without changing that ownership result.
                self._complete_library_entry_reconcile(generation, route_key)
            else:
                if restore_focus is not None:
                    restore_focus()
                self._complete_library_entry_reconcile(generation, route_key)
            return LibraryEntryReconcileResult.APPLIED

        if expected_selector:
            if restore_focus is not None:
                restore_focus()
            return self._retry_or_fail_library_entry_reconcile(generation, route_key)

        if shell.canvas_kind == "media":
            viewer = self._mounted_library_media_viewer()
            if viewer is None or not self._sync_library_media_viewer_state(viewer):
                if restore_focus is not None:
                    restore_focus()
                return self._retry_or_fail_library_entry_reconcile(
                    generation, route_key
                )

        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_SEARCH:
            try:
                self._sync_library_rag_scope_toggle_and_run_gate_widgets()
            except Exception:
                logger.debug("Library Search/RAG snapshot sync failed.")
                if restore_focus is not None:
                    restore_focus()
                return self._retry_or_fail_library_entry_reconcile(
                    generation, route_key
                )

        if restore_focus is not None:
            restore_focus()
        self._complete_library_entry_reconcile(generation, route_key)
        return LibraryEntryReconcileResult.APPLIED

    def _apply_local_source_snapshot(
        self,
        records: dict[str, tuple[Mapping[str, Any], ...]],
        counts: dict[str, int],
        total_known: dict[str, bool],
        lookup_error: str | None = None,
        recovery_state: DestinationRecoveryState | None = None,
        study_counts: dict[str, int | None] | None = None,
        *,
        schedule_reconcile: bool = True,
    ) -> bool:
        normalized_records = self._carry_selected_conversation_into_snapshot(
            dict(records)
        )
        normalized_counts = dict(counts)
        normalized_total_known = dict(total_known)
        normalized_study_counts = (
            dict(study_counts)
            if study_counts is not None
            else {"study_decks": None, "flashcards_due": None, "quizzes": None}
        )
        presentation_changed = not self._library_loaded or (
            normalized_records != self._local_source_records
            or normalized_counts != self._local_source_counts
            or normalized_total_known != self._local_source_total_known
            or lookup_error != self._library_lookup_error
            or recovery_state != self._library_lookup_recovery_state
            or normalized_study_counts != self._library_study_counts
        )
        if not presentation_changed:
            if (
                schedule_reconcile
                and self.is_attached
                and not self._file_notes_active()
                and (
                    self._library_entry_reconcile_dirty
                    or self._library_snapshot_rendered_generation
                    != self._library_snapshot_state_generation
                )
            ):
                self._library_entry_reconcile_dirty = True
                self._schedule_library_entry_reconcile(
                    self._library_snapshot_state_generation,
                    self._library_entry_route_key(),
                )
            return False

        self._local_source_records = normalized_records
        self._local_source_counts = normalized_counts
        self._local_source_total_known = normalized_total_known
        self._library_lookup_error = lookup_error
        self._library_lookup_recovery_state = recovery_state
        self._library_study_counts = normalized_study_counts
        self._library_loaded = True
        self._invalidate_library_workspace_depth_state()
        self._library_snapshot_state_generation += 1
        self._library_entry_reconcile_dirty = True
        if schedule_reconcile and self.is_attached and not self._file_notes_active():
            self._schedule_library_entry_reconcile(
                self._library_snapshot_state_generation,
                self._library_entry_route_key(),
            )
        return True

    def _seed_local_source_snapshot_from_cache(
        self, *, now: float | None = None
    ) -> bool:
        """Apply a recent detached cache snapshot before first composition."""
        stamp = getattr(self.app_instance, "_library_source_snapshot_cache_stamp", None)
        if not isinstance(stamp, (int, float)) or not math.isfinite(float(stamp)):
            return False
        age = (time.monotonic() if now is None else now) - float(stamp)
        if age < 0 or age >= LIBRARY_SNAPSHOT_CACHE_TTL_SECONDS:
            return False
        snapshot = clone_library_source_snapshot(
            getattr(self.app_instance, "_library_source_snapshot_cache", None)
        )
        if snapshot is None:
            return False
        self._apply_local_source_snapshot(*snapshot, schedule_reconcile=False)
        self._library_snapshot_rendered_generation = (
            self._library_snapshot_state_generation
        )
        self._library_entry_reconcile_dirty = False
        return True

    def _apply_source_snapshot_timeout(self) -> None:
        """Avoid leaving Library in an indefinite loading state."""
        if self._library_loaded:
            return
        self._apply_local_source_snapshot(
            {"notes": (), "media": (), "conversations": ()},
            {"notes": 0, "media": 0, "conversations": 0},
            {"notes": True, "media": True, "conversations": True},
            LIBRARY_SERVICE_ERROR_COPY,
            None,
            {"study_decks": None, "flashcards_due": None, "quizzes": None},
        )

    @staticmethod
    async def _run_library_service_call(
        callable_obj: Any,
        *args: Any,
        isolate_in_worker: bool = False,
        **kwargs: Any,
    ) -> Any:
        if inspect.iscoroutinefunction(callable_obj) and not isolate_in_worker:
            return await callable_obj(*args, **kwargs)

        def invoke_service_in_worker() -> Any:
            result = callable_obj(*args, **kwargs)
            if inspect.isawaitable(result):

                async def await_result() -> Any:
                    return await result

                # Runs via asyncio.to_thread: this thread has no event loop,
                # and the awaitable must complete here so blocking async
                # services stay off the UI loop.
                return asyncio.run(  # policy-exception: worker-thread loop
                    await_result()
                )
            return result

        if isolate_in_worker:
            return await asyncio.to_thread(invoke_service_in_worker)

        result = await asyncio.to_thread(lambda: callable_obj(*args, **kwargs))
        if inspect.isawaitable(result):
            return await result
        return result

    @staticmethod
    def _safe_text(value: Any, fallback: str = "", *, max_length: int = 500) -> str:
        text = sanitize_string(str(value or ""), max_length=max_length).strip()
        if not text:
            return fallback
        text = text.replace("<", "").replace(">", "")
        for pattern in ("javascript:", "onclick=", "onerror="):
            text = text.replace(pattern, "")
        if validate_text_input(text, max_length=max_length, allow_html=False):
            return text
        return fallback

    @staticmethod
    def _sanitize_media_field(value: Any, *, max_length: int) -> str:
        """Sanitize a user-entered media field at the UI boundary.

        Runs the shared ``input_validation`` helpers before the value is
        handed to a persistence service (``update_media_item`` /
        ``create_highlight`` / ``save_analysis_version``), so over-long
        input is truncated and control characters are stripped, and any
        HTML/script markup that trips ``validate_text_input`` is neutralized
        -- keeping unsafe or oversized content from reaching storage. Normal
        text (including a lone ``<``/``>`` in prose) is returned unchanged.

        Args:
            value: The raw widget value to sanitize.
            max_length: Maximum length to allow before truncation.

        Returns:
            The sanitized field value.
        """
        text = sanitize_string(str(value or ""), max_length=max_length)
        if not validate_text_input(text, max_length=max_length, allow_html=False):
            # A dangerous HTML/script pattern was detected: break it up
            # (drop the angle brackets and inline handlers) but keep the
            # rest of the field rather than discarding user content.
            text = text.replace("<", "").replace(">", "")
            for pattern in ("javascript:", "onclick=", "onerror="):
                text = text.replace(pattern, "")
        return text

    @staticmethod
    def _sanitize_note_content(value: Any, *, max_length: int) -> str:
        """Length-cap Library note body content without HTML neutering.

        ``_sanitize_media_field`` is right for short metadata fields (a
        title, a highlight quote), but note bodies routinely contain code
        blocks, HTML/JS snippets in prose, or long-form markdown -- running
        them through the same control-character stripping and
        angle-bracket/``onclick=``-pattern neutering would silently mangle
        legitimate content. The only boundary a note body needs is a hard
        length cap before it reaches the persistence seam.

        Args:
            value: The raw ``TextArea`` text to sanitize.
            max_length: Maximum length to allow before truncation.

        Returns:
            ``value`` unchanged, truncated to ``max_length`` if needed.
        """
        text = str(value or "")
        if len(text) > max_length:
            text = text[:max_length]
        return text

    @staticmethod
    def _note_word_count(content: str) -> int:
        """Count words in a Library note body for the meta line's status text.

        Counts whitespace-delimited runs via a regex scan instead of
        ``len(content.split())``, which would materialize a full list of
        every word just to throw it away -- wasteful for the very large
        note bodies this editor allows (see ``LIBRARY_NOTE_CONTENT_MAX_CHARS``).

        Args:
            content: The note body text to count words in.

        Returns:
            The number of whitespace-delimited words.
        """
        return sum(1 for _ in re.finditer(r"\S+", content))

    def _library_note_keywords_from_input(self, raw_value: str) -> list[str] | None:
        """Parse and sanitize the Library note editor's keywords Input.

        Args:
            raw_value: The raw ``#library-note-keywords`` Input value.

        Returns:
            A list of sanitized, non-empty keyword tokens (each capped at
            100 characters), or ``None`` when no keywords were entered --
            matching the ``save_note`` seam's "omit keywords" contract.
        """
        parsed = [item.strip() for item in (raw_value or "").split(",") if item.strip()]
        if not parsed:
            return None
        sanitized = [
            self._sanitize_media_field(item, max_length=100) for item in parsed
        ]
        sanitized = [item for item in sanitized if item]
        return sanitized or None

    def _library_notes_user_id(self) -> str:
        """Return the notes-service user id, falling back to the shared default."""
        return getattr(self.app_instance, "notes_user_id", None) or "default_user"

    @staticmethod
    def _safe_sync_scope_text(value: Any, *, max_length: int = 200) -> str | None:
        """Return a validated Sync scope value or None when unsafe/empty."""

        text = sanitize_string(str(value or ""), max_length=max_length).strip()
        text = " ".join(text.split())
        if not text:
            return None
        if validate_text_input(text, max_length=max_length, allow_html=False):
            return text
        return None

    @classmethod
    def _source_optional_title(
        cls, source_type: str, record: Mapping[str, Any]
    ) -> str | None:
        """Return a trustworthy raw source title without a display fallback."""

        title_keys_by_source = {
            "notes": ("title", "name", "note_title", "note_name"),
            "media": ("title", "name", "media_title", "file_name", "url"),
            "conversations": ("title", "name", "conversation_title", "label"),
        }
        for key in title_keys_by_source[source_type]:
            title = cls._safe_text(record.get(key))
            if title:
                return title
        return None

    @classmethod
    def _source_title(cls, source_type: str, record: Mapping[str, Any]) -> str:
        return cls._source_optional_title(source_type, record) or "Untitled source"

    @staticmethod
    def _response_records_and_count(
        result: Any,
    ) -> tuple[tuple[Mapping[str, Any], ...], int, bool]:
        total = None
        if isinstance(result, Mapping):
            raw_items = result.get("items")
            pagination = result.get("pagination")
            total = result.get("total")
            if isinstance(pagination, Mapping):
                total = pagination.get("total", pagination.get("total_items", total))
        elif isinstance(result, Sequence) and not isinstance(
            result, (str, bytes, bytearray)
        ):
            raw_items = result
        else:
            raw_items = ()

        records = tuple(
            record for record in tuple(raw_items or ()) if isinstance(record, Mapping)
        )
        total_known = total is not None
        try:
            count = int(total) if total is not None else len(records)
        except (TypeError, ValueError):
            count = len(records)
            total_known = False
        return records, max(count, 0), total_known

    async def _notes_true_count_or_none(
        self, count_notes: Any, **kwargs: Any
    ) -> int | None:
        """Fetch the authoritative local notes total, degrading quietly on failure.

        Runs inside the same ``asyncio.gather`` as the paginated ``list_notes``
        fetch (see ``_list_local_source_snapshot``). ``list_notes`` on the
        real local backend returns a plain list with no total, so the rail
        badge would otherwise always show the "showing up to N" sample-cap
        suffix. When the seam is missing entirely, the caller never invokes
        this method (guarded by ``callable(count_notes)``); when it *is*
        present but raises here, the failure is swallowed and ``None`` is
        returned so the caller falls back to the paginated response's own
        record count instead of surfacing an error or failing the whole
        snapshot fetch.

        Args:
            count_notes: The bound ``count_notes`` callable to invoke.
            **kwargs: Forwarded to ``count_notes`` (``scope``, ``user_id``).

        Returns:
            The exact notes count, or ``None`` if the call failed or
            returned something other than an ``int``.
        """
        try:
            result = await self._run_library_service_call(
                count_notes, isolate_in_worker=True, **kwargs
            )
        except Exception:
            logger.opt(exception=True).warning(
                "Failed to fetch exact local notes count; using sample count."
            )
            return None
        return result if isinstance(result, int) else None

    async def _prompts_count_or_none(
        self, count_prompts: Any, **kwargs: Any
    ) -> int | None:
        """Fetch the exact local prompts total, degrading quietly on failure.

        Runs inside the same ``asyncio.gather`` as the notes/media/
        conversations fetch (see ``_list_local_source_snapshot``). Mirrors
        ``_notes_true_count_or_none``: the count seam is optional (guarded
        by ``callable(count_prompts)`` at the call site), so when it is
        missing this method is never invoked, and when it *is* present but
        raises, the failure is swallowed and ``None`` is returned. A failed
        count has no fallback of its own, so it simply renders the Prompts
        rail row with no badge rather than failing the exact browse result.

        Args:
            count_prompts: The bound ``count_prompts`` callable to invoke.
            **kwargs: Forwarded to ``count_prompts`` (``mode``).

        Returns:
            The exact prompts count, or ``None`` if the call failed or
            returned something other than an ``int``.
        """
        try:
            result = await self._run_library_service_call(
                count_prompts, isolate_in_worker=True, **kwargs
            )
        except Exception:
            logger.opt(exception=True).warning(
                "Failed to fetch local prompts count; Prompts row will show no count."
            )
            return None
        return result if isinstance(result, int) else None

    async def _skills_context_or_none(
        self, get_context: Any, **kwargs: Any
    ) -> Mapping[str, Any] | None:
        """Fetch the local skills context, degrading quietly on failure.

        Runs inside the same ``asyncio.gather`` as the notes/media/
        conversations/prompts fetch (see ``_list_local_source_snapshot``).
        Mirrors ``_prompts_count_or_none``: the seam is optional (guarded by
        ``callable(get_context)`` at the call site), so when it is missing
        this method is never invoked, and when it *is* present but raises,
        the failure is swallowed and ``None`` is returned -- the Skills
        rail row then renders uncounted with an empty context payload
        rather than surfacing an error or failing the whole snapshot
        fetch.

        Unlike prompts (whose rail count and exact browse result have
        separate owners), a single ``get_context`` call here supplies both:
        the count is derived from its
        ``available_skills``/``blocked_skills`` lengths by the caller, and
        the same payload is stashed for a future Skills canvas to render.

        Args:
            get_context: The bound ``skills_scope_service.get_context``
                callable to invoke.
            **kwargs: Forwarded to ``get_context`` (``mode``).

        Returns:
            The normalized ``get_context`` payload (``available_skills`` +
            ``blocked_skills``), or ``None`` if the call failed or returned
            something other than a ``Mapping``.
        """
        try:
            result = await self._run_library_service_call(
                get_context, isolate_in_worker=True, **kwargs
            )
        except Exception:
            logger.opt(exception=True).warning(
                "Failed to fetch local skills context; Skills row will show no count."
            )
            return None
        return result if isinstance(result, Mapping) else None

    async def _study_count_or_none(
        self, count_callable: Any, label: str, **kwargs: Any
    ) -> int | None:
        """Fetch a decorative Create-rail count, degrading quietly on failure.

        Runs inside the same ``asyncio.gather`` as the local source snapshot
        fetch (see ``_list_local_source_snapshot``). Unlike the three browse
        sources (notes/media/conversations), study/quiz counts are purely
        decorative rail badges: the underlying scope-service methods can
        raise ``PolicyDeniedError`` (via ``_enforce_policy``) or a plain
        ``ValueError`` (e.g. local backend unavailable) depending on the
        runtime, and none of that should ever surface as Library error copy
        or fail the snapshot fetch -- it just degrades to ``None``, which
        the rail renders as an uncounted row.

        Args:
            count_callable: The bound count method to invoke (e.g.
                ``study_scope_service.count_decks``).
            label: Human-readable label for the debug log on failure.
            **kwargs: Forwarded to ``count_callable``.

        Returns:
            The exact count, or ``None`` if the call failed or returned
            something other than an ``int``.
        """
        # SQLite ``:memory:`` connections are thread-local (``threading.local``
        # on ``CharactersRAGDB``) -- only the thread that created the DB has
        # the migrated schema. Forcing this single COUNT(*) query onto a
        # worker thread would open a brand-new, unmigrated in-memory
        # connection and fail. Same guard as
        # ``LibraryLocalRagSearchService._search_conversations``.
        chachanotes_db = getattr(self.app_instance, "chachanotes_db", None)
        isolate_in_worker = not bool(getattr(chachanotes_db, "is_memory_db", False))
        try:
            result = await self._run_library_service_call(
                count_callable, isolate_in_worker=isolate_in_worker, **kwargs
            )
        except Exception:
            logger.opt(exception=True).debug(
                f"Failed to fetch {label} count for Library create rail."
            )
            return None
        return result if isinstance(result, int) else None

    async def _list_local_source_snapshot(
        self,
    ) -> tuple[
        dict[str, tuple[Mapping[str, Any], ...]],
        dict[str, int],
        dict[str, bool],
        str | None,
        DestinationRecoveryState | None,
        dict[str, int | None],
    ]:
        notes_service = getattr(self.app_instance, "notes_scope_service", None)
        media_service = getattr(self.app_instance, "media_reading_scope_service", None)
        conversation_service = getattr(
            self.app_instance, "chat_conversation_scope_service", None
        )
        study_service = getattr(self.app_instance, "study_scope_service", None)
        quiz_service = getattr(self.app_instance, "study_quiz_scope_service", None)
        prompt_service = getattr(self.app_instance, "prompt_scope_service", None)
        skills_service = getattr(self.app_instance, "skills_scope_service", None)
        list_notes = getattr(notes_service, "list_notes", None)
        list_media = getattr(media_service, "list_media_items", None)
        list_conversations = getattr(conversation_service, "list_conversations", None)
        count_notes = getattr(notes_service, "count_notes", None)
        count_notes_available = callable(count_notes)
        count_decks = getattr(study_service, "count_decks", None)
        count_due_flashcards = getattr(study_service, "count_due_flashcards", None)
        count_quizzes = getattr(quiz_service, "count_quizzes", None)
        count_prompts = getattr(prompt_service, "count_prompts", None)
        count_prompts_available = callable(count_prompts)
        get_skills_context = getattr(skills_service, "get_context", None)
        get_skills_context_available = callable(get_skills_context)
        notes_user_id = (
            getattr(self.app_instance, "notes_user_id", None) or "default_user"
        )

        empty_records: dict[str, tuple[Mapping[str, Any], ...]] = {
            "notes": (),
            "media": (),
            "conversations": (),
            # Rail-only count carrier; the second slot intentionally stays empty.
            "prompts": (None, ()),
            # Likewise ``(count, context_payload)`` -- see ``__init__``'s
            # comment on this same key.
            "skills": (None, {"available_skills": [], "blocked_skills": []}),
        }
        empty_counts = {"notes": 0, "media": 0, "conversations": 0}
        empty_total_known = {"notes": True, "media": True, "conversations": True}
        empty_study_counts: dict[str, int | None] = {
            "study_decks": None,
            "flashcards_due": None,
            "quizzes": None,
        }
        if not all(
            callable(call) for call in (list_notes, list_media, list_conversations)
        ):
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                LIBRARY_SERVICE_UNAVAILABLE_COPY,
                None,
                empty_study_counts,
            )

        gathered_calls = [
            self._run_library_service_call(
                list_notes,
                scope="local_note",
                limit=LIBRARY_SOURCE_PAGE_SIZES["notes"],
                offset=0,
                user_id=notes_user_id,
                isolate_in_worker=True,
            ),
            self._run_library_service_call(
                list_media,
                mode="local",
                page=1,
                results_per_page=LIBRARY_SOURCE_PAGE_SIZES["media"],
                include_keywords=False,
                isolate_in_worker=True,
            ),
            self._run_library_service_call(
                list_conversations,
                mode="local",
                # "all" spans global- and workspace-scoped conversations:
                # Console chats persisted inside a workspace session are
                # workspace-scoped and would be invisible (and uncounted)
                # under the service's default 'global' scope.
                scope_type="all",
                limit=LIBRARY_SOURCE_PAGE_SIZES["conversations"],
                offset=0,
            ),
        ]
        # Optional decorative/exact counts are appended (and unpacked back)
        # by key so this stays simple as the number of optional seams
        # grows -- see ``_notes_true_count_or_none``/``_study_count_or_none``
        # for the per-count degrade-to-None contract.
        optional_calls: list[tuple[str, Any]] = []
        if count_notes_available:
            optional_calls.append(
                (
                    "notes_true_count",
                    self._notes_true_count_or_none(
                        count_notes, scope="local_note", user_id=notes_user_id
                    ),
                )
            )
        if callable(count_decks):
            optional_calls.append(
                ("study_decks", self._study_count_or_none(count_decks, "study decks"))
            )
        if callable(count_due_flashcards):
            optional_calls.append(
                (
                    "flashcards_due",
                    self._study_count_or_none(count_due_flashcards, "flashcards due"),
                )
            )
        if callable(count_quizzes):
            optional_calls.append(
                ("quizzes", self._study_count_or_none(count_quizzes, "quizzes"))
            )
        if count_prompts_available:
            optional_calls.append(
                (
                    "prompts_count",
                    self._prompts_count_or_none(count_prompts, mode="local"),
                )
            )
        if get_skills_context_available:
            optional_calls.append(
                (
                    "skills_context",
                    self._skills_context_or_none(get_skills_context, mode="local"),
                )
            )
        gathered_calls.extend(call for _, call in optional_calls)

        try:
            gathered_results = await asyncio.wait_for(
                asyncio.gather(*gathered_calls),
                timeout=LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS,
            )
        except PolicyDeniedError as exc:
            policy_message = self._safe_text(
                exc.user_message, LIBRARY_SERVICE_ERROR_COPY
            )
            recovery_state = policy_denied_recovery_state(
                exc,
                unavailable_what="Use Library sources in Console",
                stable_selector="library-source-error",
                policy_message=policy_message,
            )
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                recovery_state.visible_copy,
                recovery_state,
                empty_study_counts,
            )
        except Exception:
            logger.opt(exception=True).warning(
                "Failed to load local Library source snapshot.",
            )
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                LIBRARY_SERVICE_ERROR_COPY,
                None,
                empty_study_counts,
            )

        notes_result, media_result, conversation_result, *optional_results = (
            gathered_results
        )
        optional_values = dict(
            zip((key for key, _ in optional_calls), optional_results)
        )

        notes_true_count = optional_values.get("notes_true_count")
        prompts_count = optional_values.get("prompts_count")
        skills_context = optional_values.get("skills_context")
        if isinstance(skills_context, Mapping):
            skills_available = skills_context.get("available_skills") or []
            skills_blocked = skills_context.get("blocked_skills") or []
            skills_count: int | None = len(skills_available) + len(skills_blocked)
            skills_payload: Mapping[str, Any] = skills_context
        else:
            skills_count = None
            skills_payload = {"available_skills": [], "blocked_skills": []}
        study_counts: dict[str, int | None] = {
            "study_decks": optional_values.get("study_decks"),
            "flashcards_due": optional_values.get("flashcards_due"),
            "quizzes": optional_values.get("quizzes"),
        }

        notes, notes_count, notes_total_known = self._response_records_and_count(
            notes_result
        )
        if notes_true_count is not None:
            notes_count = notes_true_count
            notes_total_known = True
        media, media_count, media_total_known = self._response_records_and_count(
            media_result
        )
        (
            conversations,
            conversations_count,
            conversations_total_known,
        ) = self._response_records_and_count(conversation_result)
        return (
            {
                "notes": notes,
                "media": media,
                "conversations": conversations,
                # The second slot is permanently empty: Prompt rows are owned
                # by the exact request-tokened browse result, not this sample.
                "prompts": (prompts_count, ()),
                # (count, context_payload) -- see the ``__init__``/
                # ``empty_records`` comments above. ``skills_count`` spans
                # BOTH ``available_skills`` and ``blocked_skills`` (needs
                # review) per the spec's blocked-skills visibility rule, and
                # degrades to ``None``/empty payload whenever the local
                # backend has no ``get_context`` seam or the fetch failed
                # (degrade-quietly contract; see ``_skills_context_or_none``).
                "skills": (skills_count, skills_payload),
            },
            {
                "notes": notes_count,
                "media": media_count,
                "conversations": conversations_count,
            },
            {
                "notes": notes_total_known,
                "media": media_total_known,
                "conversations": conversations_total_known,
            },
            None,
            None,
            study_counts,
        )

    def _has_local_sources(self) -> bool:
        return any(count > 0 for count in self._local_source_counts.values())

    def _source_snapshot_body(self) -> str:
        lines = ["Local Library source snapshot staged for Console:", ""]
        for source_type, label in (
            ("notes", "Notes"),
            ("media", "Media"),
            ("conversations", "Conversations"),
        ):
            lines.append(self._source_count_label(source_type, label))
            for index, record in enumerate(
                self._local_source_records[source_type], start=1
            ):
                lines.append(f"  {index}. {self._source_title(source_type, record)}")
            lines.append("")
        return "\n".join(lines).strip()

    def _source_count_label(self, source_type: str, label: str) -> str:
        count = self._local_source_counts[source_type]
        if self._local_source_total_known[source_type]:
            return f"{label}: {count}"
        return (
            f"{label} (showing up to {LIBRARY_SOURCE_PAGE_SIZES[source_type]}): {count}"
        )

    def _hub_source_count_label(self, source_type: str, label: str) -> str:
        count = self._local_source_counts[source_type]
        suffix = "" if self._local_source_total_known[source_type] else "+"
        return f"{label}: {count}{suffix}"

    def _source_sample_titles(self, source_type: str) -> list[str]:
        return [
            self._source_title(source_type, record)
            for record in self._local_source_records[source_type]
        ]

    def _conversation_records(self) -> tuple[Mapping[str, Any], ...]:
        return tuple(self._library_conversation_page_records)

    def _conversation_record_id(self, record: Mapping[str, Any], index: int) -> str:
        return self._source_record_id(record) or f"conversation-{index + 1}"

    def _ensure_selected_conversation_id(self) -> str:
        records = self._conversation_records()
        record_ids = {
            self._conversation_record_id(record, index)
            for index, record in enumerate(records)
        }
        if self._selected_conversation_id in record_ids:
            return self._selected_conversation_id
        self._selected_conversation_id = (
            self._conversation_record_id(records[0], 0) if records else ""
        )
        return self._selected_conversation_id

    def _selected_conversation_record(self) -> tuple[int, Mapping[str, Any]] | None:
        selected_id = self._ensure_selected_conversation_id()
        if not selected_id:
            return None
        for index, record in enumerate(self._conversation_records()):
            if self._conversation_record_id(record, index) == selected_id:
                return index, record
        return None

    @classmethod
    def _conversation_message_count_label(cls, record: Mapping[str, Any]) -> str:
        for key in (
            "message_count",
            "messages_count",
            "messageCount",
            "message_total",
            "messages_total",
        ):
            value = record.get(key)
            if isinstance(value, int):
                return f"Messages: {value}"
            if isinstance(value, str) and value.strip().isdigit():
                return f"Messages: {value.strip()}"
        messages = record.get("messages")
        if isinstance(messages, Sequence) and not isinstance(
            messages, (str, bytes, bytearray)
        ):
            return f"Messages: {len(messages)}"
        return "Messages: unknown"

    @classmethod
    def _conversation_workspace_label(cls, record: Mapping[str, Any]) -> str:
        for key in ("workspace_name", "workspace_id", "workspace", "scope_id"):
            value = cls._safe_text(record.get(key), max_length=64)
            if value:
                return f"Workspace: {value}"
        return "Workspace: unassigned"

    @classmethod
    def _conversation_updated_label(cls, record: Mapping[str, Any]) -> str:
        for key in (
            "updated_at",
            "last_modified",
            "last_updated",
            "modified_at",
            "created_at",
        ):
            value = cls._safe_text(record.get(key), max_length=64)
            if value:
                return f"Updated: {value}"
        return "Updated: unknown"

    def _selected_conversation_handoff_payload(self) -> ChatHandoffPayload | None:
        selected = self._selected_conversation_record()
        if selected is None:
            return None
        index, record = selected
        conversation_id = self._conversation_record_id(record, index)
        title = self._source_title("conversations", record)
        message_count = self._conversation_message_count_label(record)
        workspace_label = self._conversation_workspace_label(record)
        updated_label = self._conversation_updated_label(record)
        body = "\n".join(
            (
                f"Conversation: {title}",
                f"Conversation ID: {conversation_id}",
                message_count,
                workspace_label,
                updated_label,
                "Source authority: local",
            )
        )
        return ChatHandoffPayload(
            source="library",
            item_type="conversation",
            title=title,
            body=body,
            source_id=conversation_id,
            display_summary=f"Conversation staged: {title}",
            suggested_prompt="Use this conversation as source context for my next question.",
            runtime_backend="local",
            source_owner="local",
            source_selector_state="local",
            discovery_owner="conversation",
            discovery_entity_id=conversation_id,
            metadata={
                "conversation_id": conversation_id,
                "conversation_title": title,
                "message_count_label": message_count,
                "workspace_label": workspace_label,
                "updated_label": updated_label,
                "source_authority": "local",
            },
        )

    def _selected_media_handoff_payload(self) -> ChatHandoffPayload | None:
        """Build the Console handoff payload for the open Library media item.

        Mirrors ``_selected_conversation_handoff_payload``, but reads the
        currently loaded media detail (``_library_media_detail``) instead of
        a selected browser row -- the media viewer's "Use in Console" action
        stages whatever item is open in the in-canvas viewer, not a row
        selection from the list.

        Returns:
            A ``ChatHandoffPayload`` staging the open media item as Console
            context, or None when no media item is currently loaded.
        """
        detail = self._library_media_detail
        if not isinstance(detail, Mapping):
            return None
        # task-22208: memoized -- this runs inside the viewer sync's
        # unchanged compare (console representation) on every interaction.
        viewer = self._library_media_viewer_state_cached(detail)
        external_detail = self._library_media_reader_session.external_detail
        media_id = (
            self._library_media_reader_session.loaded_id
            if external_detail
            else viewer.media_id or self._safe_text(self._selected_media_id)
        )
        if not media_id:
            return None
        title = viewer.title or "Untitled source"
        media_type = (
            self._safe_text(detail.get("type"))
            or self._safe_text(detail.get("media_type"))
            or "unknown"
        )
        content = viewer.content
        excerpt = content[:LIBRARY_MEDIA_HANDOFF_EXCERPT_CHARS]
        body_truncated = len(content) > LIBRARY_MEDIA_HANDOFF_EXCERPT_CHARS
        body_lines = [f"Media: {title}", f"Media ID: {media_id}"]
        body_lines.extend(
            line
            for line in viewer.metadata_lines
            if line.startswith(("Type:", "Author:", "Keywords:"))
        )
        body_lines.append(
            f"Source authority: {'server' if external_detail else 'local'}"
        )
        body_lines.append("")
        body_lines.append("Content excerpt:")
        body_lines.append(excerpt if excerpt else "No stored content.")
        body = "\n".join(body_lines)
        return ChatHandoffPayload(
            source="library",
            item_type="media",
            title=title,
            body=body,
            body_truncated=body_truncated,
            source_id=media_id,
            display_summary=f"Media staged: {title}",
            suggested_prompt="Use this media as source context for my next question.",
            runtime_backend="server" if external_detail else "local",
            source_owner="server" if external_detail else "local",
            source_selector_state="server" if external_detail else "local",
            discovery_owner="media",
            discovery_entity_id=media_id,
            metadata={
                "media_id": media_id,
                "media_title": title,
                "media_type": media_type,
                "source_authority": "server" if external_detail else "local",
            },
        )

    def _library_media_console_representation(self) -> str:
        """Describe the exact media representation chosen by the handoff builder."""
        payload = self._selected_media_handoff_payload()
        if payload is None:
            return "Unavailable until a media item is loaded"
        if "No stored content." in payload.body:
            return "Metadata only (no stored text)"
        return (
            "Stored text excerpt (truncated)"
            if payload.body_truncated
            else "Complete stored text excerpt"
        )

    def _hub_table_cell(
        self, value: str, width: int = LIBRARY_HUB_RECENT_LABEL_WIDTH
    ) -> str:
        """Keep hub table cells readable in terminal-width layouts."""
        clean_value = " ".join(value.split())
        if len(clean_value) <= width:
            return clean_value
        suffix = "..."
        limit = max(1, width - len(suffix))
        shortened = clean_value[:limit].rsplit(" ", 1)[0].strip()
        if not shortened:
            shortened = clean_value[:limit].strip()
        return f"{shortened}{suffix}"

    def _hub_source_count_value(self, source_type: str) -> str:
        count = self._local_source_counts.get(source_type, 0)
        suffix = "" if self._local_source_total_known.get(source_type, True) else "+"
        return f"{count}{suffix}"

    def _hub_recent_items(self) -> list[tuple[str, str, str, str]]:
        """One recent item per source for the landing hub (task-2238).

        Returns:
            ``(source_type, record_id, title, label)`` tuples in the hub's
            source order, for sources whose most recent record resolves an
            id -- empty sources are skipped, so a fresh library yields an
            empty list (the old line's None-when-empty contract).
        """
        if self._library_lookup_error is not None:
            return []
        items: list[tuple[str, str, str, str]] = []
        for source_type, label in (
            ("notes", "Notes"),
            ("media", "Media"),
            ("conversations", "Conversations"),
        ):
            records = self._local_source_records.get(source_type) or ()
            for record in records:
                record_id = self._source_record_id(record)
                title = self._source_optional_title(source_type, record)
                if not record_id or title is None:
                    continue
                items.append(
                    (source_type, record_id, self._hub_table_cell(title), label)
                )
                break
        return items

    def _hub_counts_line(self) -> str:
        """Per-source counts for the F-010 landing hub.

        While the local source snapshot is still loading (and no lookup
        error has been recorded), the counts read "…" rather than the
        placeholder zeros seeded at construction time -- same honest-
        loading policy `_build_library_shell_input()` applies to the rail's
        own count suffixes. `_hub_source_count_value()` appends "+" when
        the source's total is an estimate, mirroring the rail. On a lookup
        ERROR the line carries the error itself rather than misleading
        zeros (PR #1318 review; the F-014 count policy: a failed fetch
        must not dress up as an empty Library).
        """
        if self._library_lookup_error is not None:
            return self._library_lookup_error

        def value(source_type: str) -> str:
            if not self._library_loaded:
                return "…"
            return self._hub_source_count_value(source_type)

        return (
            f"Notes ({value('notes')}) · Media ({value('media')}) · "
            f"Conversations ({value('conversations')})"
        )

    def _library_landing_canvas_state(self) -> LibraryLandingCanvasState:
        """Build the landing owner's display-only snapshot."""
        get_started = self._library_lifecycle in (
            LibraryLifecycle.UNKNOWN,
            LibraryLifecycle.STARTER,
        )
        lifecycle_status = self._library_onboarding_status_copy if get_started else ""
        attention_action = (
            self._library_landing_attention_action()
            if not get_started and not self._library_notes_compact
            else None
        )
        self._library_landing_attention_signature = attention_action
        return LibraryLandingCanvasState(
            purpose=(
                "Add something useful, then use it in Console or Study."
                if get_started
                else LIBRARY_CANVAS_LANDING_COPY
            ),
            counts_line="" if get_started else self._hub_counts_line(),
            recent_items=tuple(
                LibraryLandingRecentItem(
                    source_type=source_type,
                    record_id=record_id,
                    title=title,
                    source_label=source_label,
                )
                for source_type, record_id, title, source_label in self._hub_recent_items()
            )
            if not get_started
            else (),
            lifecycle=self._library_lifecycle,
            lifecycle_status=lifecycle_status,
            show_retry=(
                get_started
                and self._library_onboarding_status
                is LibraryEvidenceStatus.PARTIAL_FAILURE
            ),
            show_explore=get_started and self._library_rail_collapsed,
            continue_action=(
                self._library_landing_continue_action() if not get_started else None
            ),
            attention_action=attention_action,
        )

    def _library_landing_attention_action(
        self,
    ) -> LibraryLandingAttentionAction | None:
        """Return one bounded recovery derived only from current live state."""

        registry = self._library_ingest_registry()
        jobs_fn = getattr(registry, "jobs", None)
        if callable(jobs_fn):
            for job in jobs_fn():
                if (
                    job.state is IngestJobState.FAILED
                    and not job.permanent
                    and not job.dismissed
                    and not job.superseded
                ):
                    return LibraryLandingAttentionAction(
                        message="An import needs review.",
                        action_label="Review",
                        action_kind="ingest-review",
                    )

        if (
            self._library_media_browse_controller.freshness == "stale"
            and self._library_media_browse_controller.stale_copy
        ):
            return LibraryLandingAttentionAction(
                message="Media may be out of date.",
                action_label="Retry",
                action_kind="media-retry",
            )
        if (
            self._library_prompt_browse_controller.freshness == "stale"
            and self._library_prompt_browse_controller.stale_copy
        ):
            return LibraryLandingAttentionAction(
                message="Prompts may be out of date.",
                action_label="Retry",
                action_kind="prompts-retry",
            )
        if (
            self._library_conversation_freshness == "stale"
            and self._library_conversation_stale_copy
        ):
            return LibraryLandingAttentionAction(
                message="Conversations may be out of date.",
                action_label="Retry",
                action_kind="conversations-retry",
            )
        return None

    def _library_landing_continue_action(
        self,
    ) -> LibraryLandingContinueAction | None:
        """Describe the validated receipt without exposing record or query text."""

        receipt = self._library_continue_receipt
        if receipt is None:
            return None
        row_id = receipt["row_id"]
        scope = receipt["scope"]
        parts = [_LIBRARY_HELP_SURFACE_LABELS[row_id]]

        if scope.get("query"):
            parts.append("search applied")
        if row_id == LIBRARY_ROW_BROWSE_MEDIA:
            if scope["media_type"] is not None:
                parts.append(f"type: {scope['media_type']}")
            sort_labels = {
                "last_modified_desc": "recent first",
                "last_modified_asc": "oldest first",
                "date_desc": "newest date",
                "date_asc": "oldest date",
                "title_asc": "title A–Z",
                "title_desc": "title Z–A",
                "relevance": "relevance",
            }
            parts.append(sort_labels[scope["sort_by"]])
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            if scope["collection_id"] is not None:
                parts.append("collection applied")
            parts.append(
                "name A–Z"
                if scope["sort_by"] == "name" and scope["sort_order"] == "asc"
                else "name Z–A"
                if scope["sort_by"] == "name"
                else "recent first"
                if scope["sort_order"] == "desc"
                else "oldest first"
            )
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_NOTES:
            if scope["filter"]:
                parts.append("filter applied")
            parts.append(
                {
                    "newest": "recent first",
                    "oldest": "oldest first",
                    "title": "title A–Z",
                }[scope["sort"]]
            )
        elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
            if scope["filter"]:
                parts.append("filter applied")
            parts.append("status order" if scope["sort"] == "status" else "name A–Z")
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
            parts.append("RAG" if scope["mode"] == "rag" else "search")
            if scope["scope_deselected"]:
                parts.append("sources adjusted")

        return LibraryLandingContinueAction(
            label=" · ".join(parts),
            row_id=row_id,
            adjustment=(
                "Item views resume at the source list."
                if receipt["source_list_adjusted"]
                else ""
            ),
        )

    def _library_study_handoff_canvas_state(
        self, kind: str
    ) -> LibraryStudyHandoffCanvasState:
        """Build one handoff owner's display-only snapshot."""
        copy = self._study_handoff_copy(kind)
        return LibraryStudyHandoffCanvasState(
            header=copy["header"],
            purpose=copy["purpose"],
            context=copy["context"],
            owner=copy["owner"],
            recovery=copy["recovery"],
            blocked=not self._has_local_sources(),
            button_label=copy["button_label"],
            button_id={
                "study": "library-open-study",
                "flashcards": "library-open-flashcards",
                "quizzes": "library-open-quizzes",
            }.get(kind, "library-open-study"),
            action_label=copy["action_label"],
        )

    def _library_header_line(self, header_line: str) -> str:
        """Return route-owned header copy without lifecycle feedback."""
        return header_line

    def _library_lifecycle_status_copy(self) -> str:
        """Combine session feedback in the screen-owned visible carrier."""
        return "\n".join(
            copy
            for copy in (
                (
                    "Library tools are now available."
                    if self._library_graduation_announcement_visible
                    else ""
                ),
                self._library_onboarding_persistence_warning,
            )
            if copy
        )

    @classmethod
    def _source_record_id(cls, record: Mapping[str, Any]) -> str | None:
        for key in (
            "id",
            "uuid",
            "record_id",
            "backing_id",
            "source_id",
            "item_id",
            "media_id",
            "note_id",
            "conversation_id",
            "backing_media_id",
        ):
            value = cls._safe_text(record.get(key), max_length=128)
            if value:
                return value
        return None

    def _study_source_items(self) -> tuple[StudySourceItem, ...]:
        source_items: list[StudySourceItem] = []
        source_type_map = {
            "notes": "note",
            "media": "media",
        }
        for source_type, study_source_type in source_type_map.items():
            for record in self._local_source_records[source_type]:
                source_id = self._source_record_id(record)
                if not source_id:
                    continue
                source_items.append(
                    StudySourceItem(
                        source_type=study_source_type,
                        source_id=source_id,
                        label=self._source_title(source_type, record),
                    )
                )
        return tuple(source_items)

    def _source_count_metadata(self) -> dict[str, int | None]:
        metadata: dict[str, int | None] = {}
        for source_type in ("notes", "media", "conversations"):
            count = self._local_source_counts[source_type]
            metadata[f"{source_type}_sample_count"] = len(
                self._local_source_records[source_type]
            )
            metadata[f"{source_type}_total_count"] = (
                count if self._local_source_total_known[source_type] else None
            )
            if self._local_source_total_known[source_type]:
                metadata[f"{source_type}_count"] = count
        return metadata

    def _source_snapshot_metadata(self) -> dict[str, Any]:
        return {
            **self._source_count_metadata(),
            "note_titles": self._source_sample_titles("notes"),
            "media_titles": self._source_sample_titles("media"),
            "conversation_titles": self._source_sample_titles("conversations"),
        }

    def _workspace_source_records(self) -> Mapping[str, tuple[Mapping[str, Any], ...]]:
        return {
            source_type: tuple(self._local_source_records[source_type])
            for source_type in ("notes", "media", "conversations")
        }

    def _invalidate_library_workspace_depth_state(self) -> None:
        self._library_workspace_depth_state_cache = None

    def _library_workspace_depth_state(
        self,
        *,
        refresh: bool = False,
    ) -> LibraryWorkspaceDepthState:
        if refresh or self._library_workspace_depth_state_cache is None:
            self._library_workspace_depth_state_cache = (
                build_library_workspace_depth_state(
                    registry_service=getattr(
                        self.app_instance, "workspace_registry_service", None
                    ),
                    source_records=self._workspace_source_records(),
                )
            )
        return self._library_workspace_depth_state_cache

    def _library_workspace_scope_label(
        self,
        workspace_depth_state: LibraryWorkspaceDepthState,
    ) -> Text:
        """Return the left-rail workspace scope copy for the active Library mode."""
        return Text.from_markup(
            f"Active workspace: {escape_markup(workspace_depth_state.workspace_name)}"
        )

    def _source_study_context(self) -> StudyScopeContext | None:
        if not self._has_source_study_context():
            return None
        material_titles: list[str] = []
        for source_type in ("notes", "media", "conversations"):
            material_titles.extend(self._source_sample_titles(source_type))
        return StudyScopeContext(
            material_source=MATERIAL_SOURCE_LIBRARY,
            material_title=MATERIAL_TITLE_LIBRARY_SOURCES,
            material_summary=self._source_snapshot_body(),
            material_titles=tuple(material_titles),
            source_items=self._study_source_items(),
            return_hint=MATERIAL_SOURCE_LIBRARY,
        )

    def _source_study_handoff_titles(self) -> tuple[str, ...]:
        material_titles: list[str] = []
        for source_type in ("notes", "media", "conversations"):
            material_titles.extend(self._source_sample_titles(source_type))
        return tuple(material_titles)

    def _has_source_study_context(self) -> bool:
        return self._has_local_sources()

    def _study_handoff_copy(self, kind: str) -> dict[str, str]:
        mode = LIBRARY_STUDY_HANDOFF_MODES.get(
            kind,
            LIBRARY_STUDY_HANDOFF_MODES["study"],
        )
        titles = self._source_study_handoff_titles()
        has_context = self._has_source_study_context()
        action_label = mode["action_label"]
        if has_context and titles:
            context_copy = _library_carries_forward_line(titles)
        elif has_context:
            context_copy = (
                "Carries forward: Library source snapshot (titles unavailable)"
            )
        else:
            # No Library sources at all: the carries-forward line is omitted
            # entirely rather than stating the negative (the blocked
            # "recovery" line below already carries that signal).
            context_copy = ""
        return {
            "header": mode["header"],
            "action_label": action_label,
            "button_label": mode["button_label"],
            "purpose": mode["purpose"],
            "context": context_copy,
            "owner": LIBRARY_STUDY_HANDOFF_OWNERSHIP_COPY,
            "recovery": (
                "Source snapshot is ready."
                if has_context
                else (
                    "Import sources or create notes first, or open "
                    f"{action_label} globally without Library context."
                )
            ),
        }

    def _library_rag_panel_state(self) -> LibraryRagPanelState:
        # B2: explicit selection is every real source type NOT toggled off;
        # `LibraryRagScopeState.from_source_counts` intersects this with
        # actual availability, so a deselected-but-empty source can't
        # falsely count as "selected".
        #
        # PR-T1 final review (C2): that count intersection is only honest
        # once counts EXIST. `restore_state` carries `_library_rag_results`
        # across navigation but NOT `_local_source_counts` (bulk snapshots
        # are deliberately re-fetched -- see `save_state`), so a fresh
        # `LibraryScreen` composes with all-zero counts while
        # `_refresh_local_source_snapshot` is still in flight. Feeding an
        # explicit selection into that window intersects every source down
        # to nothing, and D4/task-5's scope filter then hid EVERY restored
        # evidence row, flipping the panel to "No evidence matched the
        # current query" -- naming the restored query, about rows that were
        # right there. Nothing recovered it either: the snapshot lands via
        # the BROWSE_SEARCH branch of `_apply_local_source_snapshot`, which
        # deliberately syncs only the rail + scope toggles and never the
        # results region (RAG-27, so a background ingest can't eject a user
        # mid-search). Only a revisit INSIDE `LIBRARY_SNAPSHOT_CACHE_TTL_
        # SECONDS` escaped, because the cached-snapshot path recomposes.
        #
        # So while counts are unloaded, pass the documented "no explicit
        # scope was supplied" sentinel (`None`) instead: the hybrid basis
        # in `LibraryRagPanelState.from_values` skips the filter entirely
        # for it, and `from_source_counts` derives selection from
        # availability -- which, at all-zero counts, marks exactly the same
        # options unselected as the explicit tuple would. The only
        # difference is that restored rows stay visible until the real
        # counts arrive and the honest intersection can run.
        #
        # PR-T1 fix-wave re-review: `_library_loaded` alone re-opens this
        # same hole through `_apply_source_snapshot_timeout`, which sets
        # `_library_loaded = True` together with placeholder all-zero
        # counts AND `_library_lookup_error`. Gate on the same two-conjunct
        # "counts are real" predicate `_build_library_shell_input` already
        # uses as `counts_available` (~line 4530), so a snapshot timeout's
        # fake zeros can't enable the filter either.
        selected_source_types: tuple[str, ...] | None = tuple(
            source_type
            for source_type in LIBRARY_RAG_SCOPE_TOGGLE_SOURCE_TYPES
            if source_type not in self._library_rag_scope_deselected
        )
        if not (self._library_loaded and not self._library_lookup_error):
            selected_source_types = None
        # ONE `resolve -> readiness -> name` pass per render (finding I1):
        # the same call used to be made twice inline below, and the second
        # of them threw away the `ProviderReadiness` object carrying the
        # only text that can tell a user with a selected-but-uncredentialed
        # provider what to actually do.
        provider_gate = library_rag_answer_provider_gate()
        return LibraryRagPanelState.from_values(
            source_counts={
                "notes": self._local_source_counts.get("notes", 0),
                "media": self._local_source_counts.get("media", 0),
                "conversations": self._local_source_counts.get("conversations", 0),
                # "prompts" carries (count, page_records) in
                # `_local_source_records` (see its `__init__` comment), not
                # a bare count in `_local_source_counts` -- reuse the
                # already-fetched count-seam value rather than fetching
                # again.
                "prompts": self._local_source_records.get("prompts", (None, ()))[0]
                or 0,
                "workspaces": 0,
            },
            query=self._library_rag_query,
            searched_query=self._library_rag_searched_query,
            mode=self._library_rag_mode,
            results=self._library_rag_results,
            selected_result_id=self._library_rag_selected_result_id,
            # PR-3 Task 4: the in-flight answer OVERLAYS the settled
            # retrieval status for display only ("answering" is what Task 3's
            # normalizer and run-gate override key off) -- the retrieval's
            # own status stays intact underneath, so clearing the flag
            # restores it exactly.
            retrieval_status=(
                "answering"
                if self._library_rag_answer_in_flight
                else self._library_rag_retrieval_status
            ),
            # PR-3 Task 3: named for the in-flight "Asking <provider>..."
            # line -- gated on the same flag as `retrieval_status` above,
            # belt-and-suspenders against a reset gap ever leaving a stale
            # provider name forwarded once the flag itself reads False.
            in_flight_answer_provider=(
                self._library_rag_answer_in_flight_provider
                if self._library_rag_answer_in_flight
                else ""
            ),
            recovery_copy=(
                self._library_rag_recovery_state.visible_copy
                if self._library_rag_recovery_state is not None
                else ""
            ),
            recovery_selector=(
                self._library_rag_recovery_state.stable_selector
                if self._library_rag_recovery_state is not None
                else ""
            ),
            # Deliberately always ready: the UI path never imports torch (or
            # any other optional Search/RAG dependency), and the retrieval
            # service double-guards missing runtimes/indexes at call time.
            # rag mode lazily initializes the shared RAG runtime at query
            # time, and when embeddings support is missing the retrieval
            # service itself returns the "RAG unavailable" recovery state
            # routing to setup -- honest copy a disabled Run button could not
            # carry.
            dependencies_ready=True,
            index_ready=True,
            # `provider_ready` joined this contract in task-249 as a
            # hardcoded `True` -- PR-3 task 2 activated the gate for real,
            # and PR-T2 Task 4 review collapsed it into this single
            # `provider_name` argument, derived inside `LibraryRagQueryState.
            # from_values` as `bool((provider_name or "").strip())` -- see
            # its docstring. A Library with no default LLM endpoint
            # configured (`resolve_library_rag_answer_provider()` returns
            # `(None, None)`) sees the pre-existing "Select a provider/model
            # before asking for a RAG answer." copy -- while a provider that
            # IS configured but cannot authenticate gets the credential
            # remedy instead, carried by `provider_credential_recovery`
            # below (finding I1). Once one is configured AND the gate
            # confirms its credentials actually resolve (PR-T2 Task 7 -- an endpoint
            # NAME alone used to be treated as ready, which is how the
            # Library path spent money while Console's own readiness check
            # showed a blocking wall for the same config), this same value
            # also names the provider in the ready-state quiet line's
            # paid-mode notice (`library_rag_paid_mode_notice`) -- the ONLY
            # provider-adjacent copy on this panel used to be that
            # blocked-branch text, which disappeared the instant a provider
            # was configured, the exact inversion of what a keyboard-fast
            # user needs before pressing a button that spends real money.
            # rag-mode-only by construction (`LibraryRagQueryState.
            # from_values`'s `normalized_mode == "rag"` check) -- keyword
            # Search mode never calls a provider and stays unaffected
            # regardless of this value.
            provider_name=provider_gate.provider,
            provider_credential_recovery=provider_gate.credential_recovery,
            selected_source_types=selected_source_types,
            history=self._library_search_history,
            history_collapsed=self._library_rag_history_collapsed,
            diagnostics=self._library_rag_diagnostics,
            answer=self._library_rag_answer,
        )

    def _library_collections_capture_presentation(
        self,
    ) -> CollectionsCaptureReaderPresentation:
        """Project source-neutral capture state into the render-only panes."""
        runtime_policy = getattr(self.app_instance, "runtime_policy", None)
        runtime_state = runtime_policy.state if runtime_policy is not None else None
        active_source = str(
            getattr(runtime_state, "active_source", "local") or "local"
        ).lower()
        controller = self._library_collections_capture_controller
        state = (
            controller.state
            if controller is not None
            else CollectionsCaptureControllerState(
                page_error="capture_authority_unavailable"
            )
        )
        return CollectionsCaptureReaderPresentation(
            state=state,
            capabilities=self._library_collections_capture_capabilities,
            saved_searches=self._library_collections_saved_searches,
            saved_searches_total=self._library_collections_saved_searches_total,
            active_scope=self._library_collections_active_scope,
            authority_label="Server" if active_source == "server" else "Local",
            mode=self._library_collections_reader_mode,
            highlights=self._library_collections_highlights,
            quick_capture_open=self._library_collections_quick_capture_open,
            quick_capture_url=self._library_collections_quick_capture_url,
            quick_capture_title=self._library_collections_quick_capture_title,
            quick_capture_tags=self._library_collections_quick_capture_tags,
            quick_capture_note=self._library_collections_quick_capture_note,
            save_outcome_unknown=self._library_collections_save_outcome_unknown,
            confirming_save_retry=(
                self._library_collections_confirming_save_retry
            ),
            quick_capture_saving=self._library_collections_quick_capture_saving,
            filters_open=self._library_collections_filters_open,
            more_open=self._library_collections_more_open,
            confirming_hard_delete=(
                self._library_collections_confirming_hard_delete
            ),
            legacy_recovery_rows=self._library_collections_legacy_recovery_rows,
            legacy_recovery_open=self._library_collections_legacy_recovery_open,
            legacy_recovery_lines=self._library_collections_legacy_recovery_lines,
            action_status=self._library_collections_action_status,
            action_content=self._library_collections_action_content,
        )

    def _workspace_handoff_summary_label(
        self, state: LibraryWorkspaceDepthState
    ) -> str:
        """Shorten ``state.handoff_label`` for the Workspace group's Handoff row.

        Drops the redundant "Console/RAG handoff: " prefix (the "Handoff"
        row label already says as much) and prefixes a "●" glyph directly
        before a nonzero blocked count, so this single line carries the
        signal the retired blocked-state callouts used to repeat three
        times.
        """
        label = state.handoff_label
        if label.startswith(LIBRARY_HANDOFF_LABEL_PREFIX):
            label = label[len(LIBRARY_HANDOFF_LABEL_PREFIX) :]
        match = re.search(r"(\d+) blocked", label)
        if match and int(match.group(1)) > 0:
            label = f"{label[: match.start()]}● {match.group(0)}{label[match.end() :]}"
        return label

    def _workspaces_detail_rows(
        self,
        state: LibraryWorkspaceDepthState,
    ) -> tuple[Static, ...]:
        """Build the Workspace group's Details rail rows.

        Only the two facts that change staging eligibility survive here: the
        active workspace and the Console/RAG handoff eligible/blocked
        counts. The former policy-prose lines (global browse/search rule,
        staging-scope rule, per-source visibility label, collections and
        import/export capability notes) restated the same "browse stays
        global, staging is workspace-scoped" rule several different ways;
        the Handoff row below now carries that state on its own.
        """
        return (
            Static(
                "Workspace",
                id="library-details-group-workspace",
                classes="library-details-group",
            ),
            Static(
                library_dim_label_text("Active", state.workspace_name),
                id="library-workspaces-active-workspace",
                classes="library-details-row",
            ),
            Static(
                library_dim_label_text(
                    "Handoff", self._workspace_handoff_summary_label(state)
                ),
                id="library-workspaces-handoff",
                classes="library-details-row",
            ),
        )

    def _workspace_handoff_action_state(
        self,
        workspace_depth_state: LibraryWorkspaceDepthState,
    ) -> tuple[bool, str]:
        """Return the Workspaces handoff button disabled flag and tooltip."""
        handoff_disabled = True
        handoff_tooltip = "Stage Library source context after Library finishes loading."
        if self._library_lookup_error:
            recovery_state = self._library_lookup_recovery_state
            handoff_tooltip = (
                recovery_state.disabled_tooltip
                if recovery_state is not None
                else "Library source services are unavailable; retry Library later."
            )
        elif not self._has_local_sources():
            handoff_tooltip = "Stage Library source context after adding notes, media, or conversations."
        else:
            handoff_disabled = not workspace_depth_state.context_handoff_enabled
            handoff_tooltip = (
                workspace_depth_state.context_handoff_tooltip
                if handoff_disabled
                else "Stage Library source context in Console."
            )
        return handoff_disabled, handoff_tooltip

    def _workspace_action_widgets(
        self,
        workspace_depth_state: LibraryWorkspaceDepthState,
        *,
        handoff_disabled: bool,
        handoff_tooltip: str,
    ) -> tuple[Any, ...]:
        """Build the Actions group's Details rail rows.

        Only the two action buttons plus one dim WIP note survive here; the
        Workspace group's Handoff row now carries the eligible/blocked
        status, so the retired ready/blocked/next-step callouts that used to
        repeat it are gone.
        """
        widgets: list[Any] = [
            Static(
                "Actions",
                id="library-details-group-actions",
                classes="library-details-group",
            ),
            Button(
                "Create local workspace",
                id="library-create-local-workspace",
                classes="library-source-action",
                tooltip=(
                    "Create a local-only workspace and make it active. "
                    "Server sync and ACP handoff remain WIP."
                ),
            ),
        ]
        if not workspace_depth_state.source_rows:
            widgets.append(
                Button(
                    "Import sources",
                    id="library-workspace-import-sources",
                    classes="library-source-action",
                    tooltip="Open Library Import/Export to add workspace-eligible sources.",
                )
            )
        # TASK-716: a disabled Button never emits Pressed, which made the
        # press handler's explanatory warning (the whole reason the action
        # is blocked) unreachable - the control read as dead. Keep the
        # button pressable and let the handler explain the block inline;
        # the blocked class carries the dimmed styling.
        use_in_console = Button(
            "Use in Console",
            id="library-use-in-console",
            classes="library-source-action",
            tooltip=handoff_tooltip,
        )
        if handoff_disabled:
            use_in_console.add_class("library-source-action-blocked")
        widgets.append(use_in_console)
        widgets.append(
            Static(
                "Server sync WIP · local only",
                id="library-workspace-create-local-copy",
                classes="library-rail-empty-copy",
            )
        )
        return tuple(widgets)

    def _compose_library_rail_top_action(self) -> list[Widget]:
        """Build the top-of-rail action widget(s) for the Library shell.

        Returns the rail's primary button, which jumps directly to the
        ingest media canvas, surfaced above the rail search box for
        discoverability. F-013: the label names the action in plain
        language ("ingest" stays inside the ingest canvas itself);
        task-2857: that plain language is "Import…", matching the canvas
        header, the Start button, and the completion toast.
        """
        return [
            Button(
                "Import…",
                variant="primary",
                id="library-ingest-top-button",
                tooltip="Add files, links, and transcripts to your Library.",
            )
        ]

    def _compose_workspaces_rail_body(self) -> list[Any]:
        """Build the Workspaces body for the rail Details section.

        Returns the workspace-context depth panel followed by the workspace
        action controls, mirroring the retired Workspaces mode body. Preserves
        every legacy widget id so the flows remain reachable from the rail.

        Returns:
            Freshly constructed widgets for the Details disclosure.
        """
        state = self._library_workspace_depth_state()
        handoff_disabled, handoff_tooltip = self._workspace_handoff_action_state(state)
        depth_panel = Vertical(
            *self._workspaces_detail_rows(state),
            id="library-workspaces-depth-panel",
        )
        # Vertical defaults to `height: 1fr`, which inside the Details body's
        # auto-height flow starves this panel of space for its own rows. The
        # panel then clips mid-row and the next widget (the "Actions" group
        # header) renders immediately after the truncated content, reading
        # as a visual collision. Hug the panel's real content height instead
        # so nothing below it is squeezed or overlapped.
        depth_panel.styles.height = "auto"
        widgets: list[Any] = [depth_panel]
        widgets.extend(
            self._workspace_action_widgets(
                state,
                handoff_disabled=handoff_disabled,
                handoff_tooltip=handoff_tooltip,
            )
        )
        return widgets

    def compose_content(self) -> ComposeResult:
        # TASK-23025: every whole-screen recompose passes through here (the
        # task-2856 choke-point guarantee below), so this is the one place
        # the layout ref cache and the resize gate's applied signature must
        # be invalidated -- the widgets they point at are about to be
        # replaced.
        self._library_compose_generation += 1
        self._library_layout_ref_cache.clear()
        self._library_compose_ref_cache.clear()
        self._library_reader_shell_ref = None
        self._library_resize_applied_signature = None
        self._library_notes_stage_applied_signature = None
        shell_input = self._build_library_shell_input()
        shell = build_library_shell_state(
            shell_input, selected_row_id=self._library_selected_row_id
        )
        self._library_selected_row_id = shell.selected_row_id
        # task-2856: re-derive the footer's advertised keys on EVERY
        # recompose (not only at the transition call sites that also call
        # this), so entering/leaving a detail surface (media viewer, note/
        # prompt editor) from any of their several call sites can never
        # leave the footer advertising a stale key -- the exact failure
        # mode task-2850's own review caught for a single call site.
        self._register_footer_shortcuts()
        # task-2856: re-request a pending entry-focus on EVERY recompose
        # while it's armed -- the ONE guaranteed choke point every
        # recompose passes through, no matter which of the screen's
        # several INDEPENDENT background workers triggered it (the
        # snapshot refresh several "back to list" exits kick off, but ALSO
        # the skills trust-posture load IT chains into, media/note/prompt
        # detail fetches, etc. -- each ends in its own
        # `self.refresh(recompose=True)`). Reproduced live: the skill
        # editor's Escape correctly returned to the list and briefly
        # focused its first row, but the trust-posture worker's LATER
        # recompose (rebuilding the row Buttons as fresh instances) still
        # silently dropped it -- consuming (clearing) the flag on the
        # FIRST such recompose lost that same race one level up, since it
        # left nothing armed for the trust-posture worker's later one to
        # re-request from. Re-firing without clearing, bounded by the
        # flag's own settle-window timer (``_arm_library_list_entry_focus``)
        # and disarmed immediately by user interaction (``on_key`` /
        # ``on_descendant_focus`` -- review round 2: the timer used to be
        # the ONLY disarm path, so a background recompose landing after a
        # user had already Tabbed/clicked away could yank focus back),
        # covers an arbitrary-length chain of these workers instead of
        # exactly one.
        if self._library_pending_list_entry_focus:
            pending_media_return = self._library_pending_list_entry_media_return
            if self._library_media_return_candidate(pending_media_return):
                focused = self.focused
                if focused is not None and focused.has_class("library-media-row"):
                    # The focused row is about to be replaced. Prevent Textual
                    # from implicitly selecting its semantic successor before
                    # replacement-owner geometry can settle exact scroll.
                    self.set_focus(None)
                self._library_media_return_settlement = None
            elif pending_media_return is None:
                self.call_after_refresh(self._focus_library_list_entry)
            else:
                self.call_after_refresh(
                    self._focus_library_list_entry_if_current,
                    self._library_list_entry_focus_generation,
                )
        if (
            self._library_emergency_stage == "canvas-only"
            and self._library_ordinary_route_active()
        ):
            self.call_after_refresh(self._focus_library_ordinary_canvas_entry)
        preferences = self._library_rail_preferences()

        yield Static(
            self._library_header_line(shell.header_line),
            id="library-header-line",
            classes="destination-status-row",
        )
        lifecycle_status_copy = self._library_lifecycle_status_copy()
        lifecycle_status = Static(
            lifecycle_status_copy,
            id="library-lifecycle-status",
            classes="library-hub-meta",
            markup=False,
        )
        lifecycle_status.display = bool(lifecycle_status_copy)
        yield lifecycle_status
        # TASK-23025: the install label+bar pair (a ModelInstallProgress with
        # its PausableProgressBar machinery) was mounted display=False on
        # every visit for a state most users never enter. Grow on demand
        # instead (the TASK-23024 slot-pool pattern): compose it only while
        # an install is retained; the InstallProgressed handlers mount it on
        # first use via ``_mount_library_model_install_progress``.
        if (
            self._parakeet_v2_install_progress is not None
            or self._library_model_install_progress_label
        ):
            install_label, install_progress = (
                self._build_library_model_install_progress_widgets()
            )
            yield install_label
            yield install_progress
        if shell.canvas_kind in LIBRARY_NOTES_SOURCE_STRIP_CANVAS_KINDS:
            adaptive_database_notes = (
                shell.canvas_kind
                in (LIBRARY_CANVAS_KIND_NOTES, LIBRARY_CANVAS_KIND_NOTES_CREATE)
                and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
            )
            wide_focused_task = (
                not adaptive_database_notes
                and not self._library_notes_compact
                and self._library_notes_focused_task_active()
            )
            with Horizontal(id="library-notes-source-strip"):
                task_return = Button(
                    "‹ Library / Notes",
                    id="library-notes-task-return",
                    compact=True,
                )
                task_return.display = wide_focused_task
                yield task_return
                database_selected = (
                    self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
                )
                database_source = Button(
                    "Library notes",
                    id="library-notes-source-database",
                    compact=True,
                )
                database_source.set_class(database_selected, "-selected")
                database_source.display = not wide_focused_task
                yield database_source
                source_separator = Static(
                    "|",
                    id="library-notes-source-separator",
                    markup=False,
                )
                source_separator.display = not wide_focused_task
                yield source_separator
                files_selected = (
                    self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES
                )
                files_source = Button(
                    "Folder files",
                    id="library-notes-source-files",
                    compact=True,
                )
                files_source.set_class(files_selected, "-selected")
                files_source.display = not wide_focused_task
                yield files_source
        shell_grid = Horizontal(
            id="library-shell-grid", classes="ds-panel destination-workbench"
        )
        shell_grid.styles.height = "1fr"
        shell_grid.styles.min_height = 12
        shell_grid.set_class(self._library_notes_compact, "library-notes-compact")
        self.call_after_refresh(self._sync_library_ordinary_rail_width_contract)
        single_notes_stage = (
            self._library_notes_compact and self._library_notes_compact_stage_applies()
        ) or (
            not self._library_notes_compact
            and self._library_notes_focused_task_active()
        )
        if (
            shell.canvas_kind
            in (LIBRARY_CANVAS_KIND_NOTES, LIBRARY_CANVAS_KIND_NOTES_CREATE)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            if not self._library_loaded and not self._library_lookup_error:
                items_child: Widget = Static(
                    "Loading local Library sources…",
                    id="library-canvas-loading",
                    classes="destination-purpose",
                    markup=False,
                )
            elif self._library_lookup_error:
                items_child = Static(
                    self._library_lookup_error,
                    id="library-canvas-error",
                    classes="destination-purpose",
                    markup=False,
                )
            else:
                items_child = LibraryNotesCanvas(
                    **self._library_notes_list_canvas_kwargs(),
                    id="library-notes-canvas",
                )
            items_host = Vertical(
                items_child,
                id="library-canvas",
                classes="destination-workbench-pane",
            )
            work = LibraryNoteWorkPane(
                **self._library_note_work_pane_kwargs(),
                id="library-note-work-pane",
            )
            with shell_grid:
                yield LibraryAdaptiveReaderShell(
                    library=rail,
                    items=items_host,
                    work=work,
                    layout=self._library_notes_reader_layout,
                    id_prefix="library-notes",
                    library_label="Library",
                    items_label="Notes",
                    id="library-notes-reader-shell",
                )
            self.call_after_refresh(self._sync_library_notes_reader_layout_from_shell)
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            return
        if (
            shell.canvas_kind
            in (LIBRARY_CANVAS_KIND_NOTES, LIBRARY_CANVAS_KIND_NOTES_CREATE)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES
        ):
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-file-notes-rail",
                classes="destination-workbench-pane",
            )
            workspace = self._library_file_notes_workspace
            with shell_grid:
                if workspace is None:
                    yield Static(
                        "Opening File Notes…",
                        id="library-file-notes-loading",
                        classes="destination-purpose",
                        markup=False,
                    )
                else:
                    if workspace._reader_shell is None:
                        workspace.configure_reader_shell(
                            library_pane=rail,
                            layout=self._library_file_notes_reader_layout,
                        )
                    else:
                        workspace.sync_reader_layout(
                            self._library_file_notes_reader_layout
                        )
                    yield workspace
            self.call_after_refresh(
                self._sync_library_file_notes_reader_layout_from_shell
            )
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            self.call_after_refresh(
                self._restore_library_notes_authority_focus,
                "files",
            )
            return
        if shell.canvas_kind == "collections":
            presentation = self._library_collections_capture_presentation()
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                row_context_factory=lambda row: (
                    (
                        LibraryCollectionsScopeRows(
                            presentation,
                            id="library-collections-scopes",
                        ),
                    )
                    if row.row_id == LIBRARY_ROW_BROWSE_COLLECTIONS
                    else ()
                ),
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            items = LibraryCollectionsItemsPane(
                presentation,
                id="library-collections-items",
            )
            items_host = Vertical(
                items,
                id="library-canvas",
                classes="destination-workbench-pane",
            )
            work = LibraryCollectionsWorkPane(
                presentation,
                id="library-collections-work",
            )
            with shell_grid:
                yield LibraryAdaptiveReaderShell(
                    library=rail,
                    items=items_host,
                    work=work,
                    layout=self._library_collections_reader_layout,
                    id_prefix="library-collections",
                    library_label="Library",
                    items_label="Items",
                    id="library-collections-reader-shell",
                )
            self.call_after_refresh(
                self._sync_library_collections_reader_layout_from_shell
            )
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            return
        if shell.canvas_kind == "prompts":
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            # Prompt browsing owns its dedicated PromptScopeService and does
            # not depend on the broad conversations/notes snapshot. Gating
            # this retained Items pane on `_library_loaded` left it stuck on
            # the generic loading row when the prompt request won the startup
            # race: the controller had a ready result but no canvas to sync.
            items_child = LibraryPromptsListCanvas(
                **self._library_prompts_list_canvas_kwargs(),
                id="library-prompts-canvas",
            )
            items_child.styles.min_width = 0
            items_host = Vertical(
                items_child,
                id="library-canvas",
                classes="destination-workbench-pane",
            )
            work = LibraryPromptWorkPane(
                **self._library_prompt_work_pane_kwargs(),
                id="library-prompt-work-pane",
            )
            with shell_grid:
                yield LibraryAdaptiveReaderShell(
                    library=rail,
                    items=items_host,
                    work=work,
                    layout=self._library_prompts_reader_layout,
                    id_prefix="library-prompts",
                    library_label="Library",
                    items_label="Prompts",
                    id="library-prompts-reader-shell",
                )
            self.call_after_refresh(self._sync_library_prompts_reader_layout_from_shell)
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            return
        if shell.canvas_kind == "skills":
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            # Skills owns a retained Items pane and independent trust worker.
            # Gating it on the broad Library snapshot lets that worker settle
            # before a Skills canvas exists, leaving a restored Skills route
            # permanently on the generic loading row. Mount the owner from
            # current state immediately; the normal snapshot/trust syncs patch
            # it in place when their results arrive.
            items_child = LibrarySkillsListCanvas(
                **self._library_skills_list_canvas_kwargs(),
                id="library-skills-canvas",
            )
            items_child.styles.min_width = 0
            items_host = Vertical(
                items_child,
                id="library-canvas",
                classes="destination-workbench-pane",
            )
            work = LibrarySkillWorkPane(
                **self._library_skill_work_pane_kwargs(),
                id="library-skill-work-pane",
            )
            with shell_grid:
                yield LibraryAdaptiveReaderShell(
                    library=rail,
                    items=items_host,
                    work=work,
                    layout=self._library_skills_reader_layout,
                    id_prefix="library-skills",
                    library_label="Library",
                    items_label="Skills",
                    id="library-skills-reader-shell",
                )
            self.call_after_refresh(self._sync_library_skills_reader_layout_from_shell)
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            return
        if shell.canvas_kind == "conversations":
            conversations_state = self._build_library_conversations_state()
            self._adopt_library_conversation_state_selection(
                conversations_state.selected_id
            )
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            if not self._library_loaded and not self._library_lookup_error:
                items_child: Widget = Static(
                    "Loading local Library sources…",
                    id="library-canvas-loading",
                    classes="destination-purpose",
                    markup=False,
                )
            else:
                # Conversations own a dedicated recoverable request state.
                # Keep its filter, pager, status, and retry surface mounted
                # when the broad Library snapshot fails, matching the
                # non-retained compose path below. Only the true initial
                # loading state substitutes a placeholder.
                items_child = LibraryConversationsCanvas(
                    conversations_state,
                    id="library-conversations-canvas",
                )
            items_host = Vertical(
                items_child,
                id="library-canvas",
                classes="destination-workbench-pane",
            )
            reader_metadata = dict(self._library_conversation_reader_loaded_metadata)
            if not self._library_loaded and not self._library_lookup_error:
                reader_metadata["_list_status"] = "Loading local Library sources…"
            elif self._library_lookup_error:
                reader_metadata["_list_status"] = self._library_lookup_error
            if not self._library_conversation_reader_layout.items_open:
                reader_metadata["_list_summary"] = (
                    self._conversation_reader_list_summary()
                )
            reader = LibraryConversationReader(
                self._library_conversation_reader_state,
                loaded_metadata=reader_metadata,
                selected_metadata=self._library_conversation_reader_selected_metadata,
                id="library-conversation-reader",
            )
            with shell_grid:
                yield LibraryAdaptiveReaderShell(
                    library=rail,
                    items=items_host,
                    work=reader,
                    layout=self._library_conversation_reader_layout,
                    id_prefix="library-conversations",
                    library_label="Library",
                    items_label="Items",
                    id="library-conversations-reader-shell",
                )
            self.call_after_refresh(
                self._sync_library_conversation_reader_layout_from_shell
            )
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            self.call_after_refresh(self._ensure_library_conversation_reader_selection)
            return
        if shell.canvas_kind == "media":
            self._project_library_media_stage_classes(shell_grid)
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            items_host = Vertical(
                self._build_library_media_active_child(),
                id="library-canvas",
                classes="destination-workbench-pane",
            )
            reader = self._build_library_media_reader()
            with shell_grid:
                yield LibraryMediaReaderShell(
                    rail,
                    items_host,
                    reader,
                    self._library_media_reader_layout,
                    id="library-media-reader-shell",
                )
            self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
            return
        with shell_grid:
            rail_handle = LibraryNavigationRailHandle(id="library-rail-handle")
            rail_handle.styles.height = "100%"
            rail_handle.display = (
                self._library_rail_collapsed and not single_notes_stage
            )
            yield rail_handle
            rail = LibraryRail(
                shell,
                preferences,
                query=self._library_rag_query,
                search_placeholder=self._library_rail_search_placeholder(),
                workspaces_body_factory=self._compose_workspaces_rail_body,
                top_action_factory=self._compose_library_rail_top_action,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                id="library-rail",
                classes="destination-workbench-pane",
            )
            rail.styles.height = "100%"
            rail.display = (
                not single_notes_stage or self._library_notes_stage == "rail"
            ) and not (self._library_rail_collapsed and not single_notes_stage)
            yield rail
            canvas_host = Vertical(
                id="library-canvas", classes="destination-workbench-pane"
            )
            canvas_host.styles.width = "13fr"
            canvas_host.styles.min_width = 40
            canvas_host.styles.height = "100%"
            canvas_host.set_class(self._library_notes_compact, "library-notes-compact")
            canvas_host.display = (
                not single_notes_stage or self._library_notes_stage == "notes"
            )
            emergency_return = LibraryEmergencyReturn(id="library-emergency-return")
            emergency_return.display = False
            route_content = Vertical(id="library-canvas-route-content")
            route_content.styles.height = "1fr"
            route_content.styles.min_height = 0
            with canvas_host:
                yield emergency_return
                with route_content:
                    # Only the conversations and database-notes canvases read the
                    # local source snapshot directly, so only they can show a
                    # false "no conversations"/"no notes" empty state
                    # while that snapshot is still loading. "mode" canvases
                    # (Collections, Flashcards, Search/RAG, ...) and the
                    # landing/empty canvas are unaffected and must not be
                    # replaced by this loading/error copy. Files mode (task-2850)
                    # is disk-backed, not DB-backed -- it never depends on
                    # ``_library_loaded``/``_library_lookup_error``, so it is
                    # excluded here too, or a Files-mode entry made ahead of the
                    # DB snapshot would flash the DB "Loading…" copy over it.
                    is_local_snapshot_canvas = shell.canvas_kind == "conversations" or (
                        shell.canvas_kind == LIBRARY_CANVAS_KIND_NOTES
                        and self._library_notes_source != LIBRARY_NOTES_SOURCE_FILES
                    )
                    if (
                        is_local_snapshot_canvas
                        and not self._library_loaded
                        and not self._library_lookup_error
                    ):
                        yield Static(
                            "Loading local Library sources…",
                            id="library-canvas-loading",
                            classes="destination-purpose",
                            markup=False,
                        )
                    elif (
                        is_local_snapshot_canvas
                        and self._library_lookup_error
                        and shell.canvas_kind != "conversations"
                    ):
                        yield Static(
                            self._library_lookup_error,
                            id="library-canvas-error",
                            classes="destination-purpose",
                            markup=False,
                        )
                    elif shell.canvas_kind == "conversations":
                        conversations_state = self._build_library_conversations_state()
                        self._adopt_library_conversation_state_selection(
                            conversations_state.selected_id
                        )
                        yield LibraryConversationsCanvas(
                            conversations_state,
                            id="library-conversations-canvas",
                        )
                    elif (
                        shell.canvas_kind == "media"
                        and self._library_media_view == "viewer"
                    ):
                        yield self._build_library_media_active_child()
                    elif (
                        shell.canvas_kind == "media"
                        and self._library_media_view == "trash"
                    ):
                        # task-4025: the Trash view -- the media canvas's third
                        # in-canvas view. Its in-place updater is
                        # ``_sync_library_canvas(self, "media-trash")``, which
                        # rebuilds this same state and hands it to the mounted
                        # canvas's ``sync_state`` (recompose discipline: the
                        # compose branch and the updater own the same
                        # conditionals via the one shared state builder).
                        trash_state = self._build_library_media_trash_state()
                        yield LibraryMediaTrashCanvas(
                            trash_state,
                            **self._library_media_trash_canvas_presentation(),
                            id="library-media-trash-canvas",
                        )
                    elif shell.canvas_kind == "media":
                        media_state = self._build_library_media_state()
                        self._selected_media_id = media_state.selected_id
                        yield LibraryMediaCanvas(
                            media_state,
                            **self._library_media_canvas_presentation(),
                            id="library-media-canvas",
                        )
                    elif (
                        shell.canvas_kind == LIBRARY_CANVAS_KIND_NOTES
                        and self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES
                    ):
                        # task-2850: File Notes owns the canvas PANE now, not
                        # the whole screen -- the rail and shell_grid frame
                        # above/around this branch stay mounted exactly like
                        # every other notes view (list/editor/sync), so leaving
                        # Files mode never looks like the app broke.
                        workspace = self._library_file_notes_workspace
                        if workspace is not None:
                            yield workspace
                        else:
                            yield Static(
                                "Opening File Notes…",
                                id="library-file-notes-loading",
                                classes="destination-purpose",
                                markup=False,
                            )
                    elif shell.canvas_kind in (
                        LIBRARY_CANVAS_KIND_NOTES,
                        LIBRARY_CANVAS_KIND_NOTES_CREATE,
                    ):
                        yield LibraryNotesCanvas(
                            **self._library_notes_canvas_kwargs(),
                            id="library-notes-canvas",
                        )
                    elif (
                        shell.canvas_kind == "prompts"
                        and self._library_prompts_view == "editor"
                    ):
                        if self._library_prompt_conflict_snapshot is not None:
                            # A save just lost the app-level staleness check (see
                            # `_save_library_prompt`): recompose from the user's
                            # own kept text (never the stale `_library_prompt_detail`)
                            # with the Save-as-new/Reload actions surfaced.
                            yield LibraryPromptsListCanvas(
                                **self._library_prompts_canvas_kwargs(),
                                id="library-prompts-canvas",
                            )
                        elif self._library_prompt_detail is None:
                            yield Static(
                                "Loading prompt…",
                                id="library-prompt-loading",
                                classes="destination-purpose",
                                markup=False,
                            )
                        else:
                            yield LibraryPromptsListCanvas(
                                **self._library_prompts_canvas_kwargs(),
                                id="library-prompts-canvas",
                            )
                    elif shell.canvas_kind == "prompts":
                        prompt_controller = self._library_prompt_browse_controller
                        display_scope = prompt_controller.visible_result.scope
                        yield LibraryPromptsListCanvas(
                            self._build_library_prompts_state(),
                            browse_result=prompt_controller.visible_result,
                            pager=prompt_controller.pager,
                            sort_mode=(
                                "name" if display_scope.sort_by == "name" else "newest"
                            ),
                            filter_value=prompt_controller.scope.query,
                            import_open=self._library_prompts_import_open,
                            import_path=self._library_prompts_import_path,
                            import_status=self._library_prompts_import_status,
                            collection_label=self._library_prompt_collections_controller.collection_label(
                                display_scope.collection_id
                            ),
                            sort_choices_visible=(
                                self._library_prompts_sort_choices_visible
                            ),
                            delete_receipt=self._library_prompt_delete_receipt,
                            mutation_in_flight=self._library_prompts_mutation_in_flight,
                            page_actions_disabled=(
                                prompt_controller.freshness == "stale"
                            ),
                            mutation_status=self._library_prompt_mutation_status,
                            id="library-prompts-canvas",
                        )
                    elif (
                        shell.canvas_kind == "skills"
                        and self._library_skills_view == "editor"
                    ):
                        if self._library_skill_editor_state is None:
                            yield Static(
                                "Loading skill…",
                                id="library-skill-loading",
                                classes="destination-purpose",
                                markup=False,
                            )
                        else:
                            editor_state = self._library_skill_editor_state
                            yield LibrarySkillsListCanvas(
                                mode="editor",
                                editor_state=editor_state,
                                warnings="\n".join(
                                    skill_editor_warning_lines(
                                        live_name=editor_state.name,
                                        trust_status=editor_state.trust_status,
                                        trust_blocked=editor_state.trust_blocked,
                                    )
                                ),
                                status=self._library_skill_status,
                                conflict=self._library_skill_conflict,
                                active_review=self._library_skill_active_review,
                                # Same source of truth ``_save_library_skill`` uses
                                # for its own ``is_create`` -- an empty
                                # ``_selected_skill_name`` means there is no
                                # existing skill on disk to rename, so the Name
                                # Input stays editable. Reached both via a real
                                # skill row (existing skill, name set) and via
                                # the Create rail's "New skill" row
                                # (``_enter_library_skill_create_editor`` leaves
                                # ``_selected_skill_name`` empty).
                                is_create=not self._selected_skill_name,
                                dirty=self._library_skill_dirty,
                                confirming_delete=self._library_skill_confirming_delete,
                                scroll_to_actions=self._consume_library_skill_scroll_pending(),
                                skill_path=self._library_skill_on_disk_path(),
                                # Task 5: the editor's own trust panel renders a
                                # Reset button for ``quarantined_manifest_error``
                                # (no adaptive header in editor mode, so
                                # ``trust_posture`` itself is unused here) and
                                # needs the same confirm-gate the list header
                                # uses -- both share one screen-level flag/handler
                                # set since only one view is ever mounted.
                                confirming_reset=self._library_skill_trust_confirming_reset,
                                id="library-skills-canvas",
                            )
                    elif shell.canvas_kind == "skills":
                        yield LibrarySkillsListCanvas(
                            self._build_library_skills_state(),
                            sort_mode=self._library_skills_sort,
                            filter_value=self._library_skills_filter,
                            import_open=self._library_skills_import_open,
                            import_path=self._library_skills_import_path,
                            import_status=self._library_skills_import_status,
                            import_review_name=self._library_skills_import_review_name,
                            import_in_flight=self._library_skills_import_in_flight,
                            import_package_kind=(
                                self._library_skill_import_coordinator.snapshot.package_kind
                            ),
                            import_recovery_actions=(
                                self._library_skill_import_coordinator.snapshot.recovery_actions
                            ),
                            import_retryable=(
                                self._library_skill_import_coordinator.snapshot.retryable
                            ),
                            # Task 5: the adaptive trust header + its
                            # confirm-gated standalone Reset action, computed
                            # off-thread (see ``_refresh_library_skills_trust_posture``).
                            trust_posture=self._library_skills_trust_posture,
                            confirming_reset=self._library_skill_trust_confirming_reset,
                            sort_choices_visible=(
                                self._library_skills_sort_choices_visible
                            ),
                            id="library-skills-canvas",
                        )
                    elif shell.canvas_kind == "search":
                        # A fresh compose replaces the Answer region's widgets
                        # with new instances; drop the "what is currently
                        # rendered" key so the next incremental refresh rebuilds
                        # unconditionally instead of reasoning about whether
                        # compose happened to render the same thing.
                        self._library_rag_answer_render_key = None
                        yield LibrarySearchRagPanel(
                            self._library_rag_panel_state(),
                            id="library-search-rag-panel",
                        )
                    elif shell.canvas_kind == "ingest-media":
                        yield LibraryIngestCanvas(
                            self._build_library_ingest_state(),
                            external_busy=self._library_external_submit_busy,
                            external_status=self._library_external_submit_status,
                            id="library-ingest-canvas",
                        )
                    elif shell.canvas_kind == "export":
                        yield LibraryExportCanvas(
                            self._build_library_export_state(),
                            id="library-export-canvas",
                        )
                    elif shell.canvas_kind == "handoff":
                        # Study/Flashcards/Quizzes rows (L3b Task 8): a first-class
                        # canvas kind of their own, sourced entirely from
                        # LIBRARY_STUDY_HANDOFF_MODES. UX wave D1 collapsed this
                        # to a single header (the row's own title -- "Flashcards"
                        # / "Study decks" / "Quizzes") plus the consolidated
                        # handoff detail widget below; the header no longer
                        # restates the mode name a second, differently-worded way
                        # (formerly "Flashcards mode" + a duplicated description
                        # + next-action line).
                        yield LibraryStudyHandoffCanvas(
                            self._library_study_handoff_canvas_state(
                                shell.canvas_target
                            ),
                            id="library-study-handoff-canvas",
                        )
                    else:
                        yield LibraryLandingCanvas(
                            self._library_landing_canvas_state(),
                            id="library-landing-canvas",
                        )

    def _build_library_shell_input(self) -> LibraryShellInput:
        """Build the pure shell input from live counts and runtime state.

        F-014's one count policy drives the count fields: while the local
        source snapshot is still in flight (``_library_loaded`` is False
        and no lookup error has been recorded yet) the rows render the dim
        loading placeholder via ``counts_loading``; once the snapshot has
        landed, known counts render as ``(N)``/``(N+)`` and unavailable
        sources (missing prompts/skills services) render no suffix. On a
        lookup ERROR every count is ``None`` -- a failed fetch must not
        dress up as an empty Library with a wall of misleading ``(0)``s
        (the Details error line carries the explanation).

        Returns:
            Adapter-provided Library shell input reflecting live counts and
            runtime state.
        """
        runtime_policy = getattr(self.app_instance, "runtime_policy", None)
        runtime_state = runtime_policy.state if runtime_policy is not None else None
        active_source = str(
            getattr(runtime_state, "active_source", "local") or "local"
        ).lower()
        server_label = None
        if active_source == "server":
            server_label = getattr(
                runtime_state, "last_known_server_label", None
            ) or getattr(runtime_state, "active_server_id", None)
        collections_controller = self._library_collections_capture_controller
        collections_state = (
            collections_controller.state if collections_controller is not None else None
        )
        collections_count = (
            collections_state.exact_total
            if collections_state is not None
            else None
        )
        counts = self._local_source_counts
        known = self._local_source_total_known
        counts_loading = not self._library_loaded and not self._library_lookup_error
        counts_available = self._library_loaded and not self._library_lookup_error
        prompts_entry = self._local_source_records.get("prompts")
        prompts_count = (
            prompts_entry[0]
            if isinstance(prompts_entry, tuple) and len(prompts_entry) == 2
            else None
        )
        skills_entry = self._local_source_records.get("skills")
        skills_count = (
            skills_entry[0]
            if isinstance(skills_entry, tuple) and len(skills_entry) == 2
            else None
        )
        return LibraryShellInput(
            media_count=counts.get("media") if counts_available else None,
            media_known=known.get("media", True),
            conversations_count=counts.get("conversations")
            if counts_available
            else None,
            conversations_known=known.get("conversations", True),
            notes_count=counts.get("notes") if counts_available else None,
            notes_known=known.get("notes", True),
            # Prompt rows have their own exact browse owner; this rail value
            # is either the lightweight count seam's exact result or ``None``
            # (uncounted), never a sample-derived "+" estimate.
            prompts_count=prompts_count if counts_available else None,
            prompts_known=True,
            # Same posture as prompts: no sample-cap fallback backs this
            # count either (a single ``get_context`` call, not a paginated
            # fetch), so ``skills_known`` stays ``True``.
            skills_count=skills_count if counts_available else None,
            skills_known=True,
            collections_count=collections_count,
            runtime_source=active_source,
            server_label=str(server_label) if server_label else None,
            details_lines=self._library_details_lines(active_source, server_label),
            study_decks_count=(
                self._library_study_counts.get("study_decks")
                if counts_available
                else None
            ),
            flashcards_due_count=(
                self._library_study_counts.get("flashcards_due")
                if counts_available
                else None
            ),
            quizzes_count=(
                self._library_study_counts.get("quizzes") if counts_available else None
            ),
            counts_loading=counts_loading,
        )

    def _library_details_lines(
        self, active_source: str, server_label: Any
    ) -> tuple[str, ...]:
        """Build the Status group's Details disclosure lines for the rail.

        Returns up to three plain-text values: the source value (rendered
        by the rail with a dimmed "Source" label), the local source counts
        (or a lookup-error/recovery block in place of the counts when the
        local source snapshot failed to load), and -- only when the
        DBStatusManager has cached them on the app -- the local DB file
        sizes (F-014: telemetry relocated out of the app footer; omitted
        entirely until first computed, never an "N/A" triplet).
        """
        runtime_value = (
            "Local"
            if active_source != "server"
            else f"Server: {server_label or 'unknown'}"
        )
        counts = self._local_source_counts
        if self._library_lookup_error:
            counts_or_error = self._library_lookup_error
        else:
            counts_or_error = (
                f"Notes {counts.get('notes', 0)} · "
                f"Media {counts.get('media', 0)} · "
                f"Conversations {counts.get('conversations', 0)}"
            )
        sizes_line = self._library_db_sizes_line()
        if sizes_line is not None:
            return (runtime_value, counts_or_error, sizes_line)
        return (runtime_value, counts_or_error)

    def _library_db_sizes_line(self) -> str | None:
        """Format the Details DB-sizes value from the app-level cache.

        Single source for the sizes line's format, shared by the rail's
        compose path (via ``_library_details_lines``) and the
        Details-open refresh patcher
        (``_refresh_library_details_db_sizes``) -- the recompose-
        discipline rule: the in-place updater owns the same conditional
        the compose branch owns.

        Returns:
            The formatted line, or ``None`` while the DBStatusManager has
            never cached a reading (F-014: never an "N/A" triplet).
        """
        db_sizes = getattr(self.app_instance, "db_sizes_status", None)
        if not isinstance(db_sizes, dict) or not db_sizes:
            return None
        prompts_size = _unbreakable_size_text(str(db_sizes.get("prompts", "?")))
        chachanotes_size = _unbreakable_size_text(str(db_sizes.get("chachanotes", "?")))
        media_size = _unbreakable_size_text(str(db_sizes.get("media", "?")))
        return (
            f"Prompts {prompts_size} · "
            f"Chats/Notes {chachanotes_size} · "
            f"Media {media_size}"
        )

    async def _refresh_library_details_db_sizes(self) -> None:
        """Recompute the DB sizes and patch the Details line in place.

        task-4023 AC#3 (RC-09): the Details disclosure's sizes line
        rendered once from the app-level cache and was never refreshed --
        live, it kept reporting ``Prompts 180.0KB`` while disk (incl.
        sidecars) held 4.8MB, even after closing and reopening Details.
        The refresh runs at the point of consumption (opening the
        disclosure), not on a polling loop: three stat() triples through
        ``DBStatusManager.update_db_sizes`` (WAL-inclusive, task-2859),
        then a targeted update of ``#library-details-db-sizes``. When the
        cache was empty at compose time the line was never mounted, so
        the patcher mounts it after ``#library-details-body`` -- the same
        conditional the compose branch owns (``LibraryRail.compose``).
        """
        manager = getattr(self.app_instance, "db_status_manager", None)
        update = getattr(manager, "update_db_sizes", None)
        if callable(update):
            try:
                await update()
            except Exception:
                loguru_logger.debug(
                    "Details-open DB size recompute failed; the disclosure "
                    "keeps its cached reading."
                )
        sizes_line = self._library_db_sizes_line()
        if sizes_line is None:
            return
        rendered = library_dim_label_text("DB sizes", sizes_line)
        existing = list(self.query("#library-details-db-sizes"))
        if existing:
            existing[0].update(rendered)
            return
        anchors = list(self.query("#library-details-body"))
        if not anchors:
            return
        try:
            await anchors[0].parent.mount(
                Static(
                    rendered,
                    id="library-details-db-sizes",
                    classes="library-details-row",
                ),
                after=anchors[0],
            )
        except Exception:
            loguru_logger.debug(
                "Mounting the freshly computed DB-sizes line failed; the "
                "next rail recompose renders it from the updated cache."
            )

    def _conversation_reader_record(
        self, conversation_id: str
    ) -> Mapping[str, Any] | None:
        """Return the exact retained list record for one conversation id."""
        for index, record in enumerate(self._conversation_records()):
            if self._conversation_record_id(record, index) == conversation_id:
                return record
        return None

    def _conversation_reader_list_summary(self) -> str:
        """Summarize a collapsed Items pane inside protected work status."""
        state = self._build_library_conversations_state()
        pager = state.pager
        count = pager.title_count if pager is not None else None
        heading = "Conversations" if count is None else f"Conversations ({count})"
        titles = [
            str(record.get("title") or "").strip()
            for record in self._conversation_records()[:2]
        ]
        visible_titles = [title for title in titles if title]
        return " · ".join((heading, *visible_titles))

    @staticmethod
    def _conversation_reader_record_version(
        record: Mapping[str, Any] | None,
    ) -> int | None:
        """Read an authoritative optimistic-lock version without inventing one."""
        value = record.get("version") if record is not None else None
        return value if type(value) is int and value >= 0 else None

    def _sync_library_conversation_reader(self) -> bool:
        """Patch the mounted work pane from controller-owned pure state."""
        try:
            reader = self.query_one(
                "#library-conversation-reader", LibraryConversationReader
            )
        except (NoMatches, QueryError):
            return False
        metadata = dict(self._library_conversation_reader_loaded_metadata)
        if not self._library_loaded and not self._library_lookup_error:
            metadata["_list_status"] = "Loading local Library sources…"
        elif self._library_lookup_error:
            metadata["_list_status"] = self._library_lookup_error
        if not self._library_conversation_reader_layout.items_open:
            metadata["_list_summary"] = self._conversation_reader_list_summary()
        reader.sync_state(
            self._library_conversation_reader_state,
            loaded_metadata=metadata,
            selected_metadata=self._library_conversation_reader_selected_metadata,
        )
        self._finish_library_conversation_find_focus()
        return True

    def _finish_library_conversation_find_focus(self) -> None:
        """Reveal a deferred Find match only while its user intent is current."""
        intent = self._library_conversation_find_focus_intent
        state = self._library_conversation_reader_state
        if intent is None or not state.find_complete or not state.find_matches:
            return
        generation, focus_generation, query = intent
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_CONVERSATIONS
            or generation != state.generation
            or query != state.find_query
            or focus_generation != self._library_notes_focus_intent_generation
        ):
            self._library_conversation_find_focus_intent = None
            return
        try:
            reader = self.query_one(
                "#library-conversation-reader", LibraryConversationReader
            )
        except (NoMatches, QueryError):
            return
        if reader.state.generation != generation or reader.state.find_query != query:
            self._library_conversation_find_focus_intent = None
            return
        if reader.focus_find_match(state.find_matches[0].message_id):
            self._library_conversation_find_focus_intent = None

    def _conversation_reader_request_is_current(
        self, request: ConversationReaderRequest
    ) -> bool:
        """Check the complete destination/id/version/generation request fence."""
        state = self._library_conversation_reader_state
        return (
            self._library_conversation_reader_mounted_authority
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and request.destination == "conversations"
            and request.conversation_id == state.selected_id
            and request.version == state.selected_version
            and request.generation == state.generation
        )

    def _invalidate_library_conversation_reader_authority(self) -> None:
        """Revoke every page/continuation and loaded-action generation."""
        state = self._library_conversation_reader_state
        self._library_conversation_reader_state = dataclasses.replace(
            state,
            generation=state.generation + 1,
            loading=False,
        )
        self._library_conversation_find_focus_intent = None

    def _set_library_destination_with_conversation_fence(self, row_id: str) -> None:
        """Set one admitted Library destination and revoke a Conversations read."""
        notes_rows = {LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE}
        if self._library_selected_row_id in notes_rows and row_id not in notes_rows:
            self._dispatch_library_notes_work_session(
                NotesWorkSessionEvent.LEFT_NOTES,
                sync_layout=False,
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and row_id != LIBRARY_ROW_BROWSE_CONVERSATIONS
        ):
            self._invalidate_library_conversation_reader_authority()
        self._library_selected_row_id = row_id

    def _conversation_reader_service(self) -> Any | None:
        """Return the existing local conversation detail authority."""
        direct = getattr(self.app_instance, "local_chat_conversation_service", None)
        if callable(getattr(direct, "get_library_conversation_messages", None)):
            return direct
        scope = getattr(self.app_instance, "chat_conversation_scope_service", None)
        local = getattr(scope, "local_service", None)
        if callable(getattr(local, "get_library_conversation_messages", None)):
            return local
        return None

    def _ensure_library_conversation_reader_selection(self) -> None:
        """Start the initial selected-row read once the permanent pane mounts."""
        conversation_id = self._selected_conversation_id
        if not conversation_id or self._library_conversations_select_mode:
            return
        state = self._library_conversation_reader_state
        record_version = self._conversation_reader_record_version(
            self._conversation_reader_record(conversation_id)
        )
        if state.selected_id == conversation_id and (
            (
                state.loading
                and (record_version is None or state.selected_version == record_version)
            )
            or (
                state.loaded_actions_eligible
                and (record_version is None or state.loaded_version == record_version)
            )
        ):
            return
        self._start_library_conversation_reader_selection(conversation_id)

    def _start_library_conversation_reader_selection(
        self, conversation_id: str
    ) -> None:
        """Select one list record and launch its fenced progressive reader."""
        self._library_conversation_deleted_selection_id = ""
        record = self._conversation_reader_record(conversation_id)
        if record is not None:
            self._library_conversation_reader_selected_metadata = dict(record)
        version = self._conversation_reader_record_version(record)
        if version is None:
            state = self._library_conversation_reader_state
            generation = state.generation + 1
            self._library_conversation_reader_state = dataclasses.replace(
                state,
                selected_id=conversation_id,
                selected_version=None,
                generation=generation,
                mode=state.mode if conversation_id == state.loaded_id else "read",
                error=None,
                loading=True,
                unavailable=False,
                bulk_active=False,
                bulk_selected_count=0,
                bulk_loaded_preview_selected=None,
            )
            self._sync_library_conversation_reader()
            self.run_worker(
                self._bootstrap_library_conversation_reader(
                    conversation_id, generation
                ),
                exclusive=True,
                group="library_conversation_reader",
            )
            return
        state, request = select_conversation(
            self._library_conversation_reader_state,
            conversation_id,
            version=version,
        )
        self._library_conversation_reader_state = state
        self._sync_library_conversation_reader()
        self.run_worker(
            self._load_library_conversation_reader(request),
            exclusive=True,
            group="library_conversation_reader",
        )

    async def _bootstrap_library_conversation_reader(
        self, conversation_id: str, bootstrap_generation: int
    ) -> None:
        """Obtain a missing real version from the authoritative detail envelope."""
        service = self._conversation_reader_service()
        read = getattr(service, "get_library_conversation_messages", None)
        if not callable(read):
            state = self._library_conversation_reader_state
            if self._conversation_reader_bootstrap_is_current(
                conversation_id, bootstrap_generation
            ):
                self._library_conversation_reader_state = dataclasses.replace(
                    state,
                    error="Conversation detail is unavailable.",
                    loading=False,
                    unavailable=False,
                )
                self._sync_library_conversation_reader()
            return
        try:
            response = await self._run_library_service_call(
                read,
                conversation_id,
                message_offset=0,
                message_limit=LIBRARY_CONVERSATION_PAGE_SIZE,
                max_chars=LIBRARY_CONVERSATION_READER_MAX_CHARS,
            )
        except Exception:
            if self._conversation_reader_bootstrap_is_current(
                conversation_id, bootstrap_generation
            ):
                state = self._library_conversation_reader_state
                self._library_conversation_reader_state = dataclasses.replace(
                    state,
                    error="Couldn't load this conversation. Try again.",
                    loading=False,
                    unavailable=False,
                )
                self._sync_library_conversation_reader()
            return
        if not self._conversation_reader_bootstrap_is_current(
            conversation_id, bootstrap_generation
        ):
            return
        state = self._library_conversation_reader_state
        if response is None:
            self._library_conversation_reader_state = dataclasses.replace(
                state,
                error="Conversation unavailable.",
                loading=False,
                unavailable=True,
            )
            self._sync_library_conversation_reader()
            return
        version = response.get("version") if isinstance(response, Mapping) else None
        if type(version) is not int or version < 0:
            self._library_conversation_reader_state = dataclasses.replace(
                state,
                error="Conversation detail returned no authoritative version.",
                loading=False,
            )
            self._sync_library_conversation_reader()
            return
        selected, request = select_conversation(state, conversation_id, version=version)
        self._library_conversation_reader_state = selected
        await self._load_library_conversation_reader(
            request,
            initial_response=response,
        )

    def _conversation_reader_bootstrap_is_current(
        self,
        conversation_id: str,
        bootstrap_generation: int,
    ) -> bool:
        """Fence a version bootstrap to its mounted Conversations selection."""
        state = self._library_conversation_reader_state
        return (
            self._library_conversation_reader_mounted_authority
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and state.selected_id == conversation_id
            and state.selected_version is None
            and state.generation == bootstrap_generation
        )

    async def _load_library_conversation_reader(
        self,
        request: ConversationReaderRequest,
        *,
        initial_response: Mapping[str, Any] | None = None,
    ) -> None:
        """Settle bounded pages and body continuations incrementally off-loop."""
        service = self._conversation_reader_service()
        read = getattr(service, "get_library_conversation_messages", None)
        if not callable(read):
            self._library_conversation_reader_state = settle_conversation_error(
                self._library_conversation_reader_state,
                request,
                "Conversation detail is unavailable.",
            )
            self._sync_library_conversation_reader()
            return

        response = initial_response
        while self._conversation_reader_request_is_current(request):
            try:
                if response is None:
                    response = await self._run_library_service_call(
                        read,
                        request.conversation_id,
                        message_offset=request.message_offset,
                        message_limit=request.message_limit,
                        max_chars=LIBRARY_CONVERSATION_READER_MAX_CHARS,
                    )
            except asyncio.CancelledError:
                raise
            except Exception:
                response = None
                if self._conversation_reader_request_is_current(request):
                    self._library_conversation_reader_state = settle_conversation_error(
                        self._library_conversation_reader_state,
                        request,
                        "Couldn't load this conversation. Try again.",
                    )
                    self._sync_library_conversation_reader()
                return
            if not self._conversation_reader_request_is_current(request):
                return
            if response is None:
                self._library_conversation_reader_state = (
                    settle_conversation_unavailable(
                        self._library_conversation_reader_state, request
                    )
                )
                self._sync_library_conversation_reader()
                return
            try:
                before_settle = self._library_conversation_reader_state
                previous_loaded_generation = before_settle.loaded_generation
                settled = settle_conversation_page(
                    before_settle,
                    request,
                    response,
                )
            except (TypeError, ValueError):
                before_settle = self._library_conversation_reader_state
                settled = settle_conversation_error(
                    before_settle,
                    request,
                    "Conversation detail was invalid. Try again.",
                )
            self._library_conversation_reader_state = settled
            request_content_loaded = (
                settled.loaded_id == request.conversation_id
                and settled.loaded_generation == request.generation
            )
            if (
                settled is not before_settle
                and settled.error is None
                and request_content_loaded
            ):
                metadata = dict(
                    self._library_conversation_reader_selected_metadata
                    if previous_loaded_generation != request.generation
                    else self._library_conversation_reader_loaded_metadata
                )
                title = response.get("title")
                if isinstance(title, str) and title.strip():
                    metadata["title"] = title.strip()
                metadata["version"] = request.version
                self._library_conversation_reader_loaded_metadata = metadata
            self._sync_library_conversation_reader()
            await asyncio.sleep(0)
            if settled.error:
                return

            for message in tuple(settled.messages):
                while (
                    not message.complete
                    and self._conversation_reader_request_is_current(request)
                ):
                    try:
                        continuation = await self._run_library_service_call(
                            read,
                            request.conversation_id,
                            message_offset=request.message_offset,
                            message_limit=request.message_limit,
                            max_chars=LIBRARY_CONVERSATION_READER_MAX_CHARS,
                            message_id=message.message_id,
                            char_start=len(message.text),
                        )
                    except asyncio.CancelledError:
                        raise
                    except Exception:
                        self._library_conversation_reader_state = (
                            settle_conversation_error(
                                self._library_conversation_reader_state,
                                request,
                                "Couldn't finish loading a saved message. Try again.",
                            )
                        )
                        self._sync_library_conversation_reader()
                        return
                    before = self._library_conversation_reader_state
                    if continuation is None:
                        self._library_conversation_reader_state = (
                            settle_conversation_unavailable(before, request)
                        )
                        self._sync_library_conversation_reader()
                        return
                    self._library_conversation_reader_state = (
                        settle_conversation_continuation(
                            before,
                            request,
                            continuation,
                        )
                    )
                    if self._library_conversation_reader_state is before:
                        self._library_conversation_reader_state = (
                            settle_conversation_error(
                                before,
                                request,
                                "Saved message continuation was invalid. Try again.",
                            )
                        )
                        self._sync_library_conversation_reader()
                        return
                    self._sync_library_conversation_reader()
                    await asyncio.sleep(0)
                    message = next(
                        candidate
                        for candidate in self._library_conversation_reader_state.messages
                        if candidate.message_id == message.message_id
                    )

            state = self._library_conversation_reader_state
            if state.complete:
                return
            next_offset = len(state.messages)
            if next_offset <= request.message_offset:
                self._library_conversation_reader_state = settle_conversation_error(
                    state,
                    request,
                    "Conversation loading made no progress. Try again.",
                )
                self._sync_library_conversation_reader()
                return
            request = dataclasses.replace(request, message_offset=next_offset)
            response = None

    def _build_library_conversations_state(self):
        """Build the conversations canvas display state from local records."""
        state = build_library_conversations_state(
            self._conversation_records(),
            query=self._library_conversation_query,
            selected_id=self._selected_conversation_id,
            select_mode=self._library_conversations_select_mode,
            selected_ids=self._library_conversations_row_selection.ids,
            page=self._library_conversation_page,
            requested_page=self._library_conversation_requested_page,
            page_size=self._library_conversation_page_size,
            total_count=self._library_conversation_total,
            total_known=self._library_conversation_total_known,
            has_more=self._library_conversation_has_more,
            freshness=self._library_conversation_freshness,
            stale_copy=self._library_conversation_stale_copy,
            loading=self._library_conversation_loading,
            error_copy=self._library_conversation_error,
            selection_notice=self._library_conversation_selection_notice,
        )
        state = dataclasses.replace(
            state,
            query=self._library_conversation_requested_query,
            status_copy=(
                state.status_copy or self._library_conversation_selection_notice
            ),
        )
        retained_reader_id = self._library_conversation_reader_state.selected_id
        if (
            retained_reader_id
            and not self._library_conversation_reader_state.unavailable
            and all(row.conversation_id != retained_reader_id for row in state.rows)
        ):
            state = dataclasses.replace(
                state,
                selected_id="",
                preview_lines=(),
                rows=tuple(
                    dataclasses.replace(row, selected=False) for row in state.rows
                ),
            )
        if self._library_conversation_deleted_selection_id:
            state = dataclasses.replace(
                state,
                selected_id="",
                preview_lines=(),
                rows=tuple(
                    dataclasses.replace(row, selected=False) for row in state.rows
                ),
            )
        if self._library_conversations_select_mode:
            self._library_conversations_row_selection.reconcile(
                r.conversation_id for r in state.rows
            )
        return state

    def _sync_library_conversation_canvas(
        self, *, then: Callable[[], None] | None = None
    ) -> bool:
        """Sync Conversation state through its canvas-owned action gates."""

        return _sync_library_canvas(
            self,
            "conversations",
            then=then,
            allow_screen_fallback=False,
        )

    @staticmethod
    def _normalize_library_conversation_page(page: object) -> int:
        """Return a dispatch-safe one-based page, defaulting invalid input."""

        if isinstance(page, bool) or not isinstance(page, int) or page < 1:
            return 1
        max_page = (2**63 - 1) // LIBRARY_CONVERSATION_PAGE_SIZE + 1
        return page if page <= max_page else 1

    def _start_library_conversation_page_request(
        self,
        page: int,
        query: str,
        *,
        refocus_filter: bool = False,
        focus_after_apply: str = "",
    ) -> None:
        """Start one generation-guarded conversation page request."""
        self._pending_library_source_open = None
        requested_page = self._normalize_library_conversation_page(page)
        normalized_query, generation = self._prepare_library_conversation_page_request(
            query,
            page=requested_page,
            refocus_filter=refocus_filter,
            focus_after_apply=focus_after_apply,
        )
        self.run_worker(
            self._load_library_conversation_page(
                requested_page,
                normalized_query,
                generation,
            ),
            exclusive=True,
            group="library_conversation_page",
        )

    def _prepare_library_conversation_page_request(
        self,
        query: str,
        *,
        page: int = 1,
        refocus_filter: bool = False,
        focus_after_apply: str = "",
    ) -> tuple[str, int]:
        """Invalidate older requests and publish a coherent loading state."""
        self._library_conversation_request_generation += 1
        generation = self._library_conversation_request_generation
        normalized_query = self._safe_text(query, max_length=200)
        self._library_conversation_requested_page = (
            self._normalize_library_conversation_page(page)
        )
        self._library_conversation_requested_query = normalized_query
        if refocus_filter:
            focus_after_apply = "#library-conversations-filter"
        self._library_conversation_focus_after_apply = focus_after_apply
        self._library_conversation_loading = True
        self._library_conversation_error = ""
        had_selection = (
            self._library_conversations_select_mode
            or self._library_conversations_row_selection.count > 0
        )
        self._library_conversation_selection_notice = (
            "Selection cleared." if had_selection else ""
        )
        self._library_conversations_select_mode = False
        self._library_conversations_row_selection.clear()
        self._library_conversation_reader_state = project_conversation_multiselect(
            self._library_conversation_reader_state,
            active=False,
            selected_count=0,
            loaded_preview_selected=None,
        )
        self._sync_library_conversation_reader()
        self._sync_library_conversation_canvas()
        if refocus_filter:
            self._refocus_library_conversations_filter_after_sync()
        return normalized_query, generation

    def _library_conversation_page_needs_recovery(self) -> bool:
        """Return whether Conversation entry needs its requested scope refetched."""

        return not self._library_conversation_loading and bool(
            not self._library_conversation_page_loaded
            or self._library_conversation_freshness != "fresh"
            or self._library_conversation_error
        )

    def _finish_library_conversation_request_focus(self) -> None:
        """Restore captured pager/filter focus after Conversation recomposition."""

        requested = self._library_conversation_focus_after_apply
        self._library_conversation_focus_after_apply = ""
        if not requested:
            return
        selectors = [requested]
        if requested == "#library-conversations-next":
            selectors.extend(
                ("#library-conversations-previous", "#library-conversations-filter")
            )
        elif requested == "#library-conversations-previous":
            selectors.extend(
                ("#library-conversations-next", "#library-conversations-filter")
            )
        elif requested == "#library-conversations-retry":
            selectors.append("#library-conversations-filter")
        for selector in selectors:
            matches = self.query(selector)
            if not matches:
                continue
            target = matches.first()
            if getattr(target, "disabled", False):
                continue
            target.focus()
            return

    def _finish_library_conversation_page_apply(self) -> None:
        """Finish list focus and align the permanent work selection."""
        self._finish_library_conversation_request_focus()
        self._ensure_library_conversation_reader_selection()

    def _fail_library_conversation_request(
        self,
        requested_page: int,
        requested_query: str,
        generation: int,
        *,
        copy: str = "",
    ) -> None:
        """Retain last-good applied state and publish retryable failure copy."""

        if generation != self._library_conversation_request_generation:
            return
        self._library_conversation_loading = False
        if self._library_conversation_freshness == "stale":
            self._library_conversation_error = ""
            if copy:
                self._library_conversation_stale_copy = copy
        elif copy:
            self._library_conversation_error = copy
        elif self._library_conversation_freshness == "uninitialized":
            self._library_conversation_error = "Couldn't load conversations. Try again."
        elif requested_query != self._library_conversation_query:
            self._library_conversation_error = (
                "Filter wasn’t applied; showing previous results."
            )
        else:
            self._library_conversation_error = f"Couldn't load page {requested_page}."
        self._sync_library_conversation_canvas(
            then=self._finish_library_conversation_request_focus
        )

    @staticmethod
    def _conversation_out_of_range_total(
        result: object, *, requested_offset: int
    ) -> int | None:
        """Return the coherent total proving an ordinary page is out of range."""

        if not isinstance(result, Mapping):
            return None
        items = result.get("items")
        pagination = result.get("pagination")
        if not isinstance(items, list) or items:
            return None
        if not isinstance(pagination, Mapping):
            return None
        limit = pagination.get("limit")
        offset = pagination.get("offset")
        total = pagination.get("total")
        has_more = pagination.get("has_more")
        coordinates = (limit, offset, total)
        if any(
            isinstance(value, bool) or not isinstance(value, int)
            for value in coordinates
        ):
            return None
        if (
            limit != LIBRARY_CONVERSATION_PAGE_SIZE
            or offset != requested_offset
            or total < 0
            or requested_offset == 0
            or requested_offset < total
            or has_more is not False
        ):
            return None
        return total

    def _library_conversation_absence_fence_is_current(
        self,
        *,
        conversation_id: str,
        version: int | None,
        reader_generation: int,
        page_generation: int,
    ) -> bool:
        """Fence an exact-ID absence probe to its mounted reader epoch."""
        state = self._library_conversation_reader_state
        return (
            self._library_conversation_reader_mounted_authority
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and page_generation == self._library_conversation_request_generation
            and state.selected_id == conversation_id
            and state.selected_version == version
            and state.generation == reader_generation
        )

    async def _confirm_library_conversation_page_absence(
        self,
        *,
        conversation_id: str,
        version: int | None,
        reader_generation: int,
        page_generation: int,
    ) -> Literal["exists", "deleted", "unknown", "stale"]:
        """Confirm a missing page row through the existing exact-ID locator."""
        service = getattr(self.app_instance, "chat_conversation_scope_service", None)
        locate_page = getattr(service, "locate_conversation_page", None)
        if not callable(locate_page):
            return "unknown"
        try:
            located = await self._run_library_service_call(
                locate_page,
                conversation_id,
                mode="local",
                scope_type="all",
                limit=LIBRARY_CONVERSATION_PAGE_SIZE,
            )
        except Exception:
            logger.warning("Failed to confirm missing Library conversation.")
            located = Ellipsis
        if not self._library_conversation_absence_fence_is_current(
            conversation_id=conversation_id,
            version=version,
            reader_generation=reader_generation,
            page_generation=page_generation,
        ):
            return "stale"
        if located is None:
            return "deleted"
        if located is Ellipsis:
            return "unknown"
        try:
            self._validate_library_conversation_locator(located, conversation_id)
        except (TypeError, ValueError):
            return "unknown"
        return "exists"

    async def _load_library_conversation_page(
        self,
        page: int,
        query: str,
        generation: int,
        *,
        _clamp_attempted: bool = False,
    ) -> None:
        """Load a complete service-backed page, discarding stale results."""
        service = getattr(self.app_instance, "chat_conversation_scope_service", None)
        list_conversations = getattr(service, "list_conversations", None)
        if not callable(list_conversations):
            self._fail_library_conversation_request(page, query, generation)
            return

        requested_page = self._normalize_library_conversation_page(page)
        normalized_query = self._safe_text(query, max_length=200)
        requested_offset = (requested_page - 1) * LIBRARY_CONVERSATION_PAGE_SIZE
        try:
            result = await self._run_library_service_call(
                list_conversations,
                mode="local",
                scope_type="all",
                query=normalized_query or None,
                limit=LIBRARY_CONVERSATION_PAGE_SIZE,
                offset=requested_offset,
            )
        except Exception:
            if generation != self._library_conversation_request_generation:
                return
            logger.warning("Failed to load Library conversations page.")
            self._fail_library_conversation_request(
                requested_page, normalized_query, generation
            )
            return

        if generation != self._library_conversation_request_generation:
            return

        out_of_range_total = self._conversation_out_of_range_total(
            result,
            requested_offset=requested_offset,
        )
        if out_of_range_total is not None:
            page_count = max(
                1,
                (out_of_range_total + LIBRARY_CONVERSATION_PAGE_SIZE - 1)
                // LIBRARY_CONVERSATION_PAGE_SIZE,
            )
            if _clamp_attempted:
                self._library_conversation_loading = False
                self._library_conversation_freshness = "stale"
                self._library_conversation_total_known = False
                self._library_conversation_error = ""
                self._library_conversation_stale_copy = (
                    "Source changed again; try again."
                )
                self._sync_library_conversation_canvas(
                    then=self._finish_library_conversation_request_focus
                )
                return
            self._library_conversation_requested_page = page_count
            await self._load_library_conversation_page(
                page_count,
                normalized_query,
                generation,
                _clamp_attempted=True,
            )
            return

        try:
            validated = validate_library_conversation_page(
                result,
                requested_limit=LIBRARY_CONVERSATION_PAGE_SIZE,
                requested_offset=requested_offset,
            )
        except (TypeError, ValueError):
            self._fail_library_conversation_request(
                requested_page, normalized_query, generation
            )
            return

        if generation != self._library_conversation_request_generation:
            return

        reader_state = self._library_conversation_reader_state
        previous_ids = {
            str(record.get("id") or "")
            for record in self._library_conversation_page_records
        }
        refreshed_ids = {str(record.get("id") or "") for record in validated.items}
        selected_id = reader_state.selected_id or ""
        needs_exact_confirmation = (
            self._library_conversation_page_loaded
            and requested_page == self._library_conversation_page
            and normalized_query == self._library_conversation_query
            and selected_id in previous_ids
            and selected_id not in refreshed_ids
        )
        absence_result: Literal["exists", "deleted", "unknown", "stale"] | None = None
        if needs_exact_confirmation:
            absence_result = await self._confirm_library_conversation_page_absence(
                conversation_id=selected_id,
                version=reader_state.selected_version,
                reader_generation=reader_state.generation,
                page_generation=generation,
            )
            if absence_result == "stale":
                return
        if absence_result == "deleted":
            deleted_state = confirm_conversation_deleted(
                self._library_conversation_reader_state,
                selected_id,
                version=reader_state.selected_version,
                generation=reader_state.generation,
            )
            if deleted_state is not reader_state:
                self._library_conversation_reader_state = deleted_state
                self._library_conversation_deleted_selection_id = selected_id
                self._selected_conversation_id = ""
                self._sync_library_conversation_reader()

        self._library_conversation_page_records = validated.items
        self._library_conversation_page = requested_page
        self._library_conversation_total = validated.total
        self._library_conversation_total_known = True
        self._library_conversation_has_more = validated.has_more
        self._library_conversation_page_loaded = True
        self._library_conversation_query = normalized_query
        self._library_conversation_requested_page = requested_page
        self._library_conversation_requested_query = normalized_query
        self._library_conversation_freshness = (
            "stale" if absence_result == "unknown" else "fresh"
        )
        self._library_conversation_stale_copy = (
            "Conversation location could not be confirmed; try again."
            if absence_result == "unknown"
            else ""
        )
        self._library_conversation_loading = False
        self._library_conversation_error = ""
        self._adopt_library_conversation_state_selection(
            self._build_library_conversations_state().selected_id
        )
        self._sync_library_conversation_canvas(
            then=self._finish_library_conversation_page_apply
        )

    def _build_library_media_state(self) -> LibraryMediaCanvasState:
        """Build Media rows only from the controller's retained exact page."""
        controller = self._library_media_browse_controller
        if controller.applied_result is None:
            return build_library_media_state(
                (),
                active_type=self._library_media_type_filter,
                selected_id=self._selected_media_id,
                select_mode=self._library_media_select_mode,
                selected_ids=self._library_media_row_selection.ids,
                confirming_bulk_delete=self._library_media_confirming_bulk_delete,
                delete_receipt_count=len(self._library_media_delete_receipt_ids),
                type_choices_visible=self._library_media_type_choices_visible,
            )
        state = build_library_media_browse_state(
            controller.applied_result,
            type_options=controller.type_options,
            retained_items=controller.retained_items,
            selected_id=self._selected_media_id,
            select_mode=self._library_media_select_mode,
            selected_ids=self._library_media_row_selection.ids,
            confirming_bulk_delete=self._library_media_confirming_bulk_delete,
            delete_receipt_count=len(self._library_media_delete_receipt_ids),
            type_choices_visible=self._library_media_type_choices_visible,
            loading_id=(
                (self._library_media_reader_session.selected_id or "")
                if self._library_media_reader_session.pending_request is not None
                else ""
            ),
            loaded_id=self._library_media_reader_session.loaded_id or "",
        )
        if controller.loading and controller.inflight_scope is not None:
            state = dataclasses.replace(state, query=controller.inflight_scope.query)
        if self._library_media_select_mode:
            self._library_media_row_selection.reconcile(r.media_id for r in state.rows)
        return state

    def _library_media_content_signature(self) -> tuple[object, ...]:
        """Return applied normal-Media scope plus ordered stable row IDs."""
        controller = self._library_media_browse_controller
        return (
            controller.applied_scope,
            tuple(str(item["id"]) for item in controller.retained_items),
        )

    def _library_media_layout_signature(self) -> tuple[object, ...]:
        """Return terminal allocation plus pure effective Media pane layout."""
        reader_width = self._library_media_reader_layout.reader_width
        pure_layout = resolve_media_reader_layout(
            reader_width,
            self._library_media_reader_preferences,
        )
        return (
            int(self.size.width),
            int(self.size.height),
            self._library_notes_compact,
            self._library_media_reader_preferences,
            pure_layout,
        )

    def _library_media_canvas_presentation(self) -> dict[str, Any]:
        """Return controller-owned inputs shared by every Media canvas path."""
        controller = self._library_media_browse_controller
        return {
            "pager": controller.pager,
            "type_options": self._library_media_type_options(),
            "stale_action_reason": (
                controller.stale_copy if controller.freshness == "stale" else ""
            ),
            "mutation_action_reason": (
                "Media change in progress."
                if self._library_media_bulk_delete_in_flight
                else ""
            ),
            "compact": False,
            "show_preview": False,
        }

    def _library_media_type_options(self) -> tuple[str | None, ...]:
        """Return the unfiltered sentinel plus every complete stored facet."""
        return (None, *self._library_media_browse_controller.type_options)

    def _begin_library_media_mutation(self) -> MediaBrowseScope:
        """Fence page/facet reads before the shared durable Media write."""
        if self._library_media_mutation_scope is None:
            self._library_media_mutation_scope = (
                self._library_media_browse_controller.begin_mutation()
            )
            self._library_media_mutation_authority = (
                self._library_media_lifecycle_generation
            )
            self._library_media_type_choices_visible = False
            self._sync_library_media_browse_state(None)
            self._sync_library_media_viewer_mutation_gate()
        return self._library_media_mutation_scope

    def _complete_library_media_mutation(
        self,
        *,
        committed: bool = False,
        remove_ids: tuple[str, ...] = (),
        upsert_items: tuple[Mapping[str, Any], ...] = (),
        refresh_normal_media: bool = True,
        stale_normal_media: bool = False,
    ) -> None:
        """Release the write interlock and refresh its full applied scope."""
        scope = self._library_media_mutation_scope
        has_authority = (
            self._library_media_mutation_authority
            == self._library_media_lifecycle_generation
        )
        self._library_media_mutation_scope = None
        self._library_media_mutation_authority = None
        self._library_media_bulk_delete_in_flight = False
        if not committed and not remove_ids and not upsert_items:
            if has_authority:
                self._sync_library_media_browse_state(None)
            return
        controller = self._library_media_browse_controller
        if stale_normal_media:
            controller.mark_stale_after_trash_restore()
        elif refresh_normal_media and (committed or remove_ids or upsert_items):
            controller.reconcile_committed_mutation(
                remove_ids=remove_ids,
                upsert_items=upsert_items,
            )
        if not refresh_normal_media:
            return
        refresh_scope = scope or controller.mutation_refresh_scope
        if (
            not has_authority
            or self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
        ):
            return
        controller.request(refresh_scope, focus_identity=None)
        controller.request_facets(fingerprint=refresh_scope.fingerprint)

    def _library_media_mutation_summary(
        self,
        media_id: str,
        record: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        """Normalize one known restored row for stale retained display."""
        backing_id = self._required_library_media_backing_id(media_id)
        return {
            "id": f"local:media:{backing_id}",
            "backing_media_id": backing_id,
            "title": record.get("title"),
            "media_type": record.get("media_type", record.get("type")),
            "updated_at": record.get("updated_at", record.get("last_modified")),
        }

    @staticmethod
    def _bounded_library_media_trash_title(title: str, limit: int = 80) -> str:
        """Bound mutation receipts without changing confirmation identity."""
        readable = str(title).strip()
        if len(readable) <= limit:
            return readable
        return f"{readable[: limit - 3].rstrip()}..."

    @staticmethod
    def _valid_library_media_trash_delete_ack(
        result: Any,
        *,
        media_id: int,
    ) -> bool:
        """Accept only the local delete contract for the captured identity."""
        if not isinstance(result, Mapping):
            return False
        acknowledged_id = result.get("media_id")
        return (
            result.get("ok") is True
            and type(acknowledged_id) is int
            and acknowledged_id == media_id
        )

    @staticmethod
    def _validated_library_media_trash_restore_summary(
        result: Any,
        *,
        media_id: int,
    ) -> Mapping[str, Any] | None:
        """Validate a restore response and retain only its bounded summary."""
        if not isinstance(result, Mapping):
            return None
        if "ok" in result and result.get("ok") is not True:
            return None
        restored_id = result.get("id")
        deleted = result.get("deleted")
        is_trash = result.get("is_trash")
        title = result.get("title")
        media_type = result.get("type")
        if (
            type(restored_id) is not int
            or restored_id != media_id
            or type(deleted) is not int
            or deleted != 0
            or type(is_trash) is not int
            or is_trash != 0
            or type(title) is not str
            or type(media_type) is not str
        ):
            return None
        return {
            "id": restored_id,
            "title": title.strip() or "Untitled",
            "type": media_type.strip() or None,
            "deleted": deleted,
            "is_trash": is_trash,
        }

    @staticmethod
    def _restore_library_media_scope(state: Mapping[str, Any]) -> MediaBrowseScope:
        """Return one strict dispatch-safe applied Media scope from saved state."""
        saved = state.get("library_media_scope")
        raw = saved if type(saved) is dict else {}
        query = raw.get("query", "")
        media_type = raw.get("media_type")
        sort_by = raw.get("sort_by", "last_modified_desc")
        page = raw.get("page", 1)
        if type(query) is not str:
            query = ""
        if media_type is not None and type(media_type) is not str:
            media_type = None
        if type(sort_by) is not str:
            sort_by = "last_modified_desc"
        if type(page) is not int or page < 1:
            page = 1
        else:
            try:
                MediaBrowseScope(page=page)
            except ValueError:
                page = 1
        try:
            return MediaBrowseScope(
                query=query,
                media_type=media_type,
                sort_by=sort_by,
                page=page,
            )
        except (TypeError, ValueError):
            return MediaBrowseScope()

    def _sync_library_media_browse_state(self, focus_identity: str | None) -> None:
        """Project accepted Media page/facet state into the mounted list."""
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view == "trash"
        ):
            return
        applied = self._library_media_browse_controller.applied_scope
        if applied is not None:
            self._library_media_type_filter = applied.media_type
        controller = self._library_media_browse_controller
        applied_selection_id = ""
        if (
            applied is not None
            and not controller.loading
            and applied == controller.requested_scope
        ):
            page_ids = {str(item["id"]) for item in controller.retained_items}
            if applied.query and self._library_media_filter_select_first:
                self._selected_media_id = (
                    str(controller.retained_items[0]["id"])
                    if controller.retained_items
                    else ""
                )
                applied_selection_id = self._selected_media_id
                self._library_media_filter_select_first = False
            elif not applied.query:
                self._library_media_unfiltered_scope = applied
                if self._library_media_filter_restore_id:
                    self._selected_media_id = (
                        self._library_media_filter_restore_id
                        if self._library_media_filter_restore_id in page_ids
                        else str(controller.retained_items[0]["id"])
                        if controller.retained_items
                        else ""
                    )
                    applied_selection_id = self._selected_media_id
                    self._library_media_filter_restore_id = ""
        if (
            applied_selection_id
            and self._library_media_reader_session.selected_id != applied_selection_id
        ):
            selected_title = next(
                (
                    str(item.get("title") or applied_selection_id)
                    for item in controller.retained_items
                    if str(item["id"]) == applied_selection_id
                ),
                applied_selection_id,
            )
            self._select_library_media_reader_row(
                applied_selection_id,
                selected_title,
                immediate=False,
                sync_surfaces=False,
            )
        media_state = self._build_library_media_state()
        self._selected_media_id = media_state.selected_id
        focused = self.focused
        focused_id = getattr(focused, "id", None)
        pager_focus_ids = {
            "library-media-previous",
            "library-media-next",
            "library-media-retry",
            "library-media-type-filter",
        }
        pending_receipt = self._library_pending_list_entry_media_return
        exact_pending_return = bool(
            self._library_pending_list_entry_focus
            and focus_identity is None
            and self._library_media_return_candidate(pending_receipt)
        )
        if exact_pending_return:
            self._library_media_return_settlement = None
            if (
                focused is not None
                and any(
                    widget.id == "library-media-canvas"
                    for widget in focused.ancestors
                )
            ):
                self.set_focus(None)
                focused = None
                focused_id = None
        pending_entry_focus_generation = (
            self._library_list_entry_focus_generation
            if (
                self._library_pending_list_entry_focus
                and focus_identity is None
                and not exact_pending_return
            )
            else None
        )
        if (
            not exact_pending_return
            and pending_entry_focus_generation is None
            and isinstance(focused_id, str)
            and focused_id
            and any(widget.id == "library-media-canvas" for widget in focused.ancestors)
            and not (
                focus_identity
                in {
                    "#library-media-previous",
                    "#library-media-next",
                    "#library-media-retry",
                }
                and focused_id in pager_focus_ids
            )
        ):
            focus_identity = f"#{focused_id}"
        if exact_pending_return:
            exact_generation = self._library_list_entry_focus_generation

            def arm_exact_return() -> None:
                if (
                    self._library_pending_list_entry_focus
                    and exact_generation == self._library_list_entry_focus_generation
                    and self._library_pending_list_entry_media_return
                    is pending_receipt
                    and pending_receipt is not None
                ):
                    self._focus_library_list_entry_if_current(exact_generation)

            then = arm_exact_return
        elif pending_entry_focus_generation is not None:

            def focus_pending_entry() -> None:
                try:
                    self._focus_library_list_entry_if_current(
                        pending_entry_focus_generation
                    )
                finally:
                    self._library_notes_restoring_focus = False

            then = focus_pending_entry
        elif focus_identity in {
            "#library-media-previous",
            "#library-media-next",
            "#library-media-retry",
        }:

            def focus_page_control() -> None:
                self._focus_library_media_page_control(focus_identity)

            then = focus_page_control
        else:
            then = (
                (lambda: self._focus_library_control(focus_identity))
                if focus_identity
                else None
            )
        if pending_entry_focus_generation is not None:
            # Canvas recompose temporarily drops DOM focus outside Media.
            # Treat that automatic fallback as part of this guarded restore;
            # keyboard and mouse input disarm the generation before callback.
            self._library_notes_restoring_focus = True
        _sync_library_canvas(self, "media", then=then)

    def _focus_library_media_page_control(self, invoked: str) -> None:
        """Restore pager focus without ever landing on a disabled control."""
        opposite = {
            "#library-media-previous": "#library-media-next",
            "#library-media-next": "#library-media-previous",
            "#library-media-retry": "#library-media-type-filter",
        }[invoked]
        for selector in (invoked, opposite, "#library-media-type-filter"):
            try:
                control = self.query_one(selector)
            except (NoMatches, QueryError):
                continue
            if not getattr(control, "disabled", False):
                control.focus()
                return

    def _request_library_media_browse(
        self,
        scope: MediaBrowseScope,
        *,
        focus_identity: str | None,
    ) -> Any | None:
        return self._library_media_browse_controller.request(
            scope, focus_identity=focus_identity
        )

    def _cancel_library_media_selection_settlement(self) -> None:
        """Cancel delayed traversal and invalidate its request generation."""
        if self._library_media_selection_timer is not None:
            self._library_media_selection_timer.stop()
            self._library_media_selection_timer = None
        session = self._library_media_reader_session
        if session.pending_request is None:
            return
        self._library_media_reader_session = LibraryMediaReaderSessionState(
            selected_id=session.loaded_id,
            selected_backing_id=session.loaded_backing_id,
            selected_title=session.loaded_title,
            loaded_id=session.loaded_id,
            loaded_backing_id=session.loaded_backing_id,
            loaded_title=session.loaded_title,
            request_generation=session.request_generation + 1,
            mode=session.mode,
        )

    def _dispatch_library_media_detail_request(
        self, generation: int, requested_id: str, media_id: str
    ) -> None:
        """Dispatch only the still-current canonical-id/generation request."""
        self._library_media_selection_timer = None
        pending = self._library_media_reader_session.pending_request
        if (
            pending is None
            or pending.generation != generation
            or pending.requested_id != requested_id
            or self._library_media_select_mode
        ):
            return
        self.run_worker(
            self._refresh_library_media_detail(
                media_id,
                request_generation=generation,
                requested_id=requested_id,
            ),
            group="library_media_detail",
        )

    def _select_library_media_reader_row(
        self,
        media_id: str,
        title: str,
        *,
        immediate: bool,
        sync_surfaces: bool = True,
    ) -> None:
        """Select a row now and schedule its generation-fenced detail load."""
        identity = self._library_media_reader_identity(media_id)
        if identity is None:
            return
        self._capture_library_media_loaded_progress()
        self._library_media_progress_restored_id = None
        canonical_id, backing_id = identity
        current = self._library_media_reader_session
        if (
            not immediate
            and current.selected_id == canonical_id
            and current.pending_request is not None
        ):
            return
        if self._library_media_selection_timer is not None:
            self._library_media_selection_timer.stop()
            self._library_media_selection_timer = None
        self._selected_media_id = canonical_id
        self._library_media_view = "viewer"
        self._library_media_reader_session = begin_selection(
            current,
            canonical_id,
            backing_id,
            title,
            immediate=immediate,
        )
        pending = self._library_media_reader_session.pending_request
        assert pending is not None
        if sync_surfaces:
            try:
                canvas = self.query_one("#library-media-canvas", LibraryMediaCanvas)
            except (NoMatches, QueryError):
                self._sync_library_media_browse_state(None)
            else:
                canvas.apply_reader_state(self._build_library_media_state())
            self._sync_library_media_viewer_or_recompose()
        if immediate:
            self._dispatch_library_media_detail_request(
                pending.generation, pending.requested_id, canonical_id
            )
            return
        self._library_media_selection_timer = self.set_timer(
            SELECTION_SETTLE_SECONDS,
            partial(
                self._dispatch_library_media_detail_request,
                pending.generation,
                pending.requested_id,
                canonical_id,
            ),
        )

    def _request_library_media_facets(self) -> Any | None:
        return self._library_media_browse_controller.request_facets(
            fingerprint=self._library_media_browse_controller.requested_scope.fingerprint
        )

    def _stop_library_media_filter_timer(self) -> None:
        if self._library_media_filter_timer is not None:
            self._library_media_filter_timer.stop()
            self._library_media_filter_timer = None

    def _request_library_media_filter(self, query: str) -> None:
        """Request authoritative search while preserving the unfiltered anchor."""
        query = self._safe_text(query, max_length=200).strip()
        controller = self._library_media_browse_controller
        applied = controller.applied_scope or controller.mutation_refresh_scope
        if query == controller.requested_scope.query:
            return
        self._clear_library_media_selection_for_scope_change()
        if query:
            if not applied.query:
                self._library_media_unfiltered_scope = applied
                self._library_media_unfiltered_selected_id = self._selected_media_id
            self._library_media_filter_select_first = True
            scope = dataclasses.replace(applied, query=query, page=1)
        else:
            self._library_media_filter_restore_id = (
                self._library_media_unfiltered_selected_id
            )
            self._library_media_filter_select_first = False
            scope = self._library_media_unfiltered_scope
        self._request_library_media_browse(
            scope,
            focus_identity="#library-media-filter",
        )

    @on(Input.Changed, "#library-media-filter")
    def handle_library_media_filter_changed(self, event: Input.Changed) -> None:
        """Debounce Media search through the authoritative browse controller."""
        self._stop_library_media_filter_timer()
        self._library_media_filter_timer = self.set_timer(
            SELECTION_SETTLE_SECONDS,
            partial(self._request_library_media_filter, event.value),
        )

    @on(Input.Submitted, "#library-media-filter")
    def handle_library_media_filter_submitted(self, event: Input.Submitted) -> None:
        event.stop()
        self._stop_library_media_filter_timer()
        self._request_library_media_filter(event.value)

    @on(Button.Pressed, "#library-media-filter-clear")
    def handle_library_media_filter_clear(self, event: Button.Pressed) -> None:
        event.stop()
        self._stop_library_media_filter_timer()
        self._request_library_media_filter("")

    def _load_library_media_list_if_needed(self) -> None:
        """Load the exact list after a direct viewer had no applied page."""
        controller = self._library_media_browse_controller
        if controller.applied_result is not None:
            return
        self._request_library_media_browse(
            controller.mutation_refresh_scope,
            focus_identity="#library-media-row-0",
        )
        self._request_library_media_facets()

    def _clear_library_media_selection_for_scope_change(self) -> None:
        """End page-local selection before changing the exact Media scope."""
        changed = (
            self._library_media_select_mode
            or self._library_media_row_selection.count > 0
            or self._library_media_confirming_bulk_delete
        )
        if not changed:
            return
        self._exit_library_media_select_mode(announce_discard=False)
        self._library_media_selection_notice = "Selection cleared."
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(self._library_media_selection_notice)

    def _request_library_media_page(
        self, page: int, *, focus_identity: str | None
    ) -> Any | None:
        """Request one page from the complete last-applied Media scope."""
        self._clear_library_media_selection_for_scope_change()
        return self._request_library_media_browse(
            self._library_media_browse_controller.scope_for_page(page),
            focus_identity=focus_identity,
        )

    def _request_library_media_type(
        self, media_type: str | None, *, focus_identity: str | None
    ) -> Any | None:
        """Request page one after changing only the applied Media type scope."""
        self._clear_library_media_selection_for_scope_change()
        applied = self._library_media_browse_controller.mutation_refresh_scope
        return self._request_library_media_browse(
            dataclasses.replace(applied, media_type=media_type, page=1),
            focus_identity=focus_identity,
        )

    def _retry_library_media_browse(self, *, focus_identity: str | None) -> Any | None:
        """Retry the latest requested Media draft with a fresh generation."""
        return self._library_media_browse_controller.retry(
            focus_identity=focus_identity
        )

    def _library_media_trash_retry_visible(self) -> bool:
        """Return whether the displayed status owns a browse retry target."""
        state = self._library_media_trash_browse_controller.state
        if self._library_media_trash_input_error or state.loading:
            return False
        if state.failed_scope is not None:
            return bool(state.error_copy or state.stale_copy)
        return state.freshness == "stale" and bool(state.stale_copy)

    def _build_library_media_trash_state(self) -> LibraryMediaTrashState:
        """Adapt the controller-owned exact page to the pre-Task-5 canvas."""
        state = self._library_media_trash_browse_controller.state
        applied = state.applied_result
        records: tuple[Mapping[str, Any], ...] | None = state.retained_items
        if applied is None and state.loading:
            records = None
        total = (
            applied.total
            if applied is not None and state.freshness == "fresh"
            else len(state.retained_items)
        )
        error = self._library_media_trash_input_error
        if not error:
            error = state.error_copy or state.stale_copy
            if error and self._library_media_trash_retry_visible():
                error = f"{error.rstrip('.')} · Retry"
                if state.committed_notice:
                    error = f"{state.committed_notice} {error}"
        presentation = build_library_media_trash_state(
            records,
            total=total,
            selected_id=state.selected_id,
            loading=state.loading,
            error=error,
            notice=state.committed_notice,
        )
        if not state.selected_id and presentation.selected_id:
            presentation = dataclasses.replace(
                presentation,
                rows=tuple(
                    dataclasses.replace(row, selected=False)
                    for row in presentation.rows
                ),
                selected_id="",
            )
        return presentation

    def _library_media_trash_canvas_presentation(self) -> dict[str, Any]:
        """Return screen-owned Trash controls without re-deriving page authority."""
        controller = self._library_media_trash_browse_controller
        state = controller.state
        applied = state.applied_result
        applied_scope = applied.scope if applied is not None else MediaTrashScope()
        scope_parts: list[str] = []
        if applied_scope.query:
            scope_parts.append(f"Query: {applied_scope.query}")
        if applied_scope.media_type is not None:
            scope_parts.append(f"Type: {applied_scope.media_type}")

        mutation_in_flight = bool(
            state.mutation_pending or self._library_media_bulk_delete_in_flight
        )
        if state.loading or mutation_in_flight:
            action_disabled_reason = "Trash is refreshing."
        elif state.freshness != "fresh":
            action_disabled_reason = "Refresh Trash before changing this item."
        elif not state.selected_id:
            action_disabled_reason = "Select a Trash item first."
        else:
            action_disabled_reason = ""
        return {
            "pager": controller.pager,
            "types": state.types,
            "query_draft": self._library_media_trash_query_draft,
            "applied_scope_label": " · ".join(scope_parts),
            "applied_type": applied_scope.media_type,
            "type_choices_visible": self._library_media_trash_type_choices_visible,
            "action_disabled_reason": action_disabled_reason,
            "retry_visible": self._library_media_trash_retry_visible(),
            "controls_disabled_reason": (
                "Trash is refreshing." if mutation_in_flight else ""
            ),
            "confirmation_target": state.confirmation_target,
            "commit_pending": state.mutation_pending,
        }

    def _sync_library_media_trash_state(self, focus_identity: str | None) -> None:
        """Publish one current Trash state without remounting another route."""
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view != "trash"
        ):
            return
        state = self._library_media_trash_browse_controller.state
        focus_generation = getattr(self, "_library_notes_focus_intent_generation", 0)
        authority_generation = getattr(
            self,
            "_library_media_trash_focus_authority_generation",
            focus_generation,
        )
        focused = getattr(self, "focused", None)
        focused_id = getattr(focused, "id", None)
        focused_in_trash = bool(
            focused_id
            and any(
                isinstance(ancestor, LibraryMediaTrashCanvas)
                for ancestor in getattr(focused, "ancestors_with_self", ())
            )
        )
        newer_focus_identity = (
            f"#{focused_id}"
            if (
                not state.loading
                and focus_generation != authority_generation
                and focused_in_trash
            )
            else None
        )
        if focus_identity is not None:
            request_key = (state.requested_scope, state.request_origin)
            if (
                state.loading
                or focus_identity != self._library_media_trash_focus_identity
                or request_key
                != getattr(self, "_library_media_trash_focus_request_key", None)
            ):
                self._library_media_trash_focus_authority_generation = focus_generation
                self._library_media_trash_focus_request_key = request_key
            self._library_media_trash_focus_identity = focus_identity
        if self._library_media_trash_retry_visible():
            self._library_media_trash_focus_identity = "#library-media-trash-retry"
        elif (
            not state.loading
            and state.freshness == "fresh"
            and not state.error_copy
            and self._library_media_trash_focus_identity == "#library-media-trash-retry"
        ):
            self._library_media_trash_focus_identity = {
                "entry": "#library-media-trash-row-0",
                "search": "#library-media-trash-search",
                "type": "#library-media-trash-type-filter",
                "previous": "#library-media-trash-previous",
                "next": "#library-media-trash-next",
                "retry": "#library-media-trash-back",
                "mutation": "#library-media-trash-row-0",
            }[state.request_origin]
        if newer_focus_identity is not None:
            # A real Tab/click during the request supersedes its older landing
            # intent. Preserve that semantic control through this recompose and
            # reacquire the newly mounted instance after paint.
            self._library_media_trash_focus_identity = newer_focus_identity
            self._library_media_trash_focus_authority_generation = focus_generation
        # Child teardown may temporarily move focus to a retained pane grip.
        # Mark only that recompose interval as programmatic; the queued
        # callback clears it before yielding through paint, so a real Tab in
        # the request interval still supersedes this semantic intent.
        self._library_notes_restoring_focus = True
        synced = _sync_library_canvas(
            self,
            "media-trash",
            then=self._focus_library_media_trash_intent,
        )
        if not synced:
            # Projection-suppressed and failed targeted syncs do not run the
            # queued callback. Release both one-shot focus guards immediately
            # so the next real Tab/click advances user authority.
            self._library_notes_restoring_focus = False
            self._library_notes_programmatic_focus_target = None

    def _focus_library_media_trash_intent(self) -> None:
        """Validate the mounted target, then defer through one paint cycle."""
        self._library_notes_restoring_focus = False
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view != "trash"
            or self._library_media_trash_focus_authority_generation
            != self._library_notes_focus_intent_generation
        ):
            return
        identity = self._library_media_trash_focus_identity
        generation = self._library_media_trash_focus_authority_generation
        if self._resolve_library_media_trash_focus_target(identity) is None:
            return
        self.call_after_refresh(
            self._focus_library_media_trash_after_paint,
            identity,
            generation,
        )

    def _library_media_trash_focus_selectors(self, identity: str) -> tuple[str, ...]:
        """Return deterministic fallbacks for one semantic Trash identity."""
        selectors = [identity]
        if identity.startswith("#library-media-trash-row-"):
            try:
                page_index = int(identity.rsplit("-", 1)[1])
            except ValueError:
                page_index = 0
            if page_index > 0:
                selectors.append(f"#library-media-trash-row-{page_index - 1}")
            selectors.append("#library-media-trash-back")
        elif identity == "#library-media-trash-next":
            selectors.extend(
                ("#library-media-trash-previous", "#library-media-trash-back")
            )
        elif identity == "#library-media-trash-previous":
            selectors.extend(("#library-media-trash-next", "#library-media-trash-back"))
        elif identity == "#library-media-trash-retry":
            selectors.append("#library-media-trash-back")
        elif identity == "#library-media-trash-type-choices":
            selectors.extend(
                ("#library-media-trash-type-filter", "#library-media-trash-back")
            )
        else:
            selectors.append("#library-media-trash-back")
        return tuple(dict.fromkeys(selectors))

    def _resolve_library_media_trash_focus_target(self, identity: str) -> Widget | None:
        """Reacquire the first current, enabled control for an identity."""
        for selector in self._library_media_trash_focus_selectors(identity):
            try:
                target = self.query_one(selector, Widget)
            except (NoMatches, QueryError):
                continue
            if not getattr(target, "disabled", False) and target.can_focus:
                return target
        return None

    def _focus_library_media_trash_after_paint(
        self, identity: str, generation: int
    ) -> None:
        """Reacquire immediately before focusing after compositor paint."""
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
            or self._library_media_view != "trash"
            or identity != self._library_media_trash_focus_identity
            or generation != self._library_media_trash_focus_authority_generation
            or generation != self._library_notes_focus_intent_generation
        ):
            return
        target = self._resolve_library_media_trash_focus_target(identity)
        if target is None:
            return
        self._library_notes_programmatic_focus_target = target
        target.focus()

    def _build_library_notes_state(self) -> LibraryNotesListState:
        """Build the notes canvas's list-view display state from local records."""
        source_records = (
            self._library_notes_filter_records
            if self._library_notes_filter_records is not None
            else self._local_source_records.get("notes", ())
        )
        operation = self._library_notes_operation_for_active_region()
        state = build_library_notes_list_state(
            sort_notes_records(source_records, self._library_notes_sort),
            filter_note=self._library_notes_filter,
            total_count=self._local_source_counts.get("notes"),
            select_mode=self._library_notes_select_mode,
            selected_ids=self._library_notes_row_selection.ids,
            sort_choices_visible=self._library_notes_sort_choices_visible,
            operation_status=(
                operation.status_line
                if operation is not None
                else self._library_notes_notice
            ),
            operation_running=(
                bool(operation and operation.running)
                or self._library_notes_mutation_fenced()
            ),
            delete_receipt=self._library_note_delete_receipt,
        )
        if self._library_notes_select_mode:
            projection = self._build_library_notes_tree_projection()
            if projection is None:
                visible_note_ids = (row.note_id for row in state.rows)
            else:
                visible_note_ids = (
                    row.note_id
                    for row in projection.rows
                    if row.kind == "note" and row.note_id
                )
            self._library_notes_row_selection.reconcile(visible_note_ids)
        return state

    def _build_library_notes_tree_projection(
        self,
    ) -> LibraryNotesTreeProjection | None:
        """Build either the independent filter window or browse branches."""
        filter_state = getattr(self, "_library_notes_tree_filter_state", None)
        if getattr(self, "_library_notes_filter", "").strip() and filter_state:
            projection = build_filtered_library_notes_tree(filter_state)
        else:
            branches = getattr(self, "_library_notes_tree_branches", {})
            projection = (
                build_paged_library_notes_tree(
                    branch_states=branches,
                    expanded_folder_ids=getattr(
                        self, "_library_notes_tree_expanded_ids", set()
                    ),
                    protected_folder_ids=getattr(
                        self, "_library_notes_tree_protected_folder_ids", frozenset()
                    ),
                    inactive_managed_folder_ids=getattr(
                        self,
                        "_library_notes_tree_inactive_managed_folder_ids",
                        frozenset(),
                    ),
                )
                if branches
                else None
            )
        status = getattr(self, "_library_notes_navigation_status", "")
        if not status:
            return projection
        status_row = LibraryNotesTreeRow(
            placement_id="status:notes-navigation",
            kind="pager",
            label=status,
            depth=0,
            focus_id="library-notes-navigation-status",
            loading=True,
            disabled=True,
        )
        return LibraryNotesTreeProjection(
            rows=(status_row, *(projection.rows if projection is not None else ()))
        )

    def _begin_library_notes_tree_visit(self) -> None:
        """Seed a fresh mounted visit without carrying page runtime state."""
        LibraryScreen._supersede_library_notes_navigation(self)
        self._library_notes_tree_topology_epoch = (
            getattr(self, "_library_notes_tree_topology_epoch", 0) + 1
        )
        self._library_notes_tree_branches = {}
        self._library_notes_tree_request_generations = {}
        self._library_notes_tree_navigation_requests = {}
        self._library_notes_tree_target_offsets = {}
        self._library_notes_tree_status_by_slice = {}
        self._library_notes_tree_status_revision = 0
        self._library_notes_tree_protected_folder_ids = frozenset()
        self._library_notes_tree_inactive_managed_folder_ids = frozenset()
        self._library_notes_filter_browse_receipt = None

    def _request_library_notes_tree_initial_load(self) -> None:
        """Start one fresh visit by requesting only the two root slices."""
        LibraryScreen._begin_library_notes_tree_visit(self)
        for kind in ("folders", "placements"):
            LibraryScreen._request_library_notes_tree_slice(
                self, NotesBranchKey(None, kind)
            )

    def _sync_library_notes_tree_canvas_if_present(
        self,
        *,
        then: Callable[[], bool | None] | None = None,
        notes_focus_identity: LibraryNotesFocusIdentity | None = None,
        deferred_guard: Callable[[], bool] | None = None,
    ) -> None:
        """Patch a mounted Notes canvas without tearing down a transitioning shell."""
        if not self.is_mounted or not hasattr(self, "query_one"):
            return
        try:
            self.query_one("#library-notes-canvas", LibraryNotesCanvas)
        except (NoMatches, QueryError):
            return
        _sync_library_canvas(
            self,
            "notes",
            then=then,
            notes_focus_identity=notes_focus_identity,
            deferred_guard=deferred_guard,
        )

    def _library_notes_tree_deferred_authority_is_current(
        self,
        key: NotesBranchKey,
        *,
        request_generation: int,
        topology_epoch: int,
        lifecycle_generation: int,
        focus_generation: int | None = None,
    ) -> bool:
        """Validate one deferred pager handoff against every captured owner."""
        state = self._library_notes_tree_branches.get(key)
        return bool(
            lifecycle_generation == self._library_notes_tree_lifecycle_generation
            and topology_epoch == self._library_notes_tree_topology_epoch
            and state is not None
            and state.generation == request_generation
            and self._library_notes_tree_request_generations.get(key)
            == request_generation
            and (
                focus_generation is None
                or focus_generation == self._library_notes_focus_intent_generation
            )
        )

    def _library_notes_navigation_authority_is_current(
        self,
        navigation_generation: int | None,
        *,
        topology_epoch: int,
        lifecycle_generation: int,
    ) -> bool:
        """Validate an optional route authority without coupling ordinary paging."""
        return bool(
            topology_epoch == self._library_notes_tree_topology_epoch
            and lifecycle_generation == self._library_notes_tree_lifecycle_generation
            and (
                navigation_generation is None
                or navigation_generation
                == getattr(self, "_library_notes_navigation_generation", 0)
            )
        )

    def _begin_library_notes_tree_slice_request(
        self,
        key: NotesBranchKey,
        *,
        direction: NotesLoadDirection,
        offset: int,
        recovering: bool = False,
        navigation_generation: int | None = None,
    ) -> tuple[int, int, int, tuple[str, ...]]:
        """Begin one reducer-owned request and capture all async authorities."""
        branches = self._library_notes_tree_branches
        topology_epoch = self._library_notes_tree_topology_epoch
        current = branches.get(key) or empty_notes_slice(
            key, topology_epoch=topology_epoch
        )
        generations = self._library_notes_tree_request_generations
        generation = generations.get(key, current.generation) + 1
        generations[key] = generation
        prior_ids = current.item_ids
        branches[key] = begin_notes_slice_load(
            current,
            generation=generation,
            direction=direction,
            requested_offset=offset,
            requested_limit=LIBRARY_NOTES_TREE_PAGE_SIZE,
            recovering=recovering,
        )
        navigation_requests = getattr(
            self, "_library_notes_tree_navigation_requests", None
        )
        if navigation_requests is None:
            navigation_requests = {}
            self._library_notes_tree_navigation_requests = navigation_requests
        if navigation_generation is not None:
            navigation_requests[key] = navigation_generation
        else:
            navigation_requests.pop(key, None)
        return (
            generation,
            topology_epoch,
            self._library_notes_tree_lifecycle_generation,
            prior_ids,
        )

    def _request_library_notes_tree_slice(
        self,
        key: NotesBranchKey,
        *,
        direction: NotesLoadDirection = "replace",
        offset: int = 0,
        pager_focus_id: str | None = None,
        recovering: bool = False,
        navigation_generation: int | None = None,
    ) -> Any:
        """Schedule one semantic slice without cancelling any sibling slice."""
        if direction == "target":
            self._library_notes_tree_target_offsets[key] = offset
        elif not recovering:
            self._library_notes_tree_target_offsets.pop(key, None)
        authority = LibraryScreen._begin_library_notes_tree_slice_request(
            self,
            key,
            direction=direction,
            offset=offset,
            recovering=recovering,
            navigation_generation=navigation_generation,
        )
        pager_owned = bool(
            pager_focus_id
            and LibraryScreen._library_notes_tree_pager_still_focused(
                self, pager_focus_id
            )
        )
        if pager_owned:
            focus_identity = self._capture_library_notes_focus_identity()
            focus_generation = self._library_notes_focus_intent_generation
            guard = partial(
                LibraryScreen._library_notes_tree_deferred_authority_is_current,
                self,
                key,
                request_generation=authority[0],
                topology_epoch=authority[1],
                lifecycle_generation=authority[2],
                focus_generation=focus_generation,
            )
            self._sync_library_notes_tree_canvas_if_present(
                then=guard,
                notes_focus_identity=focus_identity,
                deferred_guard=guard,
            )
        else:
            self._sync_library_notes_tree_canvas_if_present()
        return self.run_worker(
            LibraryScreen._run_library_notes_tree_slice_request(
                self,
                key,
                direction=direction,
                offset=offset,
                pager_focus_id=pager_focus_id,
                request_generation=authority[0],
                topology_epoch=authority[1],
                lifecycle_generation=authority[2],
                prior_item_ids=authority[3],
                navigation_generation=navigation_generation,
            ),
            exclusive=True,
            group=f"library_notes_tree:{key.pager_id}",
        )

    async def _load_library_notes_tree_slice(
        self,
        key: NotesBranchKey,
        *,
        direction: NotesLoadDirection,
        offset: int,
        pager_focus_id: str | None = None,
        recovering: bool = False,
        navigation_generation: int | None = None,
        mutation_operation: str | None = None,
    ) -> None:
        """Directly load one slice; used by orchestration tests and recovery."""
        if direction == "target":
            self._library_notes_tree_target_offsets[key] = offset
        elif not recovering:
            self._library_notes_tree_target_offsets.pop(key, None)
        authority = LibraryScreen._begin_library_notes_tree_slice_request(
            self,
            key,
            direction=direction,
            offset=offset,
            recovering=recovering,
            navigation_generation=navigation_generation,
        )
        await LibraryScreen._run_library_notes_tree_slice_request(
            self,
            key,
            direction=direction,
            offset=offset,
            pager_focus_id=pager_focus_id,
            request_generation=authority[0],
            topology_epoch=authority[1],
            lifecycle_generation=authority[2],
            prior_item_ids=authority[3],
            navigation_generation=navigation_generation,
            mutation_operation=mutation_operation,
        )

    async def _run_library_notes_tree_slice_request(
        self,
        key: NotesBranchKey,
        *,
        direction: NotesLoadDirection,
        offset: int,
        pager_focus_id: str | None,
        request_generation: int,
        topology_epoch: int,
        lifecycle_generation: int,
        prior_item_ids: tuple[str, ...],
        navigation_generation: int | None = None,
        mutation_operation: str | None = None,
    ) -> None:
        """Call only the exact Task 4 service seam for one slice."""
        service = getattr(self.app_instance, "notes_scope_service", None)
        method = getattr(
            service,
            "page_note_folder_children"
            if key.slice_kind == "folders"
            else "page_note_placements",
            None,
        )
        try:
            if not callable(method):
                raise RuntimeError("Folder navigation is unavailable.")
            incoming = await method(
                scope="local_note",
                parent_id=key.parent_id,
                limit=LIBRARY_NOTES_TREE_PAGE_SIZE,
                offset=offset,
                user_id=self._library_notes_user_id(),
            )
        except Exception as exc:  # noqa: BLE001 - normalized service boundary
            event = (
                "library_notes_tree_mutation_refresh_failed"
                if mutation_operation is not None
                else "library_notes_tree_page_failed"
            )
            metadata: dict[str, object] = {
                "event": event,
                "operation": (
                    "mutation_refresh" if mutation_operation is not None else "page"
                ),
                "content_kind": key.slice_kind,
                "direction": direction,
                "is_root": key.parent_id is None,
                "slice_generation": request_generation,
                "navigation_generation": navigation_generation,
                "topology_epoch": topology_epoch,
                "lifecycle_generation": lifecycle_generation,
                "exception_class": type(exc).__name__,
            }
            if mutation_operation is not None:
                metadata["mutation_operation"] = mutation_operation
            logger.bind(**metadata).warning(event)
            LibraryScreen._fail_library_notes_tree_slice(
                self,
                key,
                request_generation=request_generation,
                topology_epoch=topology_epoch,
                lifecycle_generation=lifecycle_generation,
                pager_focus_id=pager_focus_id,
                error="Could not load this branch.",
                navigation_generation=navigation_generation,
            )
            return
        await LibraryScreen._apply_library_notes_tree_slice_page(
            self,
            key,
            incoming,
            direction=direction,
            request_generation=request_generation,
            topology_epoch=topology_epoch,
            lifecycle_generation=lifecycle_generation,
            pager_focus_id=pager_focus_id,
            prior_item_ids=prior_item_ids,
            navigation_generation=navigation_generation,
        )

    def _fail_library_notes_tree_slice(
        self,
        key: NotesBranchKey,
        *,
        request_generation: int,
        topology_epoch: int,
        lifecycle_generation: int,
        pager_focus_id: str | None,
        error: str,
        navigation_generation: int | None = None,
    ) -> None:
        """Apply one local failure only while every captured authority survives."""
        if not LibraryScreen._library_notes_navigation_authority_is_current(
            self,
            navigation_generation,
            topology_epoch=topology_epoch,
            lifecycle_generation=lifecycle_generation,
        ):
            return
        current = self._library_notes_tree_branches.get(key)
        if current is None:
            return
        result = fail_notes_slice_load(
            current,
            request_generation=request_generation,
            topology_epoch=topology_epoch,
            error=error,
        )
        if result.kind == "ignored":
            return
        pager_owned = bool(
            pager_focus_id
            and LibraryScreen._library_notes_tree_pager_still_focused(
                self, pager_focus_id
            )
        )
        focus_identity = (
            self._capture_library_notes_focus_identity() if pager_owned else None
        )
        focus_generation = (
            self._library_notes_focus_intent_generation if pager_owned else None
        )
        self._library_notes_tree_branches[key] = result.state
        if navigation_generation is not None:
            self._library_notes_tree_navigation_requests.pop(key, None)
        if focus_identity is None:
            self._sync_library_notes_tree_canvas_if_present()
            return
        guard = partial(
            LibraryScreen._library_notes_tree_deferred_authority_is_current,
            self,
            key,
            request_generation=request_generation,
            topology_epoch=topology_epoch,
            lifecycle_generation=lifecycle_generation,
            focus_generation=focus_generation,
        )
        self._sync_library_notes_tree_canvas_if_present(
            then=guard,
            notes_focus_identity=focus_identity,
            deferred_guard=guard,
        )

    async def _apply_library_notes_tree_slice_page(
        self,
        key: NotesBranchKey,
        incoming: Any,
        *,
        direction: NotesLoadDirection,
        request_generation: int,
        topology_epoch: int,
        lifecycle_generation: int,
        pager_focus_id: str | None,
        prior_item_ids: tuple[str, ...],
        navigation_generation: int | None = None,
    ) -> None:
        """Fence and reduce one response, including the reducer's sole recovery."""
        if not LibraryScreen._library_notes_navigation_authority_is_current(
            self,
            navigation_generation,
            topology_epoch=topology_epoch,
            lifecycle_generation=lifecycle_generation,
        ):
            return
        current = self._library_notes_tree_branches.get(key)
        if current is None:
            return
        requested_offset = current.requested_offset
        requested_limit = current.requested_limit or LIBRARY_NOTES_TREE_PAGE_SIZE
        result = apply_notes_slice_page(
            current,
            incoming,
            direction=direction,
            request_generation=request_generation,
            topology_epoch=topology_epoch,
        )
        if result.kind == "ignored":
            return
        self._library_notes_tree_branches[key] = result.state
        if result.kind == "drift" and result.recovery is not None:
            recovery_direction: NotesLoadDirection = (
                "target" if result.recovery == "reset_target" else "replace"
            )
            recovery_offset = (
                requested_offset if result.recovery == "reset_target" else 0
            )
            if recovery_offset is None:
                recovery_offset = self._library_notes_tree_target_offsets.get(key, 0)
            if result.recovery == "reset_target":
                total = getattr(incoming, "total_folders", None)
                if total is None:
                    total = getattr(incoming, "total_placements", None)
                if type(total) is int and total >= 0:
                    last_offset = max(0, total - 1) // requested_limit * requested_limit
                    recovery_offset = min(recovery_offset, last_offset)
            await LibraryScreen._load_library_notes_tree_slice(
                self,
                key,
                direction=recovery_direction,
                offset=recovery_offset,
                pager_focus_id=pager_focus_id,
                recovering=True,
                navigation_generation=navigation_generation,
            )
            return
        if result.kind == "applied":
            LibraryScreen._update_library_notes_tree_protection(
                self,
                key,
                incoming,
                state=result.state,
                direction=direction,
            )
            if direction == "target":
                self._library_notes_tree_target_offsets.pop(key, None)
        if navigation_generation is not None:
            self._library_notes_tree_navigation_requests.pop(key, None)
        pager_owned_focus = bool(
            pager_focus_id
            and LibraryScreen._library_notes_tree_pager_still_focused(
                self, pager_focus_id
            )
        )
        if not pager_owned_focus:
            self._sync_library_notes_tree_canvas_if_present()
            return
        focus_identity = self._capture_library_notes_focus_identity()
        focus_generation = self._library_notes_focus_intent_generation
        guard = partial(
            LibraryScreen._library_notes_tree_deferred_authority_is_current,
            self,
            key,
            request_generation=request_generation,
            topology_epoch=topology_epoch,
            lifecycle_generation=lifecycle_generation,
            focus_generation=focus_generation,
        )
        if result.kind == "applied":
            callback: Callable[[], bool | None] = partial(
                LibraryScreen._focus_library_notes_tree_after_page,
                self,
                key,
                pager_focus_id=pager_focus_id,
                prior_item_ids=prior_item_ids,
                request_generation=request_generation,
                topology_epoch=topology_epoch,
                lifecycle_generation=lifecycle_generation,
                focus_generation=focus_generation,
            )
        else:
            callback = guard
        self._sync_library_notes_tree_canvas_if_present(
            then=callback,
            notes_focus_identity=focus_identity,
            deferred_guard=guard,
        )

    def _update_library_notes_tree_protection(
        self,
        key: NotesBranchKey,
        incoming: Any,
        *,
        state: NotesBranchSliceState,
        direction: NotesLoadDirection,
    ) -> None:
        """Replace one slice's authoritative managed-folder status snapshot."""
        self._library_notes_tree_status_revision += 1
        revision = self._library_notes_tree_status_revision
        incoming_statuses = {
            status.folder_id: (revision, status.state)
            for status in getattr(incoming, "folder_statuses", ())
        }
        snapshots = self._library_notes_tree_status_by_slice
        if key.slice_kind == "placements" or direction in ("replace", "target"):
            snapshots[key] = incoming_statuses
        else:
            merged = dict(snapshots.get(key, {}))
            merged.update(incoming_statuses)
            loaded_folder_ids = {
                item.folder_id for item in state.items if isinstance(item, NoteFolder)
            }
            snapshots[key] = {
                folder_id: value
                for folder_id, value in merged.items()
                if folder_id in loaded_folder_ids
            }
        current: dict[str, tuple[int, str]] = {}
        for snapshot in snapshots.values():
            for folder_id, value in snapshot.items():
                if folder_id not in current or value[0] > current[folder_id][0]:
                    current[folder_id] = value
        self._library_notes_tree_protected_folder_ids = frozenset(
            folder_id for folder_id, (_, value) in current.items() if value != "normal"
        )
        self._library_notes_tree_inactive_managed_folder_ids = frozenset(
            folder_id
            for folder_id, (_, value) in current.items()
            if value == "inactive_managed"
        )

    @staticmethod
    def _library_notes_tree_pager_still_focused(self, pager_focus_id: str) -> bool:
        focused = getattr(self, "focused", None)
        return bool(focused is not None and focused.id == pager_focus_id)

    def _focus_library_notes_tree_after_page(
        self,
        key: NotesBranchKey,
        *,
        pager_focus_id: str,
        prior_item_ids: tuple[str, ...],
        request_generation: int,
        topology_epoch: int,
        lifecycle_generation: int,
        focus_generation: int,
    ) -> bool:
        """Move from an owned pager to its first added row or parent fallback."""
        if not LibraryScreen._library_notes_tree_deferred_authority_is_current(
            self,
            key,
            request_generation=request_generation,
            topology_epoch=topology_epoch,
            lifecycle_generation=lifecycle_generation,
            focus_generation=focus_generation,
        ):
            return False
        state = self._library_notes_tree_branches.get(key)
        if state is None:
            return False
        added = next(
            (item_id for item_id in state.item_ids if item_id not in prior_item_ids),
            None,
        )
        for button in self.query(".library-notes-folder-row, .library-notes-row"):
            if added is not None and getattr(button, "placement_id", None) == added:
                button.focus()
                return False
        projection = LibraryScreen._build_library_notes_tree_projection(self)
        if projection is not None and any(
            row.kind == "pager" and row.focus_id == pager_focus_id
            for row in projection.rows
        ):
            return True
        if key.parent_id is None:
            return True
        for button in self.query(".library-notes-folder-row"):
            if getattr(button, "folder_id", None) == key.parent_id:
                button.focus()
                return False
        return True

    async def _ensure_library_notes_tree_folder_loaded(self, folder_id: str) -> None:
        """Load the two missing slices for one expansion, retaining fresh slices."""
        for kind in ("folders", "placements"):
            key = NotesBranchKey(folder_id, kind)
            state = self._library_notes_tree_branches.get(key)
            if state is None or state.freshness == "uninitialized":
                await LibraryScreen._load_library_notes_tree_slice(
                    self, key, direction="replace", offset=0
                )

    async def _locate_library_notes_tree_target(
        self,
        *,
        note_id: str = "",
        folder_id: str = "",
        preferred_folder_id: str | None = None,
        preferred_membership_id: str | None = None,
        focus: bool = True,
        focus_scroll_offset: tuple[int, int] | None = None,
        navigation_generation: int | None = None,
        restore_guard: _LibraryNotesRestoreGuard | None = None,
    ) -> bool:
        """Resolve and load one exact folder or duplicate-safe note placement."""
        if navigation_generation is None:
            navigation_generation = (
                getattr(self, "_library_notes_navigation_generation", 0) + 1
            )
            self._library_notes_navigation_generation = navigation_generation
        topology_epoch = self._library_notes_tree_topology_epoch
        lifecycle_generation = self._library_notes_tree_lifecycle_generation
        focus_generation = getattr(self, "_library_notes_focus_intent_generation", 0)
        self._library_notes_navigation_status = (
            "Locating note…" if note_id else "Locating folder…"
        )
        LibraryScreen._sync_library_notes_tree_canvas_if_present(self)

        def current() -> bool:
            return bool(
                navigation_generation
                == getattr(self, "_library_notes_navigation_generation", 0)
                and topology_epoch == self._library_notes_tree_topology_epoch
                and lifecycle_generation
                == self._library_notes_tree_lifecycle_generation
                and focus_generation
                == getattr(self, "_library_notes_focus_intent_generation", 0)
                and LibraryScreen._library_notes_restore_guard_is_current(
                    self, restore_guard
                )
            )

        service = getattr(self.app_instance, "notes_scope_service", None)
        method = getattr(
            service,
            "locate_note_tree_placement" if note_id else "locate_note_tree_folder",
            None,
        )
        try:
            if not callable(method):
                raise RuntimeError("Notes locator unavailable")
            common = {
                "scope": "local_note",
                "page_size": LIBRARY_NOTES_TREE_PAGE_SIZE,
                "user_id": self._library_notes_user_id(),
            }
            if note_id:
                location = await method(
                    **common,
                    note_id=note_id,
                    preferred_folder_id=preferred_folder_id,
                    preferred_membership_id=preferred_membership_id,
                )
            else:
                location = await method(**common, folder_id=folder_id)
        except Exception as exc:  # noqa: BLE001 - normalized locator boundary
            event = "library_notes_tree_locator_failed"
            logger.bind(
                event=event,
                operation="locator",
                locator_kind="placement" if note_id else "folder",
                target_kind="note" if note_id else "folder",
                navigation_generation=navigation_generation,
                topology_epoch=topology_epoch,
                lifecycle_generation=lifecycle_generation,
                exception_class=type(exc).__name__,
            ).warning(event)
            if current():
                self._library_notes_navigation_status = ""
                LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
            return False
        if not current():
            return False
        if location is None:
            self._library_notes_navigation_status = ""
            projection = LibraryScreen._build_library_notes_tree_projection(self)
            fallback = (
                next(
                    (row for row in projection.rows if row.kind in ("note", "folder")),
                    None,
                )
                if projection is not None
                else None
            )
            self._library_notes_tree_selected_placement_id = (
                fallback.placement_id if fallback is not None else ""
            )
            LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
            return False

        located_folder_ids: list[str] = []
        for step in location.path:
            key = NotesBranchKey(step.parent_id, "folders")
            folder_state = self._library_notes_tree_branches.get(key)
            placement_id = FolderPlacementId.folder(step.folder_id)
            if not (
                folder_state is not None
                and folder_state.freshness == "fresh"
                and not folder_state.loading
                and not folder_state.error
                and folder_state.topology_epoch == topology_epoch
                and placement_id in folder_state.item_ids
            ):
                await LibraryScreen._load_library_notes_tree_slice(
                    self,
                    key,
                    direction="target",
                    offset=step.containing_offset,
                    navigation_generation=navigation_generation,
                )
            if not current():
                return False
            folder_state = self._library_notes_tree_branches.get(key)
            if (
                folder_state is None
                or folder_state.error
                or placement_id not in folder_state.item_ids
            ):
                self._library_notes_navigation_status = ""
                LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
                return False
            located_folder_ids.append(step.folder_id)
        if location.note_id is not None:
            parent_id = location.path[-1].folder_id if location.path else None
            key = NotesBranchKey(parent_id, "placements")
            placement_state = self._library_notes_tree_branches.get(key)
            if not (
                placement_state is not None
                and placement_state.freshness == "fresh"
                and not placement_state.loading
                and not placement_state.error
                and placement_state.topology_epoch == topology_epoch
                and location.placement_id in placement_state.item_ids
            ):
                await LibraryScreen._load_library_notes_tree_slice(
                    self,
                    key,
                    direction="target",
                    offset=location.placement_offset or 0,
                    navigation_generation=navigation_generation,
                )
            if not current():
                return False
            placement_state = self._library_notes_tree_branches.get(key)
            if (
                placement_state is None
                or placement_state.error
                or location.placement_id not in placement_state.item_ids
            ):
                self._library_notes_navigation_status = ""
                LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
                return False

        self._library_notes_tree_expanded_ids.update(located_folder_ids)
        self._library_notes_navigation_status = ""
        self._library_notes_tree_selected_placement_id = location.placement_id
        if not focus:
            LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
            return True
        role = (
            f"note-placement:{location.placement_id}"
            if location.note_id is not None
            else f"folder-placement:{location.placement_id}"
        )
        identity = LibraryNotesFocusIdentity(
            stage="notes",
            region="navigator",
            note_id=location.note_id,
            semantic_role=role,
            scroll_offset=focus_scroll_offset,
        )

        def guard() -> bool:
            return current()

        restore_focus = partial(self._restore_library_notes_focus_identity, identity)
        if restore_guard is not None:
            restore_focus = partial(
                self._restore_library_notes_focus_identity,
                identity,
                restore_guard,
            )
        LibraryScreen._sync_library_notes_tree_canvas_if_present(
            self,
            then=restore_focus,
            notes_focus_identity=identity,
            deferred_guard=guard,
        )
        return True

    def _fence_library_notes_tree_mutation(self) -> int:
        """Fence paging immediately while retaining every last-good visible row."""
        epoch = self._library_notes_tree_topology_epoch + 1
        self._library_notes_tree_topology_epoch = epoch
        updated: dict[NotesBranchKey, NotesBranchSliceState] = {}
        for key, state in self._library_notes_tree_branches.items():
            updated[key] = dataclasses.replace(
                state,
                generation=state.generation + 1,
                topology_epoch=epoch,
                loading=False,
                recovery_attempted=False,
                requested_direction=None,
                requested_offset=None,
                requested_limit=None,
                request_is_recovery=False,
                failed_direction=None,
                error="",
            )
        self._library_notes_tree_branches = updated
        self._library_notes_tree_request_generations = {
            key: state.generation for key, state in updated.items()
        }
        self._library_notes_tree_navigation_requests = {}
        self._library_notes_filter_generation = (
            getattr(self, "_library_notes_filter_generation", 0) + 1
        )
        filter_state = getattr(self, "_library_notes_tree_filter_state", None)
        if filter_state is not None:
            self._library_notes_tree_filter_state = dataclasses.replace(
                filter_state,
                generation=self._library_notes_filter_generation,
                topology_epoch=epoch,
                loading=False,
                requested_direction=None,
                requested_offset=None,
                requested_limit=None,
                request_is_recovery=False,
            )
        self._library_notes_filter_navigation_generation = None
        self._library_notes_navigation_generation = (
            getattr(self, "_library_notes_navigation_generation", 0) + 1
        )
        self._library_notes_navigation_status = ""
        return epoch

    async def _load_library_notes_tree_mutation_context(
        self,
        service: Any,
        *,
        folder_ids: tuple[str, ...] = (),
        note_ids: tuple[str, ...] = (),
        include_folder_subtrees: bool = False,
        mutation_operation: str = "unknown",
        refresh: bool = False,
    ) -> Any | None:
        """Load the exact affected parents without exposing content in logs."""
        method = getattr(service, "load_note_tree_mutation_context", None)
        if not callable(method):
            return None
        try:
            return await method(
                scope="local_note",
                folder_ids=folder_ids,
                note_ids=note_ids,
                include_folder_subtrees=include_folder_subtrees,
                user_id=self._library_notes_user_id(),
            )
        except Exception as exc:  # noqa: BLE001 - normalized context boundary
            event = (
                "library_notes_tree_mutation_refresh_failed"
                if refresh
                else "library_notes_tree_mutation_context_failed"
            )
            logger.bind(
                event=event,
                operation="mutation_refresh" if refresh else "mutation_context",
                mutation_operation=mutation_operation,
                content_kind="mutation_context",
                direction="refresh_context" if refresh else "admission_context",
                is_root=None,
                slice_generation=None,
                navigation_generation=getattr(
                    self, "_library_notes_navigation_generation", None
                ),
                topology_epoch=self._library_notes_tree_topology_epoch,
                lifecycle_generation=self._library_notes_tree_lifecycle_generation,
                exception_class=type(exc).__name__,
            ).warning(event)
            raise

    async def _reconcile_library_notes_tree_mutation(
        self,
        operation: str,
        payload: Mapping[str, Any],
        *,
        before: Any | None,
        result: Any,
        partial: bool = False,
        destination_membership: NoteFolderMembership | None = None,
    ) -> None:
        """Patch committed truth, then reload only exact affected slices."""
        folder = getattr(result, "folder", None)
        if folder is None and isinstance(result, NoteFolder):
            folder = result
        if destination_membership is None and isinstance(result, NoteFolderMembership):
            destination_membership = result

        requested_folder_ids = {
            str(value)
            for value in (
                payload.get("folder_id"),
                payload.get("parent_id"),
                payload.get("source_folder_id"),
                payload.get("destination_folder_id"),
                getattr(folder, "folder_id", None),
            )
            if value
        }
        affected_folder_ids = set(
            str(value) for value in getattr(result, "affected_folder_ids", ()) if value
        )
        requested_folder_ids.update(affected_folder_ids)
        note_id = str(payload.get("note_id") or "")
        source_folder_id = str(
            payload.get("source_folder_id") or payload.get("folder_id") or ""
        )
        destination_folder_id = str(
            payload.get("destination_folder_id")
            or (folder.parent_id if folder is not None else "")
            or ""
        )
        source_placement_id = str(payload.get("source_placement_id") or "")
        source_membership_id = str(payload.get("source_membership_id") or "")
        if not source_placement_id and source_folder_id and source_membership_id:
            source_placement_id = FolderPlacementId.note(
                source_folder_id, note_id, source_membership_id
            )
        if not source_placement_id and operation in {
            "move_placement",
            "detach_placement",
        }:
            selected = self._library_notes_tree_selected_placement_id
            if selected:
                source_state = self._library_notes_tree_branches.get(
                    NotesBranchKey(source_folder_id, "placements")
                )
                if source_state is not None and selected in source_state.item_ids:
                    source_placement_id = selected

        source_folder_snapshot = next(
            (
                item
                for state in self._library_notes_tree_branches.values()
                if state.key.slice_kind == "folders"
                for item in state.items
                if isinstance(item, NoteFolder)
                and item.folder_id
                == str(payload.get("folder_id") or getattr(folder, "folder_id", ""))
            ),
            None,
        )
        try:
            after = await LibraryScreen._load_library_notes_tree_mutation_context(
                self,
                self.app_instance.notes_scope_service,
                folder_ids=tuple(sorted(requested_folder_ids)),
                note_ids=(note_id,) if note_id else (),
                include_folder_subtrees=operation
                in {"rename_folder", "move_folder", "delete_folder", "restore_folder"},
                mutation_operation=operation,
                refresh=True,
            )
        except Exception:
            after = None

        parents: set[str | None] = set()
        placement_parents: set[str | None] = set()
        involved_folders: set[str] = set(requested_folder_ids)
        context_folder_ids: set[str] = set()
        for context in (before, after):
            if context is None:
                continue
            parents.update(getattr(context, "parent_ids", ()))
            placement_parents.update(getattr(context, "placement_parent_ids", ()))
            context_folder_ids.update(getattr(context, "folder_ids", ()))
            involved_folders.update(context_folder_ids)
            involved_folders.update(getattr(context, "ancestor_ids", ()))
        for key in ("parent_id", "source_folder_id", "destination_folder_id"):
            if key in payload:
                parents.add(payload.get(key) or None)
        if folder is not None:
            parents.add(folder.parent_id)
            involved_folders.add(folder.folder_id)
        if operation in {"add_placement", "detach_placement", "move_placement"}:
            placement_parents.update(
                value
                for value in (
                    payload.get("folder_id"),
                    payload.get("source_folder_id"),
                    payload.get("destination_folder_id"),
                )
                if value
            )
        if operation in {
            "add_placement",
            "detach_placement",
            "note_create",
            "note_delete",
            "delete_folder",
            "restore_folder",
        }:
            placement_parents.add(None)

        affected = {NotesBranchKey(parent, "folders") for parent in parents}
        affected.update(
            NotesBranchKey(parent, "placements") for parent in placement_parents
        )
        for folder_id in involved_folders:
            affected.add(NotesBranchKey(folder_id, "folders"))
            affected.add(NotesBranchKey(folder_id, "placements"))

        moved_folder_id = (
            folder.folder_id
            if folder is not None and operation == "move_folder"
            else ""
        )
        if moved_folder_id:
            affected.update(
                key
                for key, state in self._library_notes_tree_branches.items()
                if key.slice_kind == "folders"
                and any(
                    isinstance(item, NoteFolder) and item.folder_id == moved_folder_id
                    for item in state.items
                )
            )
        removed_folder_ids = (
            context_folder_ids.union(
                {str(payload["folder_id"])} if payload.get("folder_id") else set()
            )
            if operation == "delete_folder"
            else set()
        )
        filter_state = getattr(self, "_library_notes_tree_filter_state", None)
        active_filter_query = getattr(self, "_library_notes_filter", "")
        filter_active = bool(
            active_filter_query
            and filter_state is not None
            and filter_state.query == active_filter_query
            and filter_state.topology_epoch == self._library_notes_tree_topology_epoch
        )
        filter_selected_before_commit = (
            self._library_notes_tree_selected_placement_id if filter_active else ""
        )
        delete_fallback = ""
        selected_placement = self._library_notes_tree_selected_placement_id
        if operation == "note_delete" and selected_placement:
            for key, state in self._library_notes_tree_branches.items():
                if (
                    key.slice_kind != "placements"
                    or selected_placement not in state.item_ids
                ):
                    continue
                selected_index = state.item_ids.index(selected_placement)
                surviving_ids = tuple(
                    item_id
                    for item_id, item in zip(state.item_ids, state.items, strict=True)
                    if not isinstance(item, NotePlacementRecord)
                    or str(item.note.get("id", item.note.get("note_id", ""))) != note_id
                )
                next_id = next(
                    (
                        item_id
                        for item_id in state.item_ids[selected_index + 1 :]
                        if item_id in surviving_ids
                    ),
                    "",
                )
                previous_id = next(
                    (
                        item_id
                        for item_id in reversed(state.item_ids[:selected_index])
                        if item_id in surviving_ids
                    ),
                    "",
                )
                delete_fallback = next_id or previous_id
                if not delete_fallback and key.parent_id is not None:
                    delete_fallback = FolderPlacementId.folder(key.parent_id)
                break

        desired_target = ""
        if folder is not None and not folder.deleted:
            desired_target = FolderPlacementId.folder(folder.folder_id)
        elif note_id and operation == "detach_placement":
            desired_target = FolderPlacementId.unfiled(note_id)
        elif note_id and destination_membership is not None:
            desired_target = FolderPlacementId.note(
                destination_membership.folder_id,
                note_id,
                destination_membership.membership_id,
            )
        elif note_id and operation == "note_create":
            desired_target = FolderPlacementId.unfiled(note_id)
        if desired_target:
            self._library_notes_tree_pending_target_placement_id = desired_target

        old_path = source_folder_snapshot.path if source_folder_snapshot else ""
        old_normalized_path = (
            source_folder_snapshot.normalized_path if source_folder_snapshot else ""
        )

        if filter_active:
            assert filter_state is not None
            filter_state = reconcile_library_notes_filter_commit(
                filter_state,
                operation=operation,
                folder=folder,
                affected_folder_ids=frozenset(involved_folders),
                removed_folder_ids=frozenset(removed_folder_ids),
                note_id=note_id,
                source_placement_id=source_placement_id,
                partial=partial,
            )
            self._library_notes_tree_filter_state = filter_state
            self._library_notes_filter_records = [
                dict(placement.note) for placement in filter_state.placements
            ]

        def item_id(item: NoteFolder | NotePlacementRecord) -> str:
            if isinstance(item, NoteFolder):
                return FolderPlacementId.folder(item.folder_id)
            record_note_id = str(item.note.get("id", item.note.get("note_id", "")))
            if item.folder_id is None:
                return FolderPlacementId.unfiled(record_note_id)
            assert item.membership is not None
            return FolderPlacementId.note(
                item.folder_id, record_note_id, item.membership.membership_id
            )

        for key in tuple(affected):
            state = self._library_notes_tree_branches.get(key)
            if state is None:
                continue
            items: tuple[NoteFolder | NotePlacementRecord, ...] = state.items
            patched: list[NoteFolder | NotePlacementRecord] = []
            for item in items:
                if (
                    operation == "delete_folder"
                    and key.slice_kind == "placements"
                    and key.parent_id in removed_folder_ids
                ):
                    continue
                if isinstance(item, NoteFolder):
                    if item.folder_id in removed_folder_ids:
                        continue
                    if folder is not None and item.folder_id == folder.folder_id:
                        if (
                            operation == "move_folder"
                            and key.parent_id != folder.parent_id
                        ):
                            continue
                        item = folder
                    elif (
                        folder is not None
                        and operation in {"rename_folder", "move_folder"}
                        and item.folder_id in involved_folders
                        and old_path
                        and item.path.startswith(f"{old_path}/")
                    ):
                        item = dataclasses.replace(
                            item,
                            path=f"{folder.path}{item.path[len(old_path) :]}",
                            normalized_path=(
                                f"{folder.normalized_path}"
                                f"{item.normalized_path[len(old_normalized_path) :]}"
                            ),
                        )
                elif note_id and operation == "note_delete":
                    if (
                        str(item.note.get("id", item.note.get("note_id", "")))
                        == note_id
                    ):
                        continue
                elif (
                    operation in {"detach_placement", "move_placement"}
                    and not partial
                    and source_placement_id
                    and item_id(item) == source_placement_id
                ):
                    continue
                patched.append(item)
            items = tuple(patched)
            item_ids = tuple(item_id(item) for item in items)
            self._library_notes_tree_branches[key] = dataclasses.replace(
                state,
                items=items,
                item_ids=item_ids,
                total=None,
                previous_offset=None,
                next_offset=None,
                freshness="stale",
                loading=False,
                error="Committed change needs refresh.",
            )

        if operation == "note_delete" and selected_placement:
            surviving_ids = {
                item_id
                for state in self._library_notes_tree_branches.values()
                for item_id in state.item_ids
            }
            if selected_placement not in surviving_ids:
                if not delete_fallback:
                    projection = LibraryScreen._build_library_notes_tree_projection(
                        self
                    )
                    delete_fallback = (
                        next(
                            (
                                row.placement_id
                                for row in projection.rows
                                if row.kind == "note"
                            ),
                            "",
                        )
                        if projection is not None
                        else ""
                    )
                self._library_notes_tree_selected_placement_id = delete_fallback

        if desired_target and operation != "note_delete":
            projection = LibraryScreen._build_library_notes_tree_projection(self)
            if projection is not None and projection.row(desired_target) is not None:
                self._library_notes_tree_selected_placement_id = desired_target
            elif destination_folder_id:
                self._library_notes_tree_selected_placement_id = (
                    FolderPlacementId.folder(destination_folder_id)
                )
            elif folder is not None and folder.parent_id is not None:
                self._library_notes_tree_selected_placement_id = (
                    FolderPlacementId.folder(folder.parent_id)
                )
            elif operation == "detach_placement":
                self._library_notes_tree_selected_placement_id = UNFILED_PLACEMENT_ID

        LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
        for key in sorted(
            affected,
            key=lambda value: (
                value.parent_id is not None,
                value.parent_id or "",
                value.slice_kind,
            ),
        ):
            state = self._library_notes_tree_branches.get(key)
            if state is None:
                continue
            await LibraryScreen._load_library_notes_tree_slice(
                self,
                key,
                direction="target",
                offset=state.start_offset,
                mutation_operation=operation,
            )

        filtered_selection = ""
        if filter_active:
            assert filter_state is not None
            await LibraryScreen._run_library_notes_filter(
                self,
                filter_state.query,
                offset=filter_state.start_offset,
                direction="target",
                navigation_generation=self._library_notes_navigation_generation,
            )
            refreshed_filter = self._library_notes_tree_filter_state
            if refreshed_filter is not None:
                filter_projection = build_filtered_library_notes_tree(refreshed_filter)
                selected = filter_selected_before_commit
                if selected and filter_projection.row(selected) is not None:
                    filtered_selection = selected
                elif (
                    desired_target and filter_projection.row(desired_target) is not None
                ):
                    filtered_selection = desired_target
                    self._library_notes_tree_selected_placement_id = desired_target

        located = False
        if folder is not None and not folder.deleted:
            located = await LibraryScreen._locate_library_notes_tree_target(
                self, folder_id=folder.folder_id, focus=False
            )
        elif note_id and operation != "note_delete":
            located = await LibraryScreen._locate_library_notes_tree_target(
                self,
                note_id=note_id,
                preferred_folder_id=destination_folder_id or None,
                preferred_membership_id=(
                    destination_membership.membership_id
                    if destination_membership is not None
                    else None
                ),
                focus=False,
            )
        if located:
            self._library_notes_tree_pending_target_placement_id = ""
        if filtered_selection:
            self._library_notes_tree_selected_placement_id = filtered_selection

    def _invalidate_library_notes_tree_for_unmount(self) -> None:
        """Synchronously revoke every Notes page authority for this visit."""
        LibraryScreen._supersede_library_notes_navigation(self, render=False)
        self._library_notes_tree_lifecycle_generation += 1
        self._library_notes_tree_topology_epoch += 1
        self._library_notes_tree_branches = {}
        self._library_notes_tree_request_generations = {}
        self._library_notes_tree_navigation_requests = {}
        self._library_notes_tree_target_offsets = {}
        self._library_notes_tree_status_by_slice = {}
        self._library_notes_tree_status_revision = 0
        self._library_notes_tree_filter_state = None
        self._library_notes_filter_records = None
        self._library_notes_filter_navigation_generation = None
        workers = getattr(self, "workers", ())
        for worker in tuple(workers):
            if str(getattr(worker, "group", "")).startswith("library_notes_tree:"):
                worker.cancel()

    async def _execute_library_notes_tree_mutation(
        self,
        operation: str,
        **payload: Any,
    ) -> bool:
        """Run one guarded normalized folder or placement mutation."""
        preclaimed = bool(payload.pop("_preclaimed", False))
        fenced_epoch = payload.pop("_fenced_epoch", None)
        if self._library_note_import_execution_active():
            if preclaimed:
                self._library_notes_mutation_in_flight = False
            return False
        if payload.get("protected"):
            self._library_notes_notice = (
                "This item is managed by sync; change its sync root instead."
            )
            if preclaimed:
                self._library_notes_mutation_in_flight = False
            return False
        if self._library_notes_mutation_in_flight and not preclaimed:
            return False
        service = getattr(self.app_instance, "notes_scope_service", None)
        methods = {
            "create_folder": "create_note_folder",
            "rename_folder": "rename_note_folder",
            "move_folder": "move_note_folder",
            "delete_folder": "delete_note_folder",
            "restore_folder": "restore_note_folder",
            "add_placement": "attach_note_to_folder",
            "detach_placement": "detach_note_from_folder",
        }
        required_methods = (
            ("attach_note_to_folder", "detach_note_from_folder")
            if operation == "move_placement"
            else (methods.get(operation, ""),)
        )
        if not required_methods[0] or any(
            not callable(getattr(service, method_name, None))
            for method_name in required_methods
        ):
            self._library_notes_notice = "That folder action is unavailable."
            if preclaimed:
                self._library_notes_mutation_in_flight = False
            return False

        if fenced_epoch is None:
            fenced_epoch = LibraryScreen._fence_library_notes_tree_mutation(self)
        folder_ids = tuple(
            sorted(
                {
                    str(value)
                    for value in (
                        payload.get("folder_id"),
                        payload.get("parent_id"),
                        payload.get("source_folder_id"),
                        payload.get("destination_folder_id"),
                    )
                    if value
                }
            )
        )
        note_id_for_context = str(payload.get("note_id") or "")
        try:
            mutation_context = (
                await LibraryScreen._load_library_notes_tree_mutation_context(
                    self,
                    service,
                    folder_ids=folder_ids,
                    note_ids=(note_id_for_context,) if note_id_for_context else (),
                    include_folder_subtrees=operation
                    in {
                        "rename_folder",
                        "move_folder",
                        "delete_folder",
                        "restore_folder",
                    },
                    mutation_operation=operation,
                )
            )
        except Exception:
            self._library_notes_notice = (
                "Could not verify affected folders — no changes were made."
            )
            if preclaimed:
                self._library_notes_mutation_in_flight = False
            LibraryScreen._sync_library_notes_tree_canvas_if_present(self)
            return False

        common = {
            "scope": "local_note",
            "user_id": self._library_notes_user_id(),
        }
        self._library_notes_mutation_in_flight = True
        try:
            result: Any = None
            destination_membership: NoteFolderMembership | None = None
            if operation == "move_placement":
                note_id = str(payload["note_id"])
                destination_id = str(payload["destination_folder_id"])
                source_id = str(payload.get("source_folder_id") or "")
                destination_membership = await service.attach_note_to_folder(
                    **common,
                    folder_id=destination_id,
                    note_id=note_id,
                )
                if not destination_membership:
                    self._library_notes_notice = (
                        "The note was not added; no folder changes were made."
                    )
                    return False
                if source_id and source_id != destination_id:
                    try:
                        result = await service.detach_note_from_folder(
                            **common,
                            folder_id=source_id,
                            note_id=note_id,
                            expected_version=int(payload["membership_version"]),
                        )
                    except Exception as exc:  # noqa: BLE001 - preserve placements
                        logger.warning(
                            "Database Notes move kept both placements after "
                            "the source detach failed; error_type={}",
                            type(exc).__name__,
                        )
                        self._library_notes_notice = (
                            "Note added to the new folder, but the original "
                            "changed; it remains safely in both folders."
                        )
                        await LibraryScreen._reconcile_library_notes_tree_mutation(
                            self,
                            operation,
                            payload,
                            before=mutation_context,
                            result=True,
                            partial=True,
                            destination_membership=destination_membership,
                        )
                        return True
                    if not result:
                        self._library_notes_notice = (
                            "Note added to the new folder, but the original "
                            "remains safely in both folders."
                        )
                        await LibraryScreen._reconcile_library_notes_tree_mutation(
                            self,
                            operation,
                            payload,
                            before=mutation_context,
                            result=True,
                            partial=True,
                            destination_membership=destination_membership,
                        )
                        return True
                else:
                    result = True
            else:
                method = getattr(service, methods[operation])
                kwargs = {
                    key: value for key, value in payload.items() if key != "protected"
                }
                result = await method(**common, **kwargs)

            if not result:
                self._library_notes_notice = (
                    "No folder changes were made; the current view is unchanged."
                )
                return False

            if operation == "delete_folder":
                folder = result.folder
                self._library_notes_deleted_folder_receipt = (
                    _LibraryNotesDeletedFolderReceipt(
                        folder_id=folder.folder_id,
                        name=folder.name,
                        expected_version=folder.version,
                    )
                )
                self._library_notes_tree_selected_placement_id = ""
            elif operation == "restore_folder":
                self._library_notes_deleted_folder_receipt = None
                folder = result.folder
                self._library_notes_tree_selected_placement_id = (
                    FolderPlacementId.folder(folder.folder_id)
                )
            elif operation == "create_folder":
                self._library_notes_tree_selected_placement_id = (
                    FolderPlacementId.folder(result.folder_id)
                )
            self._library_notes_notice = "Folder organization updated."
            await LibraryScreen._reconcile_library_notes_tree_mutation(
                self,
                operation,
                payload,
                before=mutation_context,
                result=result,
                destination_membership=destination_membership,
            )
            return True
        except FolderCollisionError:
            self._library_notes_notice = (
                "A folder with that name already exists in this location."
            )
            return False
        except FolderConflictError:
            self._library_notes_notice = (
                "That folder changed elsewhere — refresh and try again."
            )
            return False
        except FolderValidationError:
            self._library_notes_notice = "That folder name or destination is not valid."
            return False
        except FolderCapabilityError as exc:
            self._library_notes_notice = exc.user_message
            return False
        except PolicyDeniedError as exc:
            self._library_notes_notice = exc.user_message
            return False
        except Exception as exc:  # noqa: BLE001 - render a safe mutation failure
            logger.warning(
                "Database Notes tree mutation {!r} failed; error_type={}",
                operation,
                type(exc).__name__,
            )
            self._library_notes_notice = (
                "Could not update folder organization — refresh and try again."
            )
            return False
        finally:
            self._library_notes_mutation_in_flight = False
            LibraryScreen._sync_library_notes_tree_canvas_if_present(self)

    def _schedule_library_notes_tree_mutation(
        self, operation: str, **payload: Any
    ) -> None:
        """Synchronously claim the mutation interlock before starting a worker."""
        if self._library_notes_mutation_fenced():
            return
        self._library_notes_mutation_in_flight = True
        fenced_epoch = LibraryScreen._fence_library_notes_tree_mutation(self)
        self.run_worker(
            self._execute_library_notes_tree_mutation(
                operation,
                _preclaimed=True,
                _fenced_epoch=fenced_epoch,
                **payload,
            ),
            exclusive=True,
            group="library_note_mutation",
        )
        if self.is_mounted:
            _sync_library_canvas(self, "notes")

    def _selected_library_notes_tree_row(self):
        """Return the selected visible placement, if it still survives."""
        projection = self._build_library_notes_tree_projection()
        if projection is None:
            return None
        return projection.row(self._library_notes_tree_selected_placement_id)

    def _library_notes_folder_target_options(
        self, *, exclude_folder_id: str | None = None
    ) -> tuple[tuple[str, str], ...]:
        """Return bounded loaded folder choices, excluding a moved subtree."""
        folders = {
            folder.folder_id: folder
            for state in self._library_notes_tree_branches.values()
            if state.key.slice_kind == "folders"
            for folder in state.items
            if isinstance(folder, NoteFolder)
        }
        excluded_path = (
            folders[exclude_folder_id].normalized_path
            if exclude_folder_id in folders
            else ""
        )
        choices = [
            (folder.path.strip("/").replace("/", " / "), folder.folder_id)
            for folder in folders.values()
            if folder.folder_id != exclude_folder_id
            and not (
                excluded_path and folder.normalized_path.startswith(f"{excluded_path}/")
            )
        ]
        return tuple(sorted(choices, key=lambda item: (item[0].casefold(), item[1])))

    def _remove_library_note_source_record(self, note_id: str) -> None:
        """Patch one successful delete into the cached Notes rows and count."""
        target_id = str(note_id)
        records = self._local_source_records.get("notes", ())
        self._local_source_records["notes"] = tuple(
            record for record in records if self._source_record_id(record) != target_id
        )
        self._local_source_counts["notes"] = max(
            self._local_source_counts.get("notes", 0) - 1,
            0,
        )

    def _append_library_note_source_record(self, record: Mapping[str, Any]) -> bool:
        """Append one newly active note and increment the exact rail count."""
        note_id = self._source_record_id(record)
        if not note_id:
            return False
        records = self._local_source_records.get("notes", ())
        if any(self._source_record_id(item) == note_id for item in records):
            return False
        self._local_source_records["notes"] = records + (dict(record),)
        self._local_source_counts["notes"] = (
            self._local_source_counts.get("notes", 0) + 1
        )
        return True

    def _library_notes_canvas_kwargs(self) -> dict[str, Any]:
        """Return every compose input for the mounted Database Notes canvas."""
        values: dict[str, Any] = {
            "list_state": None,
            "sort_mode": self._library_notes_sort,
            "filter_value": self._library_notes_filter,
            "mode": "list",
            "presentation_state": None,
            "import_snapshot": self._library_note_import_snapshot,
            "import_receipt_available": (
                self._library_note_import_controller.snapshot.can_revisit_receipt
            ),
            "lasting_sync_snapshot": self._library_notes_lasting_sync_snapshot,
            "tree_projection": self._build_library_notes_tree_projection(),
            "tree_selected_placement_id": getattr(
                self, "_library_notes_tree_selected_placement_id", ""
            ),
            "tree_deleted_folder_available": (
                getattr(self, "_library_notes_deleted_folder_receipt", None) is not None
            ),
            "title_placeholder_only": False,
            "compact": self._library_notes_compact,
            "create_running": self._library_note_create_running,
            "create_status": self._library_note_create_status,
            "load_state": self._library_note_load_state,
            "load_message": self._library_note_load_message,
        }
        if self._library_selected_row_id == LIBRARY_ROW_CREATE_NOTE:
            values["mode"] = "create"
        elif self._library_notes_view == "import":
            values["mode"] = "import"
        elif self._library_notes_view == "lasting_add":
            values["mode"] = "lasting_add"
        elif self._library_notes_view == "lasting_roots":
            values["mode"] = "lasting_roots"
        elif self._library_notes_view == "editor":
            presentation_state = self._library_note_editor_state()
            if presentation_state is None:
                values["mode"] = "loading"
            else:
                values["mode"] = "editor"
                values["presentation_state"] = self._library_note_presentation_state()
                values["title_placeholder_only"] = (
                    self._library_note_pending_blank_gc_id is not None
                    and self._library_note_pending_blank_gc_id == self._selected_note_id
                )
        else:
            values["list_state"] = self._build_library_notes_state()
        return values

    def _library_notes_list_canvas_kwargs(self) -> dict[str, Any]:
        """Return list-only inputs for the retained Notes Items pane."""
        values = self._library_notes_canvas_kwargs()
        values.update(
            mode="list",
            list_state=self._build_library_notes_state(),
            presentation_state=None,
            title_placeholder_only=False,
        )
        return values

    def _library_note_work_pane_kwargs(self) -> dict[str, Any]:
        """Return active non-list content for the retained Notes work pane."""
        values = self._library_notes_canvas_kwargs()
        values["list_state"] = None
        return values

    def _library_prompt_basic_unavailable_reason(
        self,
        state: PromptEditorState,
        *,
        conflict: bool = False,
    ) -> str:
        """Return the forced-Advanced reason without changing the preference."""
        return prompt_basic_unavailable_reason(
            state,
            conflict=conflict,
            can_update_original=(
                state.prompt_id is None or self._library_prompt_can_update_original()
            ),
        )

    def _library_prompts_list_canvas_kwargs(self) -> dict[str, Any]:
        """Return list-only inputs for the retained Prompts Items pane."""
        controller = self._library_prompt_browse_controller
        requested_scope = controller.scope
        display_scope = controller.visible_result.scope
        return {
            "state": self._build_library_prompts_state(),
            "sort_mode": "name" if display_scope.sort_by == "name" else "newest",
            "filter_value": requested_scope.query,
            "browse_result": controller.visible_result,
            "pager": controller.pager,
            "mode": "list",
            "editor_state": None,
            "editor_mode": "basic",
            "basic_unavailable_reason": "",
            "conflict": False,
            "status": "",
            "show_open_existing": False,
            "import_open": False,
            "import_path": "",
            "import_status": "",
            "dirty": False,
            "can_update_original": False,
            "include_starter_content": False,
            "history_state": None,
            "history_current_compatible": True,
            "collection_label": self._library_prompt_collections_controller.collection_label(
                display_scope.collection_id
            ),
            "membership_state": None,
            "sort_choices_visible": self._library_prompts_sort_choices_visible,
            "delete_receipt": self._library_prompt_delete_receipt,
            "page_actions_disabled": controller.freshness == "stale",
            "mutation_in_flight": self._library_prompts_mutation_in_flight,
            "mutation_status": self._library_prompt_mutation_status,
            "write_in_flight": False,
            "bulk_read_only": False,
            "bulk_included": None,
            "identity_mismatch": False,
            "detail_notice": "",
            "detail_retryable": False,
        }

    def _library_prompt_work_pane_kwargs(self) -> dict[str, Any]:
        """Return active non-list content for the retained Prompt work pane."""
        values = self._library_prompts_canvas_kwargs()
        if self._library_prompts_import_open:
            values["mode"] = "list"
        values.update(
            state=None,
            browse_result=None,
            pager=None,
            sort_choices_visible=False,
            delete_receipt=None,
            page_actions_disabled=False,
            mutation_status="",
            bulk_read_only=(
                self._library_prompt_select_mode
                and self._library_prompts_view == "editor"
                and self._library_prompt_detail is not None
            ),
            bulk_included=(
                any(
                    entry.local_id == self._selected_prompt_id
                    for entry in self._library_prompt_selection.entries
                )
                if self._selected_prompt_id is not None
                else None
            ),
        )
        return values

    def _library_prompts_canvas_kwargs(self) -> dict[str, Any]:
        """Return every compose input for the mounted Prompts canvas."""
        membership_state = self._library_prompt_collections_controller.membership_state
        values: dict[str, Any] = {
            "state": None,
            "sort_mode": "newest",
            "filter_value": "",
            "browse_result": None,
            "pager": None,
            "mode": "list",
            "editor_state": None,
            "editor_mode": self._library_prompt_editor_mode,
            "basic_unavailable_reason": "",
            "conflict": False,
            "status": "",
            "show_open_existing": False,
            "import_open": self._library_prompts_import_open,
            "import_path": self._library_prompts_import_path,
            "import_status": self._library_prompts_import_status,
            "dirty": self._library_prompt_dirty,
            "can_update_original": False,
            "include_starter_content": (self._library_prompt_include_starter_content),
            "history_state": self._library_prompt_history_state,
            "history_current_compatible": self._library_prompt_block_state is not None,
            "collection_label": "All prompts",
            "membership_state": membership_state,
            "sort_choices_visible": False,
            "page_actions_disabled": False,
            "mutation_in_flight": self._library_prompts_mutation_in_flight,
            "write_in_flight": self._library_prompt_write_worker_is_active(),
            "bulk_read_only": False,
            "bulk_included": None,
            "identity_mismatch": False,
            "detail_notice": "",
            "detail_retryable": False,
        }
        if self._library_prompts_view == "editor":
            values["mode"] = "editor"
            if self._library_prompt_conflict_snapshot is not None:
                values["editor_state"] = self._current_library_prompt_editor_state(
                    self._library_prompt_conflict_snapshot
                )
                values["conflict"] = True
            elif self._library_prompt_detail is None:
                values["mode"] = "loading"
                values["detail_notice"] = (
                    self._library_prompt_detail_failure_notice()
                    if self._library_prompt_detail_error
                    else self._library_prompt_loading_notice()
                )
                values["detail_retryable"] = self._library_prompt_detail_retryable
            else:
                values["editor_state"] = self._current_library_prompt_editor_state()
                values["status"] = self._library_prompt_status
                values["show_open_existing"] = (
                    self._library_prompt_status
                    == LIBRARY_PROMPT_SAVE_STATUS_COPY["name-in-use"]
                )
                values["can_update_original"] = (
                    self._library_prompt_can_update_original()
                )
                values["identity_mismatch"] = (
                    self._selected_prompt_id != self._library_prompt_loaded_id
                )
                if values["identity_mismatch"]:
                    values["detail_notice"] = (
                        self._library_prompt_detail_failure_notice()
                        if self._library_prompt_detail_error
                        else self._library_prompt_loading_notice()
                    )
                    values["detail_retryable"] = self._library_prompt_detail_retryable
            if values["editor_state"] is not None:
                values["basic_unavailable_reason"] = (
                    self._library_prompt_basic_unavailable_reason(
                        values["editor_state"],
                        conflict=values["conflict"],
                    )
                )
            return values

        controller = self._library_prompt_browse_controller
        requested_scope = controller.scope
        display_scope = controller.visible_result.scope
        values.update(
            {
                "state": self._build_library_prompts_state(),
                "sort_mode": ("name" if display_scope.sort_by == "name" else "newest"),
                "filter_value": requested_scope.query,
                "browse_result": controller.visible_result,
                "pager": controller.pager,
                "page_actions_disabled": controller.freshness == "stale",
                "import_open": self._library_prompts_import_open,
                "import_path": self._library_prompts_import_path,
                "import_status": self._library_prompts_import_status,
                "collection_label": self._library_prompt_collections_controller.collection_label(
                    display_scope.collection_id
                ),
                "sort_choices_visible": self._library_prompts_sort_choices_visible,
            }
        )
        return values

    def _build_library_skill_tool_catalog(self) -> tuple[str, ...]:
        """Return the existing builtin/local tool names a Skill may restrict."""
        try:
            from ...Agents.tool_catalog import BuiltinToolProvider

            names = [entry.name for entry in BuiltinToolProvider().list_catalog()]
            console_config = getattr(self.app_instance, "app_config", {}).get(
                "console", {}
            )
            local_enabled = bool(
                isinstance(console_config, Mapping)
                and coerce_bool_setting(
                    console_config.get("local_tools_enabled"), False
                )
            )
            if local_enabled:
                from ...Agents.local_tool_provider import LocalToolProvider

                configured_root = console_config.get("workspace_root")
                workspace_root = (
                    Path(str(configured_root)).expanduser()
                    if configured_root
                    else Path.cwd()
                )
                names.extend(
                    entry.name
                    for entry in LocalToolProvider(
                        workspace_root=workspace_root
                    ).list_catalog()
                )
        except Exception:
            logger.warning("Library Skill tool catalog is temporarily unavailable.")
            return ()
        return tuple(dict.fromkeys(names))

    def _library_skills_list_canvas_kwargs(self) -> dict[str, Any]:
        """Return list-only inputs for the retained Skills Items pane."""
        values = self._library_skills_canvas_kwargs(consume_scroll=False)
        values.update(
            state=self._build_library_skills_state(),
            mode="list",
            editor_state=None,
            warnings="",
            status="",
            conflict=False,
            active_review=None,
            confirming_delete=False,
            scroll_to_actions=False,
            skill_path="",
            import_open=False,
            import_path="",
            import_status="",
            import_review_name="",
            mutation_in_flight=False,
            more_actions_open=False,
            trust_details_open=False,
            script_access_granted=False,
        )
        return values

    def _library_skill_work_pane_kwargs(self) -> dict[str, Any]:
        """Return the active non-list projection for the Skills Work pane."""
        values = self._library_skills_canvas_kwargs()
        if self._library_skills_import_open:
            values["mode"] = "list"
        values["state"] = None
        values["sort_choices_visible"] = False
        values["reader_mode"] = self._library_skill_reader_mode
        return values

    def _library_skills_canvas_kwargs(
        self, *, consume_scroll: bool = True
    ) -> dict[str, Any]:
        """Return every compose input for the mounted Skills canvas."""
        values: dict[str, Any] = {
            "state": None,
            "sort_mode": self._library_skills_sort,
            "filter_value": self._library_skills_filter,
            "mode": "list",
            "trust_posture": self._library_skills_trust_posture,
            "confirming_reset": self._library_skill_trust_confirming_reset,
            "editor_state": None,
            "warnings": "",
            "status": "",
            "conflict": False,
            "active_review": None,
            "is_create": not self._selected_skill_name,
            "dirty": self._library_skill_dirty,
            "confirming_delete": self._library_skill_confirming_delete,
            "scroll_to_actions": False,
            "skill_path": "",
            "import_open": False,
            "import_path": "",
            "import_status": "",
            "import_review_name": "",
            "import_in_flight": False,
            "import_package_kind": "",
            "import_recovery_actions": (),
            "import_retryable": False,
            "sort_choices_visible": False,
            "editor_mode": self._library_skill_editor_mode,
            "tool_catalog": self._library_skill_tool_catalog,
            "tool_filter": self._library_skill_tool_filter,
            "mutation_in_flight": self._library_skill_mutation_in_flight,
            "more_actions_open": self._library_skill_more_actions_open,
            "trust_details_open": self._library_skill_trust_details_open,
            "script_access_granted": self._library_skill_script_grant,
            "detail_notice": "",
            "detail_retryable": False,
        }
        if self._library_skills_view == "editor":
            editor_state = self._library_skill_editor_state
            if editor_state is None:
                values["mode"] = "loading"
                values["detail_notice"] = (
                    self._library_skill_detail_error or "Loading skill…"
                )
                values["detail_retryable"] = self._library_skill_detail_retryable
            else:
                values.update(
                    {
                        "mode": "editor",
                        "editor_state": editor_state,
                        "warnings": "\n".join(
                            skill_editor_warning_lines(
                                live_name=editor_state.name,
                                trust_status=editor_state.trust_status,
                                trust_blocked=editor_state.trust_blocked,
                            )
                        ),
                        "status": self._library_skill_status,
                        "conflict": self._library_skill_conflict,
                        "active_review": self._library_skill_active_review,
                        "scroll_to_actions": (
                            self._consume_library_skill_scroll_pending()
                            if consume_scroll
                            else False
                        ),
                        "skill_path": self._library_skill_on_disk_path(),
                    }
                )
            return values

        values.update(
            {
                "state": self._build_library_skills_state(),
                "import_open": self._library_skills_import_open,
                "import_path": self._library_skills_import_path,
                "import_status": self._library_skills_import_status,
                "import_review_name": self._library_skills_import_review_name,
                "import_in_flight": self._library_skills_import_in_flight,
                "import_package_kind": (
                    self._library_skill_import_coordinator.snapshot.package_kind
                ),
                "import_recovery_actions": (
                    self._library_skill_import_coordinator.snapshot.recovery_actions
                ),
                "import_retryable": (
                    self._library_skill_import_coordinator.snapshot.retryable
                ),
                "sort_choices_visible": self._library_skills_sort_choices_visible,
            }
        )
        return values

    def _build_library_prompts_state(self):
        """Build the Library prompts canvas's list-view display state.

        Rows and order come exclusively from the controller's validated
        retained page. The broad local-source snapshot remains a rail seam.
        """
        controller = self._library_prompt_browse_controller
        return build_prompt_browse_list_state(
            controller.visible_result,
            now=datetime.now(timezone.utc),
            retained_items=controller.retained_items,
            selection=self._library_prompt_selection,
            select_mode=self._library_prompt_select_mode,
        )

    def _sync_library_prompt_selection(self, focus_identity: str | None) -> None:
        """Recompose only the Prompt canvas from the screen-owned basket."""
        if not self.query("#library-prompts-canvas"):
            return
        focused = getattr(self, "focused", None)
        filter_cursor = (
            focused.cursor_position
            if focus_identity == "library-prompts-filter" and isinstance(focused, Input)
            else None
        )

        def restore_focus() -> None:
            self._restore_library_prompts_focus(focus_identity, filter_cursor)

        _sync_library_canvas(self, "prompts", then=restore_focus)

    def _clear_library_prompt_selection(self, *, announce: bool) -> None:
        """End Prompt selection and optionally announce the bounded count."""
        count = len(self._library_prompt_selection.entries)
        changed = self._library_prompt_select_mode or count > 0
        if not changed:
            return
        self._library_prompt_select_mode = False
        self._library_prompt_selection = PromptSelectionBasket()
        if self.is_running:
            self._sync_library_prompt_selection(None)
        if announce and count:
            notify = getattr(self.app_instance, "notify", None)
            if callable(notify):
                notify(f"Selection discarded · {count} prompts")

    def _sync_library_prompt_memberships(self, state) -> None:
        """Patch only membership controls; preserve editor inputs and undo state."""
        if self._library_prompts_mutation_in_flight:
            return
        try:
            self.query_one(
                "#library-prompt-work-pane", LibraryPromptWorkPane
            ).sync_memberships(state)
        except (NoMatches, QueryError):
            pass

    def _reconcile_library_prompt_memberships(self) -> None:
        self._sync_library_prompt_memberships(
            self._library_prompt_collections_controller.membership_state
        )

    def _apply_library_prompt_collection(self, collection_id: int | None) -> None:
        self._request_library_prompts_browse(
            dataclasses.replace(
                self._library_prompt_browse_controller.scope,
                collection_id=collection_id,
                page=1,
            ),
            focus_identity="library-prompts-collection",
        )

    def _sync_library_prompt_collection_label(self) -> None:
        try:
            button = self.query_one("#library-prompts-collection", Button)
        except (NoMatches, QueryError):
            return
        label = self._library_prompt_collections_controller.collection_label(
            self._library_prompt_browse_controller.visible_result.scope.collection_id
        )
        # AC#5/task-14902: the in-place patcher must build the SAME chooser
        # label the canvas composes (recompose discipline).
        button.label = library_choice_label("collection", escape_markup(label))

    def _refresh_library_prompt_after_membership_apply(self) -> None:
        """Refresh retained Items and Library counts after membership Apply.

        The Prompt editor remains mounted in Work while the independent Items
        projection reloads its exact applied scope. Prompt Save state is never
        changed here.
        """
        if self._library_prompts_mutation_in_flight:
            return
        self._request_library_prompts_browse(
            self._library_prompt_browse_controller.mutation_refresh_scope,
            focus_identity="library-prompt-memberships-apply",
        )
        self._refresh_local_source_snapshot()

    def _load_library_prompt_memberships(self) -> None:
        self.run_worker(
            self._library_prompt_collections_controller.load_memberships(),
            exclusive=True,
            group="library_prompt_memberships_load",
        )
        self.call_after_refresh(self._reconcile_library_prompt_memberships)

    def _library_prompts_focus_identity(self) -> str | None:
        """Return the current Prompt canvas descendant's stable DOM id."""
        focused = getattr(self, "focused", None)
        focused_id = getattr(focused, "id", None)
        if (
            not isinstance(focused, Widget)
            or not focused.is_mounted
            or not isinstance(focused_id, str)
            or not focused_id
        ):
            return None
        owners = (
            *self.query("#library-prompts-canvas"),
            *self.query("#library-prompt-work-pane"),
        )
        return (
            focused_id if any(owner in focused.ancestors for owner in owners) else None
        )

    def _restore_library_prompts_focus(
        self,
        focus_identity: str | None,
        filter_cursor: int | None = None,
    ) -> None:
        """Restore a surviving Prompt control, else the stable sort control."""
        if not self._library_list_canvas_showing_list():
            return
        if focus_identity:
            try:
                target = self.query_one(f"#{focus_identity}", Widget)
            except (NoMatches, QueryError):
                target = None
            if target is not None and not getattr(target, "disabled", False):
                target.focus()
                if filter_cursor is not None and isinstance(target, Input):
                    target.call_after_refresh(
                        setattr,
                        target,
                        "cursor_position",
                        min(filter_cursor, len(target.value)),
                    )
                return
        try:
            pager_fallback_id = {
                "library-prompts-page-next": "#library-prompts-page-previous",
                "library-prompts-page-previous": "#library-prompts-page-next",
            }.get(focus_identity)
            fallback_id = pager_fallback_id or (
                "#library-prompts-selection-done"
                if self._library_prompt_select_mode
                else "#library-prompts-sort"
            )
            fallback = self.query_one(fallback_id, Button)
            if not fallback.disabled:
                fallback.focus()
            elif pager_fallback_id:
                self.query_one("#library-prompts-filter", Input).focus()
        except (NoMatches, QueryError):
            pass

    def _stop_library_prompts_search_debounce(self) -> None:
        """Cancel the pending search timer without changing its request scope."""
        timer = self._library_prompts_debounce_timer
        if timer is not None:
            timer.stop()
            self._library_prompts_debounce_timer = None

    def _capture_library_prompts_filter_cursor(
        self,
        request_token: int,
        focus_identity: str | None,
    ) -> None:
        """Bind the active filter caret to one exact browse request."""
        focused = getattr(self, "focused", None)
        self._library_prompts_filter_cursor_context = (
            (request_token, focused.cursor_position)
            if focus_identity == "library-prompts-filter" and isinstance(focused, Input)
            else None
        )

    def _request_library_prompts_browse(
        self,
        scope: PromptBrowseScope,
        *,
        focus_identity: str | None = None,
    ) -> Any | None:
        """Capture presentation context and request one exact Prompt page."""
        self._stop_library_prompts_search_debounce()
        if focus_identity is None:
            focus_identity = self._library_prompts_focus_identity()
        controller = self._library_prompt_browse_controller
        token = controller.begin(scope)
        self._capture_library_prompts_filter_cursor(token, focus_identity)
        return controller.dispatch(
            scope,
            request_token=token,
            focus_identity=focus_identity,
        )

    def _sync_library_prompts_browse_result(
        self,
        result: PromptBrowseResult,
        focus_identity: str | None,
    ) -> LibraryEntryReconcileResult:
        """Project controller state and restore stable Prompt-list focus."""
        current = self._library_prompt_browse_controller.result
        route_key = self._library_entry_route_key()
        generation = self._library_snapshot_state_generation
        if (
            result.request_token != current.request_token
            or not self._library_entry_reconcile_is_current(generation, route_key)
            or self._library_selected_row_id
            not in (LIBRARY_ROW_BROWSE_PROMPTS, LIBRARY_ROW_CREATE_PROMPT)
        ):
            return LibraryEntryReconcileResult.SUPERSEDED

        live_focus_identity = self._library_prompts_focus_identity()
        live_focused = getattr(self, "focused", None)
        cursor_context = self._library_prompts_filter_cursor_context
        filter_cursor = (
            live_focused.cursor_position
            if live_focus_identity == "library-prompts-filter"
            and isinstance(live_focused, Input)
            else cursor_context[1]
            if live_focus_identity is None
            and cursor_context is not None
            and cursor_context[0] == result.request_token
            else None
        )
        restore_identity = live_focus_identity or focus_identity

        def restore_focus() -> None:
            if not self._library_entry_reconcile_is_current(generation, route_key):
                return
            if result.status == "loading" and focus_identity is not None:
                if focus_identity in {
                    "library-prompts-page-next",
                    "library-prompts-page-previous",
                }:
                    return
                try:
                    self.query_one(f"#{focus_identity}", Widget)
                except (NoMatches, QueryError):
                    return
            if result.status == "loading" or restore_identity is not None:
                self._restore_library_prompts_focus(
                    restore_identity,
                    filter_cursor,
                )
            elif not self._library_pending_list_entry_focus:
                self._restore_library_prompts_focus(None)

        if _sync_library_canvas(
            self,
            "prompts",
            then=restore_focus,
            allow_screen_fallback=False,
            sync_prompt_work=False,
        ):
            return LibraryEntryReconcileResult.APPLIED
        return LibraryEntryReconcileResult.FAILED

    def _queue_library_prompts_search(self, query: str) -> None:
        """Debounce one normalized search without blocking the UI loop."""
        if self._library_prompts_mutation_in_flight:
            return
        query = self._safe_text(query, max_length=200).strip()
        controller = self._library_prompt_browse_controller
        if query == controller.scope.query:
            return
        self._stop_library_prompts_search_debounce()
        scope = dataclasses.replace(controller.scope, query=query, page=1)
        token = controller.begin(scope)
        self._capture_library_prompts_filter_cursor(
            token,
            "library-prompts-filter",
        )

        def dispatch() -> None:
            self._library_prompts_debounce_timer = None
            controller.dispatch(
                scope,
                request_token=token,
                focus_identity="library-prompts-filter",
            )

        self._library_prompts_debounce_timer = self.set_timer(
            _LIBRARY_PROMPTS_SEARCH_DEBOUNCE_SECONDS,
            dispatch,
        )

    def _flush_library_prompts_search(self, query: str) -> None:
        """Flush Enter through the pending token without duplicating its call."""
        query = self._safe_text(query, max_length=200).strip()
        pending = self._library_prompts_debounce_timer is not None
        self._stop_library_prompts_search_debounce()
        controller = self._library_prompt_browse_controller
        current = controller.result
        if query != controller.scope.query:
            scope = dataclasses.replace(
                controller.scope,
                query=query,
                page=1,
            )
            token = controller.begin(scope)
        elif pending and current.status == "loading":
            scope = controller.scope
            token = current.request_token
        else:
            return
        self._capture_library_prompts_filter_cursor(
            token,
            "library-prompts-filter",
        )
        controller.dispatch(
            scope,
            request_token=token,
            focus_identity="library-prompts-filter",
        )

    def _invalidate_library_prompts_browse(self) -> None:
        """Cancel presentation timing and supersede the active browse token."""
        self._stop_library_prompts_search_debounce()
        self._library_prompts_filter_cursor_context = None
        self._library_prompt_browse_controller.invalidate()

    def _build_library_skills_state(self):
        """Build the Library skills canvas's list-view display state.

        Rows come exclusively from the Skills controller's validated retained
        page. The broad local-source snapshot remains a rail-count seam and
        cannot leak extra Skills into the bounded list canvas.
        """
        controller = self._library_skills_browse_controller
        items = controller.retained_items
        context_payload = {
            "available_skills": [
                item for item in items if not bool(item.get("trust_blocked"))
            ],
            "blocked_skills": [
                item for item in items if bool(item.get("trust_blocked"))
            ],
        }
        state = build_skills_list_state(
            context_payload,
            query="",
            sort=controller.visible_result.scope.sort,
            selected_name=self._selected_skill_name,
        )
        return dataclasses.replace(
            state,
            pager=controller.pager,
            blocked_total=controller.blocked_total,
            first_blocked_skill_name=controller.first_blocked_skill_name,
            actions_disabled=(
                controller.freshness != "fresh" or controller.result.status == "loading"
            ),
            source_summary_fresh=controller.freshness == "fresh",
        )

    def _request_library_skills_browse(
        self,
        scope: SkillBrowseScope,
        *,
        focus_identity: str | None = None,
    ) -> Any | None:
        """Request one exact Skills page and retain the filter caret."""
        controller = self._library_skills_browse_controller
        token = controller.begin(scope)
        focused = getattr(self, "focused", None)
        self._library_skills_filter_cursor_context = (
            (token, focused.cursor_position)
            if focus_identity == LIBRARY_SKILLS_FILTER_ID and isinstance(focused, Input)
            else None
        )
        return controller.dispatch(
            scope,
            request_token=token,
            focus_identity=focus_identity,
        )

    def _sync_library_skills_browse_result(
        self,
        result: SkillBrowseResult,
        focus_identity: str | None,
    ) -> LibraryEntryReconcileResult:
        """Project one accepted Skills generation and restore stable focus."""
        controller = self._library_skills_browse_controller
        if (
            result.request_token != controller.result.request_token
            or self._library_selected_row_id != LIBRARY_ROW_BROWSE_SKILLS
            or self._library_skills_view != "list"
        ):
            return LibraryEntryReconcileResult.SUPERSEDED

        self._library_skills_filter = controller.scope.query
        self._library_skills_sort = controller.scope.sort
        focused = getattr(self, "focused", None)
        live_focus_id = getattr(focused, "id", None)
        if (
            isinstance(focused, (Button, Input))
            and isinstance(live_focus_id, str)
            and live_focus_id.startswith("library-skills-")
        ):
            focus_identity = live_focus_id
        cursor_context = self._library_skills_filter_cursor_context
        cursor_position = (
            focused.cursor_position
            if isinstance(focused, Input) and live_focus_id == LIBRARY_SKILLS_FILTER_ID
            else cursor_context[1]
            if cursor_context is not None and cursor_context[0] == result.request_token
            else None
        )

        def restore_focus() -> None:
            if not focus_identity:
                return
            if result.status == "loading" and focus_identity in {
                LIBRARY_SKILLS_PAGE_PREVIOUS_ID,
                LIBRARY_SKILLS_PAGE_NEXT_ID,
                LIBRARY_SKILLS_RETRY_ID,
            }:
                return
            if focus_identity in {
                LIBRARY_SKILLS_PAGE_PREVIOUS_ID,
                LIBRARY_SKILLS_PAGE_NEXT_ID,
                LIBRARY_SKILLS_RETRY_ID,
            }:
                self._focus_library_skills_page_control(focus_identity)
                return
            try:
                target = self.query_one(f"#{focus_identity}", Widget)
            except (NoMatches, QueryError):
                return
            if not getattr(target, "disabled", False):
                target.focus()
                if cursor_position is not None and isinstance(target, Input):
                    target.cursor_position = cursor_position

        if _sync_library_canvas(
            self,
            "skills",
            then=restore_focus,
            allow_screen_fallback=False,
        ):
            return LibraryEntryReconcileResult.APPLIED
        return LibraryEntryReconcileResult.FAILED

    def _focus_library_skills_page_control(self, invoked: str) -> None:
        """Restore pager focus without landing on a disabled control."""
        opposite = {
            LIBRARY_SKILLS_PAGE_PREVIOUS_ID: LIBRARY_SKILLS_PAGE_NEXT_ID,
            LIBRARY_SKILLS_PAGE_NEXT_ID: LIBRARY_SKILLS_PAGE_PREVIOUS_ID,
            LIBRARY_SKILLS_RETRY_ID: LIBRARY_SKILLS_FILTER_ID,
        }[invoked]
        for control_id in (invoked, opposite, LIBRARY_SKILLS_FILTER_ID):
            try:
                control = self.query_one(f"#{control_id}", Widget)
            except (NoMatches, QueryError):
                continue
            if not getattr(control, "disabled", False):
                control.focus()
                return

    def _refresh_library_skills_after_committed_mutation(
        self,
        *,
        scope: SkillBrowseScope | None = None,
    ) -> None:
        """Invalidate exact totals after a durable Skill or trust change.

        Retained rows may remain visible, but they are explicitly stale and
        inert until the source-owned page refresh succeeds.
        """
        controller = self._library_skills_browse_controller
        refresh_scope = scope or controller.mutation_refresh_scope
        if controller.applied_result is not None:
            controller.retain_stale_items(
                controller.retained_items,
                stale_copy="Skills changed; refresh the page before acting.",
            )
        else:
            controller.invalidate(refresh_scope)
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
            and self._library_skills_view == "list"
        ):
            self._request_library_skills_browse(refresh_scope)

    def _refresh_library_skills_trust_posture(self) -> None:
        """Kick an off-thread read of the Skills trust service's posture.

        Task 5: ``SkillTrustService.trust_posture()`` may touch the OS
        keyring, so it is NEVER called on the compose/event-loop thread --
        only from here, via ``asyncio.to_thread`` in
        ``_load_library_skills_trust_posture`` below. Called on every entry
        into the skills browse row (``_select_library_rail_row``) and
        whenever the skills snapshot itself is refreshed
        (``_refresh_local_source_snapshot``), so a stale cached posture
        from a previous visit (e.g. locked -> unlocked in another session)
        never lingers.

        Hidden (``""``) rather than fetched at all when the trust service
        is absent or doesn't expose ``trust_posture`` (server mode / no
        local trust service wired). The mounted Browse Skills list is
        repainted when stale state or a stale header remains; an already-clear
        list and an open editor are not, because neither has stale posture UI
        to remove and the editor owns unsaved live fields.
        """
        service = getattr(self.app_instance, "local_skill_trust_service", None)
        posture_fn = getattr(service, "trust_posture", None)
        if not callable(posture_fn):
            should_repaint = (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
                and self._library_skills_view == "list"
                and (
                    bool(self._library_skills_trust_posture)
                    or bool(self.query("#library-skills-trust-header"))
                )
            )
            self.workers.cancel_group(self, "library_skills_trust_posture")
            self._library_skills_trust_posture = ""
            if should_repaint:
                _sync_library_canvas(
                    self,
                    "skills",
                    allow_screen_fallback=False,
                )
            return
        self.run_worker(
            self._load_library_skills_trust_posture(posture_fn),
            exclusive=True,
            group="library_skills_trust_posture",
            exit_on_error=False,
        )

    async def _load_library_skills_trust_posture(
        self, posture_fn
    ) -> LibraryEntryReconcileResult:
        """Await the off-thread ``trust_posture()`` call and apply the result.

        Args:
            posture_fn: The trust service's bound ``trust_posture`` method
                (captured by ``_refresh_library_skills_trust_posture`` so
                this never re-reads ``local_skill_trust_service`` itself --
                irrelevant here, but keeps this a pure "run this callable
                off-thread" step).
        """
        route_key = self._library_entry_route_key()
        generation = self._library_snapshot_state_generation
        try:
            posture = await asyncio.to_thread(posture_fn)
        except Exception:
            posture = ""
        self._library_skills_trust_posture = posture if isinstance(posture, str) else ""
        if (
            route_key != self._library_entry_route_key()
            or not self._library_entry_reconcile_is_current(generation, route_key)
            or self._library_selected_row_id != LIBRARY_ROW_BROWSE_SKILLS
            or self._library_skills_view != "list"
        ):
            return LibraryEntryReconcileResult.SUPERSEDED
        identity = self._capture_library_entry_focus()
        prior_callback: Callable[[], None] | None = None
        pending = (generation, route_key)
        if (
            self._library_entry_reconcile_dirty
            and self._library_entry_reconcile_pending == pending
        ):
            try:
                canvas = self.query_one(
                    "#library-skills-canvas", LibrarySkillsListCanvas
                )
            except (NoMatches, QueryError):
                canvas = None
            if canvas is not None:
                prior_callback = canvas._post_recompose_callback

        def finish_posture_sync() -> None:
            if prior_callback is not None:
                prior_callback()
            if identity is not None:
                self._restore_library_entry_focus(
                    identity,
                    generation=generation,
                    route_key=route_key,
                )

        follow_up = (
            finish_posture_sync
            if prior_callback is not None or identity is not None
            else None
        )
        if _sync_library_canvas(
            self,
            "skills",
            then=follow_up,
            allow_screen_fallback=False,
        ):
            return LibraryEntryReconcileResult.APPLIED
        return LibraryEntryReconcileResult.FAILED

    async def _refresh_library_media_detail(
        self,
        media_id: str,
        *,
        entry_origin: bool = False,
        request_generation: int | None = None,
        requested_id: str | None = None,
    ) -> LibraryEntryReconcileResult | None:
        """Fetch and store the full detail for a selected Library media item.

        Mirrors ``_refresh_library_collections_snapshot``: guards against an
        unavailable media service, offloads the (possibly blocking) service
        call via ``_run_library_service_call``, and recomposes once the
        fetched detail (or a cleared/failed state) has been stored.

        Also fetches the item's reading highlights (see
        ``_fetch_library_media_highlights``) so both the detail and the
        highlights section are ready by the single recompose at the end,
        rather than the highlights section popping in on a second refresh.

        Triggered by ``handle_library_media_row`` on media-row selection;
        ``compose_content`` renders the stored ``_library_media_detail`` via
        ``build_library_media_viewer_state`` once this worker completes.

        Args:
            media_id: The Library media item id to fetch full detail for.
        """
        entry_route_key = self._library_entry_route_key() if entry_origin else None
        entry_generation = (
            self._library_snapshot_state_generation if entry_origin else None
        )
        pending = self._library_media_reader_session.pending_request
        reader_identity = self._library_media_reader_identity(media_id)
        requested_id = requested_id or (
            reader_identity[0] if reader_identity is not None else media_id
        )
        external_detail = self._library_media_reader_session.external_detail
        if (
            request_generation is None
            and pending is None
            and reader_identity is not None
            and requested_id == self._selected_media_id
            and self._library_media_view == "viewer"
        ):
            canonical_id, backing_id = reader_identity
            self._library_media_reader_session = begin_selection(
                self._library_media_reader_session,
                canonical_id,
                backing_id,
                self._library_media_reader_session.selected_title or canonical_id,
                immediate=True,
            )
            pending = self._library_media_reader_session.pending_request
        if request_generation is None:
            request_generation = (
                pending.generation
                if pending is not None and pending.requested_id == requested_id
                else (
                    self._library_media_reader_session.request_generation
                    if external_detail
                    else None
                )
            )
        service = getattr(self.app_instance, "media_reading_scope_service", None)
        get_media_item = getattr(service, "get_media_item", None)
        if not callable(get_media_item):
            if request_generation is not None:
                self._library_media_reader_session = settle_failure(
                    self._library_media_reader_session,
                    request_generation,
                    requested_id,
                    "Media service is unavailable.",
                )
            if self.is_mounted:
                if entry_origin:
                    if entry_route_key != self._library_entry_route_key():
                        return LibraryEntryReconcileResult.SUPERSEDED
                    self.refresh(recompose=True)
                    return LibraryEntryReconcileResult.APPLIED
                # task-21116: targeted media-surface projection (list view).
                await self._apply_library_media_active_surface()
            return None
        resolved_service_media_id = self._library_media_backing_id(media_id)
        if (
            external_detail
            and isinstance(resolved_service_media_id, str)
            and resolved_service_media_id.isdecimal()
        ):
            # Server ingest persists its returned id as text, while the server
            # media client requires the numeric path parameter it reported.
            resolved_service_media_id = int(resolved_service_media_id)
        try:
            detail = await self._run_library_service_call(
                get_media_item,
                # A media item opened from a finished SERVER ingest lives in the
                # server's library, so resolving it locally would find nothing
                # (task-700). Every other route into this viewer is local.
                mode="server" if external_detail else "local",
                media_id=resolved_service_media_id,
                include_content=True,
                include_versions=True,
                isolate_in_worker=True,
            )
        except Exception:
            logger.opt(exception=True).warning(
                f"Failed to load Library media detail for {media_id!r}."
            )
            detail = None
        # Discard out-of-order results: if the user has since selected a
        # different media row (or left the viewer), a slower in-flight fetch
        # for the previous selection must not overwrite the current one. The
        # highlights fetch is a second await point, so re-check after it too
        # and store detail + highlights together only when still current.
        current_session = self._library_media_reader_session
        current_pending = current_session.pending_request
        request_is_current = (
            current_session.external_detail
            and current_session.request_generation == request_generation
            and current_session.loaded_id == requested_id
            if external_detail
            else (
                request_generation is not None
                and current_pending is not None
                and current_pending.generation == request_generation
                and current_pending.requested_id == requested_id
            )
        )
        if not request_is_current or (
            entry_route_key is not None
            and entry_route_key != self._library_entry_route_key()
        ):
            return LibraryEntryReconcileResult.SUPERSEDED if entry_origin else None
        highlights = (
            []
            if external_detail
            else await self._fetch_library_media_highlights(media_id)
        )
        reading_progress = (
            None
            if external_detail
            else await self._fetch_library_media_reading_progress(media_id)
        )
        current_session = self._library_media_reader_session
        current_pending = current_session.pending_request
        request_is_current = (
            current_session.external_detail
            and current_session.request_generation == request_generation
            and current_session.loaded_id == requested_id
            if external_detail
            else (
                request_generation is not None
                and current_pending is not None
                and current_pending.generation == request_generation
                and current_pending.requested_id == requested_id
            )
        )
        if not request_is_current or (
            entry_route_key is not None
            and entry_route_key != self._library_entry_route_key()
        ):
            return LibraryEntryReconcileResult.SUPERSEDED if entry_origin else None
        if isinstance(detail, Mapping):
            self._library_media_detail = detail
            self._library_media_highlights = highlights
            if request_generation is not None and not external_detail:
                self._cache_library_media_reading_progress(
                    request_generation, requested_id, reading_progress
                )
                self._library_media_reader_session = settle_success(
                    self._library_media_reader_session,
                    request_generation,
                    requested_id,
                )
                self._schedule_library_media_image_preview(
                    request_generation=request_generation,
                    canonical_id=requested_id,
                    backing_id=resolved_service_media_id,
                    detail=detail,
                )
        elif request_generation is not None and not external_detail:
            # Preserve the long-standing open-on-deleted contract after the
            # permanent Reader conversion: a stale Search/RAG result or a
            # record deleted between selection and fetch must not leave the
            # Reader showing an older item's detail under the missing id.
            self._library_media_detail = None
            self._library_media_highlights = []
            self._library_media_reader_session = settle_failure(
                self._library_media_reader_session,
                request_generation,
                requested_id,
                "Media item is unavailable.",
            )
            notify = getattr(self.app_instance, "notify", None)
            if callable(notify):
                notify("Media item is unavailable.", severity="warning")
        # LIB-13: default the content view per item, from the just-fetched
        # detail's own is_markdown -- computed here (once, at load) rather
        # than on every recompose, so a later Rendered<->Raw toggle press
        # is never silently reset back to the default by an unrelated
        # recompose (mirrors the note editor's ``_library_note_preview``
        # not being re-derived on every render).
        self._library_media_content_mode = (
            "rendered"
            if isinstance(self._library_media_detail, Mapping)
            and self._library_media_viewer_state_cached(
                self._library_media_detail
            ).is_markdown
            else "raw"
        )
        if (
            entry_generation is not None
            and entry_generation != self._library_snapshot_state_generation
        ):
            # The worker still owns and settles its fetched state, but a
            # newer same-route snapshot owns projection into the permanent
            # Reader (the pre-shell replacement seam enforced this fence).
            current_route_key = self._library_entry_route_key()
            if entry_route_key == current_route_key and self.is_attached:
                self._library_entry_reconcile_dirty = True
                self._schedule_library_entry_reconcile(
                    self._library_snapshot_state_generation,
                    current_route_key,
                )
            return LibraryEntryReconcileResult.SUPERSEDED
        if self.is_mounted:
            if entry_origin:
                if entry_route_key != self._library_entry_route_key():
                    return LibraryEntryReconcileResult.SUPERSEDED
                await self._apply_library_media_active_surface()
                return LibraryEntryReconcileResult.APPLIED
            # task-15458: deliberately defer the legacy non-entry refresh.
            # The open-time compose may already be rendering this exact detail;
            # the identity guard below avoids a duplicate large-document parse.
            self.call_next(self._recompose_library_media_detail_if_unrendered)
        return None

    def _library_media_image_preview_capable(self) -> bool:
        """Return whether this runtime can present terminal image previews."""
        if self._library_media_preview_factory_injected:
            return True
        try:
            return not bool(self.app.is_headless)
        except Exception:
            return False

    def _schedule_library_media_image_preview(
        self,
        *,
        request_generation: int,
        canonical_id: str,
        backing_id: int | str,
        detail: Mapping[str, Any],
        force: bool = False,
    ) -> None:
        """Schedule an additive local-original preview without delaying text."""
        if not self._library_media_image_preview_capable():
            return
        if canonical_id in self._library_media_preview_images and not force:
            return
        if self._library_media_preview_loading.get(canonical_id) == request_generation:
            return
        if force:
            self._library_media_preview_images.pop(canonical_id, None)
            self._library_media_preview_status.pop(canonical_id, None)
        self._library_media_preview_loading[canonical_id] = request_generation
        self.run_worker(
            self._load_library_media_image_preview(
                request_generation=request_generation,
                canonical_id=canonical_id,
                backing_id=backing_id,
                detail=detail,
            ),
            group="library_media_image_preview",
        )

    def _library_media_preview_request_is_current(
        self, request_generation: int, canonical_id: str
    ) -> bool:
        """Fence preview projection to the local item that still owns Reader."""
        session = self._library_media_reader_session
        return (
            not session.external_detail
            and session.request_generation == request_generation
            and session.loaded_id == canonical_id
        )

    def _cache_library_media_preview(self, canonical_id: str, image: Any) -> None:
        """Store one decoded preview and evict the oldest cached entry."""
        self._library_media_preview_images.pop(canonical_id, None)
        self._library_media_preview_images[canonical_id] = image
        while (
            len(self._library_media_preview_images) > LIBRARY_MEDIA_PREVIEW_CACHE_LIMIT
        ):
            evicted_id = next(iter(self._library_media_preview_images))
            self._library_media_preview_images.pop(evicted_id, None)
            self._library_media_preview_status.pop(evicted_id, None)
            self._library_media_preview_hidden.discard(evicted_id)
            self._library_media_preview_loading.pop(evicted_id, None)

    async def _load_library_media_image_preview(
        self,
        *,
        request_generation: int,
        canonical_id: str,
        backing_id: int | str,
        detail: Mapping[str, Any],
    ) -> None:
        """Load and decode one eligible local original behind a stale fence."""
        try:
            from ...Widgets.Library.library_media_image_preview import (
                decode_media_image,
                image_preview_eligibility,
            )

            # Remote details are rejected before even consulting local file
            # seams. This keeps previews strictly local and side-effect free.
            preliminary = image_preview_eligibility(detail, None, backend="local")
            if preliminary.reason == "remote":
                return
            service = getattr(self.app_instance, "media_reading_scope_service", None)
            check_media_file = getattr(service, "check_media_file", None)
            download_media_file = getattr(service, "download_media_file", None)
            if not callable(check_media_file) or not callable(download_media_file):
                return
            file_check = await self._run_library_service_call(
                check_media_file,
                mode="local",
                media_id=backing_id,
                file_type="original",
                isolate_in_worker=True,
            )
            eligibility = image_preview_eligibility(
                detail,
                file_check if isinstance(file_check, Mapping) else None,
                backend="local",
            )
            if not eligibility.eligible:
                if (
                    eligibility.reason == "unavailable"
                    and self._library_media_preview_request_is_current(
                        request_generation, canonical_id
                    )
                ):
                    self._library_media_preview_status[canonical_id] = (
                        "Image preview unavailable — showing complete stored text"
                    )
                    self._sync_library_media_viewer_or_recompose()
                return
            receipt = await self._run_library_service_call(
                download_media_file,
                mode="local",
                media_id=backing_id,
                file_type="original",
                isolate_in_worker=True,
            )
            content = receipt.get("content") if isinstance(receipt, Mapping) else None
            image = await asyncio.to_thread(decode_media_image, content)
            if not self._library_media_preview_request_is_current(
                request_generation, canonical_id
            ):
                return
            self._cache_library_media_preview(canonical_id, image)
            self._library_media_preview_status.pop(canonical_id, None)
            self._sync_library_media_viewer_or_recompose()
        except Exception:
            logger.opt(exception=True).warning(
                "Failed to load Library media image preview for {}.", canonical_id
            )
            if self._library_media_preview_request_is_current(
                request_generation, canonical_id
            ):
                self._library_media_preview_images.pop(canonical_id, None)
                self._library_media_preview_status[canonical_id] = (
                    "Image preview failed — showing complete stored text"
                )
                self._sync_library_media_viewer_or_recompose()
        finally:
            if (
                self._library_media_preview_loading.get(canonical_id)
                == request_generation
            ):
                self._library_media_preview_loading.pop(canonical_id, None)

    async def _fetch_library_media_reading_progress(
        self, media_id: str
    ) -> Mapping[str, Any] | None:
        """Fetch local progress for a detail request that still owns Reader."""
        service = getattr(self.app_instance, "media_reading_scope_service", None)
        get_progress = getattr(service, "get_reading_progress", None)
        if not callable(get_progress):
            return None
        try:
            progress = await self._run_library_service_call(
                get_progress,
                mode="local",
                media_id=self._required_library_media_backing_id(media_id),
                isolate_in_worker=True,
            )
        except Exception:
            logger.warning("Failed to load Library media reading progress.")
            return None
        return progress if isinstance(progress, Mapping) else None

    def _cache_library_media_reading_progress(
        self,
        request_generation: int,
        requested_id: str,
        progress: Mapping[str, Any] | None,
    ) -> bool:
        """Cache fetched progress only while its detail request still owns Reader."""
        pending = self._library_media_reader_session.pending_request
        if (
            pending is None
            or pending.generation != request_generation
            or pending.requested_id != requested_id
            or not isinstance(progress, Mapping)
        ):
            return False
        try:
            offset = (
                int(progress.get("scroll_x", 0)),
                int(progress.get("scroll_y", 0)),
            )
        except (TypeError, ValueError):
            return False
        self._library_media_read_scroll_by_id[requested_id] = offset
        # TASK-22210: the fetched value IS the durable row -- record it so a
        # later capture of the same offset skips its redundant write.
        self._library_media_progress_persisted_offsets[requested_id] = offset
        return True

    def _recompose_library_media_detail_if_unrendered(self) -> None:
        """Project the media surface unless a compose already rendered the
        current media detail.

        task-21116: the projection is the targeted media canvas-child swap
        (``_apply_library_media_active_surface``), not the retired
        whole-screen recompose -- and it skips entirely when the media
        surface no longer owns the route (the TASK-15706 rule: an async
        completion must not rebuild a surface that is transitioning away;
        the fetched detail stays cached for the next media entry).
        """
        if not self.is_mounted:
            return
        if (
            self._library_media_view == "viewer"
            and self._library_media_detail is not None
            and self._library_media_composed_detail is self._library_media_detail
        ):
            return
        self.call_next(self._apply_library_media_active_surface)

    async def _fetch_library_media_highlights(
        self, media_id: str
    ) -> list[dict[str, Any]]:
        """Fetch reading highlights for a Library media item from the local scope service.

        Guards against an unavailable ``list_highlights`` service or a failed
        call the same way ``_refresh_library_media_detail`` guards the detail
        fetch: any failure yields an empty list rather than raising, so a
        highlights outage never blocks the rest of the viewer from loading.

        Args:
            media_id: The Library media item id to fetch highlights for.

        Returns:
            The fetched highlights list, or an empty list when the service
            is unavailable or the fetch fails.
        """
        service = getattr(self.app_instance, "media_reading_scope_service", None)
        list_highlights = getattr(service, "list_highlights", None)
        if not callable(list_highlights):
            return []
        service_media_id = self._library_media_backing_id(media_id)
        try:
            highlights = await self._run_library_service_call(
                list_highlights,
                mode="local",
                item_id=service_media_id,
                isolate_in_worker=True,
            )
        except Exception:
            logger.opt(exception=True).warning(
                f"Failed to load Library media highlights for {media_id!r}."
            )
            return []
        return list(highlights) if isinstance(highlights, list) else []

    async def _reload_library_media_highlights(self, media_id: str) -> None:
        """Re-fetch and store highlights after a highlight mutation, then recompose.

        Args:
            media_id: The Library media item id whose highlights changed.
        """
        self._library_media_highlights = await self._fetch_library_media_highlights(
            media_id
        )
        if self.is_mounted:
            self.refresh(recompose=True)

    async def _project_library_note_entry_result(
        self,
        *,
        entry_origin: bool,
        then: Callable[[], None] | None = None,
    ) -> LibraryEntryReconcileResult | None:
        """Project one note-load result without a Library-screen fallback."""
        if not self.is_mounted:
            return LibraryEntryReconcileResult.SUPERSEDED if entry_origin else None
        if entry_origin and not self.query("#library-notes-canvas"):
            generation = self._library_snapshot_state_generation
            route_key = self._library_entry_route_key()
            result = await self._replace_library_canvas_child(
                LibraryNotesCanvas(
                    **self._library_notes_list_canvas_kwargs(),
                    id="library-notes-canvas",
                ),
                generation=generation,
                route_key=route_key,
            )
            if result is LibraryEntryReconcileResult.APPLIED and then is not None:
                then()
            return result
        synced = _sync_library_canvas(
            self,
            "notes",
            then=then,
            allow_screen_fallback=not entry_origin,
        )
        if entry_origin:
            return (
                LibraryEntryReconcileResult.APPLIED
                if synced
                else LibraryEntryReconcileResult.FAILED
            )
        return None

    async def _refresh_library_note_detail(
        self,
        note_id: str,
        *,
        entry_origin: bool = False,
        navigation_generation: int | None = None,
        topology_epoch: int | None = None,
        lifecycle_generation: int | None = None,
    ) -> LibraryEntryReconcileResult | None:
        """Open one normalized coordinator session and apply its typed outcome.

        Args:
            note_id: The Library note id to fetch full detail for.
        """
        entry_route_key = self._library_entry_route_key() if entry_origin else None

        def navigation_is_current() -> bool:
            return bool(
                (
                    navigation_generation is None
                    or navigation_generation
                    == self._library_notes_navigation_generation
                )
                and (
                    topology_epoch is None
                    or topology_epoch == self._library_notes_tree_topology_epoch
                )
                and (
                    lifecycle_generation is None
                    or lifecycle_generation
                    == self._library_notes_tree_lifecycle_generation
                )
            )

        if (
            not navigation_is_current()
            or note_id != self._selected_note_id
            or self._library_notes_view != "editor"
            or self._library_notes_source != LIBRARY_NOTES_SOURCE_DATABASE
        ):
            return LibraryEntryReconcileResult.SUPERSEDED if entry_origin else None
        outcome = await self._library_note_session.open_session(note_id)
        if outcome.kind is NoteLoadOutcomeKind.STALE:
            return LibraryEntryReconcileResult.SUPERSEDED if entry_origin else None
        if (
            not navigation_is_current()
            or note_id != self._selected_note_id
            or self._library_notes_view != "editor"
            or self._library_notes_source != LIBRARY_NOTES_SOURCE_DATABASE
            or (
                entry_route_key is not None
                and entry_route_key != self._library_entry_route_key()
            )
        ):
            return LibraryEntryReconcileResult.SUPERSEDED if entry_origin else None
        if outcome.kind is NoteLoadOutcomeKind.MISSING:
            logger.info("Library note is no longer available; returning to list.")
            self._dispatch_database_note_identity_cleared()
            self._reset_library_note_editor_state()
            self._notify_library_note_missing_warning()
            self._refresh_local_source_snapshot()
            return await self._project_library_note_entry_result(
                entry_origin=entry_origin
            )
        if outcome.kind is NoteLoadOutcomeKind.FAILED:
            self._library_note_load_state = "failed"
            self._library_note_load_message = (
                outcome.message or "Unable to load note. Press Retry."
            )
            return await self._project_library_note_entry_result(
                entry_origin=entry_origin
            )

        self._library_note_load_state = "loaded"
        self._library_note_load_message = ""
        self._library_note_autosave_state = "idle"
        self._library_note_preview = False
        self._library_note_context = False
        self._library_note_editor_armed = False
        self._library_notes_work_session_activation_pending = True
        if self.is_mounted:
            self.call_later(
                self._activate_database_note_work_session,
                note_id,
            )
            editor_identity = LibraryNotesFocusIdentity(
                stage="notes",
                region="editor",
                note_id=note_id,
                semantic_role="body",
            )

            def arm_and_focus_editor() -> None:
                # Deterministic (task-15457 review I4b): both of these used to
                # ride ``call_after_refresh``, which has no ordering against a
                # recompose driven by the CANVAS's own pump -- so on the
                # list -> loading -> editor row press they ran against the
                # loading children and left focus outside the canvas. Arming
                # is dirty-tracking, not cosmetics: a miss leaves the editor
                # unarmed, so this is the one that must not be lost.
                self._apply_library_notes_stage_visibility()
                self._arm_library_note_editor()
                self._restore_library_notes_focus_identity(editor_identity)

            return await self._project_library_note_entry_result(
                entry_origin=entry_origin,
                then=arm_and_focus_editor,
            )
        return None

    def _begin_library_note_load(
        self, note_id: str, *, entry_origin: bool = False
    ) -> None:
        """Reset presentation, invalidate old work, and start one editor load."""
        navigation_generation = self._supersede_library_notes_navigation()
        topology_epoch = self._library_notes_tree_topology_epoch
        lifecycle_generation = self._library_notes_tree_lifecycle_generation
        self._library_note_session.close_session()
        self._selected_note_id = note_id
        self._library_notes_view = "editor"
        self._library_note_load_state = "loading"
        self._library_note_load_message = ""
        self._library_note_autosave_state = "idle"
        self._library_note_shortcut_status = ""
        self._library_note_confirming_delete = False
        self._library_note_preview = False
        self._library_note_context = False
        self._library_note_delete_origin_context = False
        self._library_note_delete_origin_preview = False
        self._library_note_editor_armed = False
        self._apply_library_notes_stage_visibility()
        self.run_worker(
            self._refresh_library_note_detail(
                note_id,
                entry_origin=entry_origin,
                navigation_generation=navigation_generation,
                topology_epoch=topology_epoch,
                lifecycle_generation=lifecycle_generation,
            ),
            exclusive=True,
            group="library_note_detail",
        )
        self.run_worker(
            self._locate_library_notes_tree_target(
                note_id=note_id,
                focus=False,
                navigation_generation=navigation_generation,
            ),
            exclusive=True,
            group="library_notes_locator",
        )

    def _arm_library_note_editor(self, recompose_generation: int | None = None) -> None:
        """Enable dirty-tracking once the notes editor's mount-time
        ``Input.Changed`` (fired for the non-empty ``value=`` kwarg) has
        already been delivered, so it is never mistaken for a real edit.
        """
        if (
            recompose_generation is not None
            and recompose_generation != self._library_notes_recompose_generation
        ):
            return
        self._library_note_editor_armed = True

    @on(LibraryNoteWorkPane.EditorReady)
    def handle_library_note_work_pane_editor_ready(
        self, event: LibraryNoteWorkPane.EditorReady
    ) -> None:
        """Arm dirty tracking only after the retained editor children mount."""
        event.stop()
        if (
            self._library_selected_row_id != LIBRARY_ROW_BROWSE_NOTES
            or self._library_notes_view != "editor"
            or self._library_note_session.snapshot is None
            or self._selected_note_id != self._library_note_session.snapshot.note_id
        ):
            return
        self._arm_library_note_editor()
        if self._library_note_session.untouched_create_token is not None:
            self._focus_library_note_control("#library-note-title")

    def _reset_library_note_editor_state(self) -> None:
        """Clear all in-canvas Library note editor/save state.

        Shared by the Back handler, note-row selection, and rail-row
        selection so every exit from the editor leaves save/autosave/
        conflict tracking in a clean ``idle`` state for the next note.
        """
        self._dispatch_database_note_identity_cleared()
        self._library_note_session.close_session()
        if self._library_notes_view != "import":
            self._library_notes_view = "list"
        self._selected_note_id = ""
        self._library_note_load_state = "idle"
        self._library_note_load_message = ""
        self._library_note_autosave_state = "idle"
        self._library_note_shortcut_status = ""
        self._library_note_confirming_delete = False
        self._library_note_preview = False
        self._library_note_context = False
        self._library_note_delete_origin_context = False
        self._library_note_delete_origin_preview = False
        self._library_note_editor_armed = False
        # Defense in depth: the normal exit path is ``_flush_library_note_
        # save`` (which GCs a still-pending blank note and clears both
        # flags itself, before this reset ever runs); this catches the
        # other "note is gone" fallback paths that reach this reset
        # without going through that flush first, and every full editor
        # exit generally, so neither flag can outlive the editor session
        # it was armed for.
        self._library_note_pending_blank_gc_id = None
        self._library_note_session_blank_id = None
        # (P0) A full editor reset ends the session the pristine-title
        # marker belonged to; the next note starts untouched again.
        self._library_note_title_user_edited = False
        self._invalidate_library_note_autosave()

    def _reset_library_ingest_transient_state(self) -> None:
        """Clear the ingest canvas's form to defaults on rail re-entry.

        Called on every ``_select_library_rail_row`` switch so a stale
        in-progress form from a previous Ingest visit never reappears when
        the user comes back to the canvas. The job queue
        itself is registry-owned and untouched by this reset -- only the
        local form echo resets. Any in-flight pre-flight worker is
        cancelled AND generation-fenced (cancellation is cooperative, so a
        finished worker's late result would otherwise still land on the
        fresh form -- task-2011).
        """
        self._invalidate_library_ingest_preflight()
        self._invalidate_library_external_submission()
        timer = self._library_ingest_path_debounce_timer
        if timer is not None:
            timer.stop()
            self._library_ingest_path_debounce_timer = None
        self._library_ingest_clear_finished_armed = False
        self._disarm_library_ingest_retry_confirm()
        self._library_ingest_expanded_details.clear()
        self._library_ingest_form = LibraryIngestFormState()

    def _pause_library_ingest_transient_ui(self) -> None:
        """Rail-switch hygiene WITHOUT wiping the staged form (task-2043).

        Stops the typing debounce (it must not fire while another canvas is
        showing), fences off any in-flight pre-flight worker (its late
        result would otherwise land while a DIFFERENT canvas is showing --
        the stored echo persists, only the worker is fenced), and disarms
        the two-press clear; the typed path, metadata, and pre-flight echo
        persist for the session so a multi-batch workflow survives a look
        at another rail row.
        """
        timer = self._library_ingest_path_debounce_timer
        if timer is not None:
            timer.stop()
            self._library_ingest_path_debounce_timer = None
        self._library_ingest_preflight_generation += 1
        self._cancel_library_ingest_preflight()
        self._invalidate_library_external_submission()
        self._library_ingest_clear_finished_armed = False
        # (task-3314) Same hygiene for the pending Start consent: changing
        # canvases mid-consent is not a "yes".
        self._disarm_library_ingest_start_confirm()

    # ----- Export canvas -------------------------------------------------

    @staticmethod
    def _default_library_export_form() -> dict[str, Any]:
        """Build a fresh export form echo: today's stamped name, nothing else set."""
        return {
            "name": default_export_name(),
            "description": "",
            "quality": DEFAULT_MEDIA_QUALITY,
            "destination": "",
            "destination_exists": False,
        }

    def _reset_library_export_transient_state(
        self, scope: ExportScope | None = None
    ) -> None:
        """Clear the export canvas's scope/counts/form to defaults on entry.

        Called from both entry points into the export canvas -- the rail
        row's own ``_select_library_rail_row`` switch (always the default
        Everything ``scope``) and the browse-canvas "Export…" section
        actions (``_open_library_export_canvas``, their own pre-scoped
        ``ExportScope``) -- so neither a stale form from a previous Export
        visit nor a stale scope/counts pairing from a different section
        ever reappears. The name field re-stamps today's local date every
        time (mirrors the ingest form's own from-scratch reset), never
        carrying a previous visit's edited name forward.

        Also invalidates any export run still executing on its own OS
        thread (bumps ``_library_export_run_id``) -- navigating away mid-
        run resets ``running`` to ``False`` for THIS fresh visit, but the
        abandoned worker keeps running regardless (it cannot be preempted
        mid-``asyncio.run``); bumping the token here ensures that worker's
        eventual completion is recognized as stale and cannot stomp
        whatever the user is looking at by the time it lands. See
        ``_library_export_run_id``'s docstring in ``__init__``.

        Args:
            scope: The scope to open the canvas with; defaults to
                ``ExportScope(kind="everything")`` when omitted.
        """
        self._library_export_scope = scope or ExportScope(kind="everything")
        self._library_export_counts = None
        self._library_export_form = self._default_library_export_form()
        # task-14902: a fresh visit never inherits a half-open quality strip.
        self._library_export_quality_choices_visible = False
        self._library_export_running = False
        self._library_export_error = ""
        self._library_export_status = ""
        if self._library_export_cancel_event is not None:
            self._library_export_cancel_event.set()
        self._library_export_run_id += 1

    async def _open_library_export_canvas(self, scope: ExportScope) -> None:
        """Open the export canvas pre-scoped to a browse section's own filter.

        Wired to each browse canvas's "Export…" action (media/
        conversations/notes/Prompts) -- mirrors ``_select_library_rail_row``'s
        dirty-note-flush discipline for switching canvases, but only
        touches the export-specific state (the rail row's own switch
        already resets everything else on the way past); the caller's
        ``scope`` survives untouched (unlike a plain rail-row switch,
        which always resets to Everything).

        Args:
            scope: The section-specific scope to open the form with (e.g.
                ``ExportScope(kind="media", media_type=...)``).
        """
        if self._library_prompts_mutation_in_flight:
            return
        if self._library_export_is_server_mode():
            # The section "Export..." actions bypass the rail row's own
            # server-disabled gate, so re-check here (Qodo review): export
            # reads the LOCAL DBs, so running it while the Library is in
            # server runtime mode would package the wrong dataset.
            self.app_instance.notify(
                LIBRARY_EXPORT_SERVER_DISABLED_TOOLTIP, severity="warning"
            )
            return
        note_flush = await self._flush_library_note_save()
        if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
            return
        # task-4023 AC#7: remember which canvas opened Export so Escape
        # (action_library_export_back) can return there -- "Export… from
        # within Media navigates away with no return path". Recorded
        # AFTER the flush admits the switch, BEFORE the row id moves.
        self._library_export_origin_row_id = self._library_selected_row_id
        self._set_library_destination_with_conversation_fence(LIBRARY_ROW_INGEST_EXPORT)
        self._reset_library_export_transient_state(scope)
        # task-21116: rail selection + canvas-child swap only, never a
        # whole-screen rebuild for a per-click section "Export…" action.
        await self._apply_library_open_item_surface(
            lambda: LibraryExportCanvas(
                self._build_library_export_state(),
                id="library-export-canvas",
            )
        )
        self._start_library_export_counts_worker()

    def _library_export_is_server_mode(self) -> bool:
        """True when the Library is in server runtime mode.

        Export packages LOCAL content only (it reads the local media /
        ChaChaNotes / Prompt DBs), so both the rail Export row and the section
        "Export..." actions must refuse to run in server mode.
        """
        runtime_policy = getattr(self.app_instance, "runtime_policy", None)
        runtime_state = runtime_policy.state if runtime_policy is not None else None
        active_source = str(
            getattr(runtime_state, "active_source", "local") or "local"
        ).lower()
        return active_source == "server"

    def _resolve_library_export_chachanotes_db(self) -> Any:
        """Return the ChaChaNotes DB handle for export counts.

        Mirrors ``_resolve_library_notes_sync_db``'s exact access path
        (prefer ``app_instance.chachanotes_db``, fall back to
        ``notes_service.db``) -- the same canonical DB-access path this
        screen already uses elsewhere, per the F4 brief's requirement that
        the counts worker reach the DB the same way the rest of the
        screen does.
        """
        notes_service = getattr(self.app_instance, "notes_service", None)
        return getattr(self.app_instance, "chachanotes_db", None) or getattr(
            notes_service, "db", None
        )

    @staticmethod
    def _compute_library_export_counts(
        scope: ExportScope,
        media_db: Any,
        chachanotes_db: Any,
        prompts_db: Any,
    ) -> dict[str, int]:
        """Run the full-query, uncapped counts for ``scope`` (never a rendered snapshot).

        A quiet-degrade failure (a missing DB seam, an unexpected DB
        error) reports all-zero counts rather than raising -- the export
        canvas simply shows "Nothing to export in this scope." rather
        than crashing the recompose; the failure is still logged.
        """
        try:
            return count_export_scope(scope, media_db, chachanotes_db, prompts_db)
        except Exception as exc:
            logger.warning(
                "Library export counts failed scope_kind={} category={}",
                scope.kind,
                type(exc).__name__,
            )
            return {"media": 0, "conversations": 0, "notes": 0, "prompts": 0}

    def _start_library_export_counts_worker(self) -> None:
        """Kick off the export scope's full-query counts (Task 1's resolver).

        In-memory SQLite connections are thread-local -- only the thread
        that created/migrated the DB has a working connection.
        When any source DB is memory-backed (the test suite's fixtures, and
        any other future in-memory deployment), the count runs inline on
        the calling (UI) thread instead of a real worker thread -- a
        worker thread would only ever see a blank, unmigrated connection.
        A real (file-backed) deployment always takes the
        ``group="library_export_counts"`` worker-thread path.
        """
        self._library_export_counts_request_id += 1
        request_id = self._library_export_counts_request_id
        scope = self._library_export_scope
        generation = self._library_snapshot_state_generation
        route_key = self._library_entry_route_key()
        media_db = getattr(self.app_instance, "media_db", None)
        chachanotes_db = self._resolve_library_export_chachanotes_db()
        prompts_db = getattr(self.app_instance, "prompts_db", None)
        if (
            bool(getattr(media_db, "is_memory_db", False))
            or bool(getattr(chachanotes_db, "is_memory_db", False))
            or bool(getattr(prompts_db, "is_memory_db", False))
        ):
            counts = self._compute_library_export_counts(
                scope, media_db, chachanotes_db, prompts_db
            )
            result = self._apply_library_export_counts(
                scope,
                counts,
                generation=generation,
                route_key=route_key,
                request_id=request_id,
            )
            if (
                result is not LibraryEntryReconcileResult.APPLIED
                and self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT
                and route_key == self._library_entry_route_key()
            ):
                # During Screen.on_mount the screen is attached before its
                # composed Export child is queryable. Retry the same strict,
                # route-guarded field patch after that first refresh instead
                # of requiring a whole-screen recompose to expose the counts.
                self.call_after_refresh(
                    self._apply_library_export_counts,
                    scope,
                    counts,
                    generation=generation,
                    route_key=route_key,
                    request_id=request_id,
                )
            return
        self._run_library_export_counts_worker(
            scope,
            media_db,
            chachanotes_db,
            prompts_db,
            generation,
            route_key,
            request_id,
        )

    @work(thread=True, exclusive=True, group="library_export_counts")
    def _run_library_export_counts_worker(
        self,
        scope: ExportScope,
        media_db: Any,
        chachanotes_db: Any,
        prompts_db: Any,
        generation: int,
        route_key: tuple[object, ...],
        request_id: int,
    ) -> None:
        counts = self._compute_library_export_counts(
            scope, media_db, chachanotes_db, prompts_db
        )
        # ``self.app`` (Textual's own running-App property), not
        # ``self.app_instance`` -- ``call_from_thread`` needs the App whose
        # event loop is actually running this screen (see
        # ``_run_library_notes_sync``'s ``progress_callback`` for the full
        # reasoning). Guarded the same way: a shutdown mid-worker must
        # never surface as a crash.
        try:
            self.app.call_from_thread(
                self._apply_library_export_counts,
                scope,
                counts,
                generation=generation,
                route_key=route_key,
                request_id=request_id,
            )
        except Exception:
            # A shutdown/detach mid-marshal can raise RuntimeError OR
            # Textual's NoApp (which subclasses Exception, not RuntimeError)
            # -- either way the worker thread must not crash on teardown.
            pass

    def _apply_library_export_counts(
        self,
        scope: ExportScope,
        counts: dict[str, int],
        *,
        generation: int | None = None,
        route_key: tuple[object, ...] | None = None,
        request_id: int,
    ) -> LibraryEntryReconcileResult:
        """Marshal a landed counts result onto the export form (UI thread).

        Guards against a stale result from a scope the user has since
        navigated away from (a second "Export…" press, or another rail
        row entirely, before the first counts worker finished) -- dropped
        rather than overwriting fresher (or absent) counts.

        Updates the mounted canvas via targeted DOM surgery, NEVER a
        recompose (mirrors ``handle_library_ingest_path_changed``'s
        targeted-update discipline): the user may be mid-keystroke in the
        name/description ``Input`` when the counts land -- on a large
        library (this feature's whole point) that window is real -- and a
        recompose would destroy and rebuild the ``Input``, silently
        dropping keyboard focus (the typed text survives via the form
        dict; focus does not). Only three widgets can change when counts
        land, and all three are always-mounted on the export canvas: the
        scope line's text, the empty-scope helper's text/visibility
        (display-toggled rather than conditionally composed in
        ``LibraryExportCanvas.compose`` for exactly this reason), and the
        Export button's disabled gate. The media/quality rows CANNOT
        change here: their visibility (``show_media_fields``) derives
        purely from ``scope.kind``, which is pinned before the worker
        ever starts -- never from counts.

        Args:
            scope: The scope the landed ``counts`` were computed for.
            counts: The landed counts (keys "media"/"conversations"/"notes"/
                "prompts").
            request_id: Monotonic identity of the Export visit/count request.
        """
        if request_id != self._library_export_counts_request_id:
            return LibraryEntryReconcileResult.SUPERSEDED
        if scope != self._library_export_scope:
            return LibraryEntryReconcileResult.SUPERSEDED
        if (
            generation is not None
            and generation != self._library_snapshot_state_generation
        ):
            current_pending = (
                self._library_snapshot_state_generation,
                self._library_entry_route_key(),
            )
            if route_key == current_pending[1] and (
                self._library_entry_reconcile_pending == current_pending
                or self._library_entry_reconcile_dirty
                or self._library_snapshot_rendered_generation == current_pending[0]
            ):
                self.call_after_refresh(self._start_library_export_counts_worker)
            return LibraryEntryReconcileResult.SUPERSEDED
        if route_key is not None and route_key != self._library_entry_route_key():
            return LibraryEntryReconcileResult.SUPERSEDED
        if (
            not self.is_mounted
            or self._library_selected_row_id != LIBRARY_ROW_INGEST_EXPORT
        ):
            return LibraryEntryReconcileResult.SUPERSEDED
        generation = self._library_snapshot_state_generation
        active_route_key = self._library_entry_route_key()
        if not self._library_entry_reconcile_is_current(generation, active_route_key):
            return LibraryEntryReconcileResult.SUPERSEDED
        self._library_export_counts = counts
        state = self._build_library_export_state()
        try:
            canvas = self.query_one("#library-export-canvas", LibraryExportCanvas)
        except (NoMatches, QueryError):
            # Canvas not mounted (yet) -- the state fields above are set,
            # so whatever composes it next renders the landed counts.
            return LibraryEntryReconcileResult.FAILED
        # Keep the canvas's own state snapshot in step with what the
        # targeted updates below render, so any later widget-level
        # recompose can never resurrect the stale "Counting…" state.
        canvas.state = state
        try:
            self.query_one("#library-export-scope-line", Static).update(
                state.scope_line
            )
            empty_line = self.query_one("#library-export-empty-line", Static)
            empty_line.update(state.empty_scope_line)
            empty_line.display = bool(state.empty_scope_line)
            # task-2858 AC#3 (LIB-11): the tooltip flips in place with
            # `disabled`, same F-018 discipline as the select-mode
            # toolbar's export/delete buttons -- otherwise the compose-
            # time tooltip goes stale the moment counts land and this
            # patcher is the only thing that updates `disabled` here.
            # task-4023 AC#1: the shared gate helper also rebuilds the
            # "○"-marker label alongside `disabled` (recompose discipline).
            submit_button = self.query_one("#library-export-submit", Button)
            apply_library_export_submit_gate(submit_button, state)
        except (NoMatches, QueryError):
            return LibraryEntryReconcileResult.FAILED
        return LibraryEntryReconcileResult.APPLIED

    def _build_library_export_state(self) -> LibraryExportFormState:
        """Build the export canvas's full display state from screen fields."""
        form = self._library_export_form
        last_export_line = (
            format_last_export_line(
                self._library_export_last_path, self._library_export_last_at
            )
            if self._library_export_last_path
            and self._library_export_last_at is not None
            else ""
        )
        return build_library_export_form_state(
            scope=self._library_export_scope,
            counts=self._library_export_counts,
            name=str(form.get("name", "")),
            description=str(form.get("description", "")),
            media_quality=str(form.get("quality", DEFAULT_MEDIA_QUALITY)),
            destination=str(form.get("destination", "")),
            destination_exists=bool(form.get("destination_exists", False)),
            running=self._library_export_running,
            status_line=self._library_export_status,
            error_line=self._library_export_error,
            last_export_line=last_export_line,
            quality_choices_visible=self._library_export_quality_choices_visible,
        )

    # ----- Export canvas: execution (Task 3) ------------------------------

    @on(Button.Pressed, "#library-export-submit")
    def handle_library_export_submit(self, event: Button.Pressed) -> None:
        """Validate and kick off the chatbook export worker.

        Re-validates on the UI thread (destination chosen, scope non-empty,
        not already running) rather than trusting the button's ``disabled``
        state alone. A second press while an export is already running is a
        guarded no-op here (``self._library_export_running``) -- on top of
        the button itself being disabled while running and the worker's own
        ``group="library_export"``/``exclusive=True`` single-flight, this is
        belt-and-suspenders against a stale/racing ``Pressed`` event.

        The transition INTO ``running`` is the one place this feature uses
        a full recompose rather than a targeted update (see
        ``_update_library_export_canvas_after_run``'s docstring for the
        reverse transition's targeted-update discipline): the user's last
        action was clicking this button, not typing, so nothing is
        mid-keystroke -- unlike the counts-landing case Task 2 fixed, or
        the run-completion case below, where the (long-running) wait window
        gives the user time to resume typing in the still-editable name/
        description fields. Worker dispatch runs after that refresh so an
        immediate completion always targets the newly mounted running canvas,
        never the outgoing form that the recompose is replacing.
        """
        event.stop()
        if self._library_export_running:
            return
        form = self._library_export_form
        destination = str(form.get("destination", "")).strip()
        counts = self._library_export_counts
        total = sum(counts.values()) if counts else 0
        if not destination or total <= 0:
            return
        if self._library_export_is_server_mode():
            # Defense in depth: the rail row and section actions already
            # gate on server mode, but re-check at submit in case the
            # runtime source flipped while the form was open (Qodo review).
            self.app_instance.notify(
                LIBRARY_EXPORT_SERVER_DISABLED_TOOLTIP, severity="warning"
            )
            return
        # Sanitize name/description at the UI boundary before they flow into
        # the export payload, chatbook manifest, and Artifacts registry
        # (Qodo review) -- bound length + strip unsafe content via the shared
        # input_validation helpers, mirroring the media-field path.
        name = self._safe_text(form.get("name", ""), "Chatbook", max_length=200)
        description = self._safe_text(form.get("description", ""), "", max_length=2000)
        media_quality = str(form.get("quality", DEFAULT_MEDIA_QUALITY))
        self._library_export_running = True
        self._library_export_error = ""
        self._library_export_status = f"Exporting… ({total} items)"
        self._library_export_run_id += 1
        run_id = self._library_export_run_id
        self._library_export_cancel_event = threading.Event()
        cancel_event = self._library_export_cancel_event
        self.refresh(recompose=True)
        self.call_after_refresh(self._sync_library_emergency_guard_presentation)
        self.call_after_refresh(
            self._start_library_export_worker,
            run_id=run_id,
            scope=self._library_export_scope,
            name=name,
            description=description,
            media_quality=media_quality,
            destination=destination,
            cancel_event=cancel_event,
        )

    @on(Button.Pressed, "#library-export-cancel")
    def handle_library_export_cancel(self, event: "Button.Pressed") -> None:
        """Request cancellation of the in-flight export.

        Sets the worker's cancel Event (idempotent) and flips the status line to
        "Cancelling…". Deliberately does NOT bump _library_export_run_id: the run
        is still the current, visible one until the worker reports back with the
        cancelled outcome (see _apply_library_export_cancelled).
        """
        if not self._library_export_running:
            return
        if event is not None:
            event.stop()
        event_obj = self._library_export_cancel_event
        if event_obj is not None:
            event_obj.set()
        self._library_export_status = "Cancelling…"
        self._refresh_library_export_status_line()

    def _start_library_export_worker(
        self,
        *,
        run_id: int,
        scope: ExportScope,
        name: str,
        description: str,
        media_quality: str,
        destination: str,
        cancel_event: threading.Event,
    ) -> None:
        """Resolve selections (memory-DB-safe), then dispatch the real export worker.

        Mirrors ``_start_library_export_counts_worker``'s memory-vs-file-
        backed DB branch for the id-resolution step specifically: a genuine
        OS worker thread only ever sees a blank, unmigrated connection for
        an in-memory-backed DB (``threading.local``), so when any source DB is
        memory-backed, ``resolve_export_selections`` -- a pure, synchronous
        DB read with no ``asyncio`` involvement -- runs inline on the
        calling (UI) thread first, exactly like the counts worker's own
        inline fallback, and the resolved ids are handed to the worker.

        Unlike the counts worker, the ``@work(thread=True)`` dispatch below
        is never skipped: ``asyncio.run(service.export_chatbook(...))``
        would raise ("cannot be called from a running event loop") if
        invoked directly on the UI thread, which already owns Textual's
        own running event loop. A file-backed deployment defers
        ``resolve_export_selections`` into that same real thread instead
        (``preresolved_selections=None``), avoiding a synchronous full-
        library scan on the UI thread for the common (real, file-backed)
        case.
        """
        media_db = getattr(self.app_instance, "media_db", None)
        chachanotes_db = self._resolve_library_export_chachanotes_db()
        prompts_db = getattr(self.app_instance, "prompts_db", None)
        preresolved_selections: dict[ContentType, list[str]] | None = None
        if (
            bool(getattr(media_db, "is_memory_db", False))
            or bool(getattr(chachanotes_db, "is_memory_db", False))
            or bool(getattr(prompts_db, "is_memory_db", False))
        ):
            try:
                preresolved_selections = resolve_export_selections(
                    scope, media_db, chachanotes_db, prompts_db
                )
            except Exception as exc:
                logger.warning(
                    "Library export selection resolution failed "
                    "scope_kind={} category={}",
                    scope.kind,
                    type(exc).__name__,
                )
                self._apply_library_export_failure(
                    run_id, "Unable to resolve export selections."
                )
                return
        self._run_library_export_worker(
            run_id=run_id,
            scope=scope,
            name=name,
            description=description,
            media_quality=media_quality,
            destination=destination,
            media_db=media_db,
            chachanotes_db=chachanotes_db,
            prompts_db=prompts_db,
            preresolved_selections=preresolved_selections,
            cancel_event=cancel_event,
        )

    @staticmethod
    def _build_library_export_payload(
        *,
        name: str,
        description: str,
        selections: Mapping[ContentType, list[str]],
        destination: str,
        media_quality: str,
    ) -> dict[str, Any]:
        """Build the ``local_chatbook_service.export_chatbook`` request payload.

        ``include_media`` is spec-critical (F4 plan Global Constraints):
        it MUST be ``True`` whenever ``ContentType.MEDIA`` is present in
        ``selections`` -- ``ChatbookCreator`` silently skips all media
        content otherwise, even when media ids ARE present in
        ``content_selections``. Since ``resolve_export_selections`` omits
        a ``ContentType`` key entirely when that source resolves zero ids
        (see its docstring), keying off simple membership is automatically
        correct for every scope, including an "everything" scope whose
        library happens to have no media at all.
        """
        return {
            "name": name,
            "description": description,
            "content_selections": dict(selections),
            "output_path": destination,
            "media_quality": media_quality,
            "include_media": ContentType.MEDIA in selections,
        }

    @staticmethod
    def _run_library_export_via_service(
        service: Any,
        payload: dict[str, Any],
        *,
        name: str,
        description: str,
        progress_callback=None,
        cancel_check=None,
    ) -> dict[str, Any]:
        """Execute one export through ``service``, synchronously: zip first, registry only on success.

        Runs both of ``service``'s async-signature/sync-body methods
        through ``asyncio.run`` -- they never touch the app's own event
        loop, so this is only ever safe to call from a genuine OS thread
        (never the UI thread, which already owns a running loop). Exposed
        as its own (non-``@work``) static method so tests can call it
        directly with a fake ``service`` and assert call ordering /
        the include_media invariant without booting a real thread.

        ``create_chatbook`` (the registry record) is attempted ONLY when
        ``export_chatbook`` reports ``success`` -- the F4 plan's Global
        Constraints' "zip first, registry record only on success". A
        registry-recording failure AFTER a successful zip does not flip
        the overall outcome to failure (the artifact genuinely exists on
        disk; only the bookkeeping failed) -- ``registry_recorded``
        reports that separately for callers/tests that care.

        Returns a plain dict: ``success``, ``message``, ``path``,
        ``dependency_info``, ``registry_recorded``.
        """
        try:
            export_result = asyncio.run(  # policy-exception: worker-thread loop
                service.export_chatbook(
                    payload,
                    progress_callback=progress_callback,
                    cancel_check=cancel_check,
                )
            )
        except Exception as exc:
            logger.opt(exception=True).warning("Library export service call failed.")
            return {
                "success": False,
                "message": f"Export failed: {exc}",
                "path": "",
                "dependency_info": {},
                "registry_recorded": False,
                "cancelled": False,
            }

        if not export_result.get("success"):
            return {
                "success": False,
                "message": str(export_result.get("message") or "Export failed."),
                "path": export_result.get("path") or payload.get("output_path", ""),
                "dependency_info": export_result.get("dependency_info") or {},
                "registry_recorded": False,
                "cancelled": bool(export_result.get("cancelled", False)),
            }

        output_path = export_result.get("path") or payload.get("output_path", "")
        dependency_info = export_result.get("dependency_info") or {}
        registry_recorded = False
        try:
            asyncio.run(  # policy-exception: worker-thread loop
                service.create_chatbook(
                    name=name,
                    description=description,
                    file_path=output_path,
                    tags=["library-export"],
                )
            )
            registry_recorded = True
        except Exception:
            logger.opt(exception=True).warning(
                f"Library export succeeded but registry recording failed for {output_path!r}."
            )

        return {
            "success": True,
            "message": export_result.get("message") or "",
            "path": output_path,
            "dependency_info": dependency_info,
            "registry_recorded": registry_recorded,
            "cancelled": False,
        }

    @work(thread=True, exclusive=True, group="library_export")
    def _run_library_export_worker(
        self,
        *,
        run_id: int,
        scope: ExportScope,
        name: str,
        description: str,
        media_quality: str,
        destination: str,
        media_db: Any,
        chachanotes_db: Any,
        prompts_db: Any,
        preresolved_selections: dict[ContentType, list[str]] | None,
        cancel_event: threading.Event | None,
    ) -> None:
        if preresolved_selections is not None:
            selections = preresolved_selections
        else:
            try:
                selections = resolve_export_selections(
                    scope, media_db, chachanotes_db, prompts_db
                )
            except Exception as exc:
                logger.warning(
                    "Library export selection resolution failed "
                    "scope_kind={} category={}",
                    scope.kind,
                    type(exc).__name__,
                )
                self._marshal_library_export_failure(
                    run_id, "Unable to resolve export selections."
                )
                return

        service = getattr(self.app_instance, "local_chatbook_service", None)
        if service is None:
            self._marshal_library_export_failure(
                run_id, "Bundle export service unavailable."
            )
            return

        payload = self._build_library_export_payload(
            name=name,
            description=description,
            selections=selections,
            destination=destination,
            media_quality=media_quality,
        )
        throttle = ExportProgressThrottle()

        def _progress_cb(evt) -> None:
            try:
                if not throttle.should_emit(
                    evt.phase, evt.current, evt.total, time.monotonic()
                ):
                    return
                self.app.call_from_thread(
                    self._apply_library_export_progress,
                    run_id,
                    evt.phase,
                    evt.current,
                    evt.total,
                )
            except Exception:
                # NoApp/shutdown mid-marshal must not crash the worker.
                pass

        outcome = self._run_library_export_via_service(
            service,
            payload,
            name=name,
            description=description,
            progress_callback=_progress_cb,
            cancel_check=(cancel_event.is_set if cancel_event is not None else None),
        )
        if outcome.get("cancelled"):
            self._marshal_library_export_cancelled(run_id)
        elif outcome["success"]:
            self._marshal_library_export_success(
                run_id,
                outcome["path"],
                outcome["dependency_info"],
                bool(outcome["registry_recorded"]),
                outcome["message"],
            )
        else:
            self._marshal_library_export_failure(run_id, outcome["message"])

    def _marshal_library_export_success(
        self,
        run_id: int,
        path: str,
        dependency_info: Any,
        registry_recorded: bool,
        message: str = "",
    ) -> None:
        """Marshal a successful run onto the UI thread (called from the worker)."""
        try:
            self.app.call_from_thread(
                self._apply_library_export_success,
                run_id,
                path,
                dependency_info,
                registry_recorded,
                message,
            )
        except Exception:
            # A shutdown/detach mid-marshal can raise RuntimeError OR
            # Textual's NoApp (which subclasses Exception, not RuntimeError)
            # -- either way the worker thread must not crash on teardown.
            pass

    def _marshal_library_export_failure(self, run_id: int, message: str) -> None:
        """Marshal a failed run onto the UI thread (called from the worker)."""
        try:
            self.app.call_from_thread(
                self._apply_library_export_failure, run_id, message
            )
        except Exception:
            # A shutdown/detach mid-marshal can raise RuntimeError OR
            # Textual's NoApp (which subclasses Exception, not RuntimeError)
            # -- either way the worker thread must not crash on teardown.
            pass

    def _marshal_library_export_cancelled(self, run_id: int) -> None:
        """Marshal a cancelled run onto the UI thread (called from the worker)."""
        try:
            self.app.call_from_thread(self._apply_library_export_cancelled, run_id)
        except Exception:
            # A shutdown/detach mid-marshal can raise RuntimeError OR
            # Textual's NoApp (which subclasses Exception, not RuntimeError)
            # -- either way the worker thread must not crash on teardown.
            pass

    def _apply_library_export_cancelled(self, run_id: int) -> None:
        """UI-thread completion for a cancelled run: clear running, show cancelled, return to form."""
        if run_id != self._library_export_run_id:
            return
        self._library_export_running = False
        self._library_export_status = "Export cancelled."
        self._library_export_error = ""
        self._sync_library_emergency_guard_presentation()
        self._update_library_export_canvas_after_run()

    @staticmethod
    def _build_library_export_success_message(
        path: Any, dependency_info: Any, creator_message: Any = ""
    ) -> str:
        """Build the success notification text.

        Three pieces, in order:

        1. The destination path (always present), ``escape_markup``'d:
           Textual notifications render Rich console markup, so a
           user-chosen path containing ``[...]`` (legal in filenames on
           any platform) would otherwise mis-render or raise in the
           markup parser.
        2. The creator's own ``outcome["message"]`` detail (task-158):
           ``ChatbookCreator.create_chatbook`` returns a message carrying
           its own counts (e.g. missing-dependency warnings) that was
           previously discarded entirely by the caller. Its redundant
           ``"Chatbook created successfully at <path>"`` prefix -- the
           path is already the primary notify line above -- is stripped
           so only the actual detail remains; an unrecognized message
           shape (e.g. a different service implementation) is kept
           verbatim rather than guessed at.
        3. The ``dependency_info.get("auto_included")`` count suffix (the
           character ids ``ChatbookCreator`` pulled in automatically as
           conversation dependencies) -- BUT only when the creator detail
           above does not already state it. ``create_chatbook`` already
           puts an ``"Auto-included N character dependencies"`` clause
           into its own message (that clause and ``auto_included`` derive
           from the same ``self.auto_included_characters`` state), so
           emitting the suffix on top of a detail that carries that clause
           would restate the identical fact twice. The suffix therefore
           only fires when the auto-included count would otherwise go
           unstated (e.g. an empty creator message, or a creator message
           whose only detail is a missing-dependency warning).
        """
        message = f"Exported bundle to {escape_markup(str(path))}"

        detail = str(creator_message or "").strip()
        known_prefix = f"Chatbook created successfully at {path}"
        if detail.startswith(known_prefix):
            detail = detail[len(known_prefix) :].strip(" .")
        if detail:
            message += f": {escape_markup(detail)}"

        auto_included = (
            dependency_info.get("auto_included")
            if isinstance(dependency_info, dict)
            else None
        )
        # De-dup: skip the suffix when the surfaced detail already states
        # the auto-included count (see point 3 above).
        if auto_included and "auto-included" not in detail.lower():
            try:
                count = len(auto_included)
            except TypeError:
                count = auto_included
            message += f" ({count} characters auto-included)"

        return message

    def _apply_library_export_success(
        self,
        run_id: int,
        path: str,
        dependency_info: Any,
        registry_recorded: bool,
        message: str = "",
    ) -> None:
        """UI-thread completion: notify, clear running/error, update the form.

        See ``_build_library_export_success_message`` for how the
        notification text itself (path + creator detail + auto-included
        count) is assembled.

        ``registry_recorded=False`` (the zip succeeded but the
        ``create_chatbook`` registry step failed -- see
        ``_run_library_export_via_service``) fires a SECOND, warning-
        severity notification: without it the export silently never
        appears under Artifacts/Home and the user has no way to know why.
        It fires alongside the primary notification, BEFORE the staleness
        guard, deliberately: both report persistent facts about what
        actually happened on disk/in the registry, independent of which
        canvas the user is now looking at -- and the warning matters MOST
        for a superseded run, since a user who already navigated away
        would otherwise never learn the artifact is missing from
        Artifacts.

        ``run_id`` is compared against the live ``_library_export_run_id``
        BEFORE any state/DOM mutation: an export genuinely finished, so the
        notifications always fire, but a run the user has since navigated
        away from (see ``_library_export_run_id``'s docstring) must not
        stomp ``_library_export_running``/``_error``/``_status`` or the
        canvas DOM out from under whatever the user is now looking at.

        The task-2858 AC#3 (LIB-12) receipt fields
        (``_library_export_last_path``/``_last_at``) are set here too,
        BEFORE the staleness guard, for the identical reason the
        notifications above are unconditional: the zip genuinely landed on
        disk regardless of which run/canvas is currently displayed. The
        canvas DOM patch that renders the new receipt text still only
        happens for the live run (inside
        ``_update_library_export_canvas_after_run``, guarded below) -- a
        superseded run's receipt becomes visible the next time this
        screen's export state is rebuilt (e.g. the next canvas entry or
        the next completed run), never retroactively rewriting what the
        user is looking at right now.
        """
        notify_message = self._build_library_export_success_message(
            path, dependency_info, message
        )
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(notify_message, severity="information")
            if not registry_recorded:
                notify(
                    "Export saved, but couldn't be registered — it won't "
                    "appear under Artifacts.",
                    severity="warning",
                )
        self._library_export_last_path = str(path)
        self._library_export_last_at = time.time()
        if run_id != self._library_export_run_id:
            return
        self._library_export_running = False
        self._library_export_error = ""
        self._library_export_status = ""
        self._sync_library_emergency_guard_presentation()
        self._update_library_export_canvas_after_run()

    def _apply_library_export_failure(self, run_id: int, message: str) -> None:
        """UI-thread completion: render the escaped error, clear running, re-enable Export.

        See ``_apply_library_export_success``'s docstring for the
        ``run_id`` staleness guard -- a superseded run's failure is
        dropped silently here (no error line to render it into, since the
        canvas may now belong to a different scope/visit entirely) rather
        than notified, since surfacing a failure banner for a run the user
        has already navigated away from and possibly re-run successfully
        would be actively misleading.
        """
        if run_id != self._library_export_run_id:
            logger.info(
                f"Library export run {run_id} failed after being superseded "
                f"(current run {self._library_export_run_id}): {message}"
            )
            return
        self._library_export_running = False
        self._library_export_status = ""
        self._library_export_error = escape_markup(str(message))
        self._sync_library_emergency_guard_presentation()
        self._update_library_export_canvas_after_run()

    def _apply_library_export_progress(
        self, run_id: int, phase: str, current: int, total: int
    ) -> None:
        """UI-thread progress tick: update the status line in place if this run is current."""
        if run_id != self._library_export_run_id or not self._library_export_running:
            return
        self._library_export_status = format_export_progress_line(phase, current, total)
        self._refresh_library_export_status_line()

    def _refresh_library_export_status_line(self) -> None:
        """Update only the #library-export-status-line widget (no recompose)."""
        if (
            not self.is_mounted
            or self._library_selected_row_id != LIBRARY_ROW_INGEST_EXPORT
        ):
            return
        try:
            widget = self.query_one("#library-export-status-line", Static)
            widget.update(self._library_export_status)
            widget.display = bool(self._library_export_status)
        except (NoMatches, QueryError):
            pass

    def _update_library_export_canvas_after_run(self) -> None:
        """Targeted DOM update once an export run finishes (success or failure).

        Mirrors ``_apply_library_export_counts``'s targeted-update
        discipline (Task 2's fix, commit 7793257e): the transition OUT of
        ``running`` must not recompose. Unlike the Export-press transition
        INTO ``running`` (a recompose is acceptable there -- see
        ``handle_library_export_submit``'s docstring), the running window
        itself can be long enough for the user to resume typing in the
        name/description ``Input`` while waiting (nothing disables those
        fields during ``running``) -- a recompose on completion would
        destroy and rebuild that ``Input`` out from under them, silently
        dropping keyboard focus. Only the status line, the error line, the
        task-2858 AC#3 (LIB-12) receipt line, and the Export button's
        disabled/tooltip gate can change here; all three lines are
        unconditionally mounted by ``LibraryExportCanvas.compose`` (display-
        toggled, never conditionally yielded) specifically so this in-place
        update always finds them, mirroring the empty-scope helper's own
        always-mounted precedent from Task 2's fix.
        """
        if (
            not self.is_mounted
            or self._library_selected_row_id != LIBRARY_ROW_INGEST_EXPORT
        ):
            return
        state = self._build_library_export_state()
        try:
            canvas = self.query_one("#library-export-canvas", LibraryExportCanvas)
        except (NoMatches, QueryError):
            return
        canvas.state = state
        try:
            status_widget = self.query_one("#library-export-status-line", Static)
            status_widget.update(state.status_line)
            status_widget.display = bool(state.status_line)
            error_widget = self.query_one("#library-export-error-line", Static)
            error_widget.update(state.error_line)
            error_widget.display = bool(state.error_line)
            # task-2858 AC#3 (LIB-12): the durable receipt -- rendered from
            # ``_library_export_last_path``/``_last_at``, set by
            # ``_apply_library_export_success`` just before this runs on a
            # genuine success completion.
            last_export_widget = self.query_one("#library-export-last-line", Static)
            last_export_widget.update(state.last_export_line)
            last_export_widget.display = bool(state.last_export_line)
            submit_button = self.query_one("#library-export-submit", Button)
            # task-4023 AC#1: disabled + "○"-marker label + F-018 tooltip
            # through the one shared gate helper (recompose discipline).
            apply_library_export_submit_gate(submit_button, state)
            self.query_one("#library-export-cancel", Button).display = bool(
                state.running
            )
        except (NoMatches, QueryError):
            pass

    def _library_ingest_registry(self) -> Any:
        """Return the app's ingest job registry, or ``None`` when absent."""
        return getattr(self.app_instance, "library_ingest_jobs", None)

    def _handle_library_ingest_registry_changed(self) -> None:
        """Registry listener: live-recompose the ingest canvas + poke the
        source snapshot when a job finishes (Task 5).

        Registered against ``self.app_instance.library_ingest_jobs`` in
        ``on_mount``, removed in ``on_unmount``. Per the registry's own
        contract (``LibraryIngestJobRegistry._notify_listeners``), this
        fires synchronously on the UI thread after every successful
        ``submit``/``mark_parsing``/``mark_writing``/``mark_done``/
        ``mark_failed``/``requeue`` -- from two different call shapes:

        - **Synchronously inside a message handler.** "Start import" and
          ordinary Library "Retry" actions mutate the registry (firing this
          listener) before their handler's trailing dynamic-region update.
          A Research-owned retry is scheduled through its durable operation
          owner and fires the listener when that owner persists its replacement.
        - **Marshaled from a background thread**, via ``call_from_thread``
          for ``mark_parsing``/``mark_writing`` (the F3 parse-pool
          coordinator, itself invoked from a pool callback thread) and
          ``mark_done``/``mark_failed`` (the writer's worker thread) --
          these land outside any message handler, as their own turn of the
          UI event loop.

        Both shapes are safe to handle with a plain, synchronous
        ``self.refresh(recompose=True)`` call (no ``call_after_refresh``
        indirection needed): ``Widget.refresh(recompose=True)`` never
        recomposes inline -- it only sets ``_recompose_required = True``
        and schedules the actual (async) ``_check_recompose`` via
        ``call_next``, which runs on a later turn of the event loop. That
        makes calling it redundant, or from inside another handler that
        will also call it, harmless: the flag is idempotent and the
        second scheduled check becomes a no-op once the first has already
        cleared it. (Verified by reading
        ``textual.widget.Widget.refresh``/``_check_recompose`` -- Textual
        8.2.7.)

        Behavior:

        - Recomposes the canvas ONLY when the ingest canvas is the
          currently selected rail row -- a job transition must never yank
          a user looking at a different canvas away from it.
        - Independently of the canvas recompose, pokes
          ``_refresh_local_source_snapshot()`` (which updates the rail's
          ``Media (N)`` count) whenever the registry's done-job count has
          grown since this screen last checked -- deduped via
          ``_library_ingest_last_done_count`` so a running/failed
          transition (or a second notification for the same completed
          job) never re-triggers the snapshot fetch. This fires
          regardless of which canvas is selected, since the rail is
          always visible.
        - A no-op when the screen isn't mounted -- belt-and-braces
          alongside ``on_unmount``'s removal (see that method's
          docstring for why removal can't simply happen earlier, e.g. on
          suspend). Note ``self.is_mounted`` never flips back to
          ``False`` after removal in this Textual version -- it only
          guards a callback that somehow fires before this screen's very
          first mount -- so ``on_unmount``'s ``remove_listener`` call is
          what actually prevents post-teardown notifications, not this
          guard.
        """
        if not self.is_mounted:
            return
        armed = getattr(self, "_library_ingest_start_consent", None)
        if armed is not None:
            submitted_source = self._library_ingest_form.path.strip()
            pending = self._current_library_ingest_start_consent(submitted_source)
            # Lifecycle tokens are deliberately absent from the
            # fingerprint. Only a different set of active jobs invalidates
            # what the user armed against on a registry tick.
            if (
                pending.active_job_ids != armed.active_job_ids
                and not self._authoritative_library_ingest_consent_is_current(
                    armed, pending
                )
            ):
                self._disarm_library_ingest_start_confirm()
        if self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA:
            self._update_library_ingest_dynamic_regions()
            shortcuts = self._library_ingest_shortcuts_for_current_state()
            registration = ("library", tuple(shortcuts))
            if self._footer_shortcut_registration != registration:
                self.register_footer_shortcuts(source="library", shortcuts=shortcuts)
        registry = self._library_ingest_registry()
        counts_fn = getattr(registry, "counts", None)
        counts = counts_fn() if callable(counts_fn) else {}
        # (task-2015) Any registry mutation disarms a pending two-press
        # "Clear finished": the queue the user armed against just changed.
        self._library_ingest_clear_finished_armed = False
        # (task-2015) Batch-settle toast: when the active-job count crosses
        # 0 -> N a baseline of (done, failed) is captured; on N -> 0 one
        # summary toast reports the deltas -- the only above-the-fold
        # completion signal on a queue that renders below it.
        active_count = (
            counts.get("queued", 0)
            + counts.get("parsing", 0)
            + counts.get("writing", 0)
        )
        previous_active = self._library_ingest_last_active_count
        self._library_ingest_last_active_count = active_count
        done_now = counts.get("done", 0)
        failed_now = counts.get("failed", 0)
        skipped_now = counts.get("skipped", 0)
        # (task-2041) A dedup match reaches DONE without importing anything;
        # counting it as "imported" made the toast contradict the row copy.
        # Matches are recognised by the writer's progress-message prefix
        # (shared constant, so the two can never drift).
        # (task-2042 review) The registry's internal counter avoids a second
        # deep-copy ``jobs()`` snapshot per tick; the pure-function fallback
        # keeps test doubles working.
        matched_counter = getattr(registry, "count_duplicate_done", None)
        if callable(matched_counter):
            matched_now = matched_counter()
        else:
            jobs_fn = getattr(registry, "jobs", None)
            matched_now = count_duplicate_done_jobs(
                jobs_fn() if callable(jobs_fn) else ()
            )
        (
            baseline_done,
            baseline_failed,
            baseline_matched,
            baseline_skipped,
        ) = self._library_ingest_batch_baseline
        if (
            done_now < baseline_done
            or failed_now < baseline_failed
            or matched_now < baseline_matched
            or skipped_now < baseline_skipped
        ):
            # (task-2015 review) Clear/dismiss mid-batch shrinks DONE/FAILED
            # below the baseline; without re-anchoring, the settle deltas go
            # negative and completions after the clear vanish from the
            # toast.
            baseline_done = min(baseline_done, done_now)
            baseline_failed = min(baseline_failed, failed_now)
            baseline_matched = min(baseline_matched, matched_now)
            baseline_skipped = min(baseline_skipped, skipped_now)
            self._library_ingest_batch_baseline = (
                baseline_done,
                baseline_failed,
                baseline_matched,
                baseline_skipped,
            )
        if previous_active == 0 and active_count > 0:
            self._library_ingest_batch_baseline = (
                done_now,
                failed_now,
                matched_now,
                skipped_now,
            )
        elif previous_active > 0 and active_count == 0:
            (
                baseline_done,
                baseline_failed,
                baseline_matched,
                baseline_skipped,
            ) = self._library_ingest_batch_baseline
            matched = max(0, matched_now - baseline_matched)
            imported = (done_now - baseline_done) - matched
            failed = failed_now - baseline_failed
            skipped = max(0, skipped_now - baseline_skipped)
            if imported > 0 or matched > 0 or failed > 0 or skipped > 0:
                parts = []
                if imported > 0:
                    parts.append(f"{imported} imported")
                if matched > 0:
                    # (task-2837) The forecast says "will match"; the
                    # toast answers in the same word.
                    parts.append(f"{matched} matched")
                if skipped > 0:
                    parts.append(f"{skipped} skipped")
                if failed > 0:
                    parts.append(f"{failed} failed")
                notify = getattr(self.app_instance, "notify", None)
                if callable(notify):
                    # (task-2220) Skips are neutral and never warn on
                    # their own (failed == 0 -> information). Real failures
                    # with zero successes DO warn even when skips are also
                    # present -- something the user pointed at genuinely
                    # broke and nothing landed.
                    notify(
                        "Import finished — " + " · ".join(parts),
                        severity=(
                            "information"
                            if imported > 0 or matched > 0 or failed == 0
                            else "warning"
                        ),
                    )
        done_count = counts.get("done", 0)
        if done_count != self._library_ingest_last_done_count:
            grew = done_count > self._library_ingest_last_done_count
            self._library_ingest_last_done_count = done_count
            if grew:
                self._refresh_local_source_snapshot()
        attention = self._library_landing_attention_action()
        if attention != self._library_landing_attention_signature:
            self._library_landing_attention_signature = attention
            if not self._library_selected_row_id:
                self._sync_library_landing_lifecycle_presentation()

    def _handle_library_ingest_progress_changed(
        self,
        before: LibraryIngestJob,
        after: LibraryIngestJob,
    ) -> None:
        """Patch ordinary ingest telemetry without disturbing queue context.

        Progress updates cannot change lifecycle state, origin, result ids,
        error detail, or terminal actions. Local-STT cancellation is the one
        progress-owned structural exception: its action signature replaces
        Cancel with Force stop and therefore recomposes the dynamic regions.

        Args:
            before: Job snapshot immediately before the progress mutation.
            after: Job snapshot immediately after the progress mutation.
        """
        if (
            not self.is_attached
            or self._library_selected_row_id != LIBRARY_ROW_INGEST_MEDIA
        ):
            return
        if ingest_progress_action_signature(before) != ingest_progress_action_signature(
            after
        ):
            self._update_library_ingest_dynamic_regions()
            return
        try:
            progress_widget = self.query_one(
                f"#library-ingest-progress-{after.job_id}", Static
            )
        except (NoMatches, QueryError):
            return
        progress = after.progress
        if progress is None and after.state is IngestJobState.WRITING:
            progress = {"phase": "writing"}
        progress_widget.update(format_ingest_progress_line(progress, state=after.state))
        progress_widget.display = True

    def _refresh_library_ingest_canvas_preserving_context(self) -> None:
        """Recompose for a job-tick WITHOUT losing what the user was doing.

        ``refresh(recompose=True)`` remounts every widget: focus silently
        falls to the screen (so the user's next keystrokes hit the global
        digit bindings and navigate the app) and the canvas scroll snaps to
        the top on every queue transition. Capture focus id + cursor +
        scroll before scheduling the recompose, restore after -- the same
        remount-focus-loss family as ``_focus_library_search_input`` and
        the rail's ``scroll_to`` restore (task-2010).
        """
        focused = self.app.focused
        focused_id = getattr(focused, "id", None) if focused is not None else None
        cursor = (
            focused.cursor_position
            if focused_id is not None and isinstance(focused, Input)
            else None
        )
        scroll_y: float | None = None
        try:
            canvas = self.query_one(LibraryIngestCanvas)
            scroll_y = canvas.scroll_offset.y
        except (NoMatches, QueryError):
            pass
        if focused_id == "library-ingest-path":
            scroll_y = 0
        # (task-3311, second half) ``refresh(recompose=True)`` is DEFERRED:
        # the path Input below stays mounted, focused, and typeable until
        # the recompose actually runs, and whatever the user types into it
        # in that window is thrown away with the widget -- measured live
        # as 5/5 characters lost within ~150ms of Clear, 3/3 surviving at
        # >=400ms. Keeping the WIDGET (not a copy of its text) lets the
        # restore below read the value it ended up holding, which is the
        # only place those keystrokes exist. The value AT CAPTURE TIME
        # comes along as the discriminator: a difference means the user
        # typed during the window, whereas an unchanged stale value beside
        # a deliberately rewritten form (the retry re-stage) must be left
        # alone.
        stale_path_input: Input | None = None
        try:
            stale_path_input = self.query_one("#library-ingest-path", Input)
        except (NoMatches, QueryError):
            pass
        stale_path_value = (
            stale_path_input.value if stale_path_input is not None else None
        )
        self.refresh(recompose=True)
        if (
            focused_id is not None
            or scroll_y is not None
            or stale_path_input is not None
        ):
            self.call_after_refresh(
                self._restore_library_ingest_canvas_context,
                focused_id,
                cursor,
                scroll_y,
                stale_path_input,
                stale_path_value,
            )

    def _restore_library_ingest_canvas_context(
        self,
        focused_id: str | None,
        cursor: int | None,
        scroll_y: float | None,
        stale_path_input: Input | None = None,
        stale_path_value: str | None = None,
    ) -> None:
        """Re-apply focus/cursor/scroll captured before a job-tick recompose.

        Scroll first, then focus with ``scroll_visible=False`` so restoring
        focus does not itself yank the scroll position. A vanished widget id
        (a finished job's row-action button) degrades silently (task-2010).

        Also rescues keystrokes that raced the recompose (task-3311's
        second half): the replaced path Input is the only holder of text
        typed between scheduling and applying the rebuild. Adoption is
        gated on the widget's value having CHANGED since capture, so a
        deliberate form rewrite under an untouched field (the retry
        re-stage) is never undone by a stale echo. The value is written to
        the live Input rather than to the form echo, so the ordinary
        ``Input.Changed`` seam runs the whole follow-through (gate, Clear
        button, intro lines, the pre-flight debounce) exactly once.

        Args:
            focused_id: Id of the widget focused before the recompose.
            cursor: That widget's cursor position, when it was an ``Input``.
            scroll_y: The canvas's scroll offset before the recompose.
            stale_path_input: The pre-recompose path ``Input`` object.
            stale_path_value: That widget's value at capture time.
        """
        if scroll_y is not None:
            try:
                canvas = self.query_one(LibraryIngestCanvas)
                canvas.scroll_to(y=scroll_y, animate=False, force=True)
            except (NoMatches, QueryError):
                pass
        raced_text: str | None = None
        if (
            stale_path_input is not None
            and stale_path_value is not None
            and stale_path_input.value != stale_path_value
        ):
            raced_text = stale_path_input.value
        if raced_text is not None:
            try:
                live_path = self.query_one("#library-ingest-path", Input)
            except (NoMatches, QueryError):
                live_path = None
            if live_path is not None and live_path.value != raced_text:
                live_path.value = raced_text
                live_path.cursor_position = len(raced_text)
                if focused_id == "library-ingest-path":
                    cursor = len(raced_text)
        if not focused_id:
            return
        try:
            widget = self.query_one(f"#{focused_id}")
        except (NoMatches, QueryError):
            return
        widget.focus(scroll_visible=False)
        if cursor is not None and isinstance(widget, Input):
            widget.cursor_position = min(cursor, len(widget.value))

    def _update_library_ingest_gate(self, new_state: LibraryIngestCanvasState) -> None:
        """Sync the Start button + gate line in place (never a recompose).

        Args:
            new_state: The freshly built canvas state whose
                ``start_enabled``/``start_quiet_line`` are applied to the
                live widgets.
        """
        try:
            start_button = self.query_one("#library-ingest-start", Button)
        except (NoMatches, QueryError):
            return
        start_button.disabled = not new_state.start_enabled
        try:
            commit_bar = self.query_one("#library-ingest-commit-bar", Vertical)
        except (NoMatches, QueryError):
            pass
        else:
            commit_bar.display = bool(
                new_state.form.path.strip() or not new_state.queue_rows
            )
        try:
            quiet_line = self.query_one("#library-ingest-start-quiet-line", Static)
        except (NoMatches, QueryError):
            return
        quiet_line.update(new_state.start_quiet_line)
        # (task-3314) The two-press confirm lives in this updater's domain:
        # copy (above) and warning treatment (here) ride the SAME in-place
        # update, so the confirm text and its styling can never disagree
        # -- and the widget keeps identity across the hot path.
        quiet_line.set_class(new_state.start_confirm_armed, "-ingest-start-confirm")
        # (task-3305, MI-16) The commit forecast rides the SAME update as
        # the gate: a text/number option edit takes the in-place path, and
        # syncing the gate but not the forecast left "1 will import"
        # beside "Fix the highlighted options to start" -- a mixed
        # message. The state builder already empties the line whenever the
        # gate is closed, so one sync here keeps the two agreeing.
        try:
            commit_summary = self.query_one("#library-ingest-commit-summary", Static)
        except (NoMatches, QueryError):
            pass
        else:
            commit_summary.update(new_state.commit_summary_line)
            commit_summary.display = bool(new_state.commit_summary_line)
        # (task-3301) The Analyze-readiness hint shares the gate's in-place
        # update path so toggling the option or fixing the config never
        # needs a recompose to change the message.
        try:
            analysis_hint = self.query_one("#library-ingest-analysis-hint", Static)
        except (NoMatches, QueryError):
            return
        analysis_hint.update(new_state.analysis_hint_line)
        analysis_hint.display = bool(new_state.analysis_hint_line)
        # (task-3304, MI-08) Gate-line/hint changes move the fold; re-derive
        # the indicator once the new heights have actually laid out.
        self.call_after_refresh(self._update_library_ingest_fold_hint)

    def _update_library_ingest_fold_hint(self) -> None:
        """Re-derive the canvas fold indicator after an in-place update.

        (task-3304, MI-08) The hint is canvas-owned, always-mounted,
        display-managed chrome (never conditionally composed); this hook
        exists because queue/summary recomposes change content height
        WITHOUT resizing the canvas, so the canvas's own ``on_resize``
        never fires for them.
        """
        try:
            canvas = self.query_one(LibraryIngestCanvas)
        except (NoMatches, QueryError):
            return
        canvas.sync_fold_hint()

    def _scroll_library_ingest_queue_into_view(self) -> None:
        """Bring the queue heading into view after a submit (MI-08).

        Every submit used to land its outcome rows below the fold: the
        acknowledgement existed but was invisible. ``top=True`` parks the
        heading at the top of the viewport so the freshly queued rows
        below it are what the user sees.
        """
        try:
            canvas = self.query_one(LibraryIngestCanvas)
            heading = canvas.query_one("#library-ingest-queue-heading", Static)
        except (NoMatches, QueryError):
            return
        canvas.scroll_to_widget(heading, animate=False, top=True)

    def _update_library_ingest_dynamic_regions(
        self, allow_structural_recompose: bool = True
    ) -> None:
        """Refresh ONLY the pre-flight summary + queue children (task-2042).

        Recomposing the whole canvas on every pre-flight result / job tick
        remounted the form widgets: a click in flight against Start/Browse
        was swallowed (mouse-down on the old Button instance, mouse-up on
        the new one) and the canvas scroll snapped. The two dynamic blocks
        are their own render-from-state widgets, so only they recompose;
        the form region keeps widget identity, focus, and scroll for free.
        Structural changes -- the type-group set (options panels) or the
        runtime header lines -- still take the context-preserving full
        recompose, as does any unexpected canvas shape.
        """
        if self._library_selected_row_id != LIBRARY_ROW_INGEST_MEDIA:
            # (task-2043 review) A late worker result while a DIFFERENT
            # canvas is showing must not trigger the full-recompose
            # fallback and disrupt that canvas; the persisted echo renders
            # on the next ingest entry.
            return
        new_state = self._build_library_ingest_state()
        try:
            canvas = self.query_one(LibraryIngestCanvas)
            summary = canvas.query_one(LibraryIngestPreflightSummary)
            queue = canvas.query_one(LibraryIngestQueuePanel)
        except (NoMatches, QueryError):
            self._refresh_library_ingest_canvas_preserving_context()
            return
        old_state = canvas.state
        structural = (
            list(new_state.type_groups) != list(old_state.type_groups)
            or new_state.server_quiet_line != old_state.server_quiet_line
            or new_state.show_backend_switch != old_state.show_backend_switch
            or new_state.unavailable_line != old_state.unavailable_line
        )
        canvas.state = new_state
        if structural and allow_structural_recompose:
            self._refresh_library_ingest_canvas_preserving_context()
            return
        summary.state = new_state
        queue.state = new_state
        summary.refresh(recompose=True)
        queue.refresh(recompose=True)
        # Display-managed canvas-level bits + the gate.
        for intro in canvas.query(".library-ingest-intro"):
            intro.display = bool(new_state.intro_lines)
        # (task-2140) The commit-summary line is canvas-level and
        # display-managed; its content/visibility sync lives in
        # ``_update_library_ingest_gate`` (called below) so the forecast
        # and the gate can never disagree (task-3305, MI-16).
        try:
            clear_button = canvas.query_one("#library-ingest-clear-path", Button)
        except (NoMatches, QueryError):
            pass
        else:
            clear_button.display = new_state.show_clear_path
        # (task-3313) "Retry this batch" is canvas-level, always-mounted,
        # display-managed chrome; job ticks land here, so its visibility
        # tracks the settled-queue rule in place -- the widget itself is
        # never remounted (object identity across ticks).
        try:
            retry_last = canvas.query_one("#library-ingest-retry-last", Button)
        except (NoMatches, QueryError):
            pass
        else:
            retry_last.display = new_state.show_retry_last
            # (xhigh review + live-verify round) The pending destructive
            # re-stage consent rides the same in-place update, so the
            # label and the state can never disagree across a job tick.
            retry_last.label = library_ingest_retry_label(new_state.retry_confirm_armed)
        # (task-2042 review) Scope labels depend on per-group file counts,
        # which change WITHOUT the group set changing (generic is always
        # present) -- update them in place so a panel never claims files it
        # doesn't have.
        for group in new_state.type_groups:
            try:
                scope = canvas.query_one(
                    f"#type-group-{group} .type-group-scope", Static
                )
            except (NoMatches, QueryError):
                continue
            scope.update(
                ingest_scope_label(
                    get_capabilities(group),
                    bool(new_state.type_group_file_counts.get(group)),
                )
            )
        self._update_library_ingest_gate(new_state)

    def _server_binding_is_shipped_placeholder(self) -> bool:
        # A binding still matching config.py's shipped [tldw_api] template
        # values is the template, not a user decision. Drift fails OPEN
        # (the hint reappears for fresh installs) -- never hides a real
        # server -- and a test pins the constants against the template.
        api_config = resolve_tldw_api_config(
            getattr(self.app_instance, "app_config", None)
        )
        url = str(
            api_config.get("base_url")
            or api_config.get("api_url")
            or api_config.get("url")
            or ""
        ).strip()
        token = str(api_config.get("auth_token") or "").strip()
        return (
            url.rstrip("/") == TLDW_API_PLACEHOLDER_BASE_URL
            and token == TLDW_API_PLACEHOLDER_AUTH_TOKEN
        )

    def _build_library_ingest_state(self) -> LibraryIngestCanvasState:
        """Build the ingest canvas's full display state from the live registry + form.

        Reads directly from ``self.app_instance.library_ingest_jobs`` via
        quiet-degrade ``getattr`` (never assuming the seam exists) rather
        than caching a screen-owned copy, so every render -- the canvas
        compose -- sees the registry's current truth, including
        transitions a live-update listener applies between renders. The
        Open in Library/Retry/Dismiss row-action handlers do NOT go
        through this method -- they resolve their target job directly by
        ``job_id`` from ``registry.jobs()`` (see
        ``_library_ingest_job_by_id``), never by re-deriving and indexing
        into a row snapshot, so an async queue mutation between render and
        click can never mis-target a different job (PR #591 review, F1).
        """
        registry = self._library_ingest_registry()
        jobs_fn = getattr(registry, "jobs", None)
        jobs = jobs_fn() if callable(jobs_fn) else ()
        runtime_policy = getattr(self.app_instance, "runtime_policy", None)
        runtime_state = runtime_policy.state if runtime_policy is not None else None
        runtime_source = str(
            getattr(runtime_state, "active_source", "local") or "local"
        )
        # Sync generic top-level form fields into the generic options group so
        # the canvas renders current values for analyze/chunk/chunk_size.
        form = self._library_ingest_form
        generic_options = dict(form.type_options.get("generic", {}))
        generic_options["analyze"] = form.analyze
        generic_options["chunk"] = form.chunk
        generic_options["chunk_size"] = form.chunk_size
        form.type_options["generic"] = generic_options
        resolve_backend = getattr(self.app_instance, "_resolve_ingest_backend", None)
        ingest_backend = resolve_backend() if callable(resolve_backend) else "local"
        # "A server is available" means the seam exists AND can actually submit;
        # a half-wired service would otherwise advertise a switch that fails.
        server_service = getattr(
            self.app_instance, "server_media_reading_service", None
        )
        # (task-2100) ...AND a server is actually configured: gating on the
        # seam alone greeted every local-only install with server-mode talk
        # as the canvas's second line. Runtime ``server_configured`` alone
        # can't carry this: the shipped config template pre-fills
        # ``[tldw_api]`` with a placeholder URL+token, so it is True on a
        # virgin profile (live-verified) -- and reachability is normalized
        # to "unknown" whenever the runtime is local, so the untouched
        # template binding is the only remaining tell.
        server_ingest_available = (
            (
                callable(getattr(server_service, "submit_ingest_jobs", None))
                or callable(getattr(server_service, "submit_media_ingest_jobs", None))
            )
            and bool(getattr(runtime_state, "server_configured", False))
            and not self._server_binding_is_shipped_placeholder()
        )
        # (task-3301) Resolve the Analyze-after-import provider so the panel
        # can say -- BEFORE Start -- when the option is a promise the run
        # cannot keep. The builder gates the hint on the analyze toggle.
        analysis_unready_hint = ""
        if form.analyze:
            analysis_unready_hint = resolve_ingest_analysis_provider(
                getattr(self.app_instance, "app_config", None)
            ).hint
        consent = getattr(self, "_library_ingest_start_consent", None)
        start_confirm_line = ""
        if consent is not None and consent.active_job_ids:
            start_confirm_line = (
                active_ingest_start_confirm_line(
                    active_source_count=consent.active_source_count,
                    is_folder=consent.is_folder,
                    tooling_affected_count=consent.tooling_affected_count,
                )
                if consent.active_source_count
                else "Import active. Start again to queue a duplicate."
            )
        elif consent is not None and consent.candidate_changed:
            start_confirm_line = "Selection changed. Start again to queue."
        return build_library_ingest_state(
            jobs,
            form=form,
            runtime_source=runtime_source,
            media_db_available=getattr(self.app_instance, "media_db", None) is not None,
            registry_available=registry is not None,
            ingest_backend=ingest_backend,
            server_ingest_available=server_ingest_available,
            transcribe_cpp_configured=self._transcribe_cpp_configured,
            clear_finished_armed=self._library_ingest_clear_finished_armed,
            recent_ledger=tuple(self._library_ingest_recent_ledger),
            expanded_details=self._library_ingest_expanded_details,
            analysis_unready_hint=analysis_unready_hint,
            # (task-3314/3313) ``getattr`` quiet-degrade: several test
            # suites build this screen via ``object.__new__`` and seed only
            # the fields they exercise (the Clear-finished armed_at read
            # below in the queue handler set this precedent).
            start_confirm_armed=consent is not None,
            start_confirm_line=start_confirm_line,
            last_submission_available=(
                getattr(self, "_library_ingest_last_submission", None) is not None
            ),
            retry_confirm_armed=getattr(
                self, "_library_ingest_retry_confirm_armed", False
            ),
        )

    # ----- Notes editor: save, autosave, conflict policy -----------------

    def _invalidate_library_note_autosave(self) -> None:
        """Cancel the debounce and fence off any autosave already queued."""
        self._library_note_autosave_generation += 1
        if self._library_notes_autosave_timer is not None:
            self._library_notes_autosave_timer.stop()
            self._library_notes_autosave_timer = None

    def _schedule_library_note_autosave(self) -> None:
        """Rearm debounce after one genuine coordinator-owned draft mutation."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None or snapshot.in_conflict or snapshot.saving:
            return
        self._library_note_autosave_state = "idle"
        self._invalidate_library_note_autosave()
        generation = self._library_note_autosave_generation
        self._library_notes_autosave_timer = self.set_timer(
            LIBRARY_NOTES_AUTOSAVE_SECONDS,
            lambda: self._fire_library_note_autosave(generation),
        )

    @on(Input.Changed, "#library-note-title")
    def handle_library_note_title_changed(self, event: Input.Changed) -> None:
        """Mark the open note dirty and (re)arm the autosave debounce.

        Args:
            event: Input change event emitted by the editor's title field.
        """
        if (
            self._library_note_presentation_syncing
            or not self._library_note_editor_armed
        ):
            return
        # (P0) Recorded BEFORE (and independently of) the mutate result:
        # the two guards above already exclude every programmatic echo, so
        # reaching this line means the human changed the title widget --
        # even when the resulting string happens to equal the seed and the
        # coordinator reports "no change". A blank-seeded note renders its
        # title Input placeholder-only (empty value, draft still holding
        # the seed), so pasting "Untitled" into it is exactly that case:
        # a real touch that mutate() sees as a no-op. Gating the marker on
        # mutate() therefore left the GC free to destroy the note.
        self._library_note_title_user_edited = True
        if self._library_note_session.mutate(title=event.value):
            self._library_note_pending_blank_gc_id = None
            self._library_note_shortcut_status = ""
            self._schedule_library_note_autosave()
            self._apply_library_note_presentation_state()

    @on(TextArea.Changed, "#library-note-body")
    def handle_library_note_body_changed(self, event: TextArea.Changed) -> None:
        """Mark the open note dirty and (re)arm the autosave debounce.

        Args:
            event: Text change event emitted by the editor's body ``TextArea``.
        """
        if (
            self._library_note_presentation_syncing
            or not self._library_note_editor_armed
        ):
            return
        if self._library_note_session.mutate(body=event.text_area.text):
            self._library_note_pending_blank_gc_id = None
            self._library_note_shortcut_status = ""
            self._schedule_library_note_autosave()
            self._apply_library_note_presentation_state()

    @on(Input.Changed, "#library-note-keywords")
    def handle_library_note_keywords_changed(self, event: Input.Changed) -> None:
        """Mark the open note dirty and (re)arm the autosave debounce.

        Args:
            event: Input change event emitted by the editor's keywords field.
        """
        if (
            self._library_note_presentation_syncing
            or not self._library_note_editor_armed
        ):
            return
        if self._library_note_session.mutate(keywords_text=event.value):
            self._library_note_pending_blank_gc_id = None
            self._library_note_shortcut_status = ""
            self._schedule_library_note_autosave()
            self._apply_library_note_presentation_state()

    @on(Input.Changed, "#library-note-context-keywords")
    def handle_library_note_context_keywords_changed(
        self, event: Input.Changed
    ) -> None:
        """Mutate the canonical keyword draft from the Context properties field."""
        if (
            self._library_note_presentation_syncing
            or not self._library_note_editor_armed
        ):
            return
        if self._library_note_session.mutate(keywords_text=event.value):
            self._library_note_shortcut_status = ""
            self._schedule_library_note_autosave()
            self._apply_library_note_presentation_state()

    def _fire_library_note_autosave(self, generation: int) -> None:
        """Debounce-timer callback: kick the actual autosave worker."""
        if generation != self._library_note_autosave_generation:
            return
        self._library_notes_autosave_timer = None
        if not self._library_note_dirty:
            return
        self.run_worker(
            self._save_library_note(
                explicit=False,
                autosave_generation=generation,
            ),
            exclusive=True,
            group="library_note_save",
        )

    @on(Button.Pressed, "#library-note-save")
    def handle_library_note_save(self, event: Button.Pressed) -> None:
        """Explicitly save the open note, bypassing the autosave debounce."""
        event.stop()
        # LIB-14: an explicit Save is the user's own deliberate "keep it"
        # act, even if the note is still blank -- never GC a note the user
        # just told the app to save (unlike autosave, which is not a
        # deliberate signal -- see ``_library_note_session_blank_id``'s
        # docstring for why autosave alone must NOT clear it).
        self._library_note_pending_blank_gc_id = None
        self._library_note_session_blank_id = None
        self._invalidate_library_note_autosave()
        self.run_worker(
            self._save_library_note(explicit=True),
            exclusive=True,
            group="library_note_save",
        )

    def _library_note_meta_base_line(self) -> str:
        """The static Created/Modified/version portion of the meta line."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return ""
        return build_library_note_editor_state(
            {
                "id": snapshot.note_id,
                "version": snapshot.version,
                "created_at": snapshot.baseline.created_at,
                "last_modified": snapshot.baseline.modified_at,
            }
        ).meta_line

    def _update_library_note_meta_static(self, *, content: str) -> None:
        """Synchronize persistent metadata and status without recomposition.

        Args:
            content: Compatibility input from save callers. Canonical content
                is read from the coordinator snapshot.
        """
        del content
        self._apply_library_note_presentation_state()

    def _patch_library_note_list_from_session(self) -> None:
        """Patch list caches from the payload the coordinator actually saved.

        (P0) The baseline title is the DRAFT's title; the save port
        substitutes the seed for a blank one on the wire and the reply
        carries no title back, so patching rows straight from the baseline
        named an emptied-out note ``""`` while the persisted row said
        "Untitled". Both sides now run the payload through
        :func:`library_note_persisted_title`.
        """
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return
        baseline = snapshot.baseline
        persisted_title = library_note_persisted_title(baseline.title)
        self._local_source_records["notes"] = patch_note_records_after_save(
            self._local_source_records.get("notes", ()),
            baseline.note_id,
            title=persisted_title,
            modified_at=baseline.modified_at,
        )
        if self._library_notes_filter_records is not None:
            self._library_notes_filter_records = list(
                patch_note_records_after_save(
                    self._library_notes_filter_records,
                    baseline.note_id,
                    title=persisted_title,
                    modified_at=baseline.modified_at,
                )
            )

    def _focus_library_note_validation_field(self, field: str) -> None:
        """Restore keyboard focus to the field named by a validation veto."""
        selector = {
            "title": "#library-note-title",
            "body": "#library-note-body",
            "keywords": "#library-note-context-keywords",
        }.get(field)
        if selector is None or not self.is_mounted:
            return

        def focus_field() -> None:
            try:
                self.query_one(selector).focus()
            except (NoMatches, QueryError):
                return

        self.call_after_refresh(focus_field)

    def _route_library_note_validation_field(self, field: str) -> None:
        """Expose the region that owns a vetoed field without recomposing."""
        if field in {"title", "body"}:
            self._library_note_preview = False
            self._library_note_context = False
        elif field == "keywords":
            # Keywords now belong to Info -> Properties at every width.
            # Route there before focusing so validation never targets the
            # retained-but-hidden legacy inline field.
            self._library_note_context = True

    def _focus_library_note_conflict_callout(self) -> None:
        """Move keyboard focus to the explanatory conflict callout."""
        try:
            callout = self.query_one("#library-note-conflict-copy", Static)
        except (NoMatches, QueryError):
            return
        callout.can_focus = True
        callout.focus()

    def _apply_library_note_saved_presentation(
        self,
        outcome: NoteSaveOutcome,
    ) -> None:
        """Present saved only when the outcome still covers the latest draft."""
        snapshot = self._library_note_session.snapshot
        if snapshot is None or snapshot.note_id != self._selected_note_id:
            return
        if outcome.kind is NoteSaveOutcomeKind.SAVED:
            self._patch_library_note_list_from_session()
        is_current_clean_revision = (
            not snapshot.dirty
            and outcome.revision is not None
            and outcome.revision == snapshot.saved_revision
        )
        self._library_note_autosave_state = (
            "saved" if is_current_clean_revision else "idle"
        )
        self._update_library_note_meta_static(content=snapshot.body)

    def _apply_library_note_save_outcome(self, outcome: NoteSaveOutcome) -> None:
        """Translate one typed coordinator save outcome into screen presentation."""
        snapshot = self._library_note_session.snapshot
        if outcome.kind is NoteSaveOutcomeKind.STALE or snapshot is None:
            return
        if snapshot.note_id != self._selected_note_id:
            return
        if outcome.kind in {
            NoteSaveOutcomeKind.SAVED,
            NoteSaveOutcomeKind.ACKNOWLEDGED,
        }:
            self._apply_library_note_saved_presentation(outcome)
            return
        if outcome.kind is NoteSaveOutcomeKind.CONFLICTED:
            self._library_note_autosave_state = "conflict"
            self._library_note_preview = False
            self._library_note_context = False
            self._invalidate_library_note_autosave()
            if self.is_mounted:
                self._apply_library_note_presentation_state()
                self.call_after_refresh(self._focus_library_note_conflict_callout)
            return
        self._library_note_autosave_state = (
            "validation"
            if outcome.kind is NoteSaveOutcomeKind.VALIDATION_VETO
            else "error"
        )
        validation_field = outcome.veto.field if outcome.veto is not None else ""
        if outcome.kind is NoteSaveOutcomeKind.VALIDATION_VETO:
            self._route_library_note_validation_field(validation_field)
        elif self._library_note_preview:
            self._library_note_preview = False
        self._update_library_note_meta_static(content=snapshot.body)
        self._focus_library_note_validation_field(validation_field)

    async def _save_library_note(
        self,
        *,
        explicit: bool,
        autosave_generation: int | None = None,
    ) -> None:
        """Ask the portable coordinator to serialize the canonical draft.

        Args:
            explicit: Whether this save was triggered by the Save button
                (``True``) or the autosave debounce/flush (``False``). The
                coordinator uses an explicit no-op Save to acknowledge an
                untouched newly created note without calling persistence.
            autosave_generation: Timer generation captured before queuing an
                autosave, or ``None`` for deliberate save/flush authority.
        """
        if (
            autosave_generation is not None
            and autosave_generation != self._library_note_autosave_generation
        ):
            return
        snapshot = self._library_note_session.snapshot
        if (
            self._library_notes_view != "editor"
            or snapshot is None
            or snapshot.note_id != self._selected_note_id
        ):
            return
        self._library_note_shortcut_status = ""
        self._library_note_autosave_state = "saving"
        self._update_library_note_meta_static(content=snapshot.body)
        if (
            autosave_generation is not None
            and autosave_generation != self._library_note_autosave_generation
        ):
            return
        outcome = await self._library_note_session.request_save(explicit=explicit)
        self._apply_library_note_save_outcome(outcome)

    async def _flush_library_note_save(self) -> NoteFlushOutcome:
        """Cross the coordinator's pending-work barrier before navigation."""
        self._invalidate_library_note_autosave()
        if (
            self._library_note_session_blank_id
            and self._library_note_session_blank_id == self._selected_note_id
            # task-3315: never start a SECOND destructive op from the
            # untouched-blank GC while a discard/delete is already running
            # or admitted -- fall through to the session flush, whose own
            # destructive guard vetoes navigation until it settles.
            and not self._library_note_session.destructive_running
            and self._library_note_session.destructive_admission is None
        ):
            fields = self._read_library_note_editor_fields()
            if fields is not None:
                raw_title, raw_content, raw_keywords_text = fields
                # task-3315 (LIB-14 regression, pre-arc dev churn): the
                # session coordinator seeds a Blank note's title with the
                # literal seed and ``_read_library_note_editor_fields`` now
                # projects the SNAPSHOT rather than the widgets (13cf08f90,
                # notes-adaptive PR #1439) -- the editor presents that seed
                # as an empty placeholder-only Input, so it must count as
                # blank here or the untouched-blank GC never fires and every
                # abandoned Blank note leaves a permanent "Untitled" row
                # (exactly what task-2858 AC#5 forbids).
                # (P0, xhigh review + live-verify round) The seed only
                # counts as blank while it is still THE SEED. Keying on
                # string equality alone destroyed a note the user
                # deliberately titled "Untitled" (body empty) on
                # navigate-away, with no prompt and no undo -- a string
                # cannot tell the create seam's default from the same
                # letters typed by a human, so the provenance marker
                # decides. An emptied-out title is blank either way.
                # (rebase note: task-4021 independently re-derived this
                # same root cause -- the literal seed must count as blank
                # too, or this GC branch is unreachable -- but its version
                # lacked the ``_library_note_title_user_edited`` provenance
                # guard below; dev's fuller check is kept as-is and covers
                # task-4021's reachability claim too.)
                title_blank = not raw_title.strip() or (
                    raw_title == LIBRARY_NOTE_BLANK_SEED_TITLE
                    and not self._library_note_title_user_edited
                )
                if title_blank and not any(
                    value.strip() for value in (raw_content, raw_keywords_text)
                ):
                    await self._gc_pending_blank_note()
                    return NoteFlushOutcome(NoteFlushOutcomeKind.PERMITTED)
        before = self._library_note_session.snapshot
        before_saved_revision = before.saved_revision if before is not None else None
        outcome = await self._library_note_session.flush()
        snapshot = self._library_note_session.snapshot
        if outcome.kind is NoteFlushOutcomeKind.PERMITTED:
            if (
                snapshot is not None
                and before_saved_revision is not None
                and snapshot.saved_revision > before_saved_revision
            ):
                self._patch_library_note_list_from_session()
                self._library_note_autosave_state = (
                    "idle" if snapshot.dirty else "saved"
                )
                self._update_library_note_meta_static(content=snapshot.body)
            return outcome
        if snapshot is None:
            return outcome
        if outcome.kind is NoteFlushOutcomeKind.CONFLICTED:
            self._library_note_autosave_state = "conflict"
            self._library_note_preview = False
            self._library_note_context = False
            if self.is_mounted:
                self._apply_library_note_presentation_state()
                self.call_after_refresh(self._focus_library_note_conflict_callout)
            return outcome
        if outcome.kind is NoteFlushOutcomeKind.BLOCKED:
            return outcome
        self._library_note_autosave_state = (
            "validation"
            if outcome.kind is NoteFlushOutcomeKind.VALIDATION_VETO
            else "error"
        )
        validation_field = ""
        if outcome.save_outcome is not None and outcome.save_outcome.veto is not None:
            validation_field = outcome.save_outcome.veto.field
        if outcome.kind is NoteFlushOutcomeKind.VALIDATION_VETO:
            self._route_library_note_validation_field(validation_field)
        self._update_library_note_meta_static(content=snapshot.body)
        if validation_field:
            self._focus_library_note_validation_field(validation_field)
        return outcome

    async def _gc_pending_blank_note(self) -> None:
        """Delete this session's now-empty "Blank note" row before it is left behind (LIB-14).

        "Blank note" still commits its DB row immediately on click (the
        create-note seam has no create-on-first-edit branch -- see the
        AC#5 decision recorded on task-2858); this is the smaller-diff
        alternative the task allows instead: whenever the editor is left
        with this session's blank note in an effectively-empty final state
        (title/body/keywords all blank -- see the caller,
        ``_flush_library_note_save``, which covers both "never touched"
        and "typed then deleted everything"), the row is quietly removed
        here rather than surviving as a permanent literal "Untitled" row
        the user has to find and delete by hand.

        Reads ``_library_note_session_blank_id`` (not the narrower,
        edit-cleared ``_library_note_pending_blank_gc_id``) so this still
        fires after the note was typed into and then emptied out again --
        which, unlike the "never touched" case, may well have gone
        through one or more real autosaves in between (deliberately: see
        that flag's own docstring on why autosave alone must not exempt a
        session blank from GC). Each of those autosaves bumps the row's
        real DB version, so the delete below sends
        ``self._library_note_version`` (the screen's own up-to-date
        tracking of it, updated by every successful save) rather than a
        hardcoded 1 -- an earlier version of this fix hardcoded 1 and the
        delete silently failed on a version mismatch whenever a
        mid-session autosave had already bumped the row past v1 (found by
        the dedicated autosave-then-empty test). Falls back to 1 only for
        the genuinely-never-saved case, where ``_library_note_version`` is
        still ``None``. Best-effort: any failure (including a version
        conflict from a still-possible concurrent EXTERNAL change) is
        swallowed -- GC must never block the exit it runs inside, and the
        worst case on failure is the pre-existing behavior (the row
        survives), not a new regression. On success, patches the same cached
        Notes rows/count used by visible Delete, Undo, and Create while their
        one shared mutation interlock is held.

        Also clears ``_library_note_dirty`` unconditionally (review round
        1 fix): the caller, ``_flush_library_note_save``, is reached via
        the "typed then deleted everything" path with ``_library_note_
        dirty`` still ``True`` -- every exit seam (e.g.
        ``_exit_library_note_editor_guarded``) vetoes on that flag, so
        without clearing it here a successful GC would still leave the
        editor stuck open. Cleared regardless of whether the delete call
        itself succeeds, matching "GC must never block the exit it runs
        inside": on the rare failure path the row survives with its
        pre-exit content (the emptied edit is not separately persisted
        either), but the user is never trapped in the editor over it.
        """
        note_id = self._library_note_session_blank_id
        # The row's current version -- NOT hardcoded to 1 -- since a
        # mid-session autosave (deliberately still possible before GC;
        # see the docstring above) may already have bumped it past its
        # initial create-time version.
        current_version = self._library_note_version or 1
        self._library_note_session_blank_id = None
        self._library_note_pending_blank_gc_id = None
        if not note_id or self._library_notes_mutation_in_flight:
            return
        self._library_notes_mutation_in_flight = True
        service = getattr(self.app_instance, "notes_scope_service", None)
        delete_note = getattr(service, "delete_note", None)
        if not callable(delete_note):
            self._library_notes_mutation_in_flight = False
            return
        try:
            deleted = await self._run_library_service_call(
                delete_note,
                scope="local_note",
                note_id=note_id,
                version=current_version,
                user_id=self._library_notes_user_id(),
                isolate_in_worker=True,
            )
            if deleted:
                self._remove_library_note_source_record(note_id)
        except Exception:
            logger.opt(exception=True).debug(
                f"Could not GC untouched blank note {note_id!r}; leaving it in place."
            )
            return
        finally:
            self._library_notes_mutation_in_flight = False

    async def _resolve_library_note_conflict(self, *, overwrite: bool) -> None:
        """Resolve a conflict through the coordinator's token-gated action.

        Args:
            overwrite: ``True`` for Overwrite, ``False`` for Reload.
        """
        self._library_note_shortcut_status = ""
        action = ConflictAction.OVERWRITE if overwrite else ConflictAction.RELOAD
        operation = asyncio.create_task(
            self._library_note_session.resolve_conflict(action)
        )
        try:
            # Let the coordinator atomically claim its conflict token before
            # reflecting the running state. The operation's first service
            # boundary yields here; a synchronous rejection/finish needs no
            # intermediate presentation.
            await asyncio.sleep(0)
            if self._library_note_session.conflict_resolution_running:
                self._apply_library_note_presentation_state()
            outcome = await operation
        except asyncio.CancelledError:
            operation.cancel()
            await asyncio.gather(operation, return_exceptions=True)
            raise
        if outcome.kind in {
            ConflictOutcomeKind.STALE,
            ConflictOutcomeKind.ALREADY_RUNNING,
            ConflictOutcomeKind.NOT_IN_CONFLICT,
        }:
            return
        if outcome.kind is ConflictOutcomeKind.MISSING and not overwrite:
            self._dispatch_database_note_identity_cleared()
            self._reset_library_note_editor_state()
            self._notify_library_note_missing_warning()
            self._refresh_local_source_snapshot()
            if self.is_mounted:
                _sync_library_canvas(self, "notes")
            return
        snapshot = self._library_note_session.snapshot
        validation_field = ""
        if outcome.kind is ConflictOutcomeKind.OVERWRITTEN:
            if outcome.save_outcome is not None:
                self._apply_library_note_saved_presentation(outcome.save_outcome)
        elif outcome.kind is ConflictOutcomeKind.RELOADED:
            self._library_note_autosave_state = "idle"
        elif outcome.kind in {
            ConflictOutcomeKind.RENEWED_CONFLICT,
            ConflictOutcomeKind.DRAFT_CHANGED,
            ConflictOutcomeKind.MISSING,
        }:
            self._library_note_autosave_state = "conflict"
        elif outcome.kind is ConflictOutcomeKind.FAILED:
            self._library_note_autosave_state = (
                "conflict" if snapshot is not None and snapshot.in_conflict else "error"
            )
        elif outcome.kind is ConflictOutcomeKind.VALIDATION_VETO:
            self._library_note_autosave_state = "validation"
            if (
                outcome.save_outcome is not None
                and outcome.save_outcome.veto is not None
            ):
                validation_field = outcome.save_outcome.veto.field
        self._library_note_preview = False
        self._library_note_context = False
        if outcome.kind is ConflictOutcomeKind.VALIDATION_VETO:
            self._route_library_note_validation_field(validation_field)
        if self.is_mounted:
            self._apply_library_note_presentation_state()
            if snapshot is not None and snapshot.in_conflict:
                self.call_after_refresh(self._focus_library_note_conflict_callout)
            elif validation_field:
                self._focus_library_note_validation_field(validation_field)

    @on(Button.Pressed, "#library-note-conflict-overwrite")
    def handle_library_note_conflict_overwrite(self, event: Button.Pressed) -> None:
        """Resolve a shown save conflict by re-saving the kept local edits.

        Args:
            event: Button press event emitted by the conflict UI's
                "Overwrite" action.
        """
        event.stop()
        self.run_worker(
            self._resolve_library_note_conflict(overwrite=True),
            group="library_note_conflict",
        )

    @on(Button.Pressed, "#library-note-conflict-reload")
    def handle_library_note_conflict_reload(self, event: Button.Pressed) -> None:
        """Resolve a shown save conflict by discarding local edits and reloading.

        Args:
            event: Button press event emitted by the conflict UI's
                "Reload" action.
        """
        event.stop()
        self.run_worker(
            self._resolve_library_note_conflict(overwrite=False),
            group="library_note_conflict",
        )

    # ----- Notes editor: preview, export, copy, use-in-console -----------

    def _read_library_note_editor_fields(self) -> tuple[str, str, str] | None:
        """Project canonical draft fields for non-persistence utilities.

        Returns:
            ``(title, content, keywords_text)`` from the coordinator snapshot,
            or ``None`` when no Database Note session is active.
        """
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return None
        return snapshot.title, snapshot.body, snapshot.keywords_text

    @on(Button.Pressed, "#library-note-edit")
    def handle_library_note_edit_mode(self, event: Button.Pressed) -> None:
        """Show the retained editable Database Note surface."""
        event.stop()
        if self._library_notes_view != "editor":
            return
        self._library_note_preview = False
        self._library_note_context = False
        self._apply_library_note_presentation_state()

    @on(Button.Pressed, "#library-note-preview")
    def handle_library_note_preview_toggle(self, event: Button.Pressed) -> None:
        """Show the retained read-only Markdown preview.

        The coordinator already owns every raw field, so recomposition can
        switch presentation without taking a second mutable draft snapshot.

        Args:
            event: Button press event emitted by the editor's Preview/Edit
                action.
        """
        event.stop()
        if (
            self._library_notes_view != "editor"
            or self._library_note_autosave_state == "conflict"
        ):
            return
        if self._library_note_session.snapshot is None:
            return
        self._library_note_context = False
        self._library_note_preview = True
        self._apply_library_note_presentation_state()

    @on(Button.Pressed, "#library-note-context")
    def handle_library_note_context_open(self, event: Button.Pressed) -> None:
        """Show the stable Context region without replacing editor widgets.

        Args:
            event: Button press emitted by the editor's Context action.

        Returns:
            None.
        """
        event.stop()
        snapshot = self._library_note_session.snapshot
        if (
            self._library_notes_view != "editor"
            or snapshot is None
            or snapshot.in_conflict
            or self._library_note_confirming_delete
        ):
            return
        self._library_note_context = True
        self._apply_library_note_presentation_state()
        try:
            context = self.query_one("#library-note-context-region")
        except (NoMatches, QueryError):
            return
        context.focus()

    @on(Button.Pressed, "#library-note-context-back")
    def handle_library_note_context_back(self, event: Button.Pressed) -> None:
        """Return to the Edit or Preview presentation that opened Context.

        Args:
            event: Button press emitted by the Context region's Back action.

        Returns:
            None.
        """
        event.stop()
        if not self._library_note_context:
            return
        self._library_note_context = False
        self._apply_library_note_presentation_state()
        try:
            self.query_one("#library-note-context", Button).focus()
        except (NoMatches, QueryError):
            return

    async def _export_library_note(self, export_format: str) -> None:
        """Push the Export dialog for the open Library note.

        Mirrors the retired standalone Notes screen's export dialog flow --
        a ``FileSave`` prompt pre-filled with a sanitized default filename,
        whose callback writes the built export content once a path is
        chosen. The export reads the *live* editor widgets (via
        ``_read_library_note_editor_fields``), never the DB, so unlike
        Save there is nothing to flush first.

        Note: the real ``Third_Party.textual_fspicker.FileSave`` dialog
        only accepts ``location``/``title``/``default_file`` (not the
        ``default_filename``/``context`` kwargs the retired screen passed
        it, which would have raised ``TypeError`` if that path ever
        actually ran) -- this uses the dialog's real constructor shape.

        Args:
            export_format: ``"markdown"`` for the frontmatter export
                (Export .md), or ``"text"`` for the plain-text export
                (Export .txt).
        """
        if self._library_notes_view != "editor" or not self._selected_note_id:
            return
        fields = self._read_library_note_editor_fields()
        if fields is None:
            return
        operation = self._begin_library_notes_operation("export")
        if operation is None:
            return
        title, content, keywords_text = fields
        note_id = self._selected_note_id
        safe_title = (
            "".join(
                char
                for char in (title.strip() or "note")
                if char.isalnum() or char in (" ", "-", "_")
            ).rstrip()
            or "note"
        )
        default_filename = (
            f"{safe_title}.md" if export_format == "markdown" else f"{safe_title}.txt"
        )
        dialog_title = (
            "Export Note as Markdown"
            if export_format == "markdown"
            else "Export Note as Text"
        )
        await self.app.push_screen(
            FileSave(
                location=str(Path.home()),
                title=dialog_title,
                default_file=default_filename,
            ),
            callback=lambda path: self.call_after_refresh(
                self._write_library_note_export_file,
                path,
                export_format,
                title,
                content,
                keywords_text,
                note_id,
                operation,
            ),
        )

    def _write_library_note_export_file(
        self,
        selected_path: Path | None,
        export_format: str,
        title: str,
        content: str,
        keywords_text: str,
        note_id: str,
        operation: LibraryNotesOperationState | None = None,
    ) -> None:
        """Write the exported note content to the path chosen via ``FileSave``.

        Runs the dialog-returned path through ``validate_path_simple``
        before writing: ``FileSave`` lets the user pick any absolute
        destination, so there is no fixed base directory to constrain it
        to the way ``validate_path``/``safe_join_path`` require -- this is
        the same base-directory-free validator the rest of this codebase
        already uses for user-chosen save/output paths (e.g. this screen's
        note import path, ``settings_screen``'s
        storage-location fields). It rejects null bytes and other
        shell-metacharacter/traversal patterns; a rejected path is a quiet
        warning notice with no write and no crash, same as any other
        failure in this method. This method awaits nothing (the write is a
        plain synchronous ``Path.write_text``), so it is a plain method
        rather than a coroutine -- Textual's ``call_after_refresh`` (its
        only caller, via ``_export_library_note``'s ``FileSave`` callback)
        accepts either.

        Args:
            selected_path: The chosen destination, or ``None`` if the
                dialog was cancelled.
            export_format: ``"markdown"`` or ``"text"`` (see
                ``build_note_export_content``).
            title: The note title captured when Export was pressed.
            content: The note body captured when Export was pressed.
            keywords_text: The note's keywords, as a comma-separated string.
            note_id: The note's id.
        """
        active_operation = operation or self._begin_library_notes_operation("export")
        if active_operation is None:
            return
        notify = getattr(self.app_instance, "notify", None)
        if not selected_path:
            if callable(notify):
                notify("Note export cancelled.", severity="information")
            self._finish_library_notes_operation(
                active_operation,
                success=False,
                failure_next_action="choose another destination and try again",
            )
            return
        try:
            validated_path = validate_path_simple(selected_path, require_exists=False)
        except ValueError as exc:
            logger.warning(
                f"Rejected Library note export path {selected_path!r} for {note_id!r}: {exc}"
            )
            if callable(notify):
                notify(f"Rejected export path: {exc}", severity="warning")
            self._finish_library_notes_operation(
                active_operation,
                success=False,
                failure_next_action="choose another destination and try again",
            )
            return
        try:
            validated_path.write_text(
                build_note_export_content(
                    title, content, keywords_text, note_id, export_format
                ),
                encoding="utf-8",
            )
        except Exception as exc:
            logger.opt(exception=True).warning(
                f"Error exporting Library note {note_id!r} to '{validated_path}'."
            )
            if callable(notify):
                notify(f"Error exporting note: {type(exc).__name__}", severity="error")
            self._finish_library_notes_operation(
                active_operation,
                success=False,
                failure_next_action="check the destination and try again",
            )
            return
        if callable(notify):
            notify(
                f"Note exported successfully to {validated_path.name}",
                severity="information",
            )
        self._finish_library_notes_operation(active_operation, success=True)

    @on(Button.Pressed, "#library-note-context-export-md")
    @on(Button.Pressed, "#library-note-export-md")
    async def handle_library_note_export_markdown(self, event: Button.Pressed) -> None:
        """Export the open note as Markdown via a ``FileSave`` dialog.

        Args:
            event: Button press event emitted by the editor's "Export .md" action.
        """
        event.stop()
        await self._export_library_note("markdown")

    @on(Button.Pressed, "#library-note-context-export-txt")
    @on(Button.Pressed, "#library-note-export-txt")
    async def handle_library_note_export_text(self, event: Button.Pressed) -> None:
        """Export the open note as plain text via a ``FileSave`` dialog.

        Args:
            event: Button press event emitted by the editor's "Export .txt" action.
        """
        event.stop()
        await self._export_library_note("text")

    @on(Button.Pressed, "#library-note-context-copy")
    @on(Button.Pressed, "#library-note-copy")
    def handle_library_note_copy(self, event: Button.Pressed) -> None:
        """Copy the open Library note to the clipboard as markdown.

        Uses the app's ``copy_to_clipboard`` seam (the same
        ``getattr``-gated pattern every other Library handoff/action in
        this screen already uses) rather than importing ``pyperclip``
        directly the way the retired standalone Notes screen's copy action
        did -- that makes this testable via a recorded fake the way the
        rest of this screen's actions are, and doesn't add a hard runtime
        dependency on a package that isn't always installed/working.

        Args:
            event: Button press event emitted by the editor's Copy action.
        """
        event.stop()
        notify = getattr(self.app_instance, "notify", None)
        if self._library_notes_view != "editor" or not self._selected_note_id:
            return
        fields = self._read_library_note_editor_fields()
        if fields is None:
            return
        operation = self._begin_library_notes_operation("copy")
        if operation is None:
            return
        title, content, keywords_text = fields
        note_id = self._selected_note_id
        export_content = build_note_export_content(
            title, content, keywords_text, note_id, "markdown"
        )
        copy_to_clipboard = getattr(self.app_instance, "copy_to_clipboard", None)
        if not callable(copy_to_clipboard):
            if callable(notify):
                notify(
                    "Clipboard copy is unavailable in this runtime.", severity="warning"
                )
            self._finish_library_notes_operation(
                operation,
                success=False,
                failure_next_action="enable clipboard access and try again",
            )
            return
        try:
            copy_to_clipboard(export_content)
        except Exception as exc:
            logger.opt(exception=True).warning(
                f"Failed to copy Library note {note_id!r} to clipboard."
            )
            if callable(notify):
                notify(f"Error copying note: {type(exc).__name__}", severity="error")
            self._finish_library_notes_operation(
                operation,
                success=False,
                failure_next_action="check clipboard access and try again",
            )
            return
        if callable(notify):
            notify("Note copied to clipboard as markdown!", severity="information")
        self._finish_library_notes_operation(operation, success=True)

    def _selected_library_note_handoff_payload(self) -> ChatHandoffPayload | None:
        """Build the Console handoff payload for the open Library note.

        Mirrors ``_selected_media_handoff_payload``: reads the currently
        open note's live (possibly unsaved) editor fields rather than a
        list-row selection, matching the local-note handoff shape the
        retired standalone Notes screen staged.

        Returns:
            A ``ChatHandoffPayload`` staging the open note as Console
            context, or ``None`` when no note is currently open.
        """
        if self._library_notes_view != "editor" or not self._selected_note_id:
            return None
        fields = self._read_library_note_editor_fields()
        if fields is None:
            return None
        title, content, keywords_text = fields
        note_id = self._selected_note_id
        keywords = self._library_note_keywords_from_input(keywords_text) or []
        return ChatHandoffPayload.from_source_content(
            source="notes",
            item_type="note",
            title=title.strip() or "Untitled Note",
            body=content,
            source_id=str(note_id),
            suggested_prompt="Use this note as context and help me work with it.",
            runtime_backend="local",
            source_owner="local",
            source_selector_state="local",
            discovery_owner="notes",
            discovery_entity_id=str(note_id),
            scope_type="global",
            metadata={
                "note_version": self._library_note_version,
                "keywords": keywords,
            },
        )

    def _open_selected_library_note_handoff(self) -> bool:
        """Stage the note open in the editor into Console via the shared handoff.

        Mirrors ``_open_selected_media_handoff``: builds the payload, then
        guards on having an open note, the workspace context-handoff gate,
        and the app exposing ``open_chat_with_handoff`` at all.
        """
        workspace_state = self._library_workspace_depth_state()
        payload = self._selected_library_note_handoff_payload()
        notify = getattr(self.app_instance, "notify", None)
        if payload is None:
            if callable(notify):
                notify("Open a note before using it in Console.", severity="warning")
            return False
        if not workspace_state.context_handoff_enabled:
            if callable(notify):
                notify(workspace_state.context_handoff_tooltip, severity="warning")
            return False
        open_chat_with_handoff = getattr(
            self.app_instance, "open_chat_with_handoff", None
        )
        if not callable(open_chat_with_handoff):
            if callable(notify):
                notify(
                    "Console handoff is unavailable for Library Notes.",
                    severity="warning",
                )
            return False
        try:
            open_chat_with_handoff(payload, action_label="Use in Console")
        except Exception:
            logger.opt(exception=True).warning("Library note Console handoff failed.")
            if callable(notify):
                notify("Could not use this note in Console.", severity="warning")
            return False
        return True

    @on(Button.Pressed, "#library-note-context-use-in-console")
    @on(Button.Pressed, "#library-note-use-in-console")
    def handle_library_note_use_in_console(self, event: Button.Pressed) -> None:
        """Hand the open note off to Console as chat context.

        Args:
            event: Button press event emitted by the editor's
                "Use in Console" action.
        """
        event.stop()
        operation = self._begin_library_notes_operation("console")
        if operation is None:
            return
        handed_off = self._open_selected_library_note_handoff()
        self._finish_library_notes_operation(
            operation,
            success=handed_off,
            failure_next_action="check Console readiness and try again",
        )

    def _load_library_lifecycle_value(self) -> tuple[Any, bool]:
        """Read lifecycle independently from the existing section preferences."""
        app_config = self.app_instance.app_config
        library_config = app_config.get("library")
        if isinstance(library_config, dict):
            rail_state = library_config.get("rail_state")
            if isinstance(rail_state, dict) and "lifecycle" in rail_state:
                return rail_state["lifecycle"], True
        try:
            cli_rail_state = get_cli_setting("library.rail_state")
        except Exception:
            cli_rail_state = None
        if isinstance(cli_rail_state, dict) and "lifecycle" in cli_rail_state:
            return cli_rail_state["lifecycle"], True
        return None, False

    def _library_onboarding_admission_key(self) -> tuple[Any, ...]:
        """Return the profile and active-source authority for one evidence read."""
        scope = _active_library_sync_scope(self.app_instance)
        return (
            id(self.app_instance.app_config),
            getattr(self.app_instance, "notes_user_id", None) or "default_user",
            scope["source_authority"],
            scope["server_profile_id"],
            scope["authenticated_principal_id"],
            scope["workspace_scope"],
        )

    def _sync_library_onboarding_status_copy(self) -> None:
        """Keep the Task 4/5 presentation seam in sync with evidence status."""
        if self._library_onboarding_status is LibraryEvidenceStatus.LOADING:
            self._library_onboarding_status_copy = "Checking existing Library content…"
        elif self._library_onboarding_status is LibraryEvidenceStatus.PARTIAL_FAILURE:
            self._library_onboarding_status_copy = (
                "Some Library sources are unavailable."
            )
        else:
            self._library_onboarding_status_copy = ""

    def _refresh_library_onboarding_evidence(self) -> Worker | None:
        """Start one fresh, generation-fenced six-owner evidence read."""
        self._library_onboarding_generation += 1
        generation = self._library_onboarding_generation
        back_was_admitted = (
            self._library_lifecycle is LibraryLifecycle.EXPANDED
            and self._library_onboarding_all_empty
        )
        self._library_onboarding_all_empty = False
        self._library_onboarding_status = LibraryEvidenceStatus.LOADING
        self._sync_library_onboarding_status_copy()
        if not self.is_attached:
            return None
        if back_was_admitted:
            self._sync_library_rail_lifecycle_presentation()
        elif self.is_mounted:
            self._sync_library_landing_lifecycle_presentation()
        return self.run_worker(
            self._gather_library_onboarding_evidence(
                generation,
                self._library_onboarding_admission_key(),
            ),
            group="library_onboarding_evidence",
            exclusive=True,
        )

    def _sync_library_rail_lifecycle_presentation(self) -> None:
        """Recompose lifecycle owners and safely restore semantic focus."""
        rail = self._active_library_rail()
        if rail is None:
            return
        focused = self.focused
        focus_selector = ""
        if focused is not None and rail in focused.ancestors_with_self and focused.id:
            focus_selector = f"#{focused.id}"
            self.set_focus(None)
        if focus_selector:
            rail.queue_after_recompose(
                lambda: self._restore_library_lifecycle_focus(focus_selector)
            )
        rail.sync_state(
            rail.shell,
            rail.preferences,
            query=self._library_rag_query,
            lifecycle=self._library_lifecycle,
            onboarding_all_empty=self._library_onboarding_all_empty,
        )
        self._sync_library_landing_lifecycle_presentation()
        self._sync_library_lifecycle_status()
        self._register_footer_shortcuts()

    def _sync_library_lifecycle_status(self) -> None:
        """Patch the single screen-owned lifecycle feedback carrier."""
        try:
            status = self.query_one("#library-lifecycle-status", Static)
        except (NoMatches, QueryError):
            return
        copy = self._library_lifecycle_status_copy()
        status.update(copy)
        status.display = bool(copy)

    def _acknowledge_library_destination_change(self) -> None:
        """Clear transition feedback after an explicit route is admitted."""
        if not self._library_graduation_announcement_visible:
            return
        self._library_graduation_announcement_visible = False
        if self.is_mounted:
            self._sync_library_lifecycle_status()

    def _sync_library_landing_lifecycle_presentation(self) -> None:
        """Sync the retained landing, preserving a still-current focused action."""
        try:
            landing = self.query_one("#library-landing-canvas", LibraryLandingCanvas)
        except (NoMatches, QueryError):
            return
        focused = self.focused
        focus_selector = ""
        if (
            focused is not None
            and landing in focused.ancestors_with_self
            and focused.id
        ):
            focus_selector = f"#{focused.id}"
            self.set_focus(None)
        _sync_library_canvas(
            self,
            "landing",
            then=(
                partial(self._restore_library_lifecycle_focus, focus_selector)
                if focus_selector
                else None
            ),
            allow_screen_fallback=False,
        )

    def _restore_library_lifecycle_focus(self, selector: str) -> None:
        """Restore settlement focus only while the user has not moved it."""
        if self.focused is None:
            self._focus_library_rail_action(selector)

    async def _call_library_onboarding_owner(
        self,
        owner: str,
        source_authority: str,
    ) -> LibraryContentEvidence:
        """Call one source-owned evidence seam with its active authority."""
        service_attributes = {
            "notes": "notes_scope_service",
            "media": "media_reading_scope_service",
            "conversations": "chat_conversation_scope_service",
            "prompts": "prompt_scope_service",
            "skills": "skills_scope_service",
            "collections": "collections_capture_scope_service",
        }
        service = getattr(self.app_instance, service_attributes[owner], None)
        evidence_call = getattr(service, "get_library_user_content_evidence", None)
        if not callable(evidence_call):
            return LibraryContentEvidence.UNKNOWN
        if owner == "collections":
            result = await self._run_library_service_call(
                evidence_call,
            )
        elif owner == "notes":
            result = await self._run_library_service_call(
                evidence_call,
                scope="server" if source_authority == "server" else "local_note",
                user_id=(
                    None
                    if source_authority == "server"
                    else getattr(self.app_instance, "notes_user_id", None)
                    or "default_user"
                ),
            )
        else:
            result = await self._run_library_service_call(
                evidence_call,
                mode=source_authority,
            )
        return (
            result
            if isinstance(result, LibraryContentEvidence)
            else LibraryContentEvidence.UNKNOWN
        )

    async def _gather_library_onboarding_evidence(
        self,
        generation: int,
        admission_key: tuple[Any, ...],
    ) -> None:
        """Progressively settle evidence under one overall bounded deadline."""
        source_authority = str(admission_key[2])
        tasks = {
            asyncio.create_task(
                self._call_library_onboarding_owner(owner, source_authority)
            )
            for owner in (
                "notes",
                "media",
                "conversations",
                "prompts",
                "skills",
                "collections",
            )
        }
        pending = set(tasks)
        evidence: list[LibraryContentEvidence] = []
        deadline = (
            asyncio.get_running_loop().time()
            + LIBRARY_ONBOARDING_EVIDENCE_TIMEOUT_SECONDS
        )
        try:
            while pending:
                remaining = deadline - asyncio.get_running_loop().time()
                if remaining <= 0:
                    break
                done, pending = await asyncio.wait(
                    pending,
                    timeout=remaining,
                    return_when=asyncio.FIRST_COMPLETED,
                )
                if not done:
                    break
                for task in done:
                    try:
                        result = task.result()
                    except Exception:
                        result = LibraryContentEvidence.UNKNOWN
                    evidence.append(result)
                    if result is LibraryContentEvidence.HAS_USER_CONTENT:
                        evidence.extend(
                            LibraryContentEvidence.UNKNOWN
                            for _task in range(len(tasks) - len(evidence))
                        )
                        self._apply_library_onboarding_evidence(
                            generation,
                            admission_key,
                            evidence,
                        )
                        return
            evidence.extend(LibraryContentEvidence.UNKNOWN for _task in pending)
            self._apply_library_onboarding_evidence(
                generation,
                admission_key,
                evidence,
            )
        finally:
            for task in tasks:
                if not task.done():
                    task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)

    def _apply_library_onboarding_evidence(
        self,
        generation: int,
        admission_key: tuple[Any, ...],
        evidence: Sequence[LibraryContentEvidence],
    ) -> None:
        """Apply accepted evidence against the lifecycle current at settlement."""
        if (
            generation != self._library_onboarding_generation
            or not self.is_attached
            or admission_key != self._library_onboarding_admission_key()
        ):
            return
        previous_lifecycle = self._library_lifecycle
        previous_status = self._library_onboarding_status
        previous_back_admitted = (
            previous_lifecycle is LibraryLifecycle.EXPANDED
            and self._library_onboarding_all_empty
        )
        if LibraryContentEvidence.HAS_USER_CONTENT in evidence:
            self._library_onboarding_all_empty = False
            self._library_onboarding_status = LibraryEvidenceStatus.SETTLED
            self._set_library_lifecycle(LibraryLifecycle.GRADUATED)
        elif len(evidence) == 6 and all(
            item is LibraryContentEvidence.EMPTY for item in evidence
        ):
            self._library_onboarding_all_empty = True
            self._library_onboarding_status = LibraryEvidenceStatus.SETTLED
            self._set_library_lifecycle(
                aggregate_library_lifecycle(self._library_lifecycle, evidence)
            )
        else:
            self._library_onboarding_all_empty = False
            self._library_onboarding_status = LibraryEvidenceStatus.PARTIAL_FAILURE
        self._sync_library_onboarding_status_copy()
        current_back_admitted = (
            self._library_lifecycle is LibraryLifecycle.EXPANDED
            and self._library_onboarding_all_empty
        )
        if self.is_mounted and (
            self._library_lifecycle is not previous_lifecycle
            or current_back_admitted != previous_back_admitted
        ):
            self._sync_library_rail_lifecycle_presentation()
        elif self.is_mounted and self._library_onboarding_status is not previous_status:
            self._sync_library_landing_lifecycle_presentation()
        if (
            previous_lifecycle is not LibraryLifecycle.GRADUATED
            and self._library_lifecycle is LibraryLifecycle.GRADUATED
        ):
            notify = getattr(self.app_instance, "notify", None)
            if callable(notify):
                notify(
                    "Library tools are now available.",
                    severity="information",
                )

    def _mirror_library_lifecycle(self, lifecycle: LibraryLifecycle) -> None:
        app_config = self.app_instance.app_config
        library_config = app_config.get("library")
        if not isinstance(library_config, dict):
            library_config = {}
            app_config["library"] = library_config
        rail_state = library_config.get("rail_state")
        if not isinstance(rail_state, dict):
            rail_state = {}
            library_config["rail_state"] = rail_state
        rail_state["lifecycle"] = lifecycle.value

    def _set_library_lifecycle(self, lifecycle: LibraryLifecycle) -> None:
        """Accept and queue persistence for one lifecycle transition."""
        if (
            lifecycle is self._library_lifecycle
            and lifecycle is self._library_lifecycle_last_persisted
        ):
            return
        if (
            self._library_lifecycle is not LibraryLifecycle.GRADUATED
            and lifecycle is LibraryLifecycle.GRADUATED
        ):
            self._library_graduation_announcement_visible = True
        self._library_lifecycle = lifecycle
        self._queue_library_lifecycle_persistence(lifecycle)

    def _queue_library_lifecycle_persistence(
        self,
        lifecycle: LibraryLifecycle,
    ) -> None:
        """Mirror immediately and coalesce disk writes to the latest value."""
        self._mirror_library_lifecycle(lifecycle)
        self._library_lifecycle_pending_persist = lifecycle
        worker = self._library_lifecycle_persist_worker
        if not self.is_attached or (worker is not None and not worker.is_finished):
            return
        self._library_lifecycle_persist_worker = self.run_worker(
            self._drain_library_lifecycle_persistence(),
            group="library_lifecycle_persistence",
        )

    async def _drain_library_lifecycle_persistence(self) -> None:
        """Serialize lifecycle writes while retaining the latest request."""
        while self._library_lifecycle_pending_persist is not None:
            lifecycle = self._library_lifecycle_pending_persist
            self._library_lifecycle_pending_persist = None
            previous_warning = self._library_onboarding_persistence_warning
            try:
                persisted = await asyncio.to_thread(
                    save_setting_to_cli_config,
                    "library.rail_state",
                    "lifecycle",
                    lifecycle.value,
                )
            except Exception:
                self._library_onboarding_persistence_warning = "Library view is updated for this session, but the choice may not be remembered."
            else:
                if persisted is True:
                    self._library_lifecycle_last_persisted = lifecycle
                    self._library_onboarding_persistence_warning = ""
                else:
                    self._library_onboarding_persistence_warning = "Library view is updated for this session, but the choice may not be remembered."
            if (
                self.is_mounted
                and previous_warning != self._library_onboarding_persistence_warning
            ):
                self._sync_library_lifecycle_status()

    def _library_rail_preferences(self):
        """Read persisted Library rail section preferences, defensively.

        (C4) Same restart-persistence gap as
        ``_load_library_search_history``: ``self.app_instance.app_config``
        (from ``load_settings()``) can come back without a ``library``
        section at all even when ``config.toml`` has persisted
        ``[library.rail_state]`` on disk -- so a freshly started app would
        otherwise always reopen every rail section at its hardcoded
        default instead of the user's last-chosen open/collapsed state.
        Falls back to a live ``get_cli_setting("library.rail_state")`` read
        of the CLI config file when ``app_config`` doesn't already carry a
        usable ``sections`` dict; ``app_config`` wins whenever it does.
        """
        app_config = getattr(self.app_instance, "app_config", None)
        raw = None
        if isinstance(app_config, dict):
            library_config = app_config.get("library")
            if isinstance(library_config, dict):
                rail_state = library_config.get("rail_state")
                if isinstance(rail_state, dict):
                    raw = rail_state.get("sections")
        if not isinstance(raw, dict):
            try:
                # Dotted 1-arg form, same shape as
                # `_load_library_search_history`'s CLI fallback:
                # `get_cli_setting("library.rail_state")` returns
                # `config["library"]["rail_state"]` (the rail_state
                # sub-dict), not the "sections" dict directly.
                cli_rail_state = get_cli_setting("library.rail_state")
            except Exception:
                cli_rail_state = None
            if isinstance(cli_rail_state, dict):
                raw = cli_rail_state.get("sections")
        return coerce_library_rail_preferences(raw)

    def _load_library_search_history(self) -> tuple[str, ...]:
        """Read persisted Library Search/RAG query history, defensively.

        Two sources are consulted, in order:

        1. `self.app_instance.app_config["library"]["search"]["history"]` --
           the in-memory config dict. This is the primary source: it is what
           pilots seed directly, and it reflects any history recorded during
           the current session (`_record_library_search_history` mutates it
           in place, alongside persisting to disk).
        2. `get_cli_setting("library.search")` -- a live re-read of
           `config.toml` via `load_cli_config_and_ensure_existence()`. This
           fallback exists because `app.app_config` comes from
           `load_settings()`, whose merged output does NOT reliably surface
           the `[library.search]` TOML table (it can come back empty even
           when `config.toml` has history on disk) -- so a freshly started
           app would otherwise always see empty history despite having
           persisted some in a prior session. `get_cli_setting` reads the
           CLI config file directly and does carry the value.

        Only source (1) is used when it already yields a list, so pilots
        that seed `app_config` directly stay authoritative and never touch
        disk. Missing keys or a malformed shape from either source quietly
        fall back to no history; entries are coerced to trimmed strings and
        capped to the same shape `update_search_history` produces (<= 10
        entries, <= 200 chars each).

        `config.toml` is user-editable, so each entry is also run through
        `_safe_text` (control-character stripping, dangerous-pattern
        removal, length validation) before it ever becomes a history
        `Button` label -- belt-and-suspenders alongside the markup escape
        `library_rag_history_children` applies at render time.
        """
        app_config = getattr(self.app_instance, "app_config", None)
        raw = None
        if isinstance(app_config, dict):
            library_config = app_config.get("library")
            if isinstance(library_config, dict):
                search_config = library_config.get("search")
                if isinstance(search_config, dict):
                    raw = search_config.get("history")
        if not isinstance(raw, list):
            try:
                # Dotted 1-arg form: get_cli_setting("library.search") splits
                # on the first '.' into section="library", key="search" and
                # returns config["library"]["search"] (the search sub-dict,
                # not the history list) -- deliberately NOT the 3-arg
                # ("library.search", "history", default) form, which treats
                # "library.search" as a single literal top-level section key
                # and never matches the nested TOML table.
                search_config = get_cli_setting("library.search")
            except Exception:
                search_config = None
            if isinstance(search_config, dict):
                raw = search_config.get("history")
        if not isinstance(raw, list):
            return ()
        entries = tuple(
            sanitized
            for entry in raw
            if (
                sanitized := self._safe_text(
                    entry, max_length=LIBRARY_SEARCH_HISTORY_ENTRY_MAX_CHARS
                )
            )
        )
        return entries[:LIBRARY_SEARCH_HISTORY_LIMIT]

    def _record_library_search_history(self, query: str) -> None:
        """Update in-memory and persisted Library Search/RAG query history."""
        self._library_search_history = update_search_history(
            self._library_search_history, query
        )
        self._persist_library_search_history(list(self._library_search_history))

    def _persist_library_search_history(self, history_list: list[str]) -> None:
        """Write `history_list` into the in-memory config and to disk.

        Shared by `_record_library_search_history` (append a new query) and
        `clear_library_search_history` (D1: empty the list) so both funnel
        through one persistence path.
        """
        app_config = getattr(self.app_instance, "app_config", None)
        if isinstance(app_config, dict):
            library_config = app_config.get("library")
            if not isinstance(library_config, dict):
                library_config = {}
                app_config["library"] = library_config
            search_config = library_config.get("search")
            if not isinstance(search_config, dict):
                search_config = {}
                library_config["search"] = search_config
            search_config["history"] = history_list
        self._save_library_search_history(history_list)

    @work(thread=True)
    def _save_library_search_history(self, history: list[str]) -> None:
        """Persist Library Search/RAG query history without blocking the UI thread."""
        try:
            save_setting_to_cli_config("library.search", "history", history)
        except Exception:
            pass

    def _set_library_rail_section(self, section_id: str, open_state: bool) -> None:
        """Persist one section preference and sync the rail body/header."""
        if section_id not in LIBRARY_RAIL_SECTION_IDS:
            return
        from dataclasses import replace as dataclass_replace

        preferences = dataclass_replace(
            self._library_rail_preferences(), **{f"{section_id}_open": open_state}
        )
        serialized = serialize_library_rail_preferences(preferences)
        app_config = getattr(self.app_instance, "app_config", None)
        if isinstance(app_config, dict):
            library_config = app_config.get("library")
            if not isinstance(library_config, dict):
                library_config = {}
                app_config["library"] = library_config
            rail_state = library_config.get("rail_state")
            if not isinstance(rail_state, dict):
                rail_state = {}
                library_config["rail_state"] = rail_state
            rail_state["sections"] = serialized
        self._save_library_rail_preferences(serialized)
        rail = self._active_library_rail()
        if rail is None:
            return
        try:
            body = rail.query_one(f"#library-rail-section-body-{section_id}")
            header = rail.query_one(
                f"#library-rail-section-header-{section_id}",
                DestinationRailSectionHeader,
            )
        except Exception:
            return
        body.display = open_state
        header.sync_open(open_state)
        if section_id == "details" and open_state:
            # task-4023 AC#3 (RC-09): opening the disclosure is the
            # sensible refresh trigger for its DB-sizes reading -- the
            # display toggle above never recomposes the rail, so without
            # this the line keeps whatever the cache held at the last
            # full recompose (measured live: 180.0KB shown against 4.8MB
            # on disk, unchanged across close/reopen).
            self.run_worker(
                self._refresh_library_details_db_sizes(),
                exclusive=True,
                group="library_details_db_sizes",
            )

    @work(thread=True)
    def _save_library_rail_preferences(self, serialized: dict[str, bool]) -> None:
        """Persist Library rail preferences without blocking the UI thread."""
        try:
            save_setting_to_cli_config("library.rail_state", "sections", serialized)
        except Exception:
            pass

    def _set_library_rail_collapsed(self, collapsed: bool) -> None:
        """Toggle wide Library navigation in place without rebuilding state."""
        self._library_rail_collapsed = collapsed
        self._library_ingest_auto_collapsed_rail = False
        self._apply_library_notes_stage_visibility()
        single_stage = (
            self._library_notes_compact and self._library_notes_compact_stage_applies()
        )
        if not self.is_mounted or single_stage:
            return
        self._sync_library_landing_lifecycle_presentation()
        if not collapsed:
            self._focus_library_rail_action("#library-search-input")
            return
        try:
            target = self.query_one("#library-rail-open")
        except (NoMatches, QueryError):
            return
        self.set_focus(target, scroll_visible=False)

    @on(Button.Pressed, "#library-rail-collapse")
    def _collapse_library_rail(self, event: Button.Pressed) -> None:
        """Collapse the wide navigation rail to its keyboard-reachable handle."""
        event.stop()
        self._set_library_rail_collapsed(True)

    @on(Button.Pressed, "#library-rail-open")
    def _expand_library_rail(self, event: Button.Pressed) -> None:
        """Expand Library navigation and return focus to its search field."""
        event.stop()
        self._set_library_rail_collapsed(False)

    def _focus_library_rail_action(self, selector: str) -> None:
        """Focus a preferred rail action, then compact Import or Explore."""
        rail = self._active_library_rail()
        if rail is None:
            return
        for candidate in (
            selector,
            f"#library-row-{LIBRARY_ROW_INGEST_MEDIA}",
            "#library-rail-explore-all",
        ):
            try:
                target = rail.query_one(candidate, Widget)
            except (NoMatches, QueryError):
                continue
            if target.display and not getattr(target, "disabled", False):
                self.set_focus(target, scroll_visible=False)
                return

    @on(Button.Pressed, "#library-rail-explore-all")
    async def _explore_library_rail(self, event: Button.Pressed) -> None:
        """Persist full disclosure, recompose once, and focus the full rail."""
        event.stop()
        await self._explore_library_tools()

    @on(Button.Pressed, "#library-hub-explore-all")
    async def _explore_library_landing(self, event: Button.Pressed) -> None:
        """Run the same disclosure transition from a rail-hidden landing."""
        event.stop()
        await self._explore_library_tools()

    async def _explore_library_tools(self) -> None:
        """Persist full disclosure, reveal the rail, and focus its search."""
        lifecycle = explore_library_lifecycle(self._library_lifecycle)
        if lifecycle is self._library_lifecycle:
            return
        self._set_library_lifecycle(lifecycle)
        self._library_rail_collapsed = False
        await self.recompose()
        self.call_after_refresh(
            self._focus_library_rail_action,
            "#library-search-input",
        )

    @on(Button.Pressed, "#library-hub-retry-evidence")
    def _retry_library_onboarding_evidence(self, event: Button.Pressed) -> None:
        """Start one fresh guarded evidence generation after partial failure."""
        event.stop()
        if self._library_onboarding_status is LibraryEvidenceStatus.PARTIAL_FAILURE:
            self._refresh_library_onboarding_evidence()

    @on(Button.Pressed, "#library-hub-continue")
    async def _continue_library_landing(self, event: Button.Pressed) -> None:
        """Resume the receipt through the existing guarded source route."""

        event.stop()
        receipt = self._copy_library_continue_receipt(self._library_continue_receipt)
        if receipt is None:
            return
        row_id = receipt["row_id"]
        scope = receipt["scope"]
        await self._select_library_rail_row(row_id)
        if self._library_selected_row_id != row_id:
            return

        if row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            self._start_library_conversation_page_request(
                scope["page"],
                scope["query"],
            )
        elif row_id == LIBRARY_ROW_BROWSE_NOTES:
            # Generic rail admission intentionally clears the Notes filter.
            # Continue is the sole route that carries an applied Notes scope,
            # so reapply it only after every ordinary leave guard has passed.
            self._library_notes_sort = scope["sort"]
            self._library_notes_filter = scope["filter"]
            self._library_notes_filter_records = None
            if self._library_notes_filter:
                await self._run_library_notes_filter(self._library_notes_filter)
            else:
                _sync_library_canvas(self, "notes")

    @on(Button.Pressed, "#library-hub-attention-action")
    async def _recover_library_landing_attention(self, event: Button.Pressed) -> None:
        """Open the existing owner recovery for the current live attention."""

        event.stop()
        action = self._library_landing_attention_action()
        action_kind = str(getattr(event.button, "action_kind", "") or "")
        if action is None or action.action_kind != action_kind:
            return
        row_id = {
            "ingest-review": LIBRARY_ROW_INGEST_MEDIA,
            "media-retry": LIBRARY_ROW_BROWSE_MEDIA,
            "prompts-retry": LIBRARY_ROW_BROWSE_PROMPTS,
            "conversations-retry": LIBRARY_ROW_BROWSE_CONVERSATIONS,
        }.get(action_kind)
        if row_id is None:
            return
        await self._select_library_rail_row(row_id)
        if (
            action_kind == "conversations-retry"
            and self._library_selected_row_id == row_id
            and not self._library_conversation_loading
        ):
            self._start_library_conversation_page_request(
                self._library_conversation_requested_page,
                self._library_conversation_requested_query,
                focus_after_apply="#library-conversations-retry",
            )

    @on(Button.Pressed, "#library-rail-back-to-starter")
    async def _return_library_rail_to_starter(self, event: Button.Pressed) -> None:
        """Return an authoritatively empty expanded Library to Starter."""
        event.stop()
        if (
            self._library_lifecycle is not LibraryLifecycle.EXPANDED
            or self._library_onboarding_all_empty is not True
        ):
            return
        lifecycle = return_library_lifecycle_to_starter(
            self._library_lifecycle,
            (LibraryContentEvidence.EMPTY,) * 6,
        )
        if lifecycle is not LibraryLifecycle.STARTER:
            return
        self._library_selected_row_id = ""
        self._register_footer_shortcuts()
        self._set_library_lifecycle(lifecycle)
        await self.recompose()
        self._focus_library_rail_action(f"#library-row-{LIBRARY_ROW_INGEST_MEDIA}")

    @on(Button.Pressed, "#library-ingest-top-button")
    async def _on_library_ingest_top_button(self, event: Button.Pressed) -> None:
        """Jump from the rail-top Ingest button to the Ingest media canvas."""
        event.stop()
        await self._select_library_rail_row(LIBRARY_ROW_INGEST_MEDIA)

    @on(Button.Pressed, ".library-hub-recent")
    def _on_library_hub_recent(self, event: Button.Pressed) -> None:
        """Open a landing-hub recent row straight into its item (task-2238).

        The row carries the same (source_type, record_id) pair the
        Search/RAG evidence "Open" action resolves, so both share
        `_open_library_item_by_id`'s route (dirty-edit guards included).
        Runs as a worker because that route awaits the note/prompt flushes.
        """
        event.stop()
        source_type = str(getattr(event.button, "source_type", "") or "")
        record_id = str(getattr(event.button, "record_id", "") or "")
        if not source_type or not record_id:
            return
        self.run_worker(
            self._open_library_item_by_id(source_type, record_id),
            exclusive=True,
            group="library_hub_open_recent",
        )

    @on(Button.Pressed, "#library-notes-source-files")
    async def _show_library_file_notes(self, event: Button.Pressed) -> None:
        """Leave Database Notes safely and lazily mount File Notes."""
        event.stop()
        if self._library_prompts_mutation_in_flight:
            return
        if self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES:
            return
        await self._flush_library_note_save()
        if self._library_note_dirty:
            return
        if self._library_notes_view == "list":
            self._library_notes_browse_return_receipt = (
                self._capture_library_notes_browse_return_receipt()
            )
        self._evacuate_library_notes_authority_focus("database")
        self._supersede_library_notes_navigation()
        # Database Notes and Folder Files are independent retained authorities.
        # The database coordinator has already flushed above; keep its loaded
        # selection/editor projection so returning from Folder Files resumes it.
        if self._library_file_notes_workspace is None:
            self._library_file_notes_workspace = (
                self._library_file_notes_workspace_factory()
            )
        workspace = self._library_file_notes_workspace
        self._acknowledge_library_destination_change()
        self._set_library_notes_source(LIBRARY_NOTES_SOURCE_FILES)
        # task-2850: the Files-mode Escape binding only fires while
        # ``_file_notes_active()`` is true, so the footer's advertised keys
        # must follow this same transition or Escape works unadvertised.
        self._register_footer_shortcuts()
        try:
            database_shell = self.query_one(
                "#library-notes-reader-shell", LibraryAdaptiveReaderShell
            )
            shell_grid = self.query_one("#library-shell-grid", Horizontal)
        except (NoMatches, QueryError):
            self.refresh(recompose=True)
            self.call_after_refresh(
                self._restore_library_notes_authority_focus,
                "files",
            )
        else:
            if workspace._reader_shell is None:
                shell_state = build_library_shell_state(
                    self._build_library_shell_input(),
                    selected_row_id=self._library_selected_row_id,
                )
                workspace.configure_reader_shell(
                    library_pane=LibraryRail(
                        shell_state,
                        self._library_rail_preferences(),
                        query=self._library_rag_query,
                        search_placeholder=self._library_rail_search_placeholder(),
                        workspaces_body_factory=self._compose_workspaces_rail_body,
                        top_action_factory=self._compose_library_rail_top_action,
                        lifecycle=self._library_lifecycle,
                        onboarding_all_empty=self._library_onboarding_all_empty,
                        id="library-file-notes-rail",
                        classes="destination-workbench-pane",
                    ),
                    layout=self._library_file_notes_reader_layout,
                )
            if not workspace.is_attached:
                await shell_grid.mount(workspace, before=database_shell)
            database_shell.display = False
            database_shell.library.display = False
            workspace.display = True
            self._restore_library_notes_authority_focus("files")
            self._sync_library_notes_source_controls()
            self.call_after_refresh(
                self._sync_library_file_notes_reader_layout_from_shell
            )
            self.call_after_refresh(self._hide_library_adaptive_reader_rail_collapse)
        # The production app can recompose Library after the initial mount-time
        # responsive callback. Measure again once the Files canvas owns its
        # final shell geometry so a compact terminal cannot retain stale wide
        # presentation state from startup.
        self.call_after_refresh(self._update_library_notes_responsive_state)

    def _sync_library_notes_source_controls(self) -> None:
        """Patch the retained Notes source strip after an in-place switch."""
        database_selected = self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        wide_focused_task = (
            not database_selected
            and not self._library_notes_compact
            and self._library_notes_focused_task_active()
        )
        try:
            database = self.query_one("#library-notes-source-database", Button)
            files = self.query_one("#library-notes-source-files", Button)
            separator = self.query_one("#library-notes-source-separator", Widget)
            task_return = self.query_one("#library-notes-task-return", Button)
        except (NoMatches, QueryError):
            return
        database.set_class(database_selected, "-selected")
        files.set_class(not database_selected, "-selected")
        for control in (database, files, separator):
            control.display = not wide_focused_task
        task_return.display = wide_focused_task

    @on(Button.Pressed, "#library-notes-task-return")
    async def _return_from_library_notes_task(self, event: Button.Pressed) -> None:
        """Return through the active Notes owner's existing guarded exit."""
        event.stop()
        if self._file_notes_active():
            await self._return_to_library_database_notes()
            return
        if (
            self._library_notes_workflow_active()
            and self._library_notes_view == "editor"
        ):
            await self._exit_library_note_editor_guarded()

    @on(Button.Pressed, "#library-notes-source-database")
    async def _show_library_database_notes(self, event: Button.Pressed) -> None:
        """Return to Database Notes only after the File Notes leave guard."""
        event.stop()
        if self._library_prompts_mutation_in_flight:
            return
        await self._return_to_library_database_notes()

    @on(FileNotesReloadConfirmationChanged)
    def _handle_file_notes_reload_confirmation_changed(
        self,
        event: FileNotesReloadConfirmationChanged,
    ) -> None:
        """Keep footer and F1 help truthful for the inline decision state."""
        event.stop()
        if event.control is self._library_file_notes_workspace:
            self._register_footer_shortcuts()

    @on(FileNotesEditableOpened)
    def _handle_file_notes_editable_opened(
        self,
        event: FileNotesEditableOpened,
    ) -> None:
        """Activate work-first only for the current admitted Folder identity."""
        event.stop()
        if (
            event.control is self._library_file_notes_workspace
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_FILES
        ):
            self._dispatch_library_notes_work_session(
                NotesWorkSessionEvent.EDITABLE_ITEM_OPENED
            )

    @on(FileNotesIdentityCleared)
    def _handle_file_notes_identity_cleared(
        self,
        event: FileNotesIdentityCleared,
    ) -> None:
        """Reset Folder work-first only at an explicit identity clear."""
        event.stop()
        if event.control is self._library_file_notes_workspace:
            self._dispatch_library_notes_work_session(
                NotesWorkSessionEvent.FOLDER_IDENTITY_CLEARED
            )

    @on(FileNotesRootChanged)
    def _handle_file_notes_root_changed(
        self,
        event: FileNotesRootChanged,
    ) -> None:
        """Reset Folder work-first after the current root binding changes."""
        event.stop()
        if event.control is self._library_file_notes_workspace:
            self._dispatch_library_notes_work_session(
                NotesWorkSessionEvent.FOLDER_ROOT_CHANGED
            )

    async def _return_to_library_database_notes(self) -> None:
        """Leave File Notes and return to the Database Notes view.

        Shared by the "Database" strip button and the Files-mode Escape key
        (task-2850) so both exits honor the identical flush/leave-guard
        sequence -- one seam, not a parallel key-driven path that could
        drift from the button's.
        """
        if self._library_prompts_mutation_in_flight:
            return
        if self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE:
            return
        workspace = self._library_file_notes_workspace
        if workspace is not None and workspace.cancel_path_task():
            self._register_footer_shortcuts()
            return
        if not await self._flush_active_file_notes():
            return
        if workspace is not None and workspace.cancel_path_task():
            self._register_footer_shortcuts()
            return
        release_source = self._acquire_file_notes_transition("source")
        if release_source is False:
            return
        try:
            guard = _LibraryNotesRestoreGuard(
                scroll_generation=self._library_notes_scroll_intent_generation,
                focus_generation=self._library_notes_focus_intent_generation,
            )
            self._evacuate_library_notes_authority_focus("files")
            self._acknowledge_library_destination_change()
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
            self._register_footer_shortcuts()
            workspace = self._library_file_notes_workspace
            retained_switch = False
            try:
                database_shell = self.query_one(
                    "#library-notes-reader-shell", LibraryAdaptiveReaderShell
                )
            except (NoMatches, QueryError):
                await self.recompose()
                self.call_after_refresh(
                    self._restore_library_notes_authority_focus,
                    "database",
                )
            else:
                if workspace is not None:
                    workspace.display = False
                database_shell.display = True
                self._sync_library_notes_source_controls()
                self._sync_library_notes_reader_layout_from_shell()
                self._restore_library_notes_authority_focus("database")
                self._library_notes_focus_intent_generation += 1
                retained_switch = True
            receipt = self._library_notes_browse_return_receipt
            if self._library_notes_view == "editor":
                pass
            elif receipt is None:
                # task-2856 AC1: this lands on the Notes LIST (never Files'
                # own editor state), so re-focus its first row the same way
                # every other "enter/return to a list" seam does.
                self._arm_library_list_entry_focus()
            elif retained_switch:
                self.call_later(
                    self._restore_library_notes_browse_return_receipt,
                    receipt,
                )
                self.call_later(
                    self._queue_library_notes_settled_focus_restore,
                    receipt.focus,
                )
            else:
                self.call_after_refresh(
                    self._restore_library_notes_browse_return_receipt,
                    receipt,
                    guard,
                )
        finally:
            if callable(release_source):
                release_source()

    async def action_library_notes_files_back(self) -> None:
        """Escape: leave Files mode and return to Database Notes (task-2850).

        ``check_action`` gates this to ``_file_notes_active()``, so it only
        ever runs while Files mode genuinely owns the Notes canvas.
        """
        workspace = self._library_file_notes_workspace
        if workspace is not None and workspace.cancel_path_task():
            self._register_footer_shortcuts()
            return
        if workspace is not None and workspace.cancel_reload_confirmation():
            self._register_footer_shortcuts()
            return
        await self._return_to_library_database_notes()

    @on(Button.Pressed, ".library-rail-row")
    @on(Button.Pressed, ".library-hub-action")
    async def handle_library_rail_row(self, event: Button.Pressed) -> None:
        """Dispatch a Library rail row press: navigate, browse, or open a canvas.

        `.library-hub-action` covers the F-010 landing hub's next-action
        rows -- they carry the same row_id/target_kind/target_id attributes
        as rail rows, so both flow through this one dispatch (including its
        dirty-edit guards).
        """
        event.stop()
        if self._library_prompts_mutation_in_flight:
            return
        button = event.button
        target_kind = str(getattr(button, "target_kind", "") or "")
        target_id = str(getattr(button, "target_id", "") or "")
        row_id = str(getattr(button, "row_id", "") or "")
        if target_kind == "screen":
            if target_id:
                self.post_message(NavigateToScreen(target_id))
            return
        if target_kind == "canvas":
            await self._select_library_rail_row(row_id)
            if (
                target_id == "conversations"
                and row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
                and self._library_selected_row_id == row_id
                and self._library_conversation_page_needs_recovery()
            ):
                self._start_library_conversation_page_request(
                    self._library_conversation_requested_page,
                    self._library_conversation_requested_query,
                )
            return
        if target_kind == "handoff":
            # Study/Flashcards/Quizzes rows (L3b Task 8): resolves to the
            # handoff canvas.
            await self._select_library_rail_row(row_id)
            return
        # Unknown target kind: select the row and recompose from selection.
        await self._select_library_rail_row(row_id)

    async def _replace_library_browse_canvas(self, shell: LibraryShellState) -> bool:
        """Replace a Notes/Media list canvas without rebuilding the shell.

        Notes and Media are the high-frequency browse routes exercised by the
        adaptive Notes workflow. Their list canvases can be rebuilt in the
        existing canvas host while the header, rail, and workbench grid retain
        identity when the destination uses the same contextual chrome already
        mounted around that host. Crossing the Notes boundary must use the
        central whole-screen recompose seam so its Database/Files source strip
        is added or removed with the rest of the route-owned structure.

        Args:
            shell: Latest normalized Library shell state.

        Returns:
            True when the targeted update completed; False when the caller
            should use the whole-screen fallback.
        """
        try:
            media_shell_mounted = bool(self.query("#library-media-reader-shell"))
            if (shell.canvas_kind == "media") != media_shell_mounted:
                return False
            notes_source_strip_mounted = bool(self.query("#library-notes-source-strip"))
            destination_uses_notes_source_strip = (
                shell.canvas_kind in LIBRARY_NOTES_SOURCE_STRIP_CANVAS_KINDS
            )
            if notes_source_strip_mounted != destination_uses_notes_source_strip:
                return False

            if shell.canvas_kind == LIBRARY_CANVAS_KIND_NOTES:
                if (
                    self._library_notes_view != "list"
                    or self._library_notes_source != LIBRARY_NOTES_SOURCE_DATABASE
                ):
                    return False
                canvas: Widget = LibraryNotesCanvas(
                    **self._library_notes_list_canvas_kwargs(),
                    id="library-notes-canvas",
                )
            elif shell.canvas_kind == "media":
                if self._library_media_view != "list":
                    return False
                media_state = self._build_library_media_state()
                self._selected_media_id = media_state.selected_id
                canvas = LibraryMediaCanvas(
                    media_state,
                    **self._library_media_canvas_presentation(),
                    id="library-media-canvas",
                )
            else:
                return False

            header = self.query_one("#library-header-line", Static)
            rail = self.query_one("#library-rail", LibraryRail)
            canvas_host = self.query_one("#library-canvas", Vertical)
            generation = self._library_snapshot_state_generation
            route_key = self._library_entry_route_key()
            focus_identity = self._capture_library_entry_focus()
            if self.is_running:
                try:
                    self.app.capture_mouse(None)
                except Exception:
                    logger.debug(
                        "Mouse-capture release before Library route update skipped.",
                        exc_info=True,
                    )
            header.update(self._library_header_line(shell.header_line))
            rail.apply_selection(
                shell,
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
            )
            # Hide the outgoing subtree before detaching it. Textual's
            # compositor may still hold the previous geometry for one frame;
            # without this guard a removed TextArea can be asked to render
            # after its component-style context has already been released.
            # Detach before mounting because same-route replacements reuse
            # their stable canvas ID and Textual rejects duplicate siblings.
            outgoing = tuple(canvas_host.children)
            for child in outgoing:
                child.display = False
            if outgoing:
                await canvas_host.remove_children(outgoing)
            await canvas_host.mount(canvas)
            self._apply_library_notes_stage_visibility()
            self._apply_library_notes_footer_context()
            if focus_identity is not None:
                self._restore_library_entry_focus(
                    focus_identity,
                    generation=generation,
                    route_key=route_key,
                )
            return True
        except Exception:
            logger.debug(
                "Targeted Library Notes/Media route update failed; falling back "
                "to the central screen recompose seam.",
                exc_info=True,
            )
            return False

    async def _select_library_rail_row(self, row_id: str) -> None:
        """Apply a rail-row selection and recompose the canvas from it.

        Shared by the rail-row press handler and in-canvas mode shortcuts so
        that the single source of selection truth (``_library_selected_row_id``)
        always drives the recomposed canvas.

        A Notes working session is retained only while cycling among the five
        reader destinations. Every other Notes exit flushes first (awaited),
        so it never silently discards unsaved text. A dirty Prompt working copy
        has the same retained-reader boundary; every destructive Prompt exit
        remains vetoed. Dirty skill edits are vetoed (see
        ``_flush_library_skill_save`` -- explicit-Save-only, so there is nothing
        to flush, only to veto on). task-448: the skill guard was originally
        omitted here, so a rail switch silently discarded dirty skill edits
        while Back/row-switch exits vetoed them.
        """
        if self._library_prompts_mutation_in_flight:
            return
        if not await self._flush_active_file_notes():
            return
        release_source = self._acquire_file_notes_transition("source")
        if release_source is False:
            return
        try:
            await self._select_library_rail_row_after_source_admission(row_id)
        finally:
            if callable(release_source):
                release_source()

    async def _select_library_rail_row_after_source_admission(
        self,
        row_id: str,
    ) -> None:
        """Recompose a rail destination while source admission is held."""
        if self._library_prompts_mutation_in_flight:
            return
        retained_reader_rows = {
            LIBRARY_ROW_BROWSE_MEDIA,
            LIBRARY_ROW_BROWSE_COLLECTIONS,
            LIBRARY_ROW_BROWSE_CONVERSATIONS,
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
        }
        note_snapshot = self._library_note_session.snapshot
        retain_note_session = (
            self._library_selected_row_id in retained_reader_rows
            and row_id in retained_reader_rows
            and not (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
                and row_id == LIBRARY_ROW_BROWSE_NOTES
            )
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
            and self._library_notes_view == "editor"
            and self._library_note_load_state == "loaded"
            and note_snapshot is not None
            and note_snapshot.note_id == self._selected_note_id
            and self._library_note_session_blank_id is None
            and not note_snapshot.saving
            and not note_snapshot.in_conflict
            and self._library_note_autosave_state in {"idle", "saved"}
            and not self._library_note_confirming_delete
            and not self._library_note_session.destructive_running
            and self._library_note_session.destructive_admission is None
            and not self._library_note_session.conflict_resolution_running
        )
        if retain_note_session:
            self._invalidate_library_note_autosave()
        else:
            note_flush = await self._flush_library_note_save()
            if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
                return
        retain_prompt_draft = (
            self._library_prompt_dirty
            and self._library_prompts_view == "editor"
            and self._library_selected_row_id in retained_reader_rows
            and row_id in retained_reader_rows
        )
        if retain_prompt_draft:
            if self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS:
                fields = self._read_library_prompt_editor_fields()
                if fields is None or not isinstance(
                    self._library_prompt_detail, Mapping
                ):
                    return
                name, author, details, system, user, keywords = fields
                detail = dict(self._library_prompt_detail)
                detail.update(
                    {
                        "name": name,
                        "author": author,
                        "details": details,
                        "system_prompt": system,
                        "user_prompt": user,
                        "keywords": keywords,
                    }
                )
                self._library_prompt_detail = detail
        elif not await self._flush_library_prompt_save():
            self._notify_prompt_dirty_veto()
            return
        if not await self._flush_library_skill_save():
            self._notify_skill_dirty_veto()
            return
        self._advance_library_stage_interaction()
        if self._try_switch_retained_library_notes_route(row_id):
            return
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._library_media_view == "list"
            and row_id != LIBRARY_ROW_BROWSE_MEDIA
        ):
            self._disarm_library_media_return_for_route_change()
        self._acknowledge_library_destination_change()
        self._cancel_library_media_selection_settlement()
        if row_id != LIBRARY_ROW_BROWSE_MEDIA:
            self._library_media_browse_controller.invalidate()
        if (
            row_id != LIBRARY_ROW_BROWSE_COLLECTIONS
            and self._library_collections_capture_controller is not None
        ):
            self._library_collections_capture_controller.unmount()
        if row_id != LIBRARY_ROW_BROWSE_SKILLS:
            self._library_skills_filter_cursor_context = None
            self._library_skills_browse_controller.invalidate()
        self._library_navigation_context_generation += 1
        if (
            self._pending_library_source_open is not None
            and self._pending_library_source_open[0] == "conversations"
            and self._library_conversation_loading
        ):
            self._library_conversation_request_generation += 1
            self._library_conversation_requested_page = self._library_conversation_page
            self._library_conversation_requested_query = (
                self._library_conversation_query
            )
            self._library_conversation_loading = False
        self._pending_library_source_open = None
        if row_id != LIBRARY_ROW_BROWSE_PROMPTS:
            self._clear_library_prompt_selection(announce=True)
        if row_id == LIBRARY_ROW_CREATE_NOTE:
            # Create Note is a database-only Notes route. File Notes owns a
            # retained workspace, so normalize the source only after its
            # flush and transition admission have succeeded.
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
        if row_id != LIBRARY_ROW_BROWSE_PROMPTS:
            self._invalidate_library_prompts_browse()
        # A rail selection is an explicit route boundary, even when the user
        # later returns to the same visual Notes region. Invalidate the token
        # now so leave→return cannot recreate authority by region equality.
        self._library_notes_operation = None
        self._supersede_library_notes_navigation()
        if row_id == LIBRARY_ROW_CREATE_NOTE and not self._library_note_create_running:
            # Create status belongs to one visible Create attempt. Import
            # reuses the persistence seam from Navigator, so its internal
            # failure must not leak into a later fresh Create entry.
            self._library_note_create_status = ""
        self._set_library_destination_with_conversation_fence(row_id)
        if (
            row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            self._request_library_notes_tree_initial_load()
        try:
            shell_width = self.query_one("#library-shell-grid").region.width
        except (NoMatches, QueryError):
            shell_width = 0
        if shell_width > 0:
            self._sync_library_ingest_rail_for_width(shell_width)
        # task-4023 AC#7: a plain rail switch is a fresh entry -- only
        # ``_open_library_export_canvas`` (which bypasses this seam) may
        # arm an Export back-origin.
        self._library_export_origin_row_id = ""
        # task-420: keep the footer's "u" hint in sync with the row gate.
        self._register_footer_shortcuts()
        self._library_notes_explicit_stage_intent = row_id in {
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_CREATE_NOTE,
        }
        if self._library_notes_explicit_stage_intent:
            self._library_notes_stage = "notes"
        # A rail-row press is always a fresh entry into a content type, so
        # the media canvas must never resume a previously opened viewer
        # (e.g. Browse Media -> open item -> Browse Conversations -> Browse
        # Media again must show the list, not the stale viewer).
        self._library_media_view = "list"
        self._library_media_detail = None
        self._library_media_composed_detail = None
        self._library_media_editing = False
        self._library_media_confirming_delete = False
        self._library_media_highlights = []
        self._library_media_editing_analysis = False
        self._library_media_content_query = ""
        self._library_media_content_match_index = 0
        self._library_media_content_mode = "raw"
        self._library_notes_filter = ""
        self._library_notes_filter_records = None
        self._library_notes_filter_generation += 1
        self._library_notes_tree_filter_state = None
        self._library_notes_browse_return_receipt = None
        if not retain_note_session:
            self._dispatch_database_note_identity_cleared()
            self._reset_library_note_editor_state()
        if not retain_prompt_draft:
            self._reset_library_prompt_editor_state()
        if row_id != LIBRARY_ROW_BROWSE_SKILLS:
            self._library_skill_import_coordinator.invalidate_row()
        # Review finding (Spec 1 T5): this rail-switch reset block does NOT
        # route through _reset_library_skill_editor_state() (skill-editor
        # exits handle their own reset there), so the trust-reset confirm
        # gate needs its own explicit clear here too -- otherwise arming it
        # (editor manifest_error panel or the list header) and then
        # switching rail rows away leaves it armed, and it can reappear
        # unprompted on a later, unrelated entry into the skills view.
        self._library_skill_trust_confirming_reset = False
        # (task-2043) The ingest form now PERSISTS across rail switches --
        # the old full reset discarded a typed path/metadata on every
        # switch, destructive for multi-batch workflows (round-2 critique).
        # Only switch-hygiene runs here; the deep-link entry keeps its
        # documented full reset.
        self._pause_library_ingest_transient_ui()
        # Always resets to the Everything scope (a plain rail-row press,
        # unlike a browse-canvas "Export…" action, never carries a
        # section-specific filter) -- see
        # ``_reset_library_export_transient_state``'s docstring.
        self._reset_library_export_transient_state()
        self._invalidate_library_workspace_depth_state()
        if row_id == LIBRARY_ROW_CREATE_PROMPT:
            # Task 8b D1: "New prompt" -- applied AFTER
            # _reset_library_prompt_editor_state() above (which it would
            # otherwise immediately undo), mirroring the reset-then-set
            # ordering ``apply_navigation_context``'s notes-create branch
            # already uses.
            self._enter_library_prompt_create_editor()
        if row_id == LIBRARY_ROW_CREATE_SKILL:
            # Skills sub-project (skills-200 spec, "Create > New skill"):
            # same shape as the "New prompt" branch immediately above --
            # ``_enter_library_skill_create_editor`` fully (re)sets every
            # skill-editor field itself, so it needs no preceding
            # ``_reset_library_skill_editor_state()`` call here.
            self._enter_library_skill_create_editor()
        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        self._library_selected_row_id = shell.selected_row_id
        replaced = False
        if self._library_ordinary_route_active() and self.query(
            "#library-canvas-route-content"
        ):
            replacement = self._build_library_entry_active_child()
            if replacement is not None:
                replaced = (
                    await self._replace_library_canvas_child(
                        replacement,
                        generation=self._library_snapshot_state_generation,
                        route_key=self._library_entry_route_key(),
                        rail_mode="selection",
                        then=self._focus_library_ordinary_canvas_entry,
                    )
                    is LibraryEntryReconcileResult.APPLIED
                )
        elif await self._replace_library_browse_canvas(shell):
            replaced = True
        if not replaced:
            await self.recompose()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            self.run_worker(
                self._load_library_collections_capture_entry(),
                exclusive=True,
                group="library_collections_capture_entry",
            )
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            # The controller synchronizes its current/loading result
            # immediately. Dispatch only after the destination canvas is
            # mounted; dispatching before the awaited route recompose could
            # let both the immediate result and a fast worker result land in
            # the no-canvas window, permanently stranding a ready controller
            # result off screen under load.
            self._request_library_prompts_browse(
                self._library_prompt_browse_controller.mutation_refresh_scope,
                focus_identity=None,
            )
        if (
            retain_note_session
            and row_id == LIBRARY_ROW_BROWSE_NOTES
            and note_snapshot.dirty
        ):
            self._schedule_library_note_autosave()
        if self._library_ordinary_route_active():
            try:
                width = self.query_one("#library-shell-grid").region.width
            except (NoMatches, QueryError):
                width = 0
            if width > 0 and ordinary_emergency_required(width):
                self._advance_library_stage_interaction()
                self._library_emergency_stage = "canvas-only"
            self._apply_library_notes_stage_visibility()
            self.call_after_refresh(self._apply_library_notes_stage_visibility)
        else:
            self._library_emergency_stage = None
            self._library_emergency_restore_receipt = None
            self._apply_library_notes_stage_visibility()
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
            and self._library_skills_view == "list"
        ):
            # The strict posture projection requires its retained owner to exist.
            self._refresh_library_skills_trust_posture()
            self._request_library_skills_browse(
                self._library_skills_browse_controller.mutation_refresh_scope,
            )
            self.call_after_refresh(
                self._present_library_skills_import_choice_if_needed
            )
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
            self._request_library_media_browse(
                self._library_media_browse_controller.mutation_refresh_scope,
                focus_identity="#library-media-row-0",
            )
            self._request_library_media_facets()
        # task-2856 AC1: a rail-row press landing on one of the four list
        # canvases focuses its primary list's first row -- the entry-point
        # half of the same seam ``_exit_library_skill_editor_guarded`` /
        # ``_return_to_library_database_notes`` /
        # ``_exit_library_media_viewer`` / ``_exit_library_note_editor_guarded``
        # / ``_exit_library_prompt_editor_guarded`` use for the RETURN half.
        # Explicitly the four BROWSE_* ids, NOT
        # ``_LIBRARY_LIST_ROW_CLASS_BY_ROW_ID`` (which also maps CREATE_
        # PROMPT/CREATE_SKILL -- needed for the RETURN half's row-class
        # lookup once back on the list, but a FRESH press into either
        # ALWAYS lands in the editor, never the list; the branches below
        # set that editor's own field focus instead).
        if self.is_mounted and self._library_selected_row_id in (
            LIBRARY_ROW_BROWSE_MEDIA,
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
        ):
            self._arm_library_list_entry_focus()
        if self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT:
            self._start_library_export_counts_worker()
        if row_id == LIBRARY_ROW_INGEST_MEDIA and self.is_mounted:
            # task-3302 AC#1 (MI-03): entering Ingest parks the caret in
            # the path field -- the first action on this canvas is always
            # typing/pasting a path. Previously focus stayed wherever it
            # was (the rail search box in the live walk), so typing a path
            # ran a Library search. Same call_after_refresh seam the
            # CREATE_PROMPT/CREATE_SKILL entry-focus branches below use.
            self.call_after_refresh(self._focus_library_ingest_path)
            self.call_after_refresh(self._sync_library_ingest_rail_from_shell)
        if row_id == LIBRARY_ROW_CREATE_PROMPT and self.is_mounted:
            self.call_after_refresh(self._arm_library_prompt_editor)
        if row_id == LIBRARY_ROW_CREATE_SKILL and self.is_mounted:
            self.call_after_refresh(self._arm_library_skill_editor)
            # task-424: first action in a blank create editor is always
            # naming it -- put the caret there.
            self.call_after_refresh(self._focus_library_skill_name)
        if row_id in {
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_BROWSE_COLLECTIONS,
            LIBRARY_ROW_BROWSE_SEARCH,
            LIBRARY_ROW_INGEST_EXPORT,
            *LIBRARY_STUDY_HANDOFF_ROW_IDS,
        }:
            self.call_after_refresh(self._focus_library_ordinary_canvas_entry)
            if self._library_emergency_stage == "canvas-only":
                self._focus_library_ordinary_canvas_entry()

    def _try_switch_retained_library_notes_route(self, row_id: str) -> bool:
        """Switch between retained Notes list/Create routes in place.

        Navigator New and Create Back are in-reader mode transitions, not
        destination replacements. All leave guards have already admitted the
        transition before this method runs. Return ``False`` when the retained
        Notes owners are unavailable so the caller can use the legacy route
        fallback.

        Args:
            row_id: Admitted Library destination row.

        Returns:
            ``True`` when the retained Notes shell accepted the transition.
        """
        entering_create = (
            row_id == LIBRARY_ROW_CREATE_NOTE
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_notes_view == "list"
        )
        leaving_create = (
            row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_selected_row_id == LIBRARY_ROW_CREATE_NOTE
        )
        reentering_browse = (
            row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
        )
        if not (
            (entering_create or leaving_create or reentering_browse)
            and self._library_notes_source == LIBRARY_NOTES_SOURCE_DATABASE
            and self.is_mounted
        ):
            return False
        try:
            self.query_one("#library-notes-reader-shell", LibraryAdaptiveReaderShell)
            rail = self.query_one("#library-rail", LibraryRail)
            header = self.query_one("#library-header-line", Static)
        except (NoMatches, QueryError):
            return False

        self._acknowledge_library_destination_change()
        self._library_navigation_context_generation += 1
        self._pending_library_source_open = None
        self._library_notes_operation = None
        self._supersede_library_notes_navigation()
        if not self._library_note_create_running:
            self._library_note_create_status = ""
        self._dispatch_database_note_identity_cleared()
        self._reset_library_note_editor_state()
        self._set_library_destination_with_conversation_fence(row_id)
        if reentering_browse:
            self._library_notes_filter = ""
            self._library_notes_filter_records = None
            self._library_notes_filter_generation += 1
            self._library_notes_tree_filter_state = None
            self._library_notes_browse_return_receipt = None
            self._request_library_notes_tree_initial_load()
        self._library_notes_explicit_stage_intent = True
        self._library_notes_stage = "notes"
        self._invalidate_library_workspace_depth_state()
        self._register_footer_shortcuts()

        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        self._library_selected_row_id = shell.selected_row_id
        rail.apply_selection(
            shell,
            lifecycle=self._library_lifecycle,
            onboarding_all_empty=self._library_onboarding_all_empty,
        )
        header.update(self._library_header_line(shell.header_line))
        identity = LibraryNotesFocusIdentity(
            stage="notes",
            region="create" if entering_create else "navigator",
            note_id=None,
            semantic_role="create-template:blank" if entering_create else "filter",
        )
        _sync_library_canvas(
            self,
            "notes",
            then=lambda: self._restore_library_notes_focus_identity(identity),
        )
        return True

    @on(Button.Pressed, ".console-rail-section-toggle")
    def handle_library_rail_section_toggle(self, event: Button.Pressed) -> None:
        """Toggle a Library rail section and persist the preference.

        Args:
            event: Button press event emitted by a rail section's
                collapse/expand toggle.
        """
        button_id = event.button.id or ""
        prefix = f"{RAIL_SECTION_TOGGLE_PREFIX}library-"
        if not button_id.startswith(prefix):
            return
        event.stop()
        section_id = button_id.removeprefix(prefix)
        currently_open = bool(
            getattr(self._library_rail_preferences(), f"{section_id}_open", True)
        )
        self._set_library_rail_section(section_id, not currently_open)

    @on(Button.Pressed, ".library-conversation-row")
    def handle_library_conversation_row(self, event: Button.Pressed) -> None:
        """Select mode: toggle the row's checkbox. Normal mode: select the row.

        In select mode, a row press toggles that row's id in
        ``_library_conversations_row_selection`` and patches the row's
        marker, the "N selected" Static, and export-selected's disabled
        state in place (task-252 Tier 1) -- it never sets the normal-mode
        selection/detail while in select mode. Outside select mode,
        behavior is unchanged: selects the conversation and switches the
        Library rail to the conversations browse row -- a canvas-scoped
        ``sync_state`` (task-252 Tier 2), not a screen-level recompose;
        the rail row itself never changes here (this row press is only
        reachable while already browsing conversations).

        Args:
            event: Button press event emitted by a conversation row button.
        """
        event.stop()
        if self._library_conversation_freshness != "fresh":
            return
        conversation_id = str(getattr(event.button, "conversation_id", "") or "")
        if self._library_conversations_select_mode:
            self._library_conversations_row_selection.toggle(conversation_id)
            _apply_library_row_toggle(
                self, "conversations", event.button, conversation_id
            )
            self._library_conversation_reader_state = project_conversation_multiselect(
                self._library_conversation_reader_state,
                active=True,
                selected_count=self._library_conversations_row_selection.count,
                loaded_preview_selected=self._library_conversation_loaded_preview_selected(),
            )
            self._sync_library_conversation_reader()
            return
        if conversation_id:
            self._acknowledge_library_destination_change()
            self._selected_conversation_id = conversation_id
        self._library_selected_row_id = LIBRARY_ROW_BROWSE_CONVERSATIONS
        _sync_library_canvas(self, "conversations")
        if conversation_id:
            self._start_library_conversation_reader_selection(conversation_id)

    @on(Button.Pressed, "#library-conversation-reader-read")
    def show_library_conversation_reader_read(self, event: Button.Pressed) -> None:
        """Show the retained saved transcript."""
        event.stop()
        self._library_conversation_reader_state = set_conversation_reader_mode(
            self._library_conversation_reader_state, "read"
        )
        self._sync_library_conversation_reader()

    @on(Button.Pressed, "#library-conversation-reader-info")
    def show_library_conversation_reader_info(self, event: Button.Pressed) -> None:
        """Show truthful local conversation metadata."""
        event.stop()
        self._library_conversation_reader_state = set_conversation_reader_mode(
            self._library_conversation_reader_state, "info"
        )
        self._sync_library_conversation_reader()

    @on(Input.Submitted, "#library-conversation-reader-find")
    def find_in_library_conversation(self, event: Input.Submitted) -> None:
        """Find only after every saved message body is fully hydrated."""
        event.stop()
        self._library_conversation_reader_state = set_conversation_find_query(
            self._library_conversation_reader_state,
            event.value,
        )
        self._sync_library_conversation_reader()
        state = self._library_conversation_reader_state
        if not state.loading and not state.complete and state.selected_id:
            self._retry_library_conversation_reader()
            state = self._library_conversation_reader_state
        self._library_conversation_find_focus_intent = (
            (
                state.generation,
                self._library_notes_focus_intent_generation,
                state.find_query,
            )
            if state.find_query
            else None
        )
        if state.find_complete and state.find_matches:
            self._finish_library_conversation_find_focus()

    @on(LibraryConversationReader.MessagesSynced)
    def library_conversation_reader_messages_synced(
        self,
        event: LibraryConversationReader.MessagesSynced,
    ) -> None:
        """Revalidate deferred Find focus after current transcript rows mount."""
        event.stop()
        state = self._library_conversation_reader_state
        if (
            event.reader_generation != state.generation
            or event.find_query != state.find_query
        ):
            self._library_conversation_find_focus_intent = None
            return
        self._finish_library_conversation_find_focus()

    @on(Button.Pressed, "#library-conversation-reader-retry")
    def retry_library_conversation_reader(self, event: Button.Pressed) -> None:
        """Retry the selected detail with a fresh pure-state generation."""
        event.stop()
        self._retry_library_conversation_reader()

    def _retry_library_conversation_reader(self) -> None:
        """Start one generation-fenced reader retry when selection is known."""
        if (
            self._library_conversations_select_mode
            or self._library_conversation_reader_state.bulk_active
        ):
            return
        try:
            state, request = retry_conversation(self._library_conversation_reader_state)
        except ValueError:
            selected = self._library_conversation_reader_state.selected_id
            if selected:
                self._start_library_conversation_reader_selection(selected)
            return
        self._library_conversation_reader_state = state
        self._sync_library_conversation_reader()
        self.run_worker(
            self._load_library_conversation_reader(request),
            exclusive=True,
            group="library_conversation_reader",
        )

    def _library_conversation_loaded_preview_selected(self) -> bool | None:
        """Return whether the retained transcript is in the checked-row set."""
        loaded_id = self._library_conversation_reader_state.loaded_id
        if loaded_id is None:
            return None
        return self._library_conversations_row_selection.is_selected(loaded_id)

    @on(Button.Pressed, "#library-conversations-select-toggle")
    def handle_library_conversations_select_toggle(self, event: Button.Pressed) -> None:
        """Enter/exit conversations select mode; clears the selection set (both on enter and exit)."""
        event.stop()
        if self._library_conversation_freshness != "fresh":
            return
        self._library_conversations_select_mode = (
            not self._library_conversations_select_mode
        )
        self._library_conversations_row_selection.clear()
        self._library_conversation_reader_state = project_conversation_multiselect(
            self._library_conversation_reader_state,
            active=self._library_conversations_select_mode,
            selected_count=0,
            loaded_preview_selected=(
                self._library_conversation_loaded_preview_selected()
                if self._library_conversations_select_mode
                else None
            ),
        )
        self._sync_library_conversation_reader()
        _sync_library_canvas(self, "conversations")
        if not self._library_conversations_select_mode:
            self._ensure_library_conversation_reader_selection()

