    def _library_collections_capture_request(
        self,
        *,
        page: int | None = None,
        search: str | None = None,
    ) -> CapturePageRequest | None:
        """Build the exact request for the active capture scope."""
        controller = self._library_collections_capture_controller
        if controller is None or controller.state.authority_key is None:
            return None
        authority_key = controller.state.authority_key
        requested_page = page or self._library_collections_requested_page
        current = controller.state.requested_scope
        if (
            current is not None
            and current.authority_key == authority_key
            and self._library_collections_active_scope.startswith("search:")
        ):
            request = dataclasses.replace(current, page=requested_page)
        else:
            status_by_scope = {
                "saved": ("saved",),
                "reading": ("reading",),
                "read": ("read",),
                "archived": ("archived",),
            }
            request = CapturePageRequest(
                authority_key,
                statuses=status_by_scope.get(
                    self._library_collections_active_scope, ()
                ),
                favorite=(
                    True
                    if self._library_collections_active_scope == "favorites"
                    else None
                ),
                page=requested_page,
            )
        if search is not None:
            request = dataclasses.replace(request, search=search, page=1)
        return request

    def _refresh_library_collections_capture_reader(self) -> None:
        """Recompose the destination-owned capture panes from controller state."""
        if (
            self.is_mounted
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS
        ):
            self.refresh(recompose=True)

    async def _load_library_collections_capture_entry(self) -> None:
        """Adopt app authority, load bounded rail data, page, and first detail."""
        controller = self._library_collections_capture_controller
        if controller is None:
            self._refresh_library_collections_capture_reader()
            return
        controller.adopt_active_authority()
        self._refresh_library_collections_capture_reader()
        if controller.state.authority_key is None:
            return
        scope = controller.scope_service
        try:
            self._library_collections_capture_capabilities = (
                await scope.capabilities()
            )
        except Exception:
            self._library_collections_capture_capabilities = None
        try:
            saved = await scope.list_saved_searches(1)
        except Exception:
            self._library_collections_saved_searches = ()
            self._library_collections_saved_searches_total = 0
        else:
            self._library_collections_saved_searches = tuple(saved.items)
            self._library_collections_saved_searches_total = saved.total
        recovery = getattr(
            self.app_instance, "collections_legacy_recovery_service", None
        )
        if recovery is not None:
            try:
                legacy = await asyncio.to_thread(
                    recovery.list_collections,
                    page=1,
                    size=1,
                )
            except Exception:
                self._library_collections_legacy_recovery_rows = 0
            else:
                self._library_collections_legacy_recovery_rows = legacy.total
        request = self._library_collections_capture_request()
        if request is None:
            self._refresh_library_collections_capture_reader()
            return
        await controller.load_page(request)
        self._library_collections_requested_page = (
            controller.state.applied_scope.page
            if controller.state.applied_scope is not None
            else request.page
        )
        self._refresh_library_collections_capture_reader()
        if controller.state.selected_identity is not None:
            await controller.load_selected_now()
        self._refresh_library_collections_capture_reader()

    async def _run_library_collections_capture_transition(
        self,
        operation: Awaitable[bool],
    ) -> bool:
        """Let loading state paint before awaiting one controller transition."""
        task = asyncio.create_task(operation)
        await asyncio.sleep(0)
        self._refresh_library_collections_capture_reader()
        result = await task
        self._refresh_library_collections_capture_reader()
        return result

    def _notify_library_collections_warning(self, message: str) -> None:
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(message or "Collections action failed.", severity="warning")

    @on(Button.Pressed, ".library-collections-item-row")
    async def select_library_collection_capture(self, event: Button.Pressed) -> None:
        """Select a capture immediately and settle its detail request."""
        event.stop()
        identity = getattr(event.button, "capture_identity", None)
        if identity is None:
            return
        await self._select_library_collection_capture(identity)

    async def _select_library_collection_capture(
        self,
        identity: CaptureIdentity,
    ) -> None:
        """Select one identity and clear results owned by the prior selection."""
        controller = self._library_collections_capture_controller
        if controller is None:
            return
        self._library_collections_action_status = ""
        self._library_collections_action_content = ""
        try:
            await self._run_library_collections_capture_transition(
                controller.select_item(identity)
            )
        except CollectionsCaptureError as exc:
            self._notify_library_collections_warning(exc.reason)

    @on(Button.Pressed, ".library-collections-scope-row")
    async def select_library_collection_capture_scope(
        self, event: Button.Pressed
    ) -> None:
        """Apply one built-in or saved capture scope from the Library rail."""
        event.stop()
        button_id = event.button.id or ""
        prefix = "library-collections-scope-"
        if button_id.startswith(prefix):
            self._library_collections_active_scope = button_id[len(prefix) :]
            request = self._library_collections_capture_request(page=1)
        else:
            search = next(
                (
                    item
                    for item in self._library_collections_saved_searches
                    if button_id.endswith(
                        re.sub(r"[^a-zA-Z0-9_-]+", "-", item.search_id)
                        .strip("-")[:48]
                        or "item"
                    )
                ),
                None,
            )
            if search is None:
                return
            self._library_collections_active_scope = f"search:{search.search_id}"
            request = dataclasses.replace(search.request, page=1)
        controller = self._library_collections_capture_controller
        if controller is None or request is None:
            return
        self._library_collections_requested_page = 1
        await self._run_library_collections_capture_transition(
            controller.load_page(request)
        )
        if controller.state.selected_identity is not None:
            await self._run_library_collections_capture_transition(
                controller.load_selected_now()
            )

    @on(Input.Submitted, "#library-collections-filter")
    async def filter_library_collection_captures(
        self, event: Input.Submitted
    ) -> None:
        """Apply the literal capture filter as a fresh authoritative page."""
        event.stop()
        controller = self._library_collections_capture_controller
        current = controller.state.requested_scope if controller is not None else None
        request = (
            dataclasses.replace(current, search=event.value, page=1)
            if current is not None
            else self._library_collections_capture_request(page=1, search=event.value)
        )
        if controller is None or request is None:
            return
        self._library_collections_requested_page = 1
        await self._run_library_collections_capture_transition(
            controller.load_page(request)
        )
        if controller.state.selected_identity is not None:
            await self._run_library_collections_capture_transition(
                controller.load_selected_now()
            )

    @on(Button.Pressed, "#library-collections-quick-capture")
    def toggle_library_collection_quick_capture(
        self, event: Button.Pressed
    ) -> None:
        """Open or close the compact capture form in the Items pane."""
        event.stop()
        self._library_collections_quick_capture_open = (
            not self._library_collections_quick_capture_open
        )
        if not self._library_collections_quick_capture_open:
            self._reset_library_collection_quick_capture_draft()
        self._refresh_library_collections_capture_reader()

    def _capture_library_collection_quick_capture_draft(self) -> None:
        """Retain mounted form values across reader recomposition."""
        self._library_collections_quick_capture_url = self.query_one(
            "#library-collections-capture-url", Input
        ).value
        self._library_collections_quick_capture_title = self.query_one(
            "#library-collections-capture-title", Input
        ).value
        self._library_collections_quick_capture_tags = self.query_one(
            "#library-collections-capture-tags", Input
        ).value
        self._library_collections_quick_capture_note = self.query_one(
            "#library-collections-capture-note", TextArea
        ).text

    @on(
        Input.Changed,
        "#library-collections-capture-url, #library-collections-capture-title, "
        "#library-collections-capture-tags",
    )
    def retain_library_collection_quick_capture_input(
        self, event: Input.Changed
    ) -> None:
        """Retain an in-progress capture when unrelated state recomposes."""
        attributes = {
            "library-collections-capture-url": (
                "_library_collections_quick_capture_url"
            ),
            "library-collections-capture-title": (
                "_library_collections_quick_capture_title"
            ),
            "library-collections-capture-tags": (
                "_library_collections_quick_capture_tags"
            ),
        }
        attribute = attributes.get(event.input.id or "")
        if attribute is not None:
            setattr(self, attribute, event.value)

    @on(TextArea.Changed, "#library-collections-capture-note")
    def retain_library_collection_quick_capture_note(
        self, event: TextArea.Changed
    ) -> None:
        """Retain the capture note across unrelated reader recomposition."""
        self._library_collections_quick_capture_note = event.text_area.text

    def _reset_library_collection_quick_capture_draft(self) -> None:
        """Clear the capture draft and any uncertain-save confirmation state."""
        self._library_collections_quick_capture_url = ""
        self._library_collections_quick_capture_title = ""
        self._library_collections_quick_capture_tags = ""
        self._library_collections_quick_capture_note = ""
        self._library_collections_save_outcome_unknown = False
        self._library_collections_confirming_save_retry = False
        self._library_collections_quick_capture_saving = False

    @on(Button.Pressed, "#library-collections-capture-cancel")
    def cancel_library_collection_quick_capture(
        self, event: Button.Pressed
    ) -> None:
        event.stop()
        self._library_collections_quick_capture_open = False
        self._reset_library_collection_quick_capture_draft()
        self._refresh_library_collections_capture_reader()

    @on(Button.Pressed, "#library-collections-capture-save")
    async def save_library_collection_quick_capture(
        self, event: Button.Pressed
    ) -> None:
        """Persist a URL through the active capture authority and select it."""
        event.stop()
        if self._library_collections_quick_capture_saving:
            return
        self._capture_library_collection_quick_capture_draft()
        if self._library_collections_save_outcome_unknown:
            self._library_collections_confirming_save_retry = True
            self._library_collections_action_status = (
                "Confirm retry only after checking the refreshed capture list."
            )
            self._refresh_library_collections_capture_reader()
            return
        await self._submit_library_collection_quick_capture()

    @on(Button.Pressed, "#library-collections-capture-retry-confirm")
    async def retry_library_collection_quick_capture(
        self, event: Button.Pressed
    ) -> None:
        """Issue one explicit retry after an indeterminate Server response."""
        event.stop()
        if self._library_collections_quick_capture_saving:
            return
        self._capture_library_collection_quick_capture_draft()
        await self._submit_library_collection_quick_capture()

    @on(Button.Pressed, "#library-collections-capture-retry-back")
    def cancel_library_collection_quick_capture_retry(
        self, event: Button.Pressed
    ) -> None:
        """Return to the retained draft without issuing another save."""
        event.stop()
        self._capture_library_collection_quick_capture_draft()
        self._library_collections_confirming_save_retry = False
        self._refresh_library_collections_capture_reader()

    @on(Button.Pressed, "#library-collections-capture-refresh")
    async def refresh_library_collection_quick_capture(
        self, event: Button.Pressed
    ) -> None:
        """Refresh authority state while retaining an indeterminate save draft."""
        event.stop()
        self._capture_library_collection_quick_capture_draft()
        controller = self._library_collections_capture_controller
        if controller is None or controller.state.authority_key is None:
            return
        request = controller.state.requested_scope
        if request is None:
            request = self._library_collections_capture_request(
                page=self._library_collections_requested_page
            )
        if request is None:
            return
        await self._run_library_collections_capture_transition(
            controller.load_page(request)
        )
        if controller.state.selected_identity is not None:
            await self._run_library_collections_capture_transition(
                controller.load_selected_now()
            )
        self._library_collections_action_status = (
            "Capture list refreshed. Confirm whether the URL is present before retrying."
        )
        self._refresh_library_collections_capture_reader()

    async def _submit_library_collection_quick_capture(self) -> None:
        """Submit the retained capture draft exactly once."""
        controller = self._library_collections_capture_controller
        if controller is None or controller.state.authority_key is None:
            return
        url = self._library_collections_quick_capture_url.strip()
        if not validate_url(url):
            self._library_collections_action_status = (
                "Enter a valid http or https URL before saving."
            )
            self._notify_library_collections_warning(
                self._library_collections_action_status
            )
            self._refresh_library_collections_capture_reader()
            return
        title = self._library_collections_quick_capture_title.strip()
        tags = tuple(
            part.strip()
            for part in self._library_collections_quick_capture_tags.split(",")
            if part.strip()
        )
        note = self._library_collections_quick_capture_note
        self._library_collections_quick_capture_saving = True
        self._library_collections_action_status = "Saving capture…"
        self._library_collections_action_content = ""
        self._refresh_library_collections_capture_reader()
        try:
            outcome = await controller.scope_service.save_capture(
                CaptureSaveRequest(
                    controller.state.authority_key,
                    url,
                    title=title or None,
                    tags=tags,
                    freeform_note=note or None,
                )
            )
        except CollectionsCaptureError as exc:
            self._library_collections_quick_capture_saving = False
            self._library_collections_action_status = (
                f"Capture was not saved: {exc.reason.replace('_', ' ')}."
            )
            self._notify_library_collections_warning(exc.reason)
            self._refresh_library_collections_capture_reader()
            return
        except Exception:
            self._library_collections_quick_capture_saving = False
            self._library_collections_action_status = "Capture was not saved."
            self._notify_library_collections_warning("capture_save_failed")
            self._refresh_library_collections_capture_reader()
            return
        if outcome.outcome_unknown:
            self._library_collections_quick_capture_saving = False
            self._library_collections_save_outcome_unknown = True
            self._library_collections_confirming_save_retry = False
            self._library_collections_action_status = (
                "Save outcome unknown. Refresh before retrying."
            )
            self._refresh_library_collections_capture_reader()
            return

        authority = controller.scope_service.active_authority
        owner = "locally" if authority is not None and authority.kind == "local" else "to Server"
        self._library_collections_action_status = (
            f"Saved {owner}; extraction continues in the background."
            if outcome.extraction_pending
            else f"Saved {owner}."
        )
        self._library_collections_quick_capture_open = False
        self._reset_library_collection_quick_capture_draft()
        request = self._library_collections_capture_request(page=1)
        if request is None:
            self._refresh_library_collections_capture_reader()
            return
        self._library_collections_requested_page = 1
        await self._run_library_collections_capture_transition(
            controller.load_page(request)
        )
        if (
            outcome.capture is not None
            and controller.state.page is not None
            and outcome.capture.identity
            in {item.identity for item in controller.state.page.items}
        ):
            await self._run_library_collections_capture_transition(
                controller.select_item(outcome.capture.identity)
            )
        elif controller.state.selected_identity is not None:
            await self._run_library_collections_capture_transition(
                controller.load_selected_now()
            )

    @on(Button.Pressed, "#library-collections-filters")
    def toggle_library_collection_capture_filters(
        self, event: Button.Pressed
    ) -> None:
        event.stop()
        self._library_collections_filters_open = (
            not self._library_collections_filters_open
        )
        self._refresh_library_collections_capture_reader()

    def _library_collection_capture_filter_request(
        self, *, clear: bool = False
    ) -> CapturePageRequest | None:
        """Build one validated filter disclosure request from mounted inputs."""
        controller = self._library_collections_capture_controller
        current = controller.state.requested_scope if controller is not None else None
        if current is None:
            return self._library_collections_capture_request(page=1)
        if clear:
            return dataclasses.replace(
                current,
                domain=None,
                tags=(),
                date_from=None,
                date_to=None,
                page=1,
            )
        domain = self.query_one(
            "#library-collections-filter-domain", Input
        ).value.strip()
        tags = tuple(
            part.strip()
            for part in self.query_one(
                "#library-collections-filter-tags", Input
            ).value.split(",")
            if part.strip()
        )
        date_from = self.query_one(
            "#library-collections-filter-date-from", Input
        ).value.strip()
        date_to = self.query_one(
            "#library-collections-filter-date-to", Input
        ).value.strip()
        for value in (date_from, date_to):
            if value:
                try:
                    datetime.strptime(value, "%Y-%m-%d")
                except ValueError as exc:
                    raise CollectionsCaptureError("invalid_filter_date") from exc
        return dataclasses.replace(
            current,
            domain=domain or None,
            tags=tags,
            date_from=date_from or None,
            date_to=date_to or None,
            page=1,
        )

    async def _apply_library_collection_capture_request(
        self, request: CapturePageRequest
    ) -> None:
        """Apply a page-one request and settle its selected reader detail."""
        controller = self._library_collections_capture_controller
        if controller is None:
            return
        self._library_collections_requested_page = request.page
        await self._run_library_collections_capture_transition(
            controller.load_page(request)
        )
        if controller.state.selected_identity is not None:
            await self._run_library_collections_capture_transition(
                controller.load_selected_now()
            )

    @on(Button.Pressed, "#library-collections-filters-apply")
    async def apply_library_collection_capture_filters(
        self, event: Button.Pressed
    ) -> None:
        event.stop()
        try:
            request = self._library_collection_capture_filter_request()
        except CollectionsCaptureError as exc:
            self._library_collections_action_status = (
                "Use dates in YYYY-MM-DD order, with From no later than To."
            )
            self._notify_library_collections_warning(exc.reason)
            self._refresh_library_collections_capture_reader()
            return
        if request is not None:
            await self._apply_library_collection_capture_request(request)

    @on(Button.Pressed, "#library-collections-filters-clear")
    async def clear_library_collection_capture_filters(
        self, event: Button.Pressed
    ) -> None:
        event.stop()
        request = self._library_collection_capture_filter_request(clear=True)
        if request is not None:
            await self._apply_library_collection_capture_request(request)

    @on(Button.Pressed, "#library-collections-sort")
    async def cycle_library_collection_capture_sort(
        self, event: Button.Pressed
    ) -> None:
        """Cycle supported sorts, omitting relevance without a search query."""
        event.stop()
        controller = self._library_collections_capture_controller
        current = controller.state.requested_scope if controller is not None else None
        if current is None:
            return
        sorts = tuple(
            value
            for value in CAPTURE_SORTS
            if value != "relevance" or current.search
        )
        next_sort = sorts[(sorts.index(current.sort) + 1) % len(sorts)]
        await self._apply_library_collection_capture_request(
            dataclasses.replace(current, sort=next_sort, page=1)
        )

    @on(Input.Changed, "#library-rag-query-input")
    async def update_library_rag_query(self, event: Input.Changed) -> None:
        """Refresh the run gate/status region without rebuilding results/history.

        B5 (task-284): unsubmitted query text affects the run gate
        (enabled/disabled, quiet-line/recovery messaging) and the scope
        summary/recovery widgets and inspector -- all cheap, bounded
        refreshes -- but never the Evidence results list or Recent-searches
        history (search runs on Submitted). This used to call the full
        panel refresh unconditionally, which tears down and remounts
        ~100+ widgets (every result row + every history row) on every
        keystroke even though neither depends on the query text.

        Resets only the in-flight/service-reported status
        (`_reset_library_rag_in_flight_status`), not the landed results --
        unlike a full reset, this can't desync the (deliberately untouched)
        results widget from what `_library_rag_results` says it holds, so
        clicking an already-visible evidence row keeps working while the
        user types a new, not-yet-submitted query. Without resetting the
        status at all, a query typed while a prior search is still
        in-flight (or just failed) would leave the run gate stuck showing
        "Searching..."/disabled forever, since that stale request's own
        outcome gets discarded by `_apply_library_rag_search_outcome`'s
        query mismatch guard once it lands. `_start_library_rag_query`
        (Submit/Run) does its own full reset immediately before it
        replaces the results/history widgets.

        Args:
            event: The Input.Changed event carrying the query field's
                current text.
        """
        event.stop()
        if event.value == self._library_rag_query:
            return
        self._library_rag_query = event.value
        # task-4023 AC#6 (RC-08): one query truth at the WIDGET level too.
        # The STATE was already single-source, but the rail box only
        # re-seeds on recompose, so typing here left the mounted rail
        # widget visibly holding the older string (proven live: canvas
        # "terminals render" beside rail "terminals"). Patch the sibling
        # in place; its own Changed handler no-ops (value == state).
        self._patch_sibling_library_search_input("#library-search-input", event.value)
        self._reset_library_rag_in_flight_status()
        await self._refresh_search_rag_panel_state_widgets(
            include_results_and_history=False
        )

    @on(Input.Submitted, "#library-rag-query-input")
    async def submit_library_rag_query(self, event: Input.Submitted) -> None:
        """Run Library Search/RAG from the query field for keyboard-only users."""
        event.stop()
        await self._start_library_rag_query()

    def _reset_library_rag_retrieval_state(self) -> None:
        self._library_rag_results = ()
        self._library_rag_retrieval_status = ""
        self._library_rag_recovery_state = None
        self._library_rag_selected_result_id = ""
        self._library_rag_diagnostics = {}
        self._library_rag_searched_query = ""
        self._reset_library_rag_answer_state()

    def _reset_library_rag_answer_state(self) -> None:
        """Drop the answer and its staleness guards (PR-3 Task 4).

        Called wherever the results an answer was grounded in stop being the
        results on screen -- the mode toggle (via
        `_reset_library_rag_retrieval_state`) and the start of a new search.
        Clearing the two guard fields is what makes an in-flight answer's
        eventual arrival a no-op: `_apply_library_rag_answer` compares the
        request it was generated for against them, so an answer for a query
        (or mode) the panel has moved on from can never overwrite a newer
        one. The in-flight flag goes with them, so no reset path can leave a
        dangling "answering" status behind.
        """
        self._library_rag_answer = None
        self._library_rag_answer_query = ""
        self._library_rag_answer_mode = ""
        self._library_rag_answer_in_flight = False
        self._library_rag_answer_in_flight_provider = ""

    def _reset_library_rag_in_flight_status(self) -> None:
        """Un-stick the run gate without touching landed results (B5/task-284).

        Narrower than `_reset_library_rag_retrieval_state`: clears only the
        service-reported `retrieval_status`/`recovery_state` (the fields
        that can otherwise pin the run gate at "Searching..."/disabled or a
        stale failure/recovery message), leaving `_library_rag_results` and
        `_library_rag_selected_result_id` exactly as they are. Used by the
        query-edit path, which deliberately never touches the results/
        history widgets -- resetting those fields there without also
        rebuilding the widget would desync the two.

        The in-flight ANSWER flag (PR-3 Task 4) is cleared for the same
        reason its retrieval counterpart is: it too disables the Run button
        ("Answering…"), and a provider call has no bounded duration, so a
        user who starts typing a new query must not be locked out of running
        it until some model finishes. The landed `_library_rag_answer` itself
        is deliberately left alone -- it belongs to the results still on
        screen, exactly like them. The generation still running underneath
        keeps its guard fields, so its answer still applies when it lands
        (it answers the query those visible results were retrieved for).
        """
        self._library_rag_retrieval_status = ""
        self._library_rag_recovery_state = None
        self._library_rag_answer_in_flight = False
        self._library_rag_answer_in_flight_provider = ""

    @on(Button.Pressed, "#library-rag-run-query")
    async def run_library_rag_query(self, event: Button.Pressed) -> None:
        event.stop()
        await self._start_library_rag_query()

    @on(Button.Pressed, "#library-rag-open-import-export")
    async def open_import_export_from_library_rag(self, event: Button.Pressed) -> None:
        event.stop()
        # Drive the shell selection so the recomposed canvas resolves to the
        # Ingest canvas. The Import/Export row/mode this used to target is
        # retired -- the Ingest ▸ Import media canvas row is its only
        # surviving successor.
        await self._select_library_rail_row(LIBRARY_ROW_INGEST_MEDIA)

    @on(Button.Pressed, "#library-rag-mode-toggle")
    def cycle_library_rag_mode(self, event: Button.Pressed) -> None:
        """Cycle Library Search/RAG mode between keyword search and RAG answer."""
        event.stop()
        self._library_rag_mode = (
            "rag" if self._library_rag_mode == "search" else "search"
        )
        self._reset_library_rag_retrieval_state()
        _sync_library_canvas(self, "search")

    @on(Button.Pressed, ".library-rag-scope-toggle")
    def toggle_library_rag_scope_source(self, event: Button.Pressed) -> None:
        """Toggle one source type in/out of the Search/RAG retrieval scope (B2).

        Unlike the mode toggle, this does NOT reset in-flight retrieval or
        search history. It used to leave already-landed RESULTS visible too
        ("scope only affects the NEXT run") -- D4/task-5 fixed that:
        `LibraryRagPanelState.from_values` now filters already-landed rows
        against the current scope on every build, so a source toggled off
        hides its rows (and clears a selection pointing at one) in this
        exact recompose, not just the next run. Still a transition (like
        the mode toggle), so the canvas recomposes to pick up the new
        toggle labels, run-gate state, the now-filtered evidence list, and
        (if the scope is now empty) the A1 quiet line.
        """
        event.stop()
        button_id = event.button.id or ""
        source_type = button_id.removeprefix("library-rag-scope-toggle-")
        if source_type not in LIBRARY_RAG_SCOPE_TOGGLE_SOURCE_TYPES:
            return
        if source_type in self._library_rag_scope_deselected:
            self._library_rag_scope_deselected.discard(source_type)
        else:
            self._library_rag_scope_deselected.add(source_type)
        _sync_library_canvas(self, "search")

    @on(Collapsible.Toggled, "#library-rag-history")
    def sync_library_rag_history_collapsed(self, event: Collapsible.Toggled) -> None:
        """Track manual expand/collapse so recomposes preserve the user's choice.

        `Collapsible._watch_collapsed` posts this message whenever the
        `collapsed` reactive changes through the normal watcher path -- in
        practice the user clicking the title. The results-arrival
        force-collapse in `_refresh_library_rag_history_widget` deliberately
        BYPASSES the watcher (`set_reactive` + `_update_collapsed`, task-4023
        AC#6 / RC-08: the watcher's animated `scroll_visible` sailed past the
        Evidence region), so it never reaches this handler; that path keeps
        the field honest itself -- `_apply_library_rag_search_outcome` sets
        `_library_rag_history_collapsed` at the transition.
        """
        event.stop()
        self._library_rag_history_collapsed = event.collapsible.collapsed

    @on(Button.Pressed, "#library-rag-history-clear")
    async def clear_library_search_history(self, event: Button.Pressed) -> None:
        """Clear all Library Search/RAG query history, in memory and on disk (D1)."""
        event.stop()
        self._library_search_history = ()
        self._persist_library_search_history([])
        await self._refresh_library_rag_history_widget(self._library_rag_panel_state())

    @on(Button.Pressed, ".library-rag-history-row")
    async def rerun_library_search_from_history(self, event: Button.Pressed) -> None:
        """Re-run a prior Library Search/RAG query selected from history."""
        event.stop()
        index = self._trailing_index(event.button.id)
        if index is None or index >= len(self._library_search_history):
            return
        query = self._library_search_history[index]
        self._library_rag_query = query
        # Repopulate the visible query input too -- otherwise it keeps
        # whatever text (or blank) it held before the history row was
        # clicked, even though the run underneath used the history entry.
        # Set this before starting the run: `update_library_rag_query`'s
        # `Input.Changed` handler is a no-op once its value already equals
        # `_library_rag_query` (true here), so it can't clobber the new
        # run's "searching" status either way, but setting it first keeps
        # the widget and state in lockstep from the start of the run.
        try:
            self.query_one("#library-rag-query-input", Input).value = query
        except (NoMatches, QueryError):
            pass
        await self._start_library_rag_query()

    @staticmethod
    def _trailing_index(button_id: str | None) -> int | None:
        """Parse the trailing `-{index}` integer from a button id, or None."""
        if not button_id:
            return None
        try:
            index = int(button_id.rsplit("-", 1)[-1])
        except ValueError:
            return None
        return index if index >= 0 else None

    async def _start_library_rag_query(self) -> None:
        panel_state = self._library_rag_panel_state()
        run_action = panel_state.query_state.run_action
        if not run_action.enabled:
            notify = getattr(self.app_instance, "notify", None)
            if callable(notify):
                notify(run_action.disabled_reason, severity="warning")
            return

        request = LibraryRagSearchRequest(
            query=panel_state.query_state.query,
            source_types=panel_state.scope.selected_source_types,
            mode=panel_state.query_state.mode,
            top_k=panel_state.query_state.top_k,
            include_citations=panel_state.query_state.include_citations,
        )
        self._record_library_search_history(request.query)
        self._library_rag_results = ()
        self._library_rag_recovery_state = None
        self._library_rag_selected_result_id = ""
        self._library_rag_retrieval_status = "searching"
        self._library_rag_diagnostics = {}
        self._library_rag_searched_query = ""
        # PR-3 Task 4: a new search invalidates the previous answer AND any
        # generation still running for it -- clearing the guard fields is
        # what makes that older answer's arrival a discarded no-op rather
        # than a stale overwrite (`_apply_library_rag_answer`).
        self._reset_library_rag_answer_state()
        # The rail-top search box can invoke this mid-recompose -- it selects
        # the Search canvas via ``_select_library_rail_row`` and then runs the
        # query immediately after, before the scheduled recompose has mounted
        # ``#library-search-rag-panel``. The widget refresh is only attempted
        # when the panel is actually mounted; when it isn't, skipping is
        # non-fatal because the subsequent recompose renders the same state
        # (the status fields set above already carry it). This is an
        # explicit presence check, not a broad NoMatches/QueryError catch --
        # a prior version wrapped the whole refresh (results rows included)
        # in a blanket ``except (NoMatches, QueryError): pass``, which also
        # silently swallowed unrelated mid-rebuild query failures instead of
        # only tolerating the "panel not mounted yet" case it was meant for.
        if self.query("#library-search-rag-panel"):
            await self._refresh_search_rag_panel_state_widgets()
            # task-4023 AC#6 (RC-08): results used to land ~30 rows below
            # the fold behind the configuration region -- pressing Run left
            # the visible half of the canvas pixel-identical. Reveal the
            # Evidence region the moment a run starts (it already shows the
            # in-flight "Searching…" line), so the action visibly did
            # something at the point of action.
            self.call_after_refresh(self._reveal_library_rag_results)
        self._execute_library_rag_search(request)

    async def _page_library_collection_captures(self, delta: int) -> None:
        controller = self._library_collections_capture_controller
        if controller is None or not controller.state.paging_enabled:
            return
        current = controller.state.applied_scope
        if current is None:
            return
        page = max(1, current.page + delta)
        if page == current.page:
            return
        self._library_collections_requested_page = page
        await self._run_library_collections_capture_transition(
            controller.load_page(dataclasses.replace(current, page=page))
        )
        if controller.state.selected_identity is not None:
            await self._run_library_collections_capture_transition(
                controller.load_selected_now()
            )

